INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52299, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "志・願い・目的など、望んでいたことを最後までやり終えて果たす。", "primary_collocate": null, "pronunciation": "とげる", "ipa": "toɡeɾɯ", "syllable_count": 3, "sentences": [{"text": "父は若いころの志を遂げて、立派な医者になった。", "target_word": "遂げて", "complexity_tier": "T3", "furigana": "父[ちち]は若[わか]いころの志[こころざし]を遂[と]げて、立派[りっぱ]な医者[いしゃ]になった。", "sentence_source": "generated"}, {"text": "彼女は周りの反対を押し切って、思いを遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は周[まわ]りの反対[はんたい]を押[お]し切[き]って、思[おも]いを遂[と]げた。", "sentence_source": "generated"}, {"text": "彼は最後まで本懐を遂げることができなかった。", "target_word": "遂げる", "complexity_tier": "T3", "furigana": "彼[かれ]は最後[さいご]まで本懐[ほんかい]を遂[と]げることができなかった。", "sentence_source": "generated"}, {"text": "長年の望みを遂げた祖母は、満足そうに笑っていた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "長年[ながねん]の望[のぞ]みを遂[と]げた祖母[そぼ]は、満足[まんぞく]そうに笑[わら]っていた。", "sentence_source": "generated"}, {"text": "目的を遂げるまでは、決して家に帰らないと決めた。", "target_word": "遂げる", "complexity_tier": "T3", "furigana": "目的[もくてき]を遂[と]げるまでは、決[けっ]して家[いえ]に帰[かえ]らないと決[き]めた。", "sentence_source": "generated"}, {"text": "彼らは苦労の末に、ついに登頂の願いを遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "彼[かれ]らは苦労[くろう]の末[すえ]に、ついに登頂[とうちょう]の願[ねが]いを遂[と]げた。", "sentence_source": "generated"}, {"text": "復讐を遂げた主人公は、静かに故郷を去った。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "復讐[ふくしゅう]を遂[と]げた主人公[しゅじんこう]は、静[しず]かに故郷[こきょう]を去[さ]った。", "sentence_source": "generated"}, {"text": "研究者は一生をかけて、自分の目標を遂げようとしている。", "target_word": "遂げよう", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は一生[いっしょう]をかけて、自分[じぶん]の目標[もくひょう]を遂[と]げようとしている。", "sentence_source": "generated"}, {"text": "志半ばで倒れた彼は、夢を遂げることなく亡くなった。", "target_word": "遂げる", "complexity_tier": "T3", "furigana": "志半[こころざしなか]ばで倒[たお]れた彼[かれ]は、夢[ゆめ]を遂[と]げることなく亡[な]くなった。", "sentence_source": "generated"}, {"text": "彼は八十歳で、世界一周の夢を遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "彼[かれ]は八十歳[はちじっさい]で、世界一周[せかいいっしゅう]の夢[ゆめ]を遂[と]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遂げる", "label": "終止形"}, {"form": "遂げた", "label": "過去形"}, {"form": "遂げて", "label": "て形"}, {"form": "遂げない", "label": "否定形"}, {"form": "遂げれば", "label": "仮定形"}, {"form": "遂げよう", "label": "意志形"}], "register": "formal", "sense_fingerprint": "志・願い・目的など、望んでいたことを最後までやり終えて果たす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52299, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遂げて", "is_correct": true, "explanation": "「志を遂げて」は志が実現した意味で、文脈に合う。"}, {"text": "叩いて", "is_correct": false, "explanation": "「志を叩く」とは言わず、文脈に合わない。"}, {"text": "拭いて", "is_correct": false, "explanation": "「志を拭く」とは言わず、文脈に合わない。"}, {"text": "蹴って", "is_correct": false, "explanation": "「志を蹴る」は志を捨てる意味になり、「立派な医者になった」と合わない。"}], "explanations": {"遂げて": "「志を遂げて」は志が実現した意味で、文脈に合う。", "叩いて": "「志を叩く」とは言わず、文脈に合わない。", "拭いて": "「志を拭く」とは言わず、文脈に合わない。", "蹴って": "「志を蹴る」は志を捨てる意味になり、「立派な医者になった」と合わない。"}, "sentence_index": 0, "correct_answer": "遂げて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は努力の末、ついに挫折を遂げた。", "explanation": "ここは〈断念する〉の意味。挫折は望まない結果なので、遂げるとは合わない。"}, {"text": "授業中に居眠りを遂げた。", "explanation": "ここは〈うたた寝する〉の意味。居眠りは目的ではないので、遂げるとは合わない。"}, {"text": "彼は半年で失業を遂げた。", "explanation": "ここは〈解雇される〉の意味。失業は望んだ目標ではないので、遂げるとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52299, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遂げた", "is_correct": true, "explanation": "「復讐を遂げた」は目的を果たした意味で、文脈に合う。"}, {"text": "脱いだ", "is_correct": false, "explanation": "「復讐を脱ぐ」とは言わず、文脈に合わない。"}, {"text": "煮込んだ", "is_correct": false, "explanation": "「復讐を煮込む」とは言わず、文脈に合わない。"}, {"text": "散らした", "is_correct": false, "explanation": "「復讐を散らす」とは言わず、文脈に合わない。"}], "explanations": {"遂げた": "「復讐を遂げた」は目的を果たした意味で、文脈に合う。", "脱いだ": "「復讐を脱ぐ」とは言わず、文脈に合わない。", "煮込んだ": "「復讐を煮込む」とは言わず、文脈に合わない。", "散らした": "「復讐を散らす」とは言わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "遂げた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は同僚に大きな迷惑を遂げた。", "explanation": "ここは〈かける〉の意味。迷惑は目的ではないので、遂げるとは合わない。"}, {"text": "妹は昨日、喧嘩を遂げた。", "explanation": "ここは〈言い争う〉の意味。喧嘩は望んだ目標ではないので合わない。"}, {"text": "彼は友人に借りを遂げた。", "explanation": "ここは〈返済する〉の意味。借りは望んだ成果ではないので、遂げるとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52299, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は十年の努力の末、ついに夢が遂げた。", "corrected_sentence": "彼は十年の努力の末、ついに夢を遂げた。", "error_description": "「遂げる」の目的語は「夢」で、目的語を示す「を」が正しい。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遂げた", "is_correct": true, "explanation": "「思いを遂げた」の過去形で、文末の過去として正しい。"}, {"text": "遂げさせ", "is_correct": false, "explanation": "連用形だけでは文が終わらず、過去形の代わりにならない。"}, {"text": "遂げて", "is_correct": false, "explanation": "て形は文を続ける形で、文を終わらせる過去形ではない。"}, {"text": "遂げず", "is_correct": false, "explanation": "連用形だけでは文が終わらず、否定の文にもならない。"}], "correct_form": "遂げた", "base_form": "遂げる", "form_label": "過去形", "sentence_index": 1, "explanations": {"遂げた": "「思いを遂げた」の過去形で、文末の過去として正しい。", "遂げさせ": "連用形だけでは文が終わらず、過去形の代わりにならない。", "遂げて": "て形は文を続ける形で、文を終わらせる過去形ではない。", "遂げず": "連用形だけでは文が終わらず、否定の文にもならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52299, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は長年の努力の末、ついに望みを遂げるた。", "corrected_sentence": "彼は長年の努力の末、ついに望みを遂げた。", "error_description": "「遂げた」の活用形が誤り。「遂げるた」は過去形の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遂げよう", "is_correct": true, "explanation": "意志形で「遂げようとしている」の形として正しい。"}, {"text": "遂げれば", "is_correct": false, "explanation": "仮定形は条件を表し、「遂げようとしている」の形とは合わない。"}, {"text": "遂げ", "is_correct": false, "explanation": "連用形だけでは「としている」に続かず、文が成り立たない。"}, {"text": "遂げろ", "is_correct": false, "explanation": "命令形は「としている」に続かず、文が成り立たない。"}], "correct_form": "遂げよう", "base_form": "遂げる", "form_label": "意志形", "sentence_index": 7, "explanations": {"遂げよう": "意志形で「遂げようとしている」の形として正しい。", "遂げれば": "仮定形は条件を表し、「遂げようとしている」の形とは合わない。", "遂げ": "連用形だけでは「としている」に続かず、文が成り立たない。", "遂げろ": "命令形は「としている」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「発展を遂げた」の目的語を示す「を」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「遂げる」の目的語は「を」で、「発展が遂げた」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「発展に遂げた」は不自然。「遂げる」は「を」を取る。"}, {"text": "と", "is_correct": false, "explanation": "「発展と遂げた」は並列の意味にならず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「発展を遂げた」の目的語を示す「を」で正しい。", "が": "「遂げる」の目的語は「を」で、「発展が遂げた」は不自然。", "に": "「発展に遂げた」は不自然。「遂げる」は「を」を取る。", "と": "「発展と遂げた」は並列の意味にならず、不自然。"}, "error_tags": {"が": "主語と目的語の取り違え", "に": "格の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "変化や成長、変貌などを最後まで成し終えて、新しい状態に至る。", "primary_collocate": null, "pronunciation": "とげる", "ipa": "toɡeɾɯ", "syllable_count": 3, "sentences": [{"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "遂げる", "complexity_tier": "T4", "furigana": "その後[ご]、長時間[ちょうじかん]にわたる低温[ていおん]発酵[はっこう]を経[へ]ることで、グルテンの網目[あみめ]は緻密[ちみつ]さを増[ま]し、消化[しょうか]吸収[きゅうしゅう]にも優[すぐ]れた変容[へんよう]を遂[と]げる。", "sentence_source": "mined"}, {"text": "この町は、戦後わずか二十年で大きな発展を遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "この町[まち]は、戦後[せんご]わずか二十年[にじゅうねん]で大[おお]きな発展[はってん]を遂[と]げた。", "sentence_source": "generated"}, {"text": "技術の進歩により、携帯電話は急速な進化を遂げている。", "target_word": "遂げている", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の進歩[しんぽ]により、携帯電話[けいたいでんわ]は急速[きゅうそく]な進化[しんか]を遂[と]げている。", "sentence_source": "generated"}, {"text": "彼女は留学をきっかけに、見違えるような成長を遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は留学[りゅうがく]をきっかけに、見違[みちが]えるような成長[せいちょう]を遂[と]げた。", "sentence_source": "generated"}, {"text": "古い工場街は、再開発によって美しい住宅地へと変貌を遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "古[ふる]い工場街[こうじょうがい]は、再開発[さいかいはつ]によって美[うつく]しい住宅地[じゅうたくち]へと変貌[へんぼう]を遂[と]げた。", "sentence_source": "generated"}, {"text": "小さな会社だった当店も、十年で飛躍的な成長を遂げました。", "target_word": "遂げました", "complexity_tier": "T3", "furigana": "小[ちい]さな会社[かいしゃ]だった当店[とうてん]も、十年[じゅうねん]で飛躍的[ひやくてき]な成長[せいちょう]を遂[と]げました。", "sentence_source": "generated"}, {"text": "蛹は何週間もかけて、美しい蝶へと変態を遂げる。", "target_word": "遂げる", "complexity_tier": "T3", "furigana": "蛹[さなぎ]は何週間[なんしゅうかん]もかけて、美[うつく]しい蝶[ちょう]へと変態[へんたい]を遂[と]げる。", "sentence_source": "generated"}, {"text": "生物は長い時間をかけて、環境に合わせた独自の進化を遂げてきた。", "target_word": "遂げて", "complexity_tier": "T3", "furigana": "生物[せいぶつ]は長[なが]い時間[じかん]をかけて、環境[かんきょう]に合[あ]わせた独自[どくじ]の進化[しんか]を遂[と]げてきた。", "sentence_source": "generated"}, {"text": "日本の経済は高度成長期に目覚ましい発展を遂げて、世界第二位になった。", "target_word": "遂げて", "complexity_tier": "T3", "furigana": "日本[にほん]の経済[けいざい]は高度[こうど]成長期[せいちょうき]に目覚[めざ]ましい発展[はってん]を遂[と]げて、世界[せかい]第二位[だいにい]になった。", "sentence_source": "generated"}, {"text": "この地域の産業は、観光を軸に劇的な変化を遂げた。", "target_word": "遂げた", "complexity_tier": "T3", "furigana": "この地域[ちいき]の産業[さんぎょう]は、観光[かんこう]を軸[じく]に劇的[げきてき]な変化[へんか]を遂[と]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遂げる", "label": "終止形"}, {"form": "遂げた", "label": "過去形"}, {"form": "遂げて", "label": "て形"}, {"form": "遂げない", "label": "否定形"}, {"form": "遂げれば", "label": "仮定形"}, {"form": "遂げよう", "label": "意志形"}], "register": "formal", "sense_fingerprint": "発展・進化・変貌など、変化や成長を最後まで成し終える（〜を遂げる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遂げる", "is_correct": true, "explanation": "「変容を遂げる」は変化を最後まで成し終える意味で、文脈に合う。"}, {"text": "抱く", "is_correct": false, "explanation": "「抱く」は感情や考えに使い、「変容を抱く」とは言わない。"}, {"text": "失う", "is_correct": false, "explanation": "「変容を失う」は意味が逆になり、文脈に合わない。"}, {"text": "断つ", "is_correct": false, "explanation": "「断つ」は関係や習慣に使い、「変容を断つ」とは言わない。"}], "explanations": {"遂げる": "「変容を遂げる」は変化を最後まで成し終える意味で、文脈に合う。", "抱く": "「抱く」は感情や考えに使い、「変容を抱く」とは言わない。", "失う": "「変容を失う」は意味が逆になり、文脈に合わない。", "断つ": "「断つ」は関係や習慣に使い、「変容を断つ」とは言わない。"}, "sentence_index": 0, "correct_answer": "遂げる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は練習を重ねたが、ついに失敗を遂げた。", "explanation": "ここは〈しくじる〉の意味。遂げるは望んだ成果を得る語で、しくじりには使わない。"}, {"text": "車は坂道で止まらず、ついに事故を遂げた。", "explanation": "ここは〈起こす〉の意味。遂げるは望ましい達成や変化に使い、事故には使わない。"}, {"text": "彼は約束を忘れて、ついに遅刻を遂げた。", "explanation": "ここは〈遅れる〉の意味。遂げるは目的や望んだ変化に使い、遅刻には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遂げる", "is_correct": true, "explanation": "「変態を遂げる」は変化を完了する意味で、文脈に合う。"}, {"text": "担ぐ", "is_correct": false, "explanation": "「担ぐ」は物を肩に乗せる動作で、「変態を担ぐ」とは言わない。"}, {"text": "眺める", "is_correct": false, "explanation": "「眺める」は対象を見る行為で、変化を完了する意味にならない。"}, {"text": "逃す", "is_correct": false, "explanation": "「逃す」は機会を失う意味で、文脈に合わない。"}], "explanations": {"遂げる": "「変態を遂げる」は変化を完了する意味で、文脈に合う。", "担ぐ": "「担ぐ」は物を肩に乗せる動作で、「変態を担ぐ」とは言わない。", "眺める": "「眺める」は対象を見る行為で、変化を完了する意味にならない。", "逃す": "「逃す」は機会を失う意味で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "遂げる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は長年の借金をついに遂げた。", "explanation": "ここは〈返済する〉の意味。遂げるは望んだ成果や変化に使い、借金には使わない。"}, {"text": "風邪が悪化して、ついに病気を遂げた。", "explanation": "ここは〈かかる〉の意味。病気は目的ではないので、遂げるとは合わない。"}, {"text": "午後になって、ついに眠気を遂げた。", "explanation": "ここは〈催す〉の意味。眠気は望んだ目的ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は三年の努力の末、ついに大きな変化が遂げた。", "corrected_sentence": "この店は三年の努力の末、ついに大きな変化を遂げた。", "error_description": "「遂げる」の目的語は「変化」で、目的語を示す「を」が正しい。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遂げた", "is_correct": true, "explanation": "「大きな発展を遂げた」の過去形で、文末の過去として正しい。"}, {"text": "遂げさせ", "is_correct": false, "explanation": "連用形だけでは文が終わらず、過去形の代わりにならない。"}, {"text": "遂げて", "is_correct": false, "explanation": "て形は文を続ける形で、文を終わらせる過去形ではない。"}, {"text": "遂げず", "is_correct": false, "explanation": "連用形だけでは文が終わらず、否定の文にもならない。"}], "correct_form": "遂げた", "base_form": "遂げる", "form_label": "過去形", "sentence_index": 1, "explanations": {"遂げた": "「大きな発展を遂げた」の過去形で、文末の過去として正しい。", "遂げさせ": "連用形だけでは文が終わらず、過去形の代わりにならない。", "遂げて": "て形は文を続ける形で、文を終わらせる過去形ではない。", "遂げず": "連用形だけでは文が終わらず、否定の文にもならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52300, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この製品は長い試行錯誤を経て、大きな改良を遂げるた。", "corrected_sentence": "この製品は長い試行錯誤を経て、大きな改良を遂げた。", "error_description": "「遂げた」の活用形が誤り。「遂げるた」は過去形の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遂げて", "is_correct": true, "explanation": "「遂げてきた」の前の形で、「て」の形が正しい。"}, {"text": "遂げれば", "is_correct": false, "explanation": "仮定形は条件を表し、「遂げてきた」の形とは合わない。"}, {"text": "遂げよう", "is_correct": false, "explanation": "意志形は「遂げようとする」の形で、ここには合わない。"}, {"text": "遂げた", "is_correct": false, "explanation": "過去形は「遂げてきた」の前の形にならず、文が続かない。"}], "correct_form": "遂げて", "base_form": "遂げる", "form_label": "て形", "sentence_index": 7, "explanations": {"遂げて": "「遂げてきた」の前の形で、「て」の形が正しい。", "遂げれば": "仮定形は条件を表し、「遂げてきた」の形とは合わない。", "遂げよう": "意志形は「遂げようとする」の形で、ここには合わない。", "遂げた": "過去形は「遂げてきた」の前の形にならず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
