INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52301, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "きれいな金色のことです。", "primary_collocate": null, "pronunciation": "こがねいろ", "ipa": "koɡaneiɾo", "syllable_count": 5, "sentences": [{"text": "秋になると、田んぼ一面が黄金色の稲穂で埋め尽くされる。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "秋[あき]になると、田[た]んぼ一面[いちめん]が黄金色[こがねいろ]の稲穂[いなほ]で埋[う]め尽[つ]くされる。", "sentence_source": "generated"}, {"text": "夕日を受けて、海が黄金色に輝いていた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "夕日[ゆうひ]を受[う]けて、海[うみ]が黄金色[こがねいろ]に輝[かがや]いていた。", "sentence_source": "generated"}, {"text": "黄金色の麦畑が、風に揺れている。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "黄金色[こがねいろ]の麦畑[むぎばたけ]が、風[かぜ]に揺[ゆ]れている。", "sentence_source": "generated"}, {"text": "朝の光が差し込み、教会の屋根が黄金色に見えた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "朝[あさ]の光[ひかり]が差[さ]し込[こ]み、教会[きょうかい]の屋根[やね]が黄金色[こがねいろ]に見[み]えた。", "sentence_source": "generated"}, {"text": "公園の銀杏が黄金色に染まり、多くの人が写真を撮っていた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "公園[こうえん]の銀杏[いちょう]が黄金色[こがねいろ]に染[そ]まり、多[おお]くの人[ひと]が写真[しゃしん]を撮[と]っていた。", "sentence_source": "generated"}, {"text": "彼女は黄金色の髪を風になびかせて歩いていた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は黄金色[こがねいろ]の髪[かみ]を風[かぜ]になびかせて歩[ある]いていた。", "sentence_source": "generated"}, {"text": "月が黄金色に光る夜、私たちは丘に登った。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "月[つき]が黄金色[こがねいろ]に光[ひか]る夜[よる]、私[わたし]たちは丘[おか]に登[のぼ]った。", "sentence_source": "generated"}, {"text": "黄金色の紅葉が山全体を包み、まるで絵のようだった。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "黄金色[こがねいろ]の紅葉[こうよう]が山全体[やまぜんたい]を包[つつ]み、まるで絵[え]のようだった。", "sentence_source": "generated"}, {"text": "夕焼けの空が黄金色になると、子どもたちは家に帰り始めた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "夕焼[ゆや]けの空[そら]が黄金色[こがねいろ]になると、子[こ]どもたちは家[いえ]に帰[かえ]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "黄金色のカーテンが、部屋を明るく見せてくれる。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "黄金色[こがねいろ]のカーテンが、部屋[へや]を明[あか]るく見[み]せてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄金色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "稲穂・夕日・紅葉など自然の風景が見せる、きれいな金色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52301, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黄金色", "is_correct": true, "explanation": "実った稲穂の金色を表し、「黄金色の稲穂で埋め尽くされる」と自然に続く。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色や光を表す語で、稲穂の色としては成り立たない。"}, {"text": "青空", "is_correct": false, "explanation": "晴れた空の色を表し、実った稲穂の色とは合わない。"}, {"text": "霜", "is_correct": false, "explanation": "白い氷の結晶を表し、稲穂の色を示すことができない。"}], "explanations": {"黄金色": "実った稲穂の金色を表し、「黄金色の稲穂で埋め尽くされる」と自然に続く。", "夕焼け": "夕方の空の色や光を表す語で、稲穂の色としては成り立たない。", "青空": "晴れた空の色を表し、実った稲穂の色とは合わない。", "霜": "白い氷の結晶を表し、稲穂の色を示すことができない。"}, "sentence_index": 0, "correct_answer": "黄金色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この腕時計は黄金色の純度が高く、ずっしり重い。", "explanation": "ここは金属の「金」の意味。黄金色は色を表す語なので、純度や重さという金属の性質には使えない。"}, {"text": "風が黄金色の音を立てて、麦畑を吹き抜けた。", "explanation": "黄金色は色を表す語なので、音の響きを表す「音を立てて」とは結びつかない。"}, {"text": "明治の初めは、この町の黄金色の時代だった。", "explanation": "ここは「黄金時代」（最も栄えた時期）の意味。黄金色は色を表すので、時代の評価には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52301, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄金色", "is_correct": true, "explanation": "月が金色に光る様子を表し、「月が黄金色に光る夜」と自然に続く。"}, {"text": "金属", "is_correct": false, "explanation": "素材を指す名詞で、「金属に光る」は月の光の描写として不自然。"}, {"text": "雷光", "is_correct": false, "explanation": "雷の閃光を表し、夜の月の光の質感とは合わない。"}, {"text": "花火", "is_correct": false, "explanation": "夜空に散る火の光を表し、月の光を描く文には合わない。"}], "explanations": {"黄金色": "月が金色に光る様子を表し、「月が黄金色に光る夜」と自然に続く。", "金属": "素材を指す名詞で、「金属に光る」は月の光の描写として不自然。", "雷光": "雷の閃光を表し、夜の月の光の質感とは合わない。", "花火": "夜空に散る火の光を表し、月の光を描く文には合わない。"}, "sentence_index": 6, "correct_answer": "黄金色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋のカーテンは黄金色の厚みで、光をまったく通さない。", "explanation": "黄金色は色の語なので、厚さという嵩の性質は表せない。"}, {"text": "黄金色の香りがして、台所から良い匂いが漂ってきた。", "explanation": "黄金色は色の語なので、香りという嗅覚の性質は表せない。"}, {"text": "夕暮れの部屋は、黄金色の暗さに沈んでいた。", "explanation": "黄金色は明るく輝く色なので、「暗さ」を描く文とは意味が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52301, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖の水面が黄金色を輝いていた。", "corrected_sentence": "湖の水面が黄金色に輝いていた。", "error_description": "「輝く」は「〜に輝く」と続けるので、助詞「を」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52301, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空が黄金色く染まっていた。", "corrected_sentence": "空が黄金色に染まっていた。", "error_description": "「黄金色」は名詞なので、状態を表す「に」で続ける。「く」は形容詞の語尾で、名詞には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
