INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52302, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52302, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "金色に輝く色合い。特に、焼き色や光沢のある黄色を指す。", "primary_collocate": null, "pronunciation": "こがねいろ", "ipa": "koɡaneiɾo", "syllable_count": 5, "sentences": [{"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "黄金色", "complexity_tier": "T4", "furigana": "最終段階[さいしゅうだんかい]のベーキングでは、高温[こうおん]の蒸気[じょうき]と共[とも]に膨張[ぼうちょう]した生地[きじ]が、黄金色[こがねいろ]の硬質[こうしつ]で脆[もろ]いクラストを纏[まと]い、内部[ないぶ]は瑞々[みずみず]しくも弾力[だんりょく]に富[と]んだクラムへと昇華[しょうか]する。", "sentence_source": "mined"}, {"text": "こんがり焼けたパンの表面が、きれいな黄金色になった。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "こんがり焼[や]けたパンの表面[ひょうめん]が、きれいな黄金色[こがねいろ]になった。", "sentence_source": "generated"}, {"text": "天ぷらを黄金色になるまで、じっくり揚げた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "天[てん]ぷらを黄金色[こがねいろ]になるまで、じっくり揚[あ]げた。", "sentence_source": "generated"}, {"text": "黄金色に輝くバターが、フライパンの上で溶けていった。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "黄金色[こがねいろ]に輝[かがや]くバターが、フライパンの上[うえ]で溶[と]けていった。", "sentence_source": "generated"}, {"text": "焼き上がったクッキーは、縁が黄金色に色づいていた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "焼[や]き上[あ]がったクッキーは、縁[ふち]が黄金色[こがねいろ]に色[いろ]づいていた。", "sentence_source": "generated"}, {"text": "卵液を塗ると、パイは黄金色のつやが出る。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "卵液[らんえき]を塗[ぬ]ると、パイは黄金色[こがねいろ]のつやが出[で]る。", "sentence_source": "generated"}, {"text": "玉ねぎを黄金色になるまで炒めて、スープに加えた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "玉[たま]ねぎを黄金色[こがねいろ]になるまで炒[いた]めて、スープに加[くわ]えた。", "sentence_source": "generated"}, {"text": "グラスに注がれたビールは、黄金色に輝いていた。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "グラスに注[そそ]がれたビールは、黄金色[こがねいろ]に輝[かがや]いていた。", "sentence_source": "generated"}, {"text": "蜂蜜は光に透かすと、黄金色につやつやと光って見える。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "蜂蜜[はちみつ]は光[ひかり]に透[す]かすと、黄金色[こがねいろ]につやつやと光[ひか]って見[み]える。", "sentence_source": "generated"}, {"text": "揚げたてのコロッケは、衣が黄金色でとてもおいしそうだった。", "target_word": "黄金色", "complexity_tier": "T3", "furigana": "揚[あ]げたてのコロッケは、衣[ころも]が黄金色[こがねいろ]でとてもおいしそうだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄金色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "パンや揚げ物などの焼き色・光沢のある黄色い色合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: ベーキング (Zipf 1.24), 瑞々しく (Zipf 1.76)','sentence 8 above tier T3: contains vocabulary far above tier T3: 透かす (Zipf 1.59)']::text[], 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52302, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黄金色", "is_correct": true, "explanation": "焼き色や光沢のある黄色を表し、「黄金色の硬質で脆いクラスト」の色として自然に続く。"}, {"text": "雪原", "is_correct": false, "explanation": "広い雪原の景色を表し、クラストの色を形容する語にはならない。"}, {"text": "香ばしさ", "is_correct": false, "explanation": "香りの性質を表す名詞で、クラストの色を示す「〜の硬質で」の形容にはならない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を表す語で、クラストの色を示すことができない。"}], "explanations": {"黄金色": "焼き色や光沢のある黄色を表し、「黄金色の硬質で脆いクラスト」の色として自然に続く。", "雪原": "広い雪原の景色を表し、クラストの色を形容する語にはならない。", "香ばしさ": "香りの性質を表す名詞で、クラストの色を示す「〜の硬質で」の形容にはならない。", "湿気": "空気中の水分を表す語で、クラストの色を示すことができない。"}, "sentence_index": 0, "correct_answer": "黄金色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は黄金色を三キロ買って、家に持ち帰った。", "explanation": "ここは金属の「金」の意味。黄金色は色の名前なので、重さを量る物質には使えない。"}, {"text": "信号が黄金色に変わったので、車は止まった。", "explanation": "ここは「黄色」の意味。信号の色は黄色が自然で、焼き色や光沢を指す黄金色は合わない。"}, {"text": "彼のプレゼンは黄金色の出来だった。", "explanation": "ここは「黄金」（非常に優れている）の意味。「黄金の出来」とは言えるが、色を表す黄金色は出来の良さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52302, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄金色", "is_correct": true, "explanation": "玉ねぎを炒めて得られる金色の焼き色を表し、「黄金色になるまで炒めて」と自然に続く。"}, {"text": "真っ赤", "is_correct": false, "explanation": "赤色を表す語で、玉ねぎを炒めた色の変化としては不自然。"}, {"text": "白濁", "is_correct": false, "explanation": "白く濁った状態を指し、炒めて色づく過程とは合わない。"}, {"text": "漆黒", "is_correct": false, "explanation": "真っ黒を表し、焦げた状態になってしまい、炒め具合の目安にはならない。"}], "explanations": {"黄金色": "玉ねぎを炒めて得られる金色の焼き色を表し、「黄金色になるまで炒めて」と自然に続く。", "真っ赤": "赤色を表す語で、玉ねぎを炒めた色の変化としては不自然。", "白濁": "白く濁った状態を指し、炒めて色づく過程とは合わない。", "漆黒": "真っ黒を表し、焦げた状態になってしまい、炒め具合の目安にはならない。"}, "sentence_index": 6, "correct_answer": "黄金色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "揚げたてのコロッケは、衣が黄金色の大きさで、皿からはみ出すほどだった。", "explanation": "黄金色は色の語なので、大きさという寸法の表現には使えない。"}, {"text": "揚げたてのコロッケは、衣が黄金色のぱりぱりした音を立てて、おいしそうだった。", "explanation": "黄金色は色の語なので、ぱりぱりという音の響きは表せない。"}, {"text": "揚げたてのコロッケは、衣が黄金色の味がして、とても香ばしかった。", "explanation": "黄金色は色の語なので、味という風味の性質は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52302, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パンの表面が黄金色を色づいた。", "corrected_sentence": "パンの表面が黄金色に色づいた。", "error_description": "「色づく」は「〜に色づく」と続けるので、助詞「を」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52302, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホットケーキの表面が黄金色く焼けていた。", "corrected_sentence": "ホットケーキの表面が黄金色に焼けていた。", "error_description": "「黄金色」は名詞なので、状態を表す「に」で続ける。「く」は形容詞の連用形語尾で、名詞には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丈夫な", "is_correct": true, "explanation": "「脆い」の対義語。壊れにくく守りが固いという意味で、壊れやすさと反対になる。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "色の鮮明さを表す語で、物の強さの対義語ではない。"}, {"text": "静かな", "is_correct": false, "explanation": "音や様子の穏やかさを表す語で、壊れやすさとは関係しない。"}, {"text": "豊かな", "is_correct": false, "explanation": "量や内容の多さを表す語で、物の強さの対義語ではない。"}], "correct_answer": "丈夫な", "explanations": {"丈夫な": "「脆い」の対義語。壊れにくく守りが固いという意味で、壊れやすさと反対になる。", "鮮やかな": "色の鮮明さを表す語で、物の強さの対義語ではない。", "静かな": "音や様子の穏やかさを表す語で、壊れやすさとは関係しない。", "豊かな": "量や内容の多さを表す語で、物の強さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丈夫な", "is_correct": true, "explanation": "「脆い」の対義語。壊れにくく守りが固いという意味で、壊れやすさと反対になる。"}, {"text": "滑らかな", "is_correct": false, "explanation": "表面の平らさや手触りを表す語で、物の強さの対義語ではない。"}, {"text": "穏やかな", "is_correct": false, "explanation": "性質や様子の落ち着きを表す語で、壊れやすさとは関係しない。"}, {"text": "賑やかな", "is_correct": false, "explanation": "にぎやかさを表す語で、物の強さの対義語ではない。"}], "correct_answer": "丈夫な", "explanations": {"丈夫な": "「脆い」の対義語。壊れにくく守りが固いという意味で、壊れやすさと反対になる。", "滑らかな": "表面の平らさや手触りを表す語で、物の強さの対義語ではない。", "穏やかな": "性質や様子の落ち着きを表す語で、壊れやすさとは関係しない。", "賑やかな": "にぎやかさを表す語で、物の強さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "こわれやすい。", "primary_collocate": null, "pronunciation": "もろい", "ipa": "moɾoi", "syllable_count": 3, "sentences": [{"text": "湿気を吸ったクラッカーは、脆くなって手で簡単に折れた。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "湿気[しっけ]を吸[す]ったクラッカーは、脆[もろ]くなって手[て]で簡単[かんたん]に折[お]れた。", "sentence_source": "generated"}, {"text": "岩の表面が脆いので、登るときは足場をよく確かめた。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "岩[いわ]の表面[ひょうめん]が脆[もろ]いので、登[のぼ]るときは足場[あしば]をよく確[たし]かめた。", "sentence_source": "generated"}, {"text": "長年使った革のベルトは、脆くなって途中で切れた。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "長年[ながねん]使[つか]った革[かわ]のベルトは、脆[もろ]くなって途中[とちゅう]で切[き]れた。", "sentence_source": "generated"}, {"text": "この陶器は薄くて脆いため、運ぶときは新聞紙で包んだ。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "この陶器[とうき]は薄[うす]くて脆[もろ]いため、運[はこ]ぶときは新聞紙[しんぶんし]で包[つつ]んだ。", "sentence_source": "generated"}, {"text": "白アリに食われた柱は脆くなっていて、触ると崩れた。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "白[しろ]アリに食[く]われた柱[はしら]は脆[もろ]くなっていて、触[さわ]ると崩[くず]れた。", "sentence_source": "generated"}, {"text": "脆い砂の城は、波が来るとすぐに壊れてしまった。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "脆[もろ]い砂[すな]の城[しろ]は、波[なみ]が来[く]るとすぐに壊[こわ]れてしまった。", "sentence_source": "generated"}, {"text": "骨がカルシウム不足で脆くなると、転んだだけで折れやすい。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "骨[ほね]がカルシウム不足[ぶそく]で脆[もろ]くなると、転[ころ]んだだけで折[お]れやすい。", "sentence_source": "generated"}, {"text": "彼らの友情は、小さな誤解で崩れるほど脆かった。", "target_word": "脆かった", "complexity_tier": "T3", "furigana": "彼[かれ]らの友情[ゆうじょう]は、小[ちい]さな誤解[ごかい]で崩[くず]れるほど脆[もろ]かった。", "sentence_source": "generated"}, {"text": "守りが脆いチームは、強い相手に何点も取られた。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "守[まも]りが脆[もろ]いチームは、強[つよ]い相手[あいて]に何点[なんてん]も取[と]られた。", "sentence_source": "generated"}, {"text": "この古い壁は脆いから、釘を打たないでください。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "この古[ふる]い壁[かべ]は脆[もろ]いから、釘[くぎ]を打[う]たないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脆い", "label": "終止形"}, {"form": "脆く", "label": "連用形"}, {"form": "脆かった", "label": "過去形"}, {"form": "脆ければ", "label": "仮定形"}, {"form": "脆さ", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "壊れやすい。物や関係・守りなどが弱く、すぐ折れたり崩れたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆く", "is_correct": true, "explanation": "「脆くなって」と状態の変化を表し、折れやすさの説明として自然に続く。"}, {"text": "甘く", "is_correct": false, "explanation": "味を表す語で、乾いたクラッカーの状態変化には合わない。"}, {"text": "熱く", "is_correct": false, "explanation": "温度を表す語で、湿気による状態変化とは合わない。"}, {"text": "眠く", "is_correct": false, "explanation": "人の感覚を表す語で、クラッカーの状態には使えない。"}], "explanations": {"脆く": "「脆くなって」と状態の変化を表し、折れやすさの説明として自然に続く。", "甘く": "味を表す語で、乾いたクラッカーの状態変化には合わない。", "熱く": "温度を表す語で、湿気による状態変化とは合わない。", "眠く": "人の感覚を表す語で、クラッカーの状態には使えない。"}, "sentence_index": 0, "correct_answer": "脆く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この靴は脆い履き心地で、一日中歩いても疲れない。", "explanation": "脆いは壊れやすさを表す語なので、着け心地の表現には使えない。"}, {"text": "この部屋は脆い色で、とても落ち着く。", "explanation": "脆いは壊れやすさを表す語なので、色の描写には使えない。"}, {"text": "このスープは脆い味がして、とても飲みやすい。", "explanation": "脆いは壊れやすさを表す語なので、味の描写には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆く", "is_correct": true, "explanation": "「脆くなると」と状態の変化を表し、骨が折れやすくなる説明として自然に続く。"}, {"text": "辛く", "is_correct": false, "explanation": "味や感覚を表す語で、骨の状態変化には合わない。"}, {"text": "煙く", "is_correct": false, "explanation": "煙が充満する様子を表し、骨の状態を表せない。"}, {"text": "眩しく", "is_correct": false, "explanation": "光の強さを表す語で、骨の状態変化には使えない。"}], "explanations": {"脆く": "「脆くなると」と状態の変化を表し、骨が折れやすくなる説明として自然に続く。", "辛く": "味や感覚を表す語で、骨の状態変化には合わない。", "煙く": "煙が充満する様子を表し、骨の状態を表せない。", "眩しく": "光の強さを表す語で、骨の状態変化には使えない。"}, "sentence_index": 6, "correct_answer": "脆く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古い壁は脆い香りがして、懐かしい気持ちになる。", "explanation": "脆いは壊れやすさを表す語なので、香りの描写には使えない。"}, {"text": "この古い壁は脆い重さなので、一人でも簡単に動かせる。", "explanation": "脆いは壊れやすさを表す語なので、重さの表現には使えない。"}, {"text": "この古い壁は脆い高さで、子どもでも登れる。", "explanation": "脆いは壊れやすさを表す語なので、高さの表現には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨で濡れた段ボールは脆いくなり、重い荷物で破れた。", "corrected_sentence": "雨で濡れた段ボールは脆くなり、重い荷物で破れた。", "error_description": "「脆い」の連用形は「脆く」。「脆いく」は活用の誤りで、「なり」に続けるには語幹に「く」を付ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脆い", "is_correct": true, "explanation": "終止形で、理由を述べる「ので」の前に置く形。文の形に合う。"}, {"text": "脆く", "is_correct": false, "explanation": "連用形で、「ので」の前に置くと文が続かない。"}, {"text": "脆かった", "is_correct": false, "explanation": "過去形で、現在の状態を理由として述べる文には合わない。"}, {"text": "脆ければ", "is_correct": false, "explanation": "仮定形で「〜なら」の意味になり、「ので」の理由とは合わない。"}], "correct_form": "脆い", "base_form": "脆い", "form_label": "終止形", "sentence_index": 1, "explanations": {"脆い": "終止形で、理由を述べる「ので」の前に置く形。文の形に合う。", "脆く": "連用形で、「ので」の前に置くと文が続かない。", "脆かった": "過去形で、現在の状態を理由として述べる文には合わない。", "脆ければ": "仮定形で「〜なら」の意味になり、「ので」の理由とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52303, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で傷んだ壁は脆くが、ひびが入った。", "corrected_sentence": "雨で傷んだ壁は脆くなって、ひびが入った。", "error_description": "「脆く」に「が」は続かない。状態の変化を表す「なって」で続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脆かった", "is_correct": true, "explanation": "過去形で、友情が崩れやすかったという過去の状態を表す。"}, {"text": "脆ければ", "is_correct": false, "explanation": "仮定形で文が終わらず、「崩れるほど脆かった」の述語として成立しない。"}, {"text": "脆さ", "is_correct": false, "explanation": "名詞形で、「ほど脆かった」の形にならない。"}, {"text": "脆くない", "is_correct": false, "explanation": "否定形で、崩れるほどという文意と逆になる。"}], "correct_form": "脆かった", "base_form": "脆い", "form_label": "過去形", "sentence_index": 7, "explanations": {"脆かった": "過去形で、友情が崩れやすかったという過去の状態を表す。", "脆ければ": "仮定形で文が終わらず、「崩れるほど脆かった」の述語として成立しない。", "脆さ": "名詞形で、「ほど脆かった」の形にならない。", "脆くない": "否定形で、崩れるほどという文意と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丈夫な", "is_correct": true, "explanation": "「脆い」の対義語。力で壊れにくいという意味で、欠けやすさと反対になる。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "色の鮮明さを表す語で、物の強さの対義語ではない。"}, {"text": "静かな", "is_correct": false, "explanation": "音や様子の穏やかさを表す語で、壊れやすさとは関係しない。"}, {"text": "豊かな", "is_correct": false, "explanation": "量や内容の多さを表す語で、物の強さの対義語ではない。"}], "correct_answer": "丈夫な", "explanations": {"丈夫な": "「脆い」の対義語。力で壊れにくいという意味で、欠けやすさと反対になる。", "鮮やかな": "色の鮮明さを表す語で、物の強さの対義語ではない。", "静かな": "音や様子の穏やかさを表す語で、壊れやすさとは関係しない。", "豊かな": "量や内容の多さを表す語で、物の強さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丈夫な", "is_correct": true, "explanation": "「脆い」の対義語。力で壊れにくいという意味で、欠けやすさと反対になる。"}, {"text": "滑らかな", "is_correct": false, "explanation": "表面の平らさや手触りを表す語で、物の強さの対義語ではない。"}, {"text": "穏やかな", "is_correct": false, "explanation": "性質や様子の落ち着きを表す語で、壊れやすさとは関係しない。"}, {"text": "賑やかな", "is_correct": false, "explanation": "にぎやかさを表す語で、物の強さの対義語ではない。"}], "correct_answer": "丈夫な", "explanations": {"丈夫な": "「脆い」の対義語。力で壊れにくいという意味で、欠けやすさと反対になる。", "滑らかな": "表面の平らさや手触りを表す語で、物の強さの対義語ではない。", "穏やかな": "性質や様子の落ち着きを表す語で、壊れやすさとは関係しない。", "賑やかな": "にぎやかさを表す語で、物の強さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物が壊れやすく、少しの力で割れたり欠けたりする様子。", "primary_collocate": null, "pronunciation": "もろい", "ipa": "moɾoi", "syllable_count": 3, "sentences": [{"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "脆い", "complexity_tier": "T4", "furigana": "最終段階[さいしゅうだんかい]のベーキングでは、高温[こうおん]の蒸気[じょうき]と共[とも]に膨張[ぼうちょう]した生地[きじ]が、黄金色[こがねいろ]の硬質[こうしつ]で脆[もろ]いクラストを纏[まと]い、内部[ないぶ]は瑞々[みずみず]しくも弾力[だんりょく]に富[と]んだクラムへと昇華[しょうか]する。", "sentence_source": "mined"}, {"text": "このクッキーは脆いので、袋の中で割れてしまった。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "このクッキーは脆[もろ]いので、袋[ふくろ]の中[なか]で割[わ]れてしまった。", "sentence_source": "generated"}, {"text": "古い橋の板が脆くなっていて、渡るのが怖かった。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]の板[いた]が脆[もろ]くなっていて、渡[わた]るのが怖[こわ]かった。", "sentence_source": "generated"}, {"text": "氷は薄くて脆いから、湖の上に乗ってはいけない。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "氷[こおり]は薄[うす]くて脆[もろ]いから、湖[みずうみ]の上[うえ]に乗[の]ってはいけない。", "sentence_source": "generated"}, {"text": "石灰岩は水に溶けやすく、雨風で脆くなる。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "石灰岩[せっかいがん]は水[みず]に溶[と]けやすく、雨風[あめかぜ]で脆[もろ]くなる。", "sentence_source": "generated"}, {"text": "錆びた鉄の柵は、軽くたたいただけで脆く崩れた。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "錆[さ]びた鉄[てつ]の柵[さく]は、軽[かる]くたたいただけで脆[もろ]く崩[くず]れた。", "sentence_source": "generated"}, {"text": "このガラスの器は脆いので、洗うときは気をつけてください。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "このガラスの器[うつわ]は脆[もろ]いので、洗[あら]うときは気[き]をつけてください。", "sentence_source": "generated"}, {"text": "乾燥した古い紙は脆く、ページをめくると端が欠けた。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した古[ふる]い紙[かみ]は脆[もろ]く、ページをめくると端[はし]が欠[か]けた。", "sentence_source": "generated"}, {"text": "この古いレンガは脆いので、少し触れただけで角が欠けた。", "target_word": "脆い", "complexity_tier": "T3", "furigana": "この古[ふる]いレンガは脆[もろ]いので、少[すこ]し触[ふ]れただけで角[かど]が欠[か]けた。", "sentence_source": "generated"}, {"text": "焼きすぎたせんべいは、とても脆くて持つだけで欠けた。", "target_word": "脆く", "complexity_tier": "T3", "furigana": "焼[や]きすぎたせんべいは、とても脆[もろ]くて持[も]つだけで欠[か]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脆い", "label": "終止形"}, {"form": "脆く", "label": "連用形"}, {"form": "脆かった", "label": "過去形"}, {"form": "脆ければ", "label": "仮定形"}, {"form": "脆さ", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "物の質が弱く、少しの力で割れたり欠けたり崩れたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: ベーキング (Zipf 1.24)']::text[], 'dcb31bdc-ef84-4a4d-bd56-38dfa664ed53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆い", "is_correct": true, "explanation": "クラストの割れやすい質感を表し、「硬質で脆いクラスト」と自然に続く。"}, {"text": "柔らかい", "is_correct": false, "explanation": "「硬質で」と矛盾する質感を表し、文脈に合わない。"}, {"text": "甘い", "is_correct": false, "explanation": "味を表す語で、クラストの質感の形容には使えない。"}, {"text": "眩しい", "is_correct": false, "explanation": "光の強さを表す語で、クラストの質感には合わない。"}], "explanations": {"脆い": "クラストの割れやすい質感を表し、「硬質で脆いクラスト」と自然に続く。", "柔らかい": "「硬質で」と矛盾する質感を表し、文脈に合わない。", "甘い": "味を表す語で、クラストの質感の形容には使えない。", "眩しい": "光の強さを表す語で、クラストの質感には合わない。"}, "sentence_index": 0, "correct_answer": "脆い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは脆い温度で、ふうふうしないと飲めない。", "explanation": "脆いは壊れやすさを表す語なので、温度の表現には使えない。"}, {"text": "このカレーは脆い味がして、とても食べやすい。", "explanation": "脆いは壊れやすさを表す語なので、味の描写には使えない。"}, {"text": "この塔は脆い高さで、街のどこからも見える。", "explanation": "脆いは壊れやすさを表す語なので、高さの表現には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆い", "is_correct": true, "explanation": "ガラスが割れやすく注意が要る理由になり、「脆いので気をつけて」と自然に続く。"}, {"text": "辛い", "is_correct": false, "explanation": "味や辛さを表す語で、器の性質を理由にできない。"}, {"text": "眠い", "is_correct": false, "explanation": "人の状態を表す語で、器の性質には使えない。"}, {"text": "煙い", "is_correct": false, "explanation": "煙が充満する様子を表し、ガラスの器の性質には合わない。"}], "explanations": {"脆い": "ガラスが割れやすく注意が要る理由になり、「脆いので気をつけて」と自然に続く。", "辛い": "味や辛さを表す語で、器の性質を理由にできない。", "眠い": "人の状態を表す語で、器の性質には使えない。", "煙い": "煙が充満する様子を表し、ガラスの器の性質には合わない。"}, "sentence_index": 6, "correct_answer": "脆い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "焼きすぎたせんべいは脆い色をしていて、とても香ばしい。", "explanation": "脆いは壊れやすさを表す語なので、色の描写には使えない。"}, {"text": "焼きすぎたせんべいは、脆い速さで冷めていった。", "explanation": "脆いは壊れやすさを表す語なので、速さの表現には使えない。"}, {"text": "焼きすぎたせんべいは脆い重さで、一枚でもずっしり感じた。", "explanation": "脆いは壊れやすさを表す語なので、重さの表現には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この板は脆さので、踏むと割れた。", "corrected_sentence": "この板は脆いので、踏むと割れた。", "error_description": "「脆さ」は名詞形で、理由の「ので」には続かない。形容詞の終止形「脆い」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脆い", "is_correct": true, "explanation": "終止形で、理由を述べる「ので」の前に置く形。文の形に合う。"}, {"text": "脆く", "is_correct": false, "explanation": "連用形で、「ので」の前に置くと文が続かない。"}, {"text": "脆かった", "is_correct": false, "explanation": "過去形で、現在の状態を理由として述べる文には合わない。"}, {"text": "脆ければ", "is_correct": false, "explanation": "仮定形で「〜なら」の意味になり、「ので」の理由とは合わない。"}], "correct_form": "脆い", "base_form": "脆い", "form_label": "終止形", "sentence_index": 1, "explanations": {"脆い": "終止形で、理由を述べる「ので」の前に置く形。文の形に合う。", "脆く": "連用形で、「ので」の前に置くと文が続かない。", "脆かった": "過去形で、現在の状態を理由として述べる文には合わない。", "脆ければ": "仮定形で「〜なら」の意味になり、「ので」の理由とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52304, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乾燥した紙は脆に崩れて、ページの端が欠けた。", "corrected_sentence": "乾燥した紙は脆く崩れて、ページの端が欠けた。", "error_description": "形容詞「脆い」の連用形は「脆く」。「脆に」は形容詞に「に」を付けた誤りで、続く動詞「崩れて」には連用形の「脆く」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脆く", "is_correct": true, "explanation": "連用形で、読点で後続の文に続けて状態を述べる形。"}, {"text": "脆い", "is_correct": false, "explanation": "終止形のままでは「、」で続けられず、中止の形が必要。"}, {"text": "脆さ", "is_correct": false, "explanation": "名詞形で、述語として文を続けることができない。"}, {"text": "脆くない", "is_correct": false, "explanation": "否定形で、欠けたという文の内容と逆の状態になってしまう。"}], "correct_form": "脆く", "base_form": "脆い", "form_label": "連用形", "sentence_index": 7, "explanations": {"脆く": "連用形で、読点で後続の文に続けて状態を述べる形。", "脆い": "終止形のままでは「、」で続けられず、中止の形が必要。", "脆さ": "名詞形で、述語として文を続けることができない。", "脆くない": "否定形で、欠けたという文の内容と逆の状態になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d055cc-4066-4021-8115-b24d618c945b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
