INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52306, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物質がかたくて丈夫な性質。また、そのようなさま。", "primary_collocate": null, "pronunciation": "こうしつ", "ipa": "koːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "硬質", "complexity_tier": "T4", "furigana": "最終[さいしゅう]段階[だんかい]のベーキングでは、高温[こうおん]の蒸気[じょうき]と共[とも]に膨張[ぼうちょう]した生地[きじ]が、黄金色[こがねいろ]の硬質[こうしつ]で脆[もろ]いクラストを纏[まと]い、内部[ないぶ]は瑞々[みずみず]しくも弾力[だんりょく]に富[と]んだクラムへと昇華[しょうか]する。", "sentence_source": "mined"}, {"text": "このヘルメットは硬質なプラスチックでできているので、落下物から頭をしっかり守ってくれる。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "このヘルメットは硬質[こうしつ]なプラスチックでできているので、落下物[らっかぶつ]から頭[あたま]をしっかり守[まも]ってくれる。", "sentence_source": "generated"}, {"text": "硬質な岩盤だったため、トンネルの掘削には予想以上の時間がかかった。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "硬質[こうしつ]な岩盤[がんばん]だったため、トンネルの掘削[くっさく]には予想[よそう]以上[いじょう]の時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "彼女は旅行中に壊れにくいように、硬質な素材のスーツケースを選んだ。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は旅行中[りょこうちゅう]に壊[こわ]れにくいように、硬質[こうしつ]な素材[そざい]のスーツケースを選[えら]んだ。", "sentence_source": "generated"}, {"text": "この床材は硬質で傷がつきにくいので、事務所や工場でよく使われている。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "この床材[ゆかざい]は硬質[こうしつ]で傷[きず]がつきにくいので、事務所[じむしょ]や工場[こうじょう]でよく使[つか]われている。", "sentence_source": "generated"}, {"text": "硬質な木材は加工が難しいが、家具にすると何十年も使える。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "硬質[こうしつ]な木材[もくざい]は加工[かこう]が難[むずか]しいが、家具[かぐ]にすると何十年[なんじゅうねん]も使[つか]える。", "sentence_source": "generated"}, {"text": "包丁の刃には硬質の鋼が使われており、切れ味が長持ちする。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "包丁[ほうちょう]の刃[は]には硬質[こうしつ]の鋼[はがね]が使[つか]われており、切[き]れ味[あじ]が長持[ながも]ちする。", "sentence_source": "generated"}, {"text": "この作業靴は硬質な素材の中底が入っていて、釘を踏んでも足を守ってくれる。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "この作業靴[さぎょうぐつ]は硬質[こうしつ]な素材[そざい]の中底[なかぞこ]が入[はい]っていて、釘[くぎ]を踏[ふ]んでも足[あし]を守[まも]ってくれる。", "sentence_source": "generated"}, {"text": "硬質な殻に覆われたカニは、外敵から身を守ることができる。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "硬質[こうしつ]な殻[から]に覆[おお]われたカニは、外敵[がいてき]から身[み]を守[まも]ることができる。", "sentence_source": "generated"}, {"text": "工事現場では、柔らかい土と違って硬質な地盤の上に建物を建てるほうが安全だ。", "target_word": "硬質", "complexity_tier": "T3", "furigana": "工事[こうじ]現場[げんば]では、柔[やわ]らかい土[つち]と違[ちが]って硬質[こうしつ]な地盤[じばん]の上[うえ]に建物[たてもの]を建[た]てるほうが安全[あんぜん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬質", "label": "基本形"}, {"form": "硬質な", "label": "連体形"}, {"form": "硬質で", "label": "連用形"}, {"form": "硬質の", "label": "名詞修飾形"}], "register": "neutral", "sense_fingerprint": "物質がかたく丈夫であるという性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52306, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硬質", "is_correct": true, "explanation": "「黄金色の硬質で脆い」の位置に入り、材質のかたさを表す語。"}, {"text": "蒸気", "is_correct": false, "explanation": "蒸気は気体で、「黄金色の蒸気で脆い」ではクラストの質感を表せない。"}, {"text": "膨張", "is_correct": false, "explanation": "膨張は体積が大きくなる現象で、「黄金色の膨張で脆い」は意味が通らない。"}, {"text": "弾力", "is_correct": false, "explanation": "弾力は押すと戻る力で、直後の「脆い」と性質が逆になるため合わない。"}], "explanations": {"硬質": "「黄金色の硬質で脆い」の位置に入り、材質のかたさを表す語。", "蒸気": "蒸気は気体で、「黄金色の蒸気で脆い」ではクラストの質感を表せない。", "膨張": "膨張は体積が大きくなる現象で、「黄金色の膨張で脆い」は意味が通らない。", "弾力": "弾力は押すと戻る力で、直後の「脆い」と性質が逆になるため合わない。"}, "sentence_index": 0, "correct_answer": "硬質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鍋は硬質が高いので、強火で炒めても傷がつきにくい。", "explanation": "ここは〈硬度〉の意味。硬質は材質の性質そのものを指し、かたさの程度を言うなら硬度を使う。「硬質が高い」とは言わない。"}, {"text": "この橋は硬質が十分にあるので、大型トラックが通っても安全だ。", "explanation": "ここは〈強度〉の意味。荷重に耐える力は強度で表す。硬質は材料の性質なので「硬質が十分にある」とは言わない。"}, {"text": "このパンは硬質で、そのままでは食べられない。", "explanation": "ここは〈硬い（食べ物が堅くなる）〉の意味。パンなど食べ物の食感には「硬い」を使い、硬質は素材そのものの性質（かたくて丈夫）を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52306, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬質", "is_correct": true, "explanation": "「硬質の鋼」で、鋼の材質のかたさを表す語。"}, {"text": "錆", "is_correct": false, "explanation": "錆は鉄が酸化したもので、「錆の鋼」では材質の説明にならない。"}, {"text": "研磨", "is_correct": false, "explanation": "研磨は磨く作業のことで、「研磨の鋼」では鋼の性質を表せない。"}, {"text": "切れ味", "is_correct": false, "explanation": "切れ味は切れる度合いで、「切れ味の鋼」は鋼の性質の説明にならない。"}], "explanations": {"硬質": "「硬質の鋼」で、鋼の材質のかたさを表す語。", "錆": "錆は鉄が酸化したもので、「錆の鋼」では材質の説明にならない。", "研磨": "研磨は磨く作業のことで、「研磨の鋼」では鋼の性質を表せない。", "切れ味": "切れ味は切れる度合いで、「切れ味の鋼」は鋼の性質の説明にならない。"}, "sentence_index": 6, "correct_answer": "硬質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鋼は硬質が強く、衝撃を受けても折れにくい。", "explanation": "ここは〈靭性〉（粘り強さ）の意味。衝撃に耐える粘り強さは靭性で表し、硬質（かたさ）とは別の性質なので合わない。"}, {"text": "この車は車体の硬質を高めたため、カーブでもボディが歪みにくい。", "explanation": "ここは〈剛性〉（構造の変形しにくさ）の意味。構造全体の変形しにくさは剛性で言い、硬質は材料そのものの性質を指す。"}, {"text": "寒さで指が硬質になって、ボタンがうまく留められなかった。", "explanation": "ここは〈硬直〉（体の一部がこわばって動かない）の意味。人の指の状態には硬質を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52306, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この作業台は硬質に鋼板でできていて、重い工具を置いても歪みにくい。", "corrected_sentence": "この作業台は硬質の鋼板でできていて、重い工具を置いても歪みにくい。", "error_description": "「硬質」は名詞を修飾する形が「硬質の」（または「硬質な」）。「硬質に」は連用形で、直後の名詞「鋼板」を修飾できないので誤り。「硬質の鋼板」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52306, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この箱は硬質を丈夫な素材で作られていて、倉庫での積み重ねにも耐える。", "corrected_sentence": "この箱は硬質で丈夫な素材で作られていて、倉庫での積み重ねにも耐える。", "error_description": "「硬質」は形容動詞で、格助詞「を」は続かない。「丈夫な」へ続けるには連用形「硬質で」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣る", "is_correct": true, "explanation": "〈優れる〉の対義語で、能力や品質が低い水準にあること。"}, {"text": "勝る", "is_correct": false, "explanation": "〈優れる〉に近い意味の語で、対義語ではない。"}, {"text": "上回る", "is_correct": false, "explanation": "数量や基準を超えることを表し、対義語ではない。"}, {"text": "秀でる", "is_correct": false, "explanation": "〈優れる〉の類義語で、対義語ではない。"}], "correct_answer": "劣る", "explanations": {"劣る": "〈優れる〉の対義語で、能力や品質が低い水準にあること。", "勝る": "〈優れる〉に近い意味の語で、対義語ではない。", "上回る": "数量や基準を超えることを表し、対義語ではない。", "秀でる": "〈優れる〉の類義語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣る", "is_correct": true, "explanation": "〈優れる〉の対義語で、能力や品質が低い水準にあること。"}, {"text": "凌ぐ", "is_correct": false, "explanation": "相手を上回るという意味の語で、対義語ではない。"}, {"text": "抜く", "is_correct": false, "explanation": "前に出て追い越すという意味の語で、対義語ではない。"}, {"text": "匹敵する", "is_correct": false, "explanation": "同等の水準にあることを表し、対義語ではない。"}], "correct_answer": "劣る", "explanations": {"劣る": "〈優れる〉の対義語で、能力や品質が低い水準にあること。", "凌ぐ": "相手を上回るという意味の語で、対義語ではない。", "抜く": "前に出て追い越すという意味の語で、対義語ではない。", "匹敵する": "同等の水準にあることを表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "「優れる」は、ほかのものより上手だったり、いいことだという意味です。", "primary_collocate": null, "pronunciation": "すぐれる", "ipa": "sɯɡɯɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "兄は絵が上手で、美術の成績が友だちより優れている。", "target_word": "優れている", "complexity_tier": "T3", "furigana": "兄[あに]は絵[え]が上手[じょうず]で、美術[びじゅつ]の成績[せいせき]が友[とも]だちより優[すぐ]れている。", "sentence_source": "generated"}, {"text": "このパン屋のパンは味が優れていると評判で、朝から行列ができる。", "target_word": "優れている", "complexity_tier": "T3", "furigana": "このパン屋[や]のパンは味[あじ]が優[すぐ]れていると評判[ひょうばん]で、朝[あさ]から行列[ぎょうれつ]ができる。", "sentence_source": "generated"}, {"text": "優れた先生に出会えて、私は数学がとても好きになった。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "優[すぐ]れた先生[せんせい]に出会[であ]えて、私[わたし]は数学[すうがく]がとても好[す]きになった。", "sentence_source": "generated"}, {"text": "体力に優れた人でも、無理をすれば病気になることがある。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "体力[たいりょく]に優[すぐ]れた人[ひと]でも、無理[むり]をすれば病気[びょうき]になることがある。", "sentence_source": "generated"}, {"text": "彼女の歌声は、ほかの出場者よりずっと優れていた。", "target_word": "優れていた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌声[うたごえ]は、ほかの出場者[しゅつじょうしゃ]よりずっと優[すぐ]れていた。", "sentence_source": "generated"}, {"text": "優れた作品を読むと、自分も何か書いてみたくなる。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "優[すぐ]れた作品[さくひん]を読[よ]むと、自分[じぶん]も何[なに]か書[か]いてみたくなる。", "sentence_source": "generated"}, {"text": "この辞書は説明がわかりやすくて、ほかの辞書より優れている。", "target_word": "優れている", "complexity_tier": "T3", "furigana": "この辞書[じしょ]は説明[せつめい]がわかりやすくて、ほかの辞書[じしょ]より優[すぐ]れている。", "sentence_source": "generated"}, {"text": "足の速さに優れている彼が、リレーのアンカーに選ばれた。", "target_word": "優れている", "complexity_tier": "T3", "furigana": "足[あし]の速[はや]さに優[すぐ]れている彼[かれ]が、リレーのアンカーに選[えら]ばれた。", "sentence_source": "generated"}, {"text": "姉は料理の腕に優れ、友だちを呼ぶといつも感心される。", "target_word": "優れ", "complexity_tier": "T3", "furigana": "姉[あね]は料理[りょうり]の腕[うで]に優[すぐ]れ、友[とも]だちを呼[よ]ぶといつも感心[かんしん]される。", "sentence_source": "generated"}, {"text": "値段は高いが、機能に優れたこのカメラを買って満足している。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "値段[ねだん]は高[たか]いが、機能[きのう]に優[すぐ]れたこのカメラを買[か]って満足[まんぞく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "優れる", "label": "終止形"}, {"form": "優れた", "label": "過去形"}, {"form": "優れて", "label": "て形"}, {"form": "優れない", "label": "ない形"}, {"form": "優れれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ほかより上手だったり、よかったりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "優れている", "is_correct": true, "explanation": "述語として『友だちより優れている』と続き、比べて上であることを表す。"}, {"text": "優れさせる", "is_correct": false, "explanation": "使役形で目的語が必要になり、この文の述語にはならない。"}, {"text": "優れて", "is_correct": false, "explanation": "連用形で文を終えられず、『友だちより優れて。』は不自然。"}, {"text": "優れれば", "is_correct": false, "explanation": "仮定形で条件節になり、文の述語にならない。"}], "explanations": {"優れている": "述語として『友だちより優れている』と続き、比べて上であることを表す。", "優れさせる": "使役形で目的語が必要になり、この文の述語にはならない。", "優れて": "連用形で文を終えられず、『友だちより優れて。』は不自然。", "優れれば": "仮定形で条件節になり、文の述語にならない。"}, "sentence_index": 0, "correct_answer": "優れている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝不足で、今朝は冷蔵庫の中身が優れた。", "explanation": "ここは〈増える〉の意味。優れるは質の高さを表すので、中身の量が増えることは表せない。"}, {"text": "今年の売上は目標に優れた。", "explanation": "ここは〈目標を上回る〉の意味。優れるは質の高さを表し、数字の目標を超える意味では使わない。"}, {"text": "この店は在庫が優れた。", "explanation": "ここは〈在庫が増える〉の意味。優れるは質の高さを表し、数の増加は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "優れている", "is_correct": true, "explanation": "『ほかの辞書より優れている』と続き、比較して上であることを表す。"}, {"text": "優れ", "is_correct": false, "explanation": "連用形は文末に置けず、『ほかの辞書より優れ。』では文が終わらない。"}, {"text": "優れよう", "is_correct": false, "explanation": "意志・推量の形で文の述語にはならず、不自然。"}, {"text": "優れさせる", "is_correct": false, "explanation": "使役形で目的語が必要になり、この文には入らない。"}], "explanations": {"優れている": "『ほかの辞書より優れている』と続き、比較して上であることを表す。", "優れ": "連用形は文末に置けず、『ほかの辞書より優れ。』では文が終わらない。", "優れよう": "意志・推量の形で文の述語にはならず、不自然。", "優れさせる": "使役形で目的語が必要になり、この文には入らない。"}, "sentence_index": 6, "correct_answer": "優れている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このカメラは年式が優れている。", "explanation": "ここは〈古い〉の意味。優れるは質の高さを表し、製造からの年数には使わない。"}, {"text": "このカメラは値段が優れている。", "explanation": "ここは〈値段が高い〉の意味。値段の高低は優れるでは表せない。"}, {"text": "このカメラは重さが優れている。", "explanation": "ここは〈重い〉の意味。重さの大小は優れるでは表せず、〈重い〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は絵に優れるで、友だちより上手だ。", "corrected_sentence": "兄は絵に優れていて、友だちより上手だ。", "error_description": "『優れる』の終止形に『で』が続いて文法的に誤り。状態を述べる『優れていて』の形が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "優れている", "is_correct": true, "explanation": "『味が優れていると評判』と続き、状態を述べる形として正しい。"}, {"text": "優れさせる", "is_correct": false, "explanation": "使役形で、「味が優れさせると評判」は成り立たない。"}, {"text": "優れて", "is_correct": false, "explanation": "連用形で、『味が優れて、と評判』とは続けられない。"}, {"text": "優れれば", "is_correct": false, "explanation": "仮定形で、『味が優れれば評判』は意味が通らない。"}], "correct_form": "優れている", "base_form": "優れる", "form_label": "ている形", "sentence_index": 1, "explanations": {"優れている": "『味が優れていると評判』と続き、状態を述べる形として正しい。", "優れさせる": "使役形で、「味が優れさせると評判」は成り立たない。", "優れて": "連用形で、『味が優れて、と評判』とは続けられない。", "優れれば": "仮定形で、『味が優れれば評判』は意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52307, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このカメラは機能を優れていて、初心者でも扱いやすい。", "corrected_sentence": "このカメラは機能に優れていて、初心者でも扱いやすい。", "error_description": "『優れる』は『〜に優れる』の形で助詞『に』を取る。『を』は誤りで、正しくは『に』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "優れている", "is_correct": true, "explanation": "『足の速さに優れている彼が』と続き、状態を述べて名詞を修飾する形として正しい。"}, {"text": "優れ", "is_correct": false, "explanation": "連用形は『〜彼が』に直接続かず、文の流れが成り立たない。"}, {"text": "優れよう", "is_correct": false, "explanation": "意志・推量の形で、ここでは文として続かない。"}, {"text": "優れさせる", "is_correct": false, "explanation": "使役形で、『足の速さに優れさせる彼』は成り立たない。"}], "correct_form": "優れている", "base_form": "優れる", "form_label": "ている形", "sentence_index": 7, "explanations": {"優れている": "『足の速さに優れている彼が』と続き、状態を述べて名詞を修飾する形として正しい。", "優れ": "連用形は『〜彼が』に直接続かず、文の流れが成り立たない。", "優れよう": "意志・推量の形で、ここでは文として続かない。", "優れさせる": "使役形で、『足の速さに優れさせる彼』は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣る", "is_correct": true, "explanation": "〈優れる〉の対義語で、能力や品質が低い水準にあること。"}, {"text": "勝る", "is_correct": false, "explanation": "〈優れる〉に近い意味の語で、対義語ではない。"}, {"text": "上回る", "is_correct": false, "explanation": "数量や基準を超えることを表し、対義語ではない。"}, {"text": "秀でる", "is_correct": false, "explanation": "〈優れる〉の類義語で、対義語ではない。"}], "correct_answer": "劣る", "explanations": {"劣る": "〈優れる〉の対義語で、能力や品質が低い水準にあること。", "勝る": "〈優れる〉に近い意味の語で、対義語ではない。", "上回る": "数量や基準を超えることを表し、対義語ではない。", "秀でる": "〈優れる〉の類義語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "劣る", "is_correct": true, "explanation": "〈優れる〉の対義語で、質や能力が低い水準にあること。"}, {"text": "凌ぐ", "is_correct": false, "explanation": "相手を上回るという意味の語で、対義語ではない。"}, {"text": "抜く", "is_correct": false, "explanation": "前に出て追い越すという意味の語で、対義語ではない。"}, {"text": "匹敵する", "is_correct": false, "explanation": "同等の水準にあることを表し、対義語ではない。"}], "correct_answer": "劣る", "explanations": {"劣る": "〈優れる〉の対義語で、質や能力が低い水準にあること。", "凌ぐ": "相手を上回るという意味の語で、対義語ではない。", "抜く": "前に出て追い越すという意味の語で、対義語ではない。", "匹敵する": "同等の水準にあることを表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "「優れる」は、能力や品質などが、他のものより高い水準にあることを表す動詞です。", "primary_collocate": null, "pronunciation": "すぐれる", "ipa": "sɯɡɯɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "優れた", "complexity_tier": "T4", "furigana": "その後[そのあと]、長時間[ちょうじかん]にわたる低温[ていおん]発酵[はっこう]を経[へ]ることで、グルテンの網目[あみめ]は緻密[ちみつ]さを増[ま]し、消化[しょうか]吸収[きゅうしゅう]にも優[すぐ]れた変容[へんよう]を遂[と]げる。", "sentence_source": "mined"}, {"text": "彼は語学の才能に優れ、三年で五つの言語を話せるようになった。", "target_word": "優れ", "complexity_tier": "T3", "furigana": "彼[かれ]は語学[ごがく]の才能[さいのう]に優[すぐ]れ、三年[さんねん]で五[いつ]つの言語[げんご]を話[はな]せるようになった。", "sentence_source": "generated"}, {"text": "この製品は耐久性に優れているため、屋外でも長く使える。", "target_word": "優れている", "complexity_tier": "T3", "furigana": "この製品[せいひん]は耐久性[たいきゅうせい]に優[すぐ]れているため、屋外[おくがい]でも長[なが]く使[つか]える。", "sentence_source": "generated"}, {"text": "優れた指導者は、部下の意見に耳を傾けることを忘れない。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "優[すぐ]れた指導者[しどうしゃ]は、部下[ぶか]の意見[いけん]に耳[みみ]を傾[かたむ]けることを忘[わす]れない。", "sentence_source": "generated"}, {"text": "彼女は判断力に優れて、困った場面でもいつも冷静に決断する。", "target_word": "優れて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は判断力[はんだんりょく]に優[すぐ]れて、困[こま]った場面[ばめん]でもいつも冷静[れいせい]に決断[けつだん]する。", "sentence_source": "generated"}, {"text": "品質の優れた野菜を選ぶために、農家から直接買うことにした。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "品質[ひんしつ]の優[すぐ]れた野菜[やさい]を選[えら]ぶために、農家[のうか]から直接[ちょくせつ]買[か]うことにした。", "sentence_source": "generated"}, {"text": "この車は燃費性能で他社の製品より優れている。", "target_word": "優れている", "complexity_tier": "T3", "furigana": "この車[くるま]は燃費[ねんぴ]性能[せいのう]で他社[たしゃ]の製品[せいひん]より優[すぐ]れている。", "sentence_source": "generated"}, {"text": "記憶力に優れた子どもでも、復習しなければ内容は忘れてしまう。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "記憶力[きおくりょく]に優[すぐ]れた子[こ]どもでも、復習[ふくしゅう]しなければ内容[ないよう]は忘[わす]れてしまう。", "sentence_source": "generated"}, {"text": "彼のチームは守備力に優れ、今季は失点がほとんどなかった。", "target_word": "優れ", "complexity_tier": "T3", "furigana": "彼[かれ]のチームは守備力[しゅびりょく]に優[すぐ]れ、今季[こんき]は失点[しってん]がほとんどなかった。", "sentence_source": "generated"}, {"text": "優れた翻訳は、原文の意味だけでなく雰囲気まで正確に伝える。", "target_word": "優れた", "complexity_tier": "T3", "furigana": "優[すぐ]れた翻訳[ほんやく]は、原文[げんぶん]の意味[いみ]だけでなく雰囲気[ふんいき]まで正確[せいかく]に伝[つた]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "優れる", "label": "終止形"}, {"form": "優れた", "label": "過去形"}, {"form": "優れて", "label": "て形"}, {"form": "優れない", "label": "ない形"}, {"form": "優れれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "能力や品質が他より高い水準にある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "優れた", "is_correct": true, "explanation": "連体形で、後ろの名詞『変容』を修飾する。『消化吸収にも優れた変容』の形になるのでここに入る。"}, {"text": "優れよう", "is_correct": false, "explanation": "意志・推量の形で名詞を修飾できず、「優れよう変容」は成り立たない。"}, {"text": "優れて", "is_correct": false, "explanation": "連用形は名詞に続けられないため、『優れて変容』とはならない。"}, {"text": "優れれば", "is_correct": false, "explanation": "仮定形は名詞修飾に使えず、『優れれば変容』は成立しない。"}], "explanations": {"優れた": "連体形で、後ろの名詞『変容』を修飾する。『消化吸収にも優れた変容』の形になるのでここに入る。", "優れよう": "意志・推量の形で名詞を修飾できず、「優れよう変容」は成り立たない。", "優れて": "連用形は名詞に続けられないため、『優れて変容』とはならない。", "優れれば": "仮定形は名詞修飾に使えず、『優れれば変容』は成立しない。"}, "sentence_index": 0, "correct_answer": "優れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題は今日中に優れるはずだ。", "explanation": "ここは〈終わる〉の意味。優れるは能力や品質が高い水準にあることを表し、作業が完了することは表せない。"}, {"text": "会場は女性の来場者が優れていた。", "explanation": "ここは〈多い〉の意味。優れるは質の高さを表すので、来場者の人数の多さは表せない。"}, {"text": "この町は人口が優れている。", "explanation": "ここは〈人口が多い〉の意味。優れるは質の高さを表すので、人の数の多さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "優れている", "is_correct": true, "explanation": "文末の述語として『他社の製品より優れている』と続き、比較して上回る状態を表す。"}, {"text": "優れ", "is_correct": false, "explanation": "連用形は文末に置けず、『他社の製品より優れ。』では文が終わらない。"}, {"text": "優れよう", "is_correct": false, "explanation": "意志・推量の形で文の述語にはならず、『より優れよう』は不自然。"}, {"text": "優れさせる", "is_correct": false, "explanation": "使役形で目的語が必要になり、この文の流れには入らない。"}], "explanations": {"優れている": "文末の述語として『他社の製品より優れている』と続き、比較して上回る状態を表す。", "優れ": "連用形は文末に置けず、『他社の製品より優れ。』では文が終わらない。", "優れよう": "意志・推量の形で文の述語にはならず、『より優れよう』は不自然。", "優れさせる": "使役形で目的語が必要になり、この文の流れには入らない。"}, "sentence_index": 6, "correct_answer": "優れている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この翻訳は誤字が優れていて、校正に一日かかった。", "explanation": "ここは〈多い〉の意味。誤字の多さは優れるで表せず、質の高さを表す語ではない。"}, {"text": "この翻訳は締め切りに優れて、一週間前に届いた。", "explanation": "ここは〈早く終わる〉の意味。優れるは質の高さを表し、期限より早く仕上がることは表せない。"}, {"text": "この翻訳は語数が優れている。", "explanation": "ここは〈語数が多い・少ない〉の意味。優れるは質の高さを表すので、数の大小には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は判断力を優れていて、難しい場面でも冷静さを保つ。", "corrected_sentence": "彼女は判断力に優れていて、難しい場面でも冷静さを保つ。", "error_description": "『優れる』は『〜に優れる』の形で助詞『に』を取る。『を』は誤りで、正しくは『に』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "優れ", "is_correct": true, "explanation": "連用形で、『才能に優れ、』のように文を中止して続ける形。"}, {"text": "優れる", "is_correct": false, "explanation": "終止形は『、』の前で文を中止できず、『才能に優れる、三年で』は不自然。"}, {"text": "優れた", "is_correct": false, "explanation": "連体形は後ろに名詞が必要で、『才能に優れた、』では文が途切れる。"}, {"text": "優れれば", "is_correct": false, "explanation": "仮定形は条件節になり、この文の『、三年で〜』という流れに合わない。"}], "correct_form": "優れ", "base_form": "優れる", "form_label": "連用形（中止）", "sentence_index": 1, "explanations": {"優れ": "連用形で、『才能に優れ、』のように文を中止して続ける形。", "優れる": "終止形は『、』の前で文を中止できず、『才能に優れる、三年で』は不自然。", "優れた": "連体形は後ろに名詞が必要で、『才能に優れた、』では文が途切れる。", "優れれば": "仮定形は条件節になり、この文の『、三年で〜』という流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52308, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この翻訳は細部に優れるで、読み手を惹きつける。", "corrected_sentence": "この翻訳は細部に優れていて、読み手を惹きつける。", "error_description": "『優れる』の終止形に『で』が続いて文法的に誤り。状態を述べる『優れていて』の形が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "優れた", "is_correct": true, "explanation": "連体形で、後ろの名詞『子ども』を修飾する。『記憶力に優れた子ども』として正しい。"}, {"text": "優れて", "is_correct": false, "explanation": "連用形は名詞を修飾できず、『記憶力に優れて子ども』は成り立たない。"}, {"text": "優れ", "is_correct": false, "explanation": "連用形で名詞修飾には使えず、『記憶力に優れ子ども』は不自然。"}, {"text": "優れよう", "is_correct": false, "explanation": "意志・推量の形で、名詞を修飾できない。"}], "correct_form": "優れた", "base_form": "優れる", "form_label": "連体形（た形）", "sentence_index": 7, "explanations": {"優れた": "連体形で、後ろの名詞『子ども』を修飾する。『記憶力に優れた子ども』として正しい。", "優れて": "連用形は名詞を修飾できず、『記憶力に優れて子ども』は成り立たない。", "優れ": "連用形で名詞修飾には使えず、『記憶力に優れ子ども』は不自然。", "優れよう": "意志・推量の形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
