INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52309, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンの外側のかたい部分。", "primary_collocate": null, "pronunciation": "くらすと", "ipa": "kɯɾasɯto", "syllable_count": 4, "sentences": [{"text": "食パンのクラストは、トーストにするとよりかたく香ばしくなる。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "食[しょく]パンのクラストは、トーストにするとよりかたく香[こう]ばしくなる。", "sentence_source": "generated"}, {"text": "祖父はパンの中身より、クラストの香ばしさが好きだと言う。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "祖父[そふ]はパンの中身[なかみ]より、クラストの香[こう]ばしさが好[す]きだと言[い]う。", "sentence_source": "generated"}, {"text": "子どもがクラストを残すので、サンドイッチでは切り落として出している。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "子[こ]どもがクラストを残[のこ]すので、サンドイッチでは切[き]り落[お]として出[だ]している。", "sentence_source": "generated"}, {"text": "このバゲットはクラストがかたすぎて、歯が痛くなった。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "このバゲットはクラストがかたすぎて、歯[は]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "オーブンの温度が高すぎたのか、パンのクラストが焦げてしまった。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "オーブンの温度[おんど]が高[たか]すぎたのか、パンのクラストが焦[こ]げてしまった。", "sentence_source": "generated"}, {"text": "焼きたてのパンは、クラストを軽く叩くと乾いた音がする。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンは、クラストを軽[かる]く叩[たた]くと乾[かわ]いた音[おと]がする。", "sentence_source": "generated"}, {"text": "スープにクラストを浸して食べると、かたいパンも食べやすい。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "スープにクラストを浸[ひた]して食[た]べると、かたいパンも食[た]べやすい。", "sentence_source": "generated"}, {"text": "クラストが厚いパンは、日持ちするがかみ切るのに時間がかかる。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "クラストが厚[あつ]いパンは、日持[ひも]ちするがかみ切[き]るのに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "パン屋の主人は、クラストの色を見て焼き上がりを判断する。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "パン屋[や]の主人[しゅじん]は、クラストの色[いろ]を見[み]て焼[や]き上[あ]がりを判断[はんだん]する。", "sentence_source": "generated"}, {"text": "蒸気を入れて焼くと、クラストが薄くてパリッとしたパンになる。", "target_word": "クラスト", "complexity_tier": "T3", "furigana": "蒸気[じょうき]を入[い]れて焼[や]くと、クラストが薄[うす]くてパリッとしたパンになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "クラスト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "パンの外側の、焼けてかたくなった皮の部分。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52309, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中身", "is_correct": false, "explanation": "パンの内側のやわらかい部分を指す。トーストしてかたく香ばしくなるのは外側なので、文意に合わない。"}, {"text": "クラスト", "is_correct": true, "explanation": "パンの外側のかたい部分を指す。トーストするとよりかたく香ばしくなる、という文意に合う。"}, {"text": "小麦粉", "is_correct": false, "explanation": "パンの原料の粉。焼いてかたく香ばしくなる部位ではないので、文の主語として合わない。"}, {"text": "酵母", "is_correct": false, "explanation": "生地を発酵させる微生物で、パンの部位ではない。かたく香ばしくなる主語にはならない。"}], "explanations": {"中身": "パンの内側のやわらかい部分を指す。トーストしてかたく香ばしくなるのは外側なので、文意に合わない。", "クラスト": "パンの外側のかたい部分を指す。トーストするとよりかたく香ばしくなる、という文意に合う。", "小麦粉": "パンの原料の粉。焼いてかたく香ばしくなる部位ではないので、文の主語として合わない。", "酵母": "生地を発酵させる微生物で、パンの部位ではない。かたく香ばしくなる主語にはならない。"}, "sentence_index": 0, "correct_answer": "クラスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ぶどうのクラストを剥いてから食べた。", "explanation": "ここは〈皮〉の意味。クラストはパンや焼き菓子の焼けた外側を指すので、果物の皮には使わない。"}, {"text": "パンのクラストは、真っ白でふわふわだ。", "explanation": "ここは〈中身〉の意味。クラストは外側のかたい部分なので、真っ白でふわふわという特徴とは合わない。"}, {"text": "ゆで卵のクラストは、むくと簡単にむける。", "explanation": "ここは〈殻〉の意味。ゆで卵の硬い外側は殻と言い、パンの焼けた外側を指すクラストは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52309, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発酵", "is_correct": false, "explanation": "パン生地を膨らませる工程。スープに浸して食べるものではないので合わない。"}, {"text": "焼き型", "is_correct": false, "explanation": "パンを焼くための型。スープに浸す対象として文が成り立たない。"}, {"text": "天板", "is_correct": false, "explanation": "オーブンで使う焼き板。食べ物として浸すという文意に合わない。"}, {"text": "クラスト", "is_correct": true, "explanation": "パンのかたい外側。スープに浸して食べるとかたいパンも食べやすくなる、という文意に合う。"}], "explanations": {"発酵": "パン生地を膨らませる工程。スープに浸して食べるものではないので合わない。", "焼き型": "パンを焼くための型。スープに浸す対象として文が成り立たない。", "天板": "オーブンで使う焼き板。食べ物として浸すという文意に合わない。", "クラスト": "パンのかたい外側。スープに浸して食べるとかたいパンも食べやすくなる、という文意に合う。"}, "sentence_index": 6, "correct_answer": "クラスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木のクラストは、ごつごつしていて厚い。", "explanation": "ここは〈樹皮〉の意味。木の外側を覆う皮は樹皮と言い、パンの焼けた外側を指すクラストとは違う。"}, {"text": "パンのクラストは、ふんわりして白い。", "explanation": "ここは〈中央〉の意味。クラストはふんわり白い部分ではなく、外側のかたい部分なので合わない。"}, {"text": "みかんのクラストは、食べると少し苦い。", "explanation": "ここは〈薄皮〉の意味。みかんの薄皮はクラストとは言わず、焼けたパンの外側の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52309, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、トーストのクラストに香ばしくて喜んだ。", "corrected_sentence": "祖父は、トーストのクラストが香ばしくて喜んだ。", "error_description": "「香ばしい」の主語は「が」。「クラストに」の「に」は誤りで、正しくは「クラストが香ばしい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52309, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このパンはクラストに薄くてパリッとしている。", "corrected_sentence": "このパンはクラストが薄くてパリッとしている。", "error_description": "「薄い」の主語を示すのは「が」。「クラストに」の「に」は誤りで、正しくは「クラストが薄い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
