INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52311, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンのやわらかい中身。", "primary_collocate": null, "pronunciation": "くらむ", "ipa": "kɯɾamɯ", "syllable_count": 3, "sentences": [{"text": "パンを半分に切ると、中のクラムは真っ白でふわふわだった。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "パンを半分[はんぶん]に切[き]ると、中[なか]のクラムは真[ま]っ白[しろ]でふわふわだった。", "sentence_source": "generated"}, {"text": "私はパンの皮よりクラムのほうが好きだ。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "私[わたし]はパンの皮[かわ]よりクラムのほうが好[す]きだ。", "sentence_source": "generated"}, {"text": "このパンのクラムは、牛乳の甘い香りがする。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "このパンのクラムは、牛乳[ぎゅうにゅう]の甘[あま]い香[かお]りがする。", "sentence_source": "generated"}, {"text": "ちぎったクラムは、指で押すとふわっと沈んだ。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "ちぎったクラムは、指[ゆび]で押[お]すとふわっと沈[しず]んだ。", "sentence_source": "generated"}, {"text": "古くなったパンのクラムは、乾いてぼろぼろになる。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "古[ふる]くなったパンのクラムは、乾[かわ]いてぼろぼろになる。", "sentence_source": "generated"}, {"text": "クラムが湿っぽいのは、中まで焼けていない証拠だ。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "クラムが湿[しめ]っぽいのは、中[なか]まで焼[や]けていない証拠[しょうこ]だ。", "sentence_source": "generated"}, {"text": "赤ちゃんには、クラムだけをちぎって食べさせた。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんには、クラムだけをちぎって食[た]べさせた。", "sentence_source": "generated"}, {"text": "外はカリッとしても、クラムは柔らかいままだった。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "外[そと]はカリッとしても、クラムは柔[やわ]らかいままだった。", "sentence_source": "generated"}, {"text": "パンのクラムを丸めて、小さな団子にして遊んだ。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "パンのクラムを丸[まる]めて、小[ちい]さな団子[だんご]にして遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "フレンチトーストには、クラムがしっかりしたパンが向いている。", "target_word": "クラム", "complexity_tier": "T3", "furigana": "フレンチトーストには、クラムがしっかりしたパンが向[む]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "クラム", "label": "基本形"}], "register": "口語（日常・料理）", "sense_fingerprint": "パンの皮の内側にある、やわらかい中身の部分。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52311, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焼き型", "is_correct": false, "explanation": "パンを焼くための型。切った断面の中身として、真っ白でふわふわという文意に合わない。"}, {"text": "包丁", "is_correct": false, "explanation": "調理道具。パンの断面の状態を述べる主語にはならない。"}, {"text": "外皮", "is_correct": false, "explanation": "パンの外側の皮。中が真っ白でふわふわという文意には合わない。"}, {"text": "クラム", "is_correct": true, "explanation": "パンの皮の内側にある柔らかい中身。切ると真っ白でふわふわという文意に合う。"}], "explanations": {"焼き型": "パンを焼くための型。切った断面の中身として、真っ白でふわふわという文意に合わない。", "包丁": "調理道具。パンの断面の状態を述べる主語にはならない。", "外皮": "パンの外側の皮。中が真っ白でふわふわという文意には合わない。", "クラム": "パンの皮の内側にある柔らかい中身。切ると真っ白でふわふわという文意に合う。"}, "sentence_index": 0, "correct_answer": "クラム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食パンのクラムは、外が焦げて黒くなった。", "explanation": "ここは〈外側〉の意味。焦げて黒くなるのは外側で、やわらかい中身のクラムには合わない。"}, {"text": "パンのクラムは、焼くとパリッとして香ばしい。", "explanation": "ここは〈皮〉の意味。クラムは中のやわらかい部分で、パリッと香ばしいのは皮なので合わない。"}, {"text": "卵のクラムは、泡立てるとふわふわになる。", "explanation": "ここは〈白身〉の意味。卵の白身はクラムとは言わず、泡立ててふわふわにする話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52311, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天板", "is_correct": false, "explanation": "オーブンで使う焼き板。赤ちゃんに食べさせる対象として文が成り立たない。"}, {"text": "酵母", "is_correct": false, "explanation": "生地を発酵させる微生物。食べ物として赤ちゃんにちぎって与える対象にはならない。"}, {"text": "発酵", "is_correct": false, "explanation": "パン生地を膨らませる工程。ちぎって食べさせるものではないので合わない。"}, {"text": "クラム", "is_correct": true, "explanation": "パンの柔らかい中身。赤ちゃん向けにちぎって食べさせる、という文意に合う。"}], "explanations": {"天板": "オーブンで使う焼き板。赤ちゃんに食べさせる対象として文が成り立たない。", "酵母": "生地を発酵させる微生物。食べ物として赤ちゃんにちぎって与える対象にはならない。", "発酵": "パン生地を膨らませる工程。ちぎって食べさせるものではないので合わない。", "クラム": "パンの柔らかい中身。赤ちゃん向けにちぎって食べさせる、という文意に合う。"}, "sentence_index": 6, "correct_answer": "クラム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "クラムを寝かせると、グルテンが育つ。", "explanation": "ここは〈生地〉の意味。焼いた後の内部を指すこの語は、寝かせてグルテンを育てる対象にはならない。"}, {"text": "クラムを霧吹きすると、パリッと仕上がる。", "explanation": "ここは〈表面〉の意味。内部のやわらかい部分を霧吹きしてパリッと仕上げる話にはならない。"}, {"text": "クラムはかたく香ばしく焼き上がる。", "explanation": "ここは〈外皮〉の意味。かたく香ばしく焼き上がるのは外皮で、内部のクラムには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52311, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "やわらかいクラムに、指でそっと押してみた。", "corrected_sentence": "やわらかいクラムを、指でそっと押してみた。", "error_description": "「押す」の目的語は「を」で示す。「クラムに」の「に」は誤りで、正しくは「クラムを押す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52311, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "クラムがしっとりしていて、翌日も固くならなる。", "corrected_sentence": "クラムがしっとりしていて、翌日も固くならない。", "error_description": "「固くならない」の否定形が正しい形。「ならなる」は誤った活用で、「ならない」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
