INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52313, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "食べ物や果物が、中にたくさん水が入っていて、しっとりしていることです。", "primary_collocate": null, "pronunciation": "みずみずしい", "ipa": "mizɯmizɯɕiː", "syllable_count": 6, "sentences": [{"text": "このみかんは、皮をむくと中がとても瑞々しい。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "このみかんは、皮[かわ]をむくと中[なか]がとても瑞々[みずみず]しい。", "sentence_source": "generated"}, {"text": "瑞々しいぶどうを冷やして、デザートに出した。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "瑞々[みずみず]しいぶどうを冷[ひ]やして、デザートに出[だ]した。", "sentence_source": "generated"}, {"text": "瑞々しいトマトのサラダは、夏の食卓にぴったりだ。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "瑞々[みずみず]しいトマトのサラダは、夏[なつ]の食卓[しょくたく]にぴったりだ。", "sentence_source": "generated"}, {"text": "できたてのパンケーキは、中が瑞々しくてやわらかかった。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "できたてのパンケーキは、中[なか]が瑞々[みずみず]しくてやわらかかった。", "sentence_source": "generated"}, {"text": "冷蔵庫で保存すると、いちごは三日たっても瑞々しく保てる。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]で保存[ほぞん]すると、いちごは三日[みっか]たっても瑞々[みずみず]しく保[たも]てる。", "sentence_source": "generated"}, {"text": "母が切ってくれた梨は、瑞々しくて、甘かった。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "母[はは]が切[き]ってくれた梨[なし]は、瑞々[みずみず]しくて、甘[あま]かった。", "sentence_source": "generated"}, {"text": "瑞々しくないレタスでは、サラダがおいしくならない。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "瑞々[みずみず]しくないレタスでは、サラダがおいしくならない。", "sentence_source": "generated"}, {"text": "雨上がりの畑で採れたなすは、瑞々しいうえに味が濃い。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "雨上[あまあ]がりの畑[はたけ]で採[と]れたなすは、瑞々[みずみず]しいうえに味[あじ]が濃[こ]い。", "sentence_source": "generated"}, {"text": "このメロンは果肉が瑞々しくて、スプーンですくうと果汁が出てきた。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "このメロンは果肉[かにく]が瑞々[みずみず]しくて、スプーンですくうと果汁[かじゅう]が出[で]てきた。", "sentence_source": "generated"}, {"text": "瑞々しかったりんごも、一週間置くとぱさぱさになった。", "target_word": "瑞々しかった", "complexity_tier": "T3", "furigana": "瑞々[みずみず]しかったりんごも、一週間[いっしゅうかん]置[お]くとぱさぱさになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "瑞々しい", "label": "終止形・連体形"}, {"form": "瑞々しく", "label": "連用形"}, {"form": "瑞々しかった", "label": "過去形"}, {"form": "瑞々しくない", "label": "否定形"}, {"form": "瑞々しければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "食べ物や果物の中に水分がたっぷり入っていて、しっとりしている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52313, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瑞々しい", "is_correct": true, "explanation": "皮をむくと中に水分がたっぷりあることを表し、みかんの中身の描写に合う。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す語で、みかんの中身の状態には合わない。"}, {"text": "騒がしい", "is_correct": false, "explanation": "音を表す語で、みかんの中身には合わない。"}, {"text": "寂しい", "is_correct": false, "explanation": "感情を表す語で、果物の中身の状態には合わない。"}], "explanations": {"瑞々しい": "皮をむくと中に水分がたっぷりあることを表し、みかんの中身の描写に合う。", "眠い": "眠気を表す語で、みかんの中身の状態には合わない。", "騒がしい": "音を表す語で、みかんの中身には合わない。", "寂しい": "感情を表す語で、果物の中身の状態には合わない。"}, "sentence_index": 0, "correct_answer": "瑞々しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝に揚がったアジは瑞々しく、身がしまっている。", "explanation": "ここは〈新鮮〉の意味。魚の鮮度には『新鮮』を使い、瑞々しいは植物や果物の水分の充実に使うので合わない。"}, {"text": "焼きすぎたスポンジは瑞々しくて、すっかりこわばった。", "explanation": "ここは〈こわばった〉の意味。水分が抜けて固くなった状態を指すので、水分が十分な様子の瑞々しいとは合わない。"}, {"text": "妹は瑞々しく笑いながら駆け回った。", "explanation": "ここは〈生き生き〉の意味。人の元気な様子を言うので、果物や野菜の水分を表す瑞々しいとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52313, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瑞々しく", "is_correct": true, "explanation": "否定形『瑞々しくない』の一部で、レタスの水分の状態を表すので文に合う。"}, {"text": "荒く", "is_correct": false, "explanation": "表面の粗さを表す語で、レタスの水分を否定する文脈には合わない。"}, {"text": "恥ずかしく", "is_correct": false, "explanation": "感情を表す語で、レタスの状態を表す文には合わない。"}, {"text": "煩わしく", "is_correct": false, "explanation": "わずらわしさを表す語で、レタスの状態を表す文には合わない。"}], "explanations": {"瑞々しく": "否定形『瑞々しくない』の一部で、レタスの水分の状態を表すので文に合う。", "荒く": "表面の粗さを表す語で、レタスの水分を否定する文脈には合わない。", "恥ずかしく": "感情を表す語で、レタスの状態を表す文には合わない。", "煩わしく": "わずらわしさを表す語で、レタスの状態を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "瑞々しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早朝の森は、落ち葉が瑞々しく割れていた。", "explanation": "ここは〈枯れた〉の意味。枯れて乾いた落ち葉を指すので、水分が十分な様子の瑞々しいとは合わない。"}, {"text": "雨の日の押し入れは瑞々しく、かびやすい。", "explanation": "ここは〈湿っぽい〉の意味。じめじめした湿気を表すので、新鮮で良好な水分を表す瑞々しいとは合わない。"}, {"text": "薄めた出汁は瑞々しくて、味がぼやけている。", "explanation": "ここは〈水っぽい〉の意味。味が薄くうま味が少ない様子を指すので、良い状態を表す瑞々しいとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52313, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このみかんは、皮をむくと中が瑞々しいて、とても甘い。", "corrected_sentence": "このみかんは、皮をむくと中が瑞々しくて、とても甘い。", "error_description": "『瑞々しい』を『て』でつなぐには連用形『瑞々しく』を使う。『瑞々しいて』は誤りで、正しくは『瑞々しくて』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "瑞々しい", "is_correct": true, "explanation": "連体形で、後ろの名詞『ぶどう』を修飾する形として正しい。"}, {"text": "瑞々しく", "is_correct": false, "explanation": "連用形で、名詞の前には置けないので『瑞々しくぶどう』は不自然。"}, {"text": "瑞々しければ", "is_correct": false, "explanation": "仮定形で「〜ならば」の条件の意味になり、名詞「ぶどう」の前には入らない。"}, {"text": "瑞々しくて", "is_correct": false, "explanation": "「て」の形で、名詞「ぶどう」を直接修飾できないので文が成り立たない。"}], "correct_form": "瑞々しい", "base_form": "瑞々しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"瑞々しい": "連体形で、後ろの名詞『ぶどう』を修飾する形として正しい。", "瑞々しく": "連用形で、名詞の前には置けないので『瑞々しくぶどう』は不自然。", "瑞々しければ": "仮定形で「〜ならば」の条件の意味になり、名詞「ぶどう」の前には入らない。", "瑞々しくて": "「て」の形で、名詞「ぶどう」を直接修飾できないので文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52313, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母が切ってくれた瑞々しいの梨は、甘かった。", "corrected_sentence": "母が切ってくれた瑞々しい梨は、甘かった。", "error_description": "『瑞々しい』は直後の名詞『梨』を直接修飾するので、間に『の』は入れない。『瑞々しいの梨』は誤りで、正しくは『瑞々しい梨』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "瑞々しい", "is_correct": true, "explanation": "終止形で、『うえに』の前に続く言い切りの形として正しい。"}, {"text": "瑞々しさ", "is_correct": false, "explanation": "名詞形で、『うえに』の前には述語が来ないので文が成り立たない。"}, {"text": "瑞々しけれ", "is_correct": false, "explanation": "文語の已然形で、現代語の『うえに』の前には置けないので文が成り立たない。"}, {"text": "瑞々しかろう", "is_correct": false, "explanation": "推量の形で『〜だろう』の意味になり、なすの今の状態を言い切る文には合わない。"}], "correct_form": "瑞々しい", "base_form": "瑞々しい", "form_label": "終止形", "sentence_index": 7, "explanations": {"瑞々しい": "終止形で、『うえに』の前に続く言い切りの形として正しい。", "瑞々しさ": "名詞形で、『うえに』の前には述語が来ないので文が成り立たない。", "瑞々しけれ": "文語の已然形で、現代語の『うえに』の前には置けないので文が成り立たない。", "瑞々しかろう": "推量の形で『〜だろう』の意味になり、なすの今の状態を言い切る文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
