INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52314, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "水分が十分に含まれていて、みずみずしく新鮮な様子。特に果物や野菜、焼きたてのパンの内部などに使われる。", "primary_collocate": null, "pronunciation": "みずみずしい", "ipa": "mizɯmizɯɕiː", "syllable_count": 6, "sentences": [{"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "瑞々しく", "complexity_tier": "T4", "furigana": "最終[さいしゅう]段階[だんかい]のベーキングでは、高温[こうおん]の蒸気[じょうき]と共[とも]に膨張[ぼうちょう]した生地[きじ]が、黄金色[こがねいろ]の硬質[こうしつ]で脆[もろ]いクラストを纏[まと]い、内部[ないぶ]は瑞々[みずみず]しくも弾力[だんりょく]に富[と]んだクラムへと昇華[しょうか]する。", "sentence_source": "mined"}, {"text": "朝市で買ったトマトは、皮にはりがあって、中まで瑞々しい。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "朝市[あさいち]で買[か]ったトマトは、皮[かわ]にはりがあって、中[なか]まで瑞々[みずみず]しい。", "sentence_source": "generated"}, {"text": "瑞々しい梨をかじると、甘い果汁が口いっぱいに広がった。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "瑞々[みずみず]しい梨[なし]をかじると、甘[あま]い果汁[かじゅう]が口[くち]いっぱいに広[ひろ]がった。", "sentence_source": "generated"}, {"text": "包丁で切ると、きゅうりの瑞々しい断面が光っていた。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "包丁[ほうちょう]で切[き]ると、きゅうりの瑞々[みずみず]しい断面[だんめん]が光[ひか]っていた。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れ忘れたので、レタスが瑞々しくなくなってしまった。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れ忘[わす]れたので、レタスが瑞々[みずみず]しくなくなってしまった。", "sentence_source": "generated"}, {"text": "このパンは焼きたてなので、中が瑞々しくてやわらかい。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "このパンは焼[や]きたてなので、中[なか]が瑞々[みずみず]しくてやわらかい。", "sentence_source": "generated"}, {"text": "洗ったばかりの野菜が、水をはじいて瑞々しく見える。", "target_word": "瑞々しく", "complexity_tier": "T3", "furigana": "洗[あら]ったばかりの野菜[やさい]が、水[みず]をはじいて瑞々[みずみず]しく見[み]える。", "sentence_source": "generated"}, {"text": "店先には、瑞々しい桃がきれいに並べられていた。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "店先[みせさき]には、瑞々[みずみず]しい桃[もも]がきれいに並[なら]べられていた。", "sentence_source": "generated"}, {"text": "畑でとれた野菜は、スーパーのものより瑞々しかった。", "target_word": "瑞々しかった", "complexity_tier": "T3", "furigana": "畑[はたけ]でとれた野菜[やさい]は、スーパーのものより瑞々[みずみず]しかった。", "sentence_source": "generated"}, {"text": "切ったばかりのスイカが瑞々しいうちに、みんなで食べよう。", "target_word": "瑞々しい", "complexity_tier": "T3", "furigana": "切[き]ったばかりのスイカが瑞々[みずみず]しいうちに、みんなで食[た]べよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "瑞々しい", "label": "終止形・連体形"}, {"form": "瑞々しく", "label": "連用形"}, {"form": "瑞々しかった", "label": "過去形"}, {"form": "瑞々しくない", "label": "否定形"}, {"form": "瑞々しければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "果物や野菜、焼きたてのパンの内部などが水分を十分に含み、新鮮でうるおっている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52314, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瑞々しく", "is_correct": true, "explanation": "水分が十分で内部がしっとりしている様子を表し、焼きたてのクラムの状態に合う。"}, {"text": "苦く", "is_correct": false, "explanation": "味を表す『苦い』の連用形で、内部のしっとりした状態を述べる文には合わない。"}, {"text": "冷たく", "is_correct": false, "explanation": "温度を表すので、焼きたての内部を描く文脈とは合わない。"}, {"text": "赤く", "is_correct": false, "explanation": "色を表すので、内部の水分の状態を描く文脈には合わない。"}], "explanations": {"瑞々しく": "水分が十分で内部がしっとりしている様子を表し、焼きたてのクラムの状態に合う。", "苦く": "味を表す『苦い』の連用形で、内部のしっとりした状態を述べる文には合わない。", "冷たく": "温度を表すので、焼きたての内部を描く文脈とは合わない。", "赤く": "色を表すので、内部の水分の状態を描く文脈には合わない。"}, "sentence_index": 0, "correct_answer": "瑞々しく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "畑の土は長く雨が降らず、瑞々しくひび割れていた。", "explanation": "ここは〈乾燥〉の意味。雨がなく水分が抜けた土を指すので、水分が十分な様子の瑞々しいとは合わない。"}, {"text": "夏の市場で、しなびたトマトが瑞々しく並んでいた。", "explanation": "ここは〈水分が抜けた〉状態の意味。しなびたものを指すので、水分が十分な様子の瑞々しいとは合わない。"}, {"text": "梅雨の部屋は瑞々しくて、洗濯物が乾かない。", "explanation": "ここは〈湿っぽい〉の意味。じめじめした不快な湿気を指すので、新鮮で潤った良い状態の瑞々しいとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52314, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瑞々しく", "is_correct": true, "explanation": "水分が十分で新鮮な様子を表し、洗ったばかりの野菜の見え方に合う。"}, {"text": "狭く", "is_correct": false, "explanation": "広さを表すので、野菜の見た目の描写には合わない。"}, {"text": "騒がしく", "is_correct": false, "explanation": "音を表す語で、野菜の見た目には合わない。"}, {"text": "恥ずかしく", "is_correct": false, "explanation": "感情を表す語で、野菜の見た目の説明には合わない。"}], "explanations": {"瑞々しく": "水分が十分で新鮮な様子を表し、洗ったばかりの野菜の見え方に合う。", "狭く": "広さを表すので、野菜の見た目の描写には合わない。", "騒がしく": "音を表す語で、野菜の見た目には合わない。", "恥ずかしく": "感情を表す語で、野菜の見た目の説明には合わない。"}, "sentence_index": 6, "correct_answer": "瑞々しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "六十歳を過ぎても、彼女の感性は瑞々しかった。", "explanation": "ここは〈若々しく感性が豊か〉の意味。人の感性を言うので、野菜や果物の水分の充実を表す義項とは別の意味。"}, {"text": "子どもたちが瑞々しく校庭を走り回った。", "explanation": "ここは〈生き生き〉の意味。人の元気な様子を言うので、野菜や果物の水分を表す瑞々しいとは合わない。"}, {"text": "安いスープは瑞々しくて、味が薄い。", "explanation": "ここは〈水っぽい〉の意味。うま味が少なく薄い味を指すので、良い状態を表す瑞々しいとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52314, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝摘みのいちごは、瑞々しいくて、とても甘い。", "corrected_sentence": "朝摘みのいちごは、瑞々しくて、とても甘い。", "error_description": "『瑞々しい』は形容詞なので、『て』に続けるときは連用形『瑞々しく』にする。『瑞々しいくて』は語尾の誤りで、正しくは『瑞々しくて』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "瑞々しい", "is_correct": true, "explanation": "文末で言い切る終止形で、トマトの状態を述べる文に合う。"}, {"text": "瑞々しく", "is_correct": false, "explanation": "連用形で、文を言い切る形にならないので文末には入らない。"}, {"text": "瑞々しくて", "is_correct": false, "explanation": "「て」の形で、文を言い切れず「中まで瑞々しくて。」は文が続かないので不可。"}, {"text": "瑞々しければ", "is_correct": false, "explanation": "仮定形で、「〜ならば」の続きがないと文が終わらないので不可。"}], "correct_form": "瑞々しい", "base_form": "瑞々しい", "form_label": "終止形", "sentence_index": 1, "explanations": {"瑞々しい": "文末で言い切る終止形で、トマトの状態を述べる文に合う。", "瑞々しく": "連用形で、文を言い切る形にならないので文末には入らない。", "瑞々しくて": "「て」の形で、文を言い切れず「中まで瑞々しくて。」は文が続かないので不可。", "瑞々しければ": "仮定形で、「〜ならば」の続きがないと文が終わらないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52314, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "瑞々しいのレタスは、冷蔵庫で保存するとよい。", "corrected_sentence": "瑞々しいレタスは、冷蔵庫で保存するとよい。", "error_description": "『瑞々しい』は直後の名詞を直接修飾するので、間に『の』は入れない。『瑞々しいのレタス』は誤りで、正しくは『瑞々しいレタス』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "瑞々しい", "is_correct": true, "explanation": "連体形で、後ろの名詞『桃』を修飾する形として正しい。"}, {"text": "瑞々しさ", "is_correct": false, "explanation": "名詞形で、後ろの『桃』を直接修飾できず『瑞々しさ桃』は成り立たない。"}, {"text": "瑞々しけれ", "is_correct": false, "explanation": "文語の已然形で、現代語の名詞修飾には使えないので『瑞々しけれ桃』は不可。"}, {"text": "瑞々しかろう", "is_correct": false, "explanation": "推量の形で『〜だろう』の意味になり、名詞『桃』を修飾する形ではないので合わない。"}], "correct_form": "瑞々しい", "base_form": "瑞々しい", "form_label": "連体形", "sentence_index": 7, "explanations": {"瑞々しい": "連体形で、後ろの名詞『桃』を修飾する形として正しい。", "瑞々しさ": "名詞形で、後ろの『桃』を直接修飾できず『瑞々しさ桃』は成り立たない。", "瑞々しけれ": "文語の已然形で、現代語の名詞修飾には使えないので『瑞々しけれ桃』は不可。", "瑞々しかろう": "推量の形で『〜だろう』の意味になり、名詞『桃』を修飾する形ではないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「英知を集める」の対象は「を」で示すので、この文になる。"}, {"text": "が", "is_correct": false, "explanation": "「英知が集めて」では主語が立たない。「集める」の対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「英知に集めて」は不自然。「に」は方向や相手を示すので、集める対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "「英知と集めて」は意味が通らない。「と」は並列や相手を示すが、ここは集める対象。"}], "correct_answer": "を", "explanations": {"を": "正解。「英知を集める」の対象は「を」で示すので、この文になる。", "が": "「英知が集めて」では主語が立たない。「集める」の対象は「を」で示す。", "に": "「英知に集めて」は不自然。「に」は方向や相手を示すので、集める対象にならない。", "と": "「英知と集めて」は意味が通らない。「と」は並列や相手を示すが、ここは集める対象。"}, "error_tags": {"が": "主語", "に": "方向・相手", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「英知のある人」は、英知を持つ人という修飾関係で、「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「英知を ある人」は成り立たない。「を」は動作の対象を示すので修飾にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「英知へある人」は不自然。「へ」は方向を示すので、修飾関係にならない。"}, {"text": "から", "is_correct": false, "explanation": "「英知からある人」は意味が通らない。「から」は起点を示すので、修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「英知のある人」は、英知を持つ人という修飾関係で、「の」が正しい。", "を": "「英知を ある人」は成り立たない。「を」は動作の対象を示すので修飾にならない。", "へ": "「英知へある人」は不自然。「へ」は方向を示すので、修飾関係にならない。", "から": "「英知からある人」は意味が通らない。「から」は起点を示すので、修飾にならない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもかしこいこと。よくわかること。", "primary_collocate": null, "pronunciation": "えいち", "ipa": "eːtɕi", "syllable_count": 3, "sentences": [{"text": "祖父は長い人生で得た英知を、孫に伝えてくれた。", "target_word": "英知", "complexity_tier": "T3", "furigana": "祖父[そふ]は長[なが]い人生[じんせい]で得[え]た英知[えいち]を、孫[まご]に伝[つた]えてくれた。", "sentence_source": "generated"}, {"text": "人類の英知を集めて、この難しい問題に取り組む。", "target_word": "英知", "complexity_tier": "T3", "furigana": "人類[じんるい]の英知[えいち]を集[あつ]めて、この難[むずか]しい問題[もんだい]に取[と]り組[く]む。", "sentence_source": "generated"}, {"text": "先生の話には、深い英知が感じられた。", "target_word": "英知", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]には、深[ふか]い英知[えいち]が感[かん]じられた。", "sentence_source": "generated"}, {"text": "昔の人の英知のおかげで、この橋は今も丈夫だ。", "target_word": "英知", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]の英知[えいち]のおかげで、この橋[はし]は今[いま]も丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "彼は英知にあふれた人で、みんなが相談に行く。", "target_word": "英知", "complexity_tier": "T3", "furigana": "彼[かれ]は英知[えいち]にあふれた人[ひと]で、みんなが相談[そうだん]に行[い]く。", "sentence_source": "generated"}, {"text": "世界中の英知が集まる会議が、来週開かれる。", "target_word": "英知", "complexity_tier": "T3", "furigana": "世界中[せかいじゅう]の英知[えいち]が集[あつ]まる会議[かいぎ]が、来週[らいしゅう]開[ひら]かれる。", "sentence_source": "generated"}, {"text": "古い本には、先人の英知がたくさん詰まっている。", "target_word": "英知", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]には、先人[せんじん]の英知[えいち]がたくさん詰[つ]まっている。", "sentence_source": "generated"}, {"text": "英知のある人は、困ったときでも落ち着いて考える。", "target_word": "英知", "complexity_tier": "T3", "furigana": "英知[えいち]のある人[ひと]は、困[こま]ったときでも落[お]ち着[つ]いて考[かんが]える。", "sentence_source": "generated"}, {"text": "学校では知識だけでなく、英知も身につけたい。", "target_word": "英知", "complexity_tier": "T3", "furigana": "学校[がっこう]では知識[ちしき]だけでなく、英知[えいち]も身[み]につけたい。", "sentence_source": "generated"}, {"text": "村の長老は英知にあふれた言葉で、争いをおさめた。", "target_word": "英知", "complexity_tier": "T3", "furigana": "村[むら]の長老[ちょうろう]は英知[えいち]にあふれた言葉[ことば]で、争[あらそ]いをおさめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "英知", "label": "基本形"}], "register": "中立", "sense_fingerprint": "とても賢いこと、よく理解できること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英知", "is_correct": true, "explanation": "正解。「得た英知を伝える」は、長年の知恵を次の世代に渡すという意味で自然。"}, {"text": "疲労", "is_correct": false, "explanation": "「得た疲労を孫に伝える」は成り立たない。疲労は伝える対象の知識ではない。"}, {"text": "眠気", "is_correct": false, "explanation": "「得た眠気を孫に伝える」は意味をなさない。眠気は体の感覚で、教えるものではない。"}, {"text": "寒気", "is_correct": false, "explanation": "「得た寒気を孫に伝える」は不自然。寒気は体の感覚で、伝承の対象にはならない。"}], "explanations": {"英知": "正解。「得た英知を伝える」は、長年の知恵を次の世代に渡すという意味で自然。", "疲労": "「得た疲労を孫に伝える」は成り立たない。疲労は伝える対象の知識ではない。", "眠気": "「得た眠気を孫に伝える」は意味をなさない。眠気は体の感覚で、教えるものではない。", "寒気": "「得た寒気を孫に伝える」は不自然。寒気は体の感覚で、伝承の対象にはならない。"}, "sentence_index": 0, "correct_answer": "英知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はこの分野の英知を覚えるため、毎晩勉強している。", "explanation": "ここは〈知識〉の意味。覚えて使う事実の集まりは知識で、英知は深い理解や知恵を指すので覚える対象とは言わない。"}, {"text": "市長は英知を下し、計画を中止した。", "explanation": "ここは〈英断〉（思い切った決断）の意味。英知は知恵のことで、決断を下すとは言わないので合わない。"}, {"text": "彼女は英知が器用で、細かい細工も上手だ。", "explanation": "ここは〈器用さ〉の意味。細工が上手なのは手先の器用さによるもので、英知は知恵を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英知", "is_correct": true, "explanation": "正解。「英知が詰まっている」は、古い本に先人の知恵が多く含まれるという意味で自然。"}, {"text": "湿気", "is_correct": false, "explanation": "「先人の湿気が詰まっている」とは言わない。湿気は空気中の水分で、本の中身にはならない。"}, {"text": "酸素", "is_correct": false, "explanation": "「先人の酸素が詰まっている」は意味をなさない。酸素は気体で、本に詰まる内容ではない。"}, {"text": "体温", "is_correct": false, "explanation": "「先人の体温が詰まっている」は不自然。体温は体の状態で、本に詰まるものではない。"}], "explanations": {"英知": "正解。「英知が詰まっている」は、古い本に先人の知恵が多く含まれるという意味で自然。", "湿気": "「先人の湿気が詰まっている」とは言わない。湿気は空気中の水分で、本の中身にはならない。", "酸素": "「先人の酸素が詰まっている」は意味をなさない。酸素は気体で、本に詰まる内容ではない。", "体温": "「先人の体温が詰まっている」は不自然。体温は体の状態で、本に詰まるものではない。"}, "sentence_index": 6, "correct_answer": "英知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は音楽の英知に恵まれ、若くして表彰された。", "explanation": "ここは〈才能〉の意味。音楽に恵まれるのは才能で、英知は深い知恵を指すので代わりにはならない。"}, {"text": "英知の首相が来週、初めて来日する。", "explanation": "ここは〈英国〉の意味。「英」で始まる似た語だが、英知は国名ではないので首相の所属には使えない。"}, {"text": "この犬は英知が高く、簡単な芸なら一度で覚える。", "explanation": "ここは〈知能〉の意味。物事を理解し覚える力は知能で、英知は深い知恵を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は英知に大切にして、生徒に語りかけた。", "corrected_sentence": "先生は英知を大切にして、生徒に語りかけた。", "error_description": "「大切にする」の対象は助詞「を」で示す。「英知に」は誤りで、正しくは「英知を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52315, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は英知に身につけたいと思い、本を読み続けている。", "corrected_sentence": "彼は英知を身につけたいと思い、本を読み続けている。", "error_description": "「身につける」の対象は助詞「を」で示す。「英知に」は誤りで、正しくは「英知を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「英知は」と主題を示し、「物事の本質を見抜く力にあらわれている」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「英知を」は目的語を示すが、「あらわれる」は自動詞で目的語を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「英知の」と続けても「は」の主題が立たず、文が完結しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、英知が向かう先を表さないので合わない。"}], "correct_answer": "は", "explanations": {"は": "正解。「英知は」と主題を示し、「物事の本質を見抜く力にあらわれている」と続く。", "を": "「英知を」は目的語を示すが、「あらわれる」は自動詞で目的語を取らないので合わない。", "の": "「英知の」と続けても「は」の主題が立たず、文が完結しない。", "へ": "方向の「へ」は、英知が向かう先を表さないので合わない。"}, "error_tags": {"を": "目的格（自動詞に不適合）", "の": "名詞修飾（主題が立たない）", "へ": "方向格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「英知が試される」で、試される側を主語として示す「が」。"}, {"text": "の", "is_correct": false, "explanation": "「英知の試される」は名詞修飾になり、文が述語を失って完結しないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す「より」は、試される主語にならず文が成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は主語を表せず、「英知から試される」は文として不自然なので合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「英知が試される」で、試される側を主語として示す「が」。", "の": "「英知の試される」は名詞修飾になり、文が述語を失って完結しないので合わない。", "より": "比較の基準を示す「より」は、試される主語にならず文が成り立たないので合わない。", "から": "起点を示す「から」は主語を表せず、「英知から試される」は文として不自然なので合わない。"}, "error_tags": {"の": "名詞修飾（述語が欠ける）", "より": "比較格", "から": "起点格（主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すぐれた知恵。物事の本質を深く理解する能力。", "primary_collocate": null, "pronunciation": "えいち", "ipa": "eːtɕi", "syllable_count": 3, "sentences": [{"text": "科学者たちは英知を結集して、新しい薬を開発した。", "target_word": "英知", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]たちは英知[えいち]を結集[けっしゅう]して、新[あたら]しい薬[くすり]を開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "彼女の英知は、物事の本質を見抜く力にあらわれている。", "target_word": "英知", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の英知[えいち]は、物事[ものごと]の本質[ほんしつ]を見抜[みぬ]く力[ちから]にあらわれている。", "sentence_source": "generated"}, {"text": "長い歴史の中で育まれた英知が、この文化を支えている。", "target_word": "英知", "complexity_tier": "T3", "furigana": "長[なが]い歴史[れきし]の中[なか]で育[はぐく]まれた英知[えいち]が、この文化[ぶんか]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "賢い王は、英知をもって国を治めた。", "target_word": "英知", "complexity_tier": "T3", "furigana": "賢[かしこ]い王[おう]は、英知[えいち]をもって国[くに]を治[おさ]めた。", "sentence_source": "generated"}, {"text": "若者の勢いと年長者の英知が合わされば、計画はうまくいく。", "target_word": "英知", "complexity_tier": "T3", "furigana": "若者[わかもの]の勢[いきお]いと年長者[ねんちょうしゃ]の英知[えいち]が合[あ]わされば、計画[けいかく]はうまくいく。", "sentence_source": "generated"}, {"text": "哲学は、人間の英知を深めるための学問である。", "target_word": "英知", "complexity_tier": "T3", "furigana": "哲学[てつがく]は、人間[にんげん]の英知[えいち]を深[ふか]めるための学問[がくもん]である。", "sentence_source": "generated"}, {"text": "彼の判断には、経験に裏打ちされた英知がある。", "target_word": "英知", "complexity_tier": "T3", "furigana": "彼[かれ]の判断[はんだん]には、経験[けいけん]に裏打[うらう]ちされた英知[えいち]がある。", "sentence_source": "generated"}, {"text": "困難な時代こそ、人々の英知が試される。", "target_word": "英知", "complexity_tier": "T3", "furigana": "困難[こんなん]な時代[じだい]こそ、人々[ひとびと]の英知[えいち]が試[ため]される。", "sentence_source": "generated"}, {"text": "大学は、未来を担う人に英知を授ける場所だ。", "target_word": "英知", "complexity_tier": "T3", "furigana": "大学[だいがく]は、未来[みらい]を担[にな]う人[ひと]に英知[えいち]を授[さず]ける場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "古代の人々は、星の動きから暦を作る英知を持っていた。", "target_word": "英知", "complexity_tier": "T3", "furigana": "古代[こだい]の人々[ひとびと]は、星[ほし]の動[うご]きから暦[こよみ]を作[つく]る英知[えいち]を持[も]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "英知", "label": "基本形"}], "register": "中立", "sense_fingerprint": "すぐれた知恵、物事の本質を見抜く力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英知", "is_correct": true, "explanation": "正解。「結集する」の対象として、すぐれた知恵を表す「英知」が合う。"}, {"text": "感情", "is_correct": false, "explanation": "「感情を結集する」は言わず、新しい薬の開発とも結びつかない。"}, {"text": "手順", "is_correct": false, "explanation": "「手順を結集する」は不自然で、薬の開発という文脈に合わない。"}, {"text": "音色", "is_correct": false, "explanation": "「音色を結集する」は意味が通らず、薬の開発とは無関係。"}], "explanations": {"英知": "正解。「結集する」の対象として、すぐれた知恵を表す「英知」が合う。", "感情": "「感情を結集する」は言わず、新しい薬の開発とも結びつかない。", "手順": "「手順を結集する」は不自然で、薬の開発という文脈に合わない。", "音色": "「音色を結集する」は意味が通らず、薬の開発とは無関係。"}, "sentence_index": 0, "correct_answer": "英知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この百科事典には英知がたくさん載っていて、どんな質問にも答えられる。", "explanation": "ここは〈知識〉の意味。英知は事実を多く蓄えた量ではなく、物事を見抜く深い賢さを指すので合わない。"}, {"text": "彼は英知に恵まれていて、どんな楽器も弾きこなす。", "explanation": "ここは〈才能〉の意味。英知は本質を見抜く賢さで、楽器の腕前には使わないので合わない。"}, {"text": "彼女は英知の授業で、ネイティブと話す練習をした。", "explanation": "ここは〈英語〉の意味。英知は「すぐれた知恵」で、言語のことではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英知", "is_correct": true, "explanation": "正解。「経験に裏打ちされた」と合い、判断に備わる深い賢さを指す。"}, {"text": "騒音", "is_correct": false, "explanation": "「判断に騒音がある」は判断の性質として成り立たず、「裏打ちされた」とも結びつかない。"}, {"text": "寝不足", "is_correct": false, "explanation": "判断に寝不足があるとは言わず、経験に裏打ちされるものでもないので合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "「判断に退屈がある」は判断の特徴として不自然で、裏打ちもできない。"}], "explanations": {"英知": "正解。「経験に裏打ちされた」と合い、判断に備わる深い賢さを指す。", "騒音": "「判断に騒音がある」は判断の性質として成り立たず、「裏打ちされた」とも結びつかない。", "寝不足": "判断に寝不足があるとは言わず、経験に裏打ちされるものでもないので合わない。", "退屈": "「判断に退屈がある」は判断の特徴として不自然で、裏打ちもできない。"}, "sentence_index": 6, "correct_answer": "英知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マラソンの最後、彼は英知を振り絞って走った。", "explanation": "ここは〈体力〉の意味。英知は物事を見抜く賢さで、走り続ける力には使わないので合わない。"}, {"text": "この倉庫は英知がとても広く、トラックが何台も入る。", "explanation": "ここは〈広さ〉の意味。英知は物事を見抜く賢さで、場所の広さには使わないので合わない。"}, {"text": "この職人は英知が高く、伝統の工芸品を一つずつ丁寧に作る。", "explanation": "ここは〈技術〉の意味。英知は本質を見抜く賢さで、手仕事の腕前には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者たちは英知を結集して、難しい問題を挑んだ。", "corrected_sentence": "研究者たちは英知を結集して、難しい問題に挑んだ。", "error_description": "「挑む」は助詞「に」で対象を示す。「問題を」は誤りで、正しくは「問題に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52316, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熟練した職人の英知に、この伝統を支えている。", "corrected_sentence": "熟練した職人の英知が、この伝統を支えている。", "error_description": "「支えている」の主語は助詞「が」で示す。「英知に」は誤りで、正しくは「英知が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す格で、「東京」で人生が一緒になったことを表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を取る動詞ではなく、場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「人生が」の主語が既にあり、重ねると文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格で、重なる場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す格で、「東京」で人生が一緒になったことを表し、文に合う。", "を": "目的語を取る動詞ではなく、場所を示せない。", "が": "「人生が」の主語が既にあり、重ねると文が成り立たない。", "から": "起点を示す格で、重なる場所を表せない。"}, "error_tags": {"を": "目的語を取る動詞ではなく、場所を示せない", "が": "主語が既にあり、重ねると文が成り立たない", "から": "起点を示す格で、重なる場所を表せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「同じ現場で交差した」の形で、仕事が重なった場所を表し、文に合う。"}, {"text": "の", "is_correct": false, "explanation": "連体の格で、動詞の直前には置けない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、重なる場所を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格で、重なる場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "「同じ現場で交差した」の形で、仕事が重なった場所を表し、文に合う。", "の": "連体の格で、動詞の直前には置けない。", "へ": "方向を示す格で、重なる場所を表せない。", "から": "起点を示す格で、重なる場所を表せない。"}, "error_tags": {"の": "連体の格で、動詞の直前には置けない", "へ": "方向を示す格で、重なる場所を表せない", "から": "起点を示す格で、重なる場所を表せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものが、一つの場所や時間で、一緒になること。", "primary_collocate": null, "pronunciation": "こうさ", "ipa": "koːsa", "syllable_count": 3, "sentences": [{"text": "二人の旅人の道は、小さな宿屋で交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "二人[ふたり]の旅人[たびびと]の道[みち]は、小[ちい]さな宿屋[やどや]で交差[こうさ]した。", "sentence_source": "generated"}, {"text": "別々に育った兄弟の人生が、大人になってから東京で交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "別々[べつべつ]に育[そだ]った兄弟[きょうだい]の人生[じんせい]が、大人[おとな]になってから東京[とうきょう]で交差[こうさ]した。", "sentence_source": "generated"}, {"text": "あの日の夕方、二人の視線が駅のホームで一瞬だけ交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "あの日[ひ]の夕方[ゆうがた]、二人[ふたり]の視線[しせん]が駅[えき]のホームで一瞬[いっしゅん]だけ交差[こうさ]した。", "sentence_source": "generated"}, {"text": "二隻の船の航路が、霧の深い海で交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "二隻[にせき]の船[ふね]の航路[こうろ]が、霧[きり]の深[ふか]い海[うみ]で交差[こうさ]した。", "sentence_source": "generated"}, {"text": "渡り鳥の群れが夕方の空で交差して、一つの大きな群れになった。", "target_word": "交差", "complexity_tier": "T3", "furigana": "渡[わた]り鳥[どり]の群[む]れが夕方[ゆうがた]の空[そら]で交差[こうさ]して、一[ひと]つの大[おお]きな群[む]れになった。", "sentence_source": "generated"}, {"text": "終電の駅で、別々に帰るはずだった二人の帰り道が交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "終電[しゅうでん]の駅[えき]で、別々[べつべつ]に帰[かえ]るはずだった二人[ふたり]の帰[かえ]り道[みち]が交差[こうさ]した。", "sentence_source": "generated"}, {"text": "祭りの日、二つの行列が広場で交差し、大きな拍手が起こった。", "target_word": "交差", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]、二[ふた]つの行列[ぎょうれつ]が広場[ひろば]で交差[こうさ]し、大[おお]きな拍手[はくしゅ]が起[お]こった。", "sentence_source": "generated"}, {"text": "十年ぶりに、二人の仕事が同じ現場で交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "十年[じゅうねん]ぶりに、二人[ふたり]の仕事[しごと]が同[おな]じ現場[げんば]で交差[こうさ]した。", "sentence_source": "generated"}, {"text": "二人の留学生の生活は、一か月だけ同じ寮で交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "二人[ふたり]の留学生[りゅうがくせい]の生活[せいかつ]は、一[いっ]か月[げつ]だけ同[おな]じ寮[りょう]で交差[こうさ]した。", "sentence_source": "generated"}, {"text": "兄と私の旅の日程が、偶然ローマで交差した。", "target_word": "交差", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]の旅[たび]の日程[にってい]が、偶然[ぐうぜん]ローマで交差[こうさ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交差する", "label": "終止形"}, {"form": "交差した", "label": "過去形"}, {"form": "交差して", "label": "て形"}, {"form": "交差しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "二つのものが同じ場所や時間に重なり合うこと(する名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交差", "is_correct": true, "explanation": "「道は小さな宿屋で交差した」の形で、道が同じ場所で一緒になったことを表す。"}, {"text": "爆発", "is_correct": false, "explanation": "「道は小さな宿屋で爆発した」は意味が通らず、文に合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "「道は小さな宿屋で沸騰した」は道を主語にすると成り立たず、不自然。"}, {"text": "減少", "is_correct": false, "explanation": "「道は小さな宿屋で減少した」は場所と合わず、道の説明として意味が通らない。"}], "explanations": {"交差": "「道は小さな宿屋で交差した」の形で、道が同じ場所で一緒になったことを表す。", "爆発": "「道は小さな宿屋で爆発した」は意味が通らず、文に合わない。", "沸騰": "「道は小さな宿屋で沸騰した」は道を主語にすると成り立たず、不自然。", "減少": "「道は小さな宿屋で減少した」は場所と合わず、道の説明として意味が通らない。"}, "sentence_index": 0, "correct_answer": "交差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二隻の船は同じ港を目指し、ずっと並んで交差していた。", "explanation": "並んで同じ方向へ進む様子には〈交差〉を使わない。一か所で重なるという意味ではない。"}, {"text": "二人は昨日、電話で交差した。", "explanation": "遠く離れて連絡する場面に〈交差〉は使わない。同じ場所や時間に重なる意味ではない。"}, {"text": "二人の答えは、最後の問題で交差せず、大きく食い違った。", "explanation": "〈交差〉は一緒になる意味で、食い違う答えには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交差", "is_correct": true, "explanation": "「二つの行列が広場で交差し」の形で、二つの行列が同じ場所で重なったことを表す。"}, {"text": "増幅", "is_correct": false, "explanation": "「行列が広場で増幅し」は行列の動きとして意味が通らず、文に合わない。"}, {"text": "激減", "is_correct": false, "explanation": "「行列が広場で激減し」は祭りの流れと合わず、文が不自然。"}, {"text": "分解", "is_correct": false, "explanation": "「行列が広場で分解し」は行列の状態として成り立たず、文に合わない。"}], "explanations": {"交差": "「二つの行列が広場で交差し」の形で、二つの行列が同じ場所で重なったことを表す。", "増幅": "「行列が広場で増幅し」は行列の動きとして意味が通らず、文に合わない。", "激減": "「行列が広場で激減し」は祭りの流れと合わず、文が不自然。", "分解": "「行列が広場で分解し」は行列の状態として成り立たず、文に合わない。"}, "sentence_index": 6, "correct_answer": "交差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄と私は、旅先で一人ずつ交差して、別々に帰った。", "explanation": "一人では〈交差〉は成り立たない。二つ以上のものが同じ場所や時間に重なる意味で使う。"}, {"text": "兄と私は、ローマで旅の日程を交差させた。", "explanation": "日程を一緒にする場面は〈調整〉で表す。〈交差〉は重なる意味で、この文の意図とは合わない。"}, {"text": "二人の日程表は、ローマの街で交差して照らし合わされた。", "explanation": "照らし合わせて確かめる意味は〈照合〉で表す。〈交差〉は線や道が出会う意味で当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二隻の貨物船の航路が、霧の深い海で交差させた。", "corrected_sentence": "二隻の貨物船の航路が、霧の深い海で交差した。", "error_description": "「交差させた」は使役で、目的語のない航路が主語では成り立たない。自然に重なる意味には「交差した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52319, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "十年ぶりに、二人の仕事を同じ港で交差した。", "corrected_sentence": "十年ぶりに、二人の仕事が同じ港で交差した。", "error_description": "主語「仕事」に「を」を付けている。主語には「が」を使い、「仕事が同じ港で交差した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す格で、線や道が交わる「この点」を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「交差している」は目的語を取らず、場所を示す「を」は置けない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格で、交わる場所を表せない。"}, {"text": "の", "is_correct": false, "explanation": "連体の格で、動詞の直前には置けない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す格で、線や道が交わる「この点」を表し、文に合う。", "を": "「交差している」は目的語を取らず、場所を示す「を」は置けない。", "から": "起点を示す格で、交わる場所を表せない。", "の": "連体の格で、動詞の直前には置けない。"}, "error_tags": {"を": "目的語を取る動詞ではなく、場所を示せない", "から": "起点を示す格で、交わる場所を表せない", "の": "連体の格で、動詞の直前には置けない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「糸を交差させて」の「を」で、交差させる対象を示し、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語になり、「糸が交差させて」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す格で、交差させる対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、交差させる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「糸を交差させて」の「を」で、交差させる対象を示し、文に合う。", "が": "主語になり、「糸が交差させて」では文が成り立たない。", "に": "場所を示す格で、交差させる対象を表せない。", "へ": "方向を示す格で、交差させる対象を表せない。"}, "error_tags": {"が": "主語になり、「糸が交差させて」では文が成り立たない", "に": "場所を示す格で、交差させる対象を表せない", "へ": "方向を示す格で、交差させる対象を表せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つ以上の線や道が、一つの点で出会うこと。また、物事が互いに関係し合うこと。", "primary_collocate": null, "pronunciation": "こうさ", "ipa": "koːsa", "syllable_count": 3, "sentences": [{"text": "この一連の工程は、自然の摂理と人間の叡智が交差する、紛れもなく芸術的な創造物である。", "target_word": "交差", "complexity_tier": "T4", "furigana": "この一連[いちれん]の工程[こうてい]は、自然[しぜん]の摂理[せつり]と人間[にんげん]の叡智[えいち]が交差[こうさ]する、紛[まぎ]れもなく芸術的[げいじゅつてき]な創造物[そうぞうぶつ]である。", "sentence_source": "mined"}, {"text": "二本の線は、この点で交差している。", "target_word": "交差", "complexity_tier": "T3", "furigana": "二本[にほん]の線[せん]は、この点[てん]で交差[こうさ]している。", "sentence_source": "generated"}, {"text": "駅の前で、二つの大きな道が交差している。", "target_word": "交差", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]で、二[ふた]つの大[おお]きな道[みち]が交差[こうさ]している。", "sentence_source": "generated"}, {"text": "地図を見ると、川と線路が町の北で交差していた。", "target_word": "交差", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、川[かわ]と線路[せんろ]が町[まち]の北[きた]で交差[こうさ]していた。", "sentence_source": "generated"}, {"text": "数学の授業で、二つの直線が交差する点の座標を求めた。", "target_word": "交差", "complexity_tier": "T3", "furigana": "数学[すうがく]の授業[じゅぎょう]で、二[ふた]つの直線[ちょくせん]が交差[こうさ]する点[てん]の座標[ざひょう]を求[もと]めた。", "sentence_source": "generated"}, {"text": "異なる文化が交差する港町には、いろいろな食べ物がある。", "target_word": "交差", "complexity_tier": "T3", "furigana": "異[こと]なる文化[ぶんか]が交差[こうさ]する港町[みなとまち]には、いろいろな食[た]べ物[もの]がある。", "sentence_source": "generated"}, {"text": "彼の研究は、医学と工学が交差する分野にある。", "target_word": "交差", "complexity_tier": "T3", "furigana": "彼[かれ]の研究[けんきゅう]は、医学[いがく]と工学[こうがく]が交差[こうさ]する分野[ぶんや]にある。", "sentence_source": "generated"}, {"text": "糸を交差させて編むと、丈夫な布になる。", "target_word": "交差", "complexity_tier": "T3", "furigana": "糸[いと]を交差[こうさ]させて編[あ]むと、丈夫[じょうぶ]な布[ぬの]になる。", "sentence_source": "generated"}, {"text": "空に飛行機の白い線が交差して、大きな×の形になった。", "target_word": "交差", "complexity_tier": "T3", "furigana": "空[そら]に飛行機[ひこうき]の白[しろ]い線[せん]が交差[こうさ]して、大[おお]きな×[ばつ]の形[かたち]になった。", "sentence_source": "generated"}, {"text": "二人の関心が交差するところに、新しい企画が生まれた。", "target_word": "交差", "complexity_tier": "T3", "furigana": "二人[ふたり]の関心[かんしん]が交差[こうさ]するところに、新[あたら]しい企画[きかく]が生[う]まれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交差する", "label": "終止形"}, {"form": "交差した", "label": "過去形"}, {"form": "交差して", "label": "て形"}, {"form": "交差しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "線や道が一点で交わること、また物事が互いに関わり合うこと(する名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15ff9fe7-707a-4585-aee1-5053efbd78c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交差", "is_correct": true, "explanation": "「交差する」の形で、ものが互いに関係し合うことを表し、ここに入る。"}, {"text": "爆発", "is_correct": false, "explanation": "「摂理と叡智が爆発する」は意味が通らず、文の流れに合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "「摂理と叡智が沸騰する」は比喩としても不自然で、文に合わない。"}, {"text": "減少", "is_correct": false, "explanation": "「摂理と叡智が減少する」は主語と合わず、創造物の説明として成り立たない。"}], "explanations": {"交差": "「交差する」の形で、ものが互いに関係し合うことを表し、ここに入る。", "爆発": "「摂理と叡智が爆発する」は意味が通らず、文の流れに合わない。", "沸騰": "「摂理と叡智が沸騰する」は比喩としても不自然で、文に合わない。", "減少": "「摂理と叡智が減少する」は主語と合わず、創造物の説明として成り立たない。"}, "sentence_index": 0, "correct_answer": "交差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は同じ方向へ並んで歩き、ずっと交差し続けた。", "explanation": "同じ方向に並んで進む様子には〈交差〉を使わない。線や道が一点で出会う意味ではない。"}, {"text": "二本の線は、どこまでも交差したまま、一度も重ならなかった。", "explanation": "〈交差〉は線が出会う意味で、「一度も重ならない」とは矛盾する。平行の場面を表す語。"}, {"text": "彼は部屋の中で、一人きりで交差していた。", "explanation": "〈交差〉は二つ以上のものが出会う意味なので、一人では成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交差", "is_correct": true, "explanation": "「医学と工学が交差する分野」の形で、二つの分野が重なり合う領域を表す。"}, {"text": "凝固", "is_correct": false, "explanation": "「医学と工学が凝固する分野」は意味が通らず、分野の説明として成り立たない。"}, {"text": "氾濫", "is_correct": false, "explanation": "「医学と工学が氾濫する分野」は分野の性質として不自然で、文に合わない。"}, {"text": "腐食", "is_correct": false, "explanation": "「医学と工学が腐食する分野」は分野の説明として成り立たず、意味が通らない。"}], "explanations": {"交差": "「医学と工学が交差する分野」の形で、二つの分野が重なり合う領域を表す。", "凝固": "「医学と工学が凝固する分野」は意味が通らず、分野の説明として成り立たない。", "氾濫": "「医学と工学が氾濫する分野」は分野の性質として不自然で、文に合わない。", "腐食": "「医学と工学が腐食する分野」は分野の説明として成り立たず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "交差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人は昨日、電話で交差した。", "explanation": "電話で連絡する場面に〈交差〉は使わない。線や道が出会う意味ではない。"}, {"text": "二本の線は並んで交差し、どこまでも平行に進んだ。", "explanation": "〈交差〉は線が交わる意味で、「平行に進んだ」とは矛盾する。平行の場面に当たる語。"}, {"text": "二つの報告書の数字は、ひとつずつ交差して確かめられた。", "explanation": "照らし合わせて確かめる意味は〈確認〉で表す。〈交差〉は線や道が出会う意味で、確かめる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの道は、町の中心で交差しいる。", "corrected_sentence": "二つの道は、町の中心で交差している。", "error_description": "「交差している」の「て」が抜けている。「交差しいる」は活用として成り立たず、「交差している」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52320, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの道は、橋の上で交差させている。", "corrected_sentence": "二つの道は、橋の上で交差している。", "error_description": "自動詞「交差する」を使役の「交差させる」に替えている。道が自分で交わる意味には「交差している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '756040c1-37ff-47fa-8b7d-9c1d20b9a3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝ごはんの主食」の「の」。名詞の主食を修飾する正しい形。"}, {"text": "を", "is_correct": false, "explanation": "「朝ごはんを主食は」は目的語の形になり、主語の「は」と合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「朝ごはんへ主食は」は方向の意味になり、主題として成り立たず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「朝ごはんで主食」は手段の意味になり、主食を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「朝ごはんの主食」の「の」。名詞の主食を修飾する正しい形。", "を": "「朝ごはんを主食は」は目的語の形になり、主語の「は」と合わず不自然。", "へ": "「朝ごはんへ主食は」は方向の意味になり、主題として成り立たず不自然。", "で": "「朝ごはんで主食」は手段の意味になり、主食を修飾できない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「お弁当の主食」の「の」。名詞を修飾する正しい形。"}, {"text": "へ", "is_correct": false, "explanation": "「お弁当へ主食は」は方向の意味になり、主食を修飾できない。"}, {"text": "より", "is_correct": false, "explanation": "「お弁当より主食は」は比較の意味になり、文が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「お弁当から主食は」は起点の意味で、主食を説明できない。"}], "correct_answer": "の", "explanations": {"の": "「お弁当の主食」の「の」。名詞を修飾する正しい形。", "へ": "「お弁当へ主食は」は方向の意味になり、主食を修飾できない。", "より": "「お弁当より主食は」は比較の意味になり、文が通らない。", "から": "「お弁当から主食は」は起点の意味で、主食を説明できない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "毎日食べる、一番大事な食べ物のことです。ごはんやパンなどです。", "primary_collocate": null, "pronunciation": "しゅしょく", "ipa": "ɕɯɕokɯ", "syllable_count": 3, "sentences": [{"text": "私の国では、お米が主食です。", "target_word": "主食", "complexity_tier": "T3", "furigana": "私[わたし]の国[くに]では、お米[こめ]が主食[しゅしょく]です。", "sentence_source": "generated"}, {"text": "朝ごはんの主食は、いつもパンです。", "target_word": "主食", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんの主食[しゅしょく]は、いつもパンです。", "sentence_source": "generated"}, {"text": "パンとごはんのどちらを主食にしますか。", "target_word": "主食", "complexity_tier": "T3", "furigana": "パンとごはんのどちらを主食[しゅしょく]にしますか。", "sentence_source": "generated"}, {"text": "この町では、じゃがいもを主食にしている人が多いです。", "target_word": "主食", "complexity_tier": "T3", "furigana": "この町[まち]では、じゃがいもを主食[しゅしょく]にしている人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "主食を食べないと、おなかがすいて力が出ません。", "target_word": "主食", "complexity_tier": "T3", "furigana": "主食[しゅしょく]を食[た]べないと、おなかがすいて力[ちから]が出[で]ません。", "sentence_source": "generated"}, {"text": "おかずは少なくても、主食のごはんだけはしっかり食べたいです。", "target_word": "主食", "complexity_tier": "T3", "furigana": "おかずは少[すく]なくても、主食[しゅしょく]のごはんだけはしっかり食[た]べたいです。", "sentence_source": "generated"}, {"text": "南の地方では米が主食で、北の地方では小麦を食べる人が多いです。", "target_word": "主食", "complexity_tier": "T3", "furigana": "南[みなみ]の地方[ちほう]では米[こめ]が主食[しゅしょく]で、北[きた]の地方[ちほう]では小麦[こむぎ]を食[た]べる人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "お弁当の主食は、おにぎりにしました。", "target_word": "主食", "complexity_tier": "T3", "furigana": "お弁当[べんとう]の主食[しゅしょく]は、おにぎりにしました。", "sentence_source": "generated"}, {"text": "毎日の主食が同じだと、あきてしまうことがあります。", "target_word": "主食", "complexity_tier": "T3", "furigana": "毎日[まいにち]の主食[しゅしょく]が同[おな]じだと、あきてしまうことがあります。", "sentence_source": "generated"}, {"text": "祖母の家では、主食のごはんに、みそ汁と魚がつきます。", "target_word": "主食", "complexity_tier": "T3", "furigana": "祖母[そぼ]の家[いえ]では、主食[しゅしょく]のごはんに、みそ汁[しる]と魚[さかな]がつきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主食", "label": "基本形"}, {"form": "主食の", "label": "連体形"}], "register": "polite", "sense_fingerprint": "毎日の食事でいちばん大事な、ごはんやパンなどの食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主食", "is_correct": true, "explanation": "お米が毎日の食事の中心になる食べ物だと示し、文が通る。"}, {"text": "住所", "is_correct": false, "explanation": "住んでいる場所を表すので、お米の説明に合わない。"}, {"text": "調味料", "is_correct": false, "explanation": "味を調える材料で、お米が何かを表す文に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、お米の説明として成り立たない。"}], "explanations": {"主食": "お米が毎日の食事の中心になる食べ物だと示し、文が通る。", "住所": "住んでいる場所を表すので、お米の説明に合わない。", "調味料": "味を調える材料で、お米が何かを表す文に合わない。", "冷蔵庫": "食品を冷やす家電で、お米の説明として成り立たない。"}, "sentence_index": 0, "correct_answer": "主食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカレーの主食は、玉ねぎです。", "explanation": "ここは〈主材料〉（料理の中心になる材料）の意味。玉ねぎは毎日の食事の中心になる食べ物ではないので、主食とは言わない。"}, {"text": "コーヒーは主食です。", "explanation": "コーヒーは食事の中心になる食べ物ではないので、主食とは言わない。"}, {"text": "味噌汁は主食です。", "explanation": "ここは〈副食〉（主食に添える料理）の意味。味噌汁はご飯に添えるものなので、主食とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主食", "is_correct": true, "explanation": "南の地方で米が毎日の中心となる食べ物だと示し、文が通る。"}, {"text": "方言", "is_correct": false, "explanation": "地域で使われる言葉で、食べ物の説明に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表し、米の説明として成り立たない。"}, {"text": "遠足", "is_correct": false, "explanation": "出かける行事で、食べ物の説明にならない。"}], "explanations": {"主食": "南の地方で米が毎日の中心となる食べ物だと示し、文が通る。", "方言": "地域で使われる言葉で、食べ物の説明に合わない。", "季節": "一年の時期を表し、米の説明として成り立たない。", "遠足": "出かける行事で、食べ物の説明にならない。"}, "sentence_index": 6, "correct_answer": "主食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うちの店の主食は、和菓子です。", "explanation": "ここは〈主力〉（最も力を入れる商品）の意味。和菓子は毎日の食事の中心ではないので、主食とは言わない。"}, {"text": "今度の映画の主食は、あの俳優です。", "explanation": "ここは〈主演〉（主役を演じる人）の意味。俳優は食べ物ではないので、主食とは言わない。"}, {"text": "この本の主食は、家族の大切さです。", "explanation": "ここは〈主題〉（作品の中心テーマ）の意味。テーマは食べ物ではないので、主食とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎朝、パンを主食でしています。", "corrected_sentence": "祖父は毎朝、パンを主食にしています。", "error_description": "「に」を「で」にする誤り。「〜を主食にする」の形で「に」が必要。「で」では文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52321, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日の主食なごはんは、やわらかい方が好きです。", "corrected_sentence": "毎日の主食のごはんは、やわらかい方が好きです。", "error_description": "「な」を「の」にする誤り。名詞「ごはん」を修飾するので「の」が正しい。「な」は名詞の前には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「主食にしている」の「に」。「〜を主食にする」の形で、主食として扱う意味を示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「主食をしている」は「する」の対象が「主食」になり、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「主食でしている」は手段や場所の「で」が「している」と結びつかず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「主食へしている」は方向の「へ」で、「している」の対象にならず不自然。"}], "correct_answer": "に", "explanations": {"に": "「主食にしている」の「に」。「〜を主食にする」の形で、主食として扱う意味を示すので正しい。", "を": "「主食をしている」は「する」の対象が「主食」になり、文が通らない。", "で": "「主食でしている」は手段や場所の「で」が「している」と結びつかず、不自然。", "へ": "「主食へしている」は方向の「へ」で、「している」の対象にならず不自然。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "日常の食事で中心となる食べ物。米、パン、麺類などが代表的。", "primary_collocate": null, "pronunciation": "しゅしょく", "ipa": "ɕɯɕokɯ", "syllable_count": 3, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "主食", "complexity_tier": "T3", "furigana": "微生物[びせいぶつ]の代謝作用[たいしゃさよう]である発酵[はっこう]は、単[たん]なる保存技法[ほぞんぎほう]の域[いき]を超[こ]え、主食[しゅしょく]の持[も]つ潜在能力[せんざいのうりょく]を飛躍的[ひやくてき]に拡張[かくちょう]する化学的芸術[かがくてきげいじゅつ]である。", "sentence_source": "mined"}, {"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "主食", "complexity_tier": "T3", "furigana": "例[たと]えば、穀物[こくもつ]や豆類[まめるい]を主食[しゅしょく]として摂取[せっしゅ]する際[さい]、その細胞壁[さいぼうへき]に阻[はば]まれた栄養[えいよう]は、生体利用率[せいたいりようりつ]が低[ひく]いという宿命[しゅくめい]を背負[せお]っている。", "sentence_source": "mined"}, {"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "主食", "complexity_tier": "T3", "furigana": "さらに、アミノ酸[さん]や有機酸[ゆうきさん]が複雑[ふくざつ]に絡[から]み合[あ]い、主食[しゅしょく]に奥深[おくぶか]い風味[ふうみ]と旨味[うまみ]の層[そう]を付与[ふよ]する。", "sentence_source": "mined"}, {"text": "日本では、米が昔から主食として食べられてきた。", "target_word": "主食", "complexity_tier": "T3", "furigana": "日本[にほん]では、米[こめ]が昔[むかし]から主食[しゅしょく]として食[た]べられてきた。", "sentence_source": "generated"}, {"text": "この地域ではじゃがいもが主食で、毎日の食事に欠かせない。", "target_word": "主食", "complexity_tier": "T3", "furigana": "この地域[ちいき]ではじゃがいもが主食[しゅしょく]で、毎日[まいにち]の食事[しょくじ]に欠[か]かせない。", "sentence_source": "generated"}, {"text": "主食と主菜と副菜をそろえると、栄養のバランスがよくなる。", "target_word": "主食", "complexity_tier": "T3", "furigana": "主食[しゅしょく]と主菜[しゅさい]と副菜[ふくさい]をそろえると、栄養[えいよう]のバランスがよくなる。", "sentence_source": "generated"}, {"text": "ダイエット中でも、主食を抜きすぎると力が出なくなってしまう。", "target_word": "主食", "complexity_tier": "T3", "furigana": "ダイエット中[ちゅう]でも、主食[しゅしょく]を抜[ぬ]きすぎると力[ちから]が出[で]なくなってしまう。", "sentence_source": "generated"}, {"text": "南米では、とうもろこしを主食にしている国が多い。", "target_word": "主食", "complexity_tier": "T3", "furigana": "南米[なんべい]では、とうもろこしを主食[しゅしょく]にしている国[くに]が多[おお]い。", "sentence_source": "generated"}, {"text": "弟はパンが主食で、朝も昼もパンしか食べない。", "target_word": "主食", "complexity_tier": "T3", "furigana": "弟[おとうと]はパンが主食[しゅしょく]で、朝[あさ]も昼[ひる]もパンしか食[た]べない。", "sentence_source": "generated"}, {"text": "夕食の主食をご飯にするか麺にするか、家族で話し合った。", "target_word": "主食", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]の主食[しゅしょく]をご飯[はん]にするか麺[めん]にするか、家族[かぞく]で話[はな]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主食", "label": "基本形"}, {"form": "主食として", "label": "として形"}], "register": "標準", "sense_fingerprint": "食事の中心となる、米・パン・麺類などの食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主食", "is_correct": true, "explanation": "食事の中心となる食べ物を指し、発酵が潜在能力を拡張する対象として文が成り立つ。"}, {"text": "食器", "is_correct": false, "explanation": "食べ物を盛る道具で、化学的芸術の対象として文が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、潜在能力を拡張する対象にならない。"}, {"text": "包丁", "is_correct": false, "explanation": "食材を切る道具で、発酵の対象として文が成り立たない。"}], "explanations": {"主食": "食事の中心となる食べ物を指し、発酵が潜在能力を拡張する対象として文が成り立つ。", "食器": "食べ物を盛る道具で、化学的芸術の対象として文が通らない。", "冷蔵庫": "食品を冷やす家電で、潜在能力を拡張する対象にならない。", "包丁": "食材を切る道具で、発酵の対象として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "主食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の主食は、肉料理が人気だ。", "explanation": "ここは〈主菜〉（献立の中心になるおかず）の意味。肉料理は主食ではないので、この言葉では合わない。"}, {"text": "コーヒーは主食として楽しまれている。", "explanation": "コーヒーは食事の中心になる食べ物ではないので、主食とは言わない。"}, {"text": "味噌汁は主食として、ご飯に添えられる。", "explanation": "ここは〈副食〉（主食に添えるおかず）の意味。味噌汁はご飯に添える料理なので、主食とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主食", "is_correct": true, "explanation": "抜きすぎると力が出なくなる食事の中心の食べ物で、文の意味に合う。"}, {"text": "料金", "is_correct": false, "explanation": "支払う金額で、抜きすぎるという文脈に合わない。"}, {"text": "電話", "is_correct": false, "explanation": "連絡する道具や行為で、抜く対象にならない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う小さな券で、抜く対象として文が成り立たない。"}], "explanations": {"主食": "抜きすぎると力が出なくなる食事の中心の食べ物で、文の意味に合う。", "料金": "支払う金額で、抜きすぎるという文脈に合わない。", "電話": "連絡する道具や行為で、抜く対象にならない。", "切手": "郵便に使う小さな券で、抜く対象として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "主食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小説の主食は、家族の再生だ。", "explanation": "ここは〈主題〉（作品の中心テーマ）の意味。テーマは食べ物ではないので、主食とは言わない。"}, {"text": "この映画の主食は、新人の俳優だ。", "explanation": "ここは〈主演〉（主役を演じる人）の意味。俳優は食べ物ではないので、主食とは言わない。"}, {"text": "このチームの主食は、若手の選手だ。", "explanation": "ここは〈主力〉（中心となる戦力）の意味。選手は食べ物ではないので、主食とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の主食で、玄米を食べている。", "corrected_sentence": "毎日の主食として、玄米を食べている。", "error_description": "「として」を「で」にした誤り。役割を示す「として」が必要で、「で」では文が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52322, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は、パンが主食にしている。", "corrected_sentence": "弟は、パンを主食にしている。", "error_description": "「が」を「を」にする誤り。「主食にする」の対象は「を」で示す。「が」にすると主語が二つになり文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べ物を摂取してはいけない」の目的語を示す格助詞。ここに入るのはこれだけ。"}, {"text": "に", "is_correct": false, "explanation": "「食べ物に摂取してはいけない」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「食べ物へ摂取する」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「食べ物より摂取してはいけない」は文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「食べ物を摂取してはいけない」の目的語を示す格助詞。ここに入るのはこれだけ。", "に": "「食べ物に摂取してはいけない」は成り立たない。", "へ": "「へ」は方向を示すため、「食べ物へ摂取する」は不自然。", "より": "「より」は比較を示すため、「食べ物より摂取してはいけない」は文が通らない。"}, "error_tags": {"に": "着点・相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お酒を摂取したあと」の目的語を示す格助詞。ここに入るのはこれだけ。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「お酒から摂取したあと」は目的語として合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共にする相手を示し、「お酒と摂取したあと」は文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示し、「お酒で摂取したあと」は目的語を示せないため不自然。"}], "correct_answer": "を", "explanations": {"を": "「お酒を摂取したあと」の目的語を示す格助詞。ここに入るのはこれだけ。", "から": "「から」は起点を示し、「お酒から摂取したあと」は目的語として合わない。", "と": "「と」は共にする相手を示し、「お酒と摂取したあと」は文脈に合わない。", "で": "「で」は手段を示し、「お酒で摂取したあと」は目的語を示せないため不自然。"}, "error_tags": {"から": "起点", "と": "共同・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べ物や飲み物を体の中に入れること。", "primary_collocate": null, "pronunciation": "せっしゅ", "ipa": "seɕɕɯ", "syllable_count": 3, "sentences": [{"text": "水分を摂取しないと、夏は熱中症になる危険がある。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "水分[すいぶん]を摂取[せっしゅ]しないと、夏[なつ]は熱中症[ねっちゅうしょう]になる危険[きけん]がある。", "sentence_source": "generated"}, {"text": "手術の前は、食べ物を摂取してはいけないと医者に言われた。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]の前[まえ]は、食[た]べ物[もの]を摂取[せっしゅ]してはいけないと医者[いしゃ]に言[い]われた。", "sentence_source": "generated"}, {"text": "赤ちゃんがミルクを摂取できないと、体重が増えにくい。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんがミルクを摂取[せっしゅ]できないと、体重[たいじゅう]が増[ふ]えにくい。", "sentence_source": "generated"}, {"text": "朝は何も摂取せずに家を出ると、昼までに力が出なくなる。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "朝[あさ]は何[なに]も摂取[せっしゅ]せずに家[いえ]を出[で]ると、昼[ひる]までに力[ちから]が出[で]なくなる。", "sentence_source": "generated"}, {"text": "山で遭難した人は、わずかな水を摂取して救助を待った。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "山[やま]で遭難[そうなん]した人[ひと]は、わずかな水[みず]を摂取[せっしゅ]して救助[きゅうじょ]を待[ま]った。", "sentence_source": "generated"}, {"text": "この薬を飲む前後は、牛乳を摂取しないでください。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "この薬[くすり]を飲[の]む前後[ぜんご]は、牛乳[ぎゅうにゅう]を摂取[せっしゅ]しないでください。", "sentence_source": "generated"}, {"text": "食事を摂取する力が弱くなった高齢者のために、やわらかい料理が出される。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "食事[しょくじ]を摂取[せっしゅ]する力[ちから]が弱[よわ]くなった高齢者[こうれいしゃ]のために、やわらかい料理[りょうり]が出[だ]される。", "sentence_source": "generated"}, {"text": "お酒を摂取したあとは、車の運転をしてはいけない。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "お酒[さけ]を摂取[せっしゅ]したあとは、車[くるま]の運転[うんてん]をしてはいけない。", "sentence_source": "generated"}, {"text": "毎日三回、決まった時間に食事を摂取するようにしている。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "毎日[まいにち]三回[さんかい]、決[き]まった時間[じかん]に食事[しょくじ]を摂取[せっしゅ]するようにしている。", "sentence_source": "generated"}, {"text": "動物園では、動物が毎日どれだけ餌を摂取したかを記録している。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、動物[どうぶつ]が毎日[まいにち]どれだけ餌[えさ]を摂取[せっしゅ]したかを記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "摂取", "label": "基本形"}, {"form": "摂取する", "label": "する形"}, {"form": "摂取した", "label": "過去形"}, {"form": "摂取せず", "label": "否定形"}], "register": "文章語", "sense_fingerprint": "食べ物や飲み物を口から体の中に入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摂取", "is_correct": true, "explanation": "「水分を摂取しないと熱中症になる」の空所で、飲み物を体に入れる意味に合う。ここに入るのはこの語だけ。"}, {"text": "運搬", "is_correct": false, "explanation": "「水分を運搬しないと」は文脈に合わない。"}, {"text": "点検", "is_correct": false, "explanation": "「水分を点検しないと熱中症になる」は成り立たない。"}, {"text": "放送", "is_correct": false, "explanation": "「水分を放送しない」は意味をなさない。"}], "explanations": {"摂取": "「水分を摂取しないと熱中症になる」の空所で、飲み物を体に入れる意味に合う。ここに入るのはこの語だけ。", "運搬": "「水分を運搬しないと」は文脈に合わない。", "点検": "「水分を点検しないと熱中症になる」は成り立たない。", "放送": "「水分を放送しない」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "摂取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事の合間に十分に睡眠を摂取して、体を休めた。", "explanation": "ここは〈休息〉の意味。睡眠は食べ物や飲み物ではないので、〈摂取〉は合わない。"}, {"text": "山の空気を摂取して、胸いっぱいに吸った。", "explanation": "ここは〈吸う〉の意味。空気は〈吸う〉で表し、〈摂取〉は食べ物や飲み物に使うので合わない。"}, {"text": "店員は代金を摂取して、レシートを渡した。", "explanation": "ここは〈受領〉の意味。代金を受け取るのは〈受領〉で、〈摂取〉は食べ物や飲み物を体に入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摂取", "is_correct": true, "explanation": "「食事を摂取する力が弱くなった」の空所で、口から食べ物を取り入れる意味に合う。ここに入るのはこの語だけ。"}, {"text": "温度", "is_correct": false, "explanation": "「食事を温度する力」は成り立たない。"}, {"text": "騒音", "is_correct": false, "explanation": "「食事を騒音する力」は意味が通らない。"}, {"text": "機械", "is_correct": false, "explanation": "「食事を機械する力」は成り立たない。"}], "explanations": {"摂取": "「食事を摂取する力が弱くなった」の空所で、口から食べ物を取り入れる意味に合う。ここに入るのはこの語だけ。", "温度": "「食事を温度する力」は成り立たない。", "騒音": "「食事を騒音する力」は意味が通らない。", "機械": "「食事を機械する力」は成り立たない。"}, "sentence_index": 6, "correct_answer": "摂取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生はテストの答案を摂取して、点数を書き込んだ。", "explanation": "ここは〈採点〉の意味。答案に点をつけるのは〈採点〉で、〈摂取〉は体に取り入れる意味なので合わない。"}, {"text": "バスは燃料を摂取して、ターミナルを出発した。", "explanation": "ここは〈補給〉の意味。燃料を入れるのは〈補給〉で、〈摂取〉は生き物が食べ物などを取り入れる場合に使うので合わない。"}, {"text": "アンケートの結果を摂取して、グラフにまとめた。", "explanation": "ここは〈集計〉の意味。数をまとめるのは〈集計〉で、〈摂取〉は体に取り入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お茶をたくさん摂取すので、夜中に目が覚めた。", "corrected_sentence": "お茶をたくさん摂取したので、夜中に目が覚めた。", "error_description": "前の出来事を表す過去形は「摂取した」が正しい。「摂取す」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52323, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カフェインの摂取で、夜を避けるのがよい。", "corrected_sentence": "カフェインの摂取は、夜を避けるのがよい。", "error_description": "「摂取」に続けて主題を示すには「は」が正しい。「で」は手段や場所を表すため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「塩分の摂取が多すぎる」の主語を示す格助詞。ここに入るのはこれだけ。"}, {"text": "を", "is_correct": false, "explanation": "「多すぎる」の主語は「摂取が」になるので、目的語を示す「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「摂取に多すぎる」は成り立たない。「に」は相手や位置を示すため不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「摂取で多すぎる」は主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「塩分の摂取が多すぎる」の主語を示す格助詞。ここに入るのはこれだけ。", "を": "「多すぎる」の主語は「摂取が」になるので、目的語を示す「を」は合わない。", "に": "「摂取に多すぎる」は成り立たない。「に」は相手や位置を示すため不自然。", "で": "「で」は手段や場所を示すため、「摂取で多すぎる」は主語を示せない。"}, "error_tags": {"を": "目的語マーカー", "に": "着点・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「鉄分を摂取する」の目的語を示す格助詞。ここに入るのはこれだけ。"}, {"text": "へ", "is_correct": false, "explanation": "「鉄分へ摂取する」は方向を示すため不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「鉄分から摂取する」は目的語として合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「鉄分より摂取する」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「鉄分を摂取する」の目的語を示す格助詞。ここに入るのはこれだけ。", "へ": "「鉄分へ摂取する」は方向を示すため不自然。", "から": "「から」は起点を示し、「鉄分から摂取する」は目的語として合わない。", "より": "「より」は比較を示すため、「鉄分より摂取する」は成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "栄養や成分などを体内に取り入れること。", "primary_collocate": null, "pronunciation": "せっしゅ", "ipa": "seɕɕɯ", "syllable_count": 3, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "例[たと]えば、穀物[こくもつ]や豆類[まめるい]を主食[しゅしょく]として摂取[せっしゅ]する際[さい]、その細胞壁[さいぼうへき]に阻[はば]まれた栄養[えいよう]は、生体利用率[せいたいりようりつ]が低[ひく]いという宿命[しゅくめい]を背負[せお]っている。", "sentence_source": "mined"}, {"text": "塩分の摂取が多すぎると、血圧が上がりやすくなる。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "塩分[えんぶん]の摂取[せっしゅ]が多[おお]すぎると、血圧[けつあつ]が上[あ]がりやすくなる。", "sentence_source": "generated"}, {"text": "カルシウムを十分に摂取するために、毎日牛乳を飲んでいる。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "カルシウムを十分[じゅうぶん]に摂取[せっしゅ]するために、毎日[まいにち]牛乳[ぎゅうにゅう]を飲[の]んでいる。", "sentence_source": "generated"}, {"text": "ビタミンDは、日光を浴びるだけでなく、食事からも摂取できる。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "ビタミンDは、日光[にっこう]を浴[あ]びるだけでなく、食事[しょくじ]からも摂取[せっしゅ]できる。", "sentence_source": "generated"}, {"text": "運動のあとは、たんぱく質を早めに摂取すると筋肉の回復によい。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、たんぱく質[しつ]を早[はや]めに摂取[せっしゅ]すると筋肉[きんにく]の回復[かいふく]によい。", "sentence_source": "generated"}, {"text": "カフェインを摂取しすぎると、夜に眠れなくなることがある。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "カフェインを摂取[せっしゅ]しすぎると、夜[よる]に眠[ねむ]れなくなることがある。", "sentence_source": "generated"}, {"text": "医師は、糖分の摂取を控えるように患者に伝えた。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "医師[いし]は、糖分[とうぶん]の摂取[せっしゅ]を控[ひか]えるように患者[かんじゃ]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "サプリメントで鉄分を摂取する前に、まず食事の内容を見直すべきだ。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "サプリメントで鉄分[てつぶん]を摂取[せっしゅ]する前[まえ]に、まず食事[しょくじ]の内容[ないよう]を見直[みなお]すべきだ。", "sentence_source": "generated"}, {"text": "食物繊維を摂取すれば、腸の調子が整うと言われている。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "食物繊維[しょくもつせんい]を摂取[せっしゅ]すれば、腸[ちょう]の調子[ちょうし]が整[ととの]うと言[い]われている。", "sentence_source": "generated"}, {"text": "この調査では、日本人がどれくらい食塩を摂取しているかを調べた。", "target_word": "摂取", "complexity_tier": "T3", "furigana": "この調査[ちょうさ]では、日本人[にほんじん]がどれくらい食塩[しょくえん]を摂取[せっしゅ]しているかを調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "摂取", "label": "基本形"}, {"form": "摂取する", "label": "する形"}, {"form": "摂取した", "label": "過去形"}, {"form": "摂取できる", "label": "可能形"}], "register": "文章語", "sense_fingerprint": "栄養素や成分(塩分・ビタミン・カフェインなど)を体に取り入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摂取", "is_correct": true, "explanation": "「主食として〜する際」の文脈で、栄養を体に取り入れる動作を表す。ここに入るのはこの語だけ。"}, {"text": "運動", "is_correct": false, "explanation": "「主食として運動する際」は文として成り立たない。"}, {"text": "相談", "is_correct": false, "explanation": "「主食として相談する際」は意味が通らない。"}, {"text": "点検", "is_correct": false, "explanation": "「主食として点検する際」は文脈に合わない。"}], "explanations": {"摂取": "「主食として〜する際」の文脈で、栄養を体に取り入れる動作を表す。ここに入るのはこの語だけ。", "運動": "「主食として運動する際」は文として成り立たない。", "相談": "「主食として相談する際」は意味が通らない。", "点検": "「主食として点検する際」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "摂取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腎臓は血液から老廃物を摂取して、尿として体の外へ出す。", "explanation": "ここは〈排泄〉の意味。老廃物を体の外へ出すのは〈排泄〉で、〈摂取〉は体に取り入れる意味なので合わない。"}, {"text": "観光客の写真を摂取して、ホテルのロビーに飾った。", "explanation": "ここは〈撮影〉の意味。写真を撮ることは〈撮影〉で、〈摂取〉は栄養や食べ物に使うので合わない。"}, {"text": "乾いた砂が雨水を一瞬で摂取した。", "explanation": "ここは〈吸収〉の意味。砂のように液体を吸い込む場合は〈吸収〉を使い、〈摂取〉は生き物が栄養を取り入れる場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摂取", "is_correct": true, "explanation": "「糖分の摂取を控える」の空所で、食べる量を減らす意味に合う。ここに入るのはこの語だけ。"}, {"text": "温度", "is_correct": false, "explanation": "「糖分の温度を控える」は意味が通らない。"}, {"text": "騒音", "is_correct": false, "explanation": "「糖分の騒音」は文脈に合わない。"}, {"text": "機械", "is_correct": false, "explanation": "「糖分の機械を控える」は成り立たない。"}], "explanations": {"摂取": "「糖分の摂取を控える」の空所で、食べる量を減らす意味に合う。ここに入るのはこの語だけ。", "温度": "「糖分の温度を控える」は意味が通らない。", "騒音": "「糖分の騒音」は文脈に合わない。", "機械": "「糖分の機械を控える」は成り立たない。"}, "sentence_index": 6, "correct_answer": "摂取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車は燃料を摂取して走る。", "explanation": "ここは〈消費〉の意味。燃料を使うのは〈消費〉で、〈摂取〉は体に取り入れる場合に使うので合わない。"}, {"text": "図書館で借りた本を摂取して返した。", "explanation": "ここは〈返却〉の意味。本を戻すのは〈返却〉で、〈摂取〉は食べ物や栄養に使うので合わない。"}, {"text": "会社は新人の意見を摂取して、来年の方針に決めた。", "explanation": "ここは〈採用〉の意味。意見を取り入れて決めるのは〈採用〉で、〈摂取〉は体に取り入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日、食事からビタミンを摂取しると体によい。", "corrected_sentence": "毎日、食事からビタミンを摂取すると体によい。", "error_description": "「摂取する」に仮定の「と」を続けると「摂取すると」になる。「摂取しる」という活用は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52324, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前は水分の摂取で控える。", "corrected_sentence": "寝る前は水分の摂取を控える。", "error_description": "「控える」は「〜を控える」の形で、目的語は「を」で示す。「摂取で」の「で」は誤りで、「摂取を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「台所を拡張した」の目的語を示す格助詞。ここに入るのはこれだけ。"}, {"text": "に", "is_correct": false, "explanation": "「台所に拡張した」は着点を示すため、目的語として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「台所へ拡張した」は方向を示すため、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共にする相手を示すが、「台所と拡張した」は文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「台所を拡張した」の目的語を示す格助詞。ここに入るのはこれだけ。", "に": "「台所に拡張した」は着点を示すため、目的語として合わない。", "へ": "「台所へ拡張した」は方向を示すため、文が通らない。", "と": "「と」は共にする相手を示すが、「台所と拡張した」は文が通らない。"}, "error_tags": {"に": "着点", "へ": "方向", "と": "共同・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "「売り場の拡張」の対義語。売り場を縮めることに当たる。"}, {"text": "維持", "is_correct": false, "explanation": "「維持」は現状を保つ意味で、拡張の対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "「保存」は残す意味で、拡張の対義語ではない。"}, {"text": "固定", "is_correct": false, "explanation": "「固定」は動かないようにする意味で、拡張の対義語とは言えない。"}], "correct_answer": "縮小", "explanations": {"縮小": "「売り場の拡張」の対義語。売り場を縮めることに当たる。", "維持": "「維持」は現状を保つ意味で、拡張の対義語ではない。", "保存": "「保存」は残す意味で、拡張の対義語ではない。", "固定": "「固定」は動かないようにする意味で、拡張の対義語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「工場の拡張にともない」の「に」で、「ともなう」と結びつく格助詞。ここに入るのはこれだけ。"}, {"text": "を", "is_correct": false, "explanation": "「拡張をともない」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「拡張でともない」は文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「拡張よりともない」は意味をなさない。"}], "correct_answer": "に", "explanations": {"に": "「工場の拡張にともない」の「に」で、「ともなう」と結びつく格助詞。ここに入るのはこれだけ。", "を": "「拡張をともない」は成り立たない。", "で": "「拡張でともない」は文が通らない。", "より": "「より」は比較を示すため、「拡張よりともない」は意味をなさない。"}, "error_tags": {"へ": "方向", "で": "手段", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "「ダムの拡張工事」の対義語。ダムを縮めることに当たる。"}, {"text": "停止", "is_correct": false, "explanation": "「停止」は止まる意味で、拡張の対義語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "「安定」は変わらない状態で、拡張の対義語ではない。"}, {"text": "保留", "is_correct": false, "explanation": "「保留」は決めずに残す意味で、拡張の対義語ではない。"}], "correct_answer": "縮小", "explanations": {"縮小": "「ダムの拡張工事」の対義語。ダムを縮めることに当たる。", "停止": "「停止」は止まる意味で、拡張の対義語ではない。", "安定": "「安定」は変わらない状態で、拡張の対義語ではない。", "保留": "「保留」は決めずに残す意味で、拡張の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを大きくしたり、広げたりすること。", "primary_collocate": null, "pronunciation": "かくちょう", "ipa": "kakɯtɕoː", "syllable_count": 4, "sentences": [{"text": "市は駅前の道路を拡張する工事を始めた。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "市[し]は駅前[えきまえ]の道路[どうろ]を拡張[かくちょう]する工事[こうじ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "子どもが生まれたので、この家は台所を拡張した。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "子[こ]どもが生[う]まれたので、この家[いえ]は台所[だいどころ]を拡張[かくちょう]した。", "sentence_source": "generated"}, {"text": "パソコンのメモリを拡張すれば、動きが速くなる。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "パソコンのメモリを拡張[かくちょう]すれば、動[うご]きが速[はや]くなる。", "sentence_source": "generated"}, {"text": "客が増えて、店は売り場の拡張が必要になった。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "客[きゃく]が増[ふ]えて、店[みせ]は売[う]り場[ば]の拡張[かくちょう]が必要[ひつよう]になった。", "sentence_source": "generated"}, {"text": "空港の滑走路が拡張され、大きな飛行機も降りられるようになった。", "target_word": "拡張", "complexity_tier": "T4", "furigana": "空港[くうこう]の滑走路[かっそうろ]が拡張[かくちょう]され、大[おお]きな飛行機[ひこうき]も降[お]りられるようになった。", "sentence_source": "generated"}, {"text": "公園を拡張するために、市は隣の土地を買った。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "公園[こうえん]を拡張[かくちょう]するために、市[し]は隣[となり]の土地[とち]を買[か]った。", "sentence_source": "generated"}, {"text": "庭が狭いので、塀を後ろへ動かして拡張したい。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "庭[にわ]が狭[せま]いので、塀[へい]を後[うし]ろへ動[うご]かして拡張[かくちょう]したい。", "sentence_source": "generated"}, {"text": "工場の拡張にともない、新しい社員を募集している。", "target_word": "拡張", "complexity_tier": "T4", "furigana": "工場[こうじょう]の拡張[かくちょう]にともない、新[あたら]しい社員[しゃいん]を募集[ぼしゅう]している。", "sentence_source": "generated"}, {"text": "この棚は横に拡張できるので、本が増えても困らない。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "この棚[たな]は横[よこ]に拡張[かくちょう]できるので、本[ほん]が増[ふ]えても困[こま]らない。", "sentence_source": "generated"}, {"text": "ダムの拡張工事のため、山の道は通れなくなっている。", "target_word": "拡張", "complexity_tier": "T4", "furigana": "ダムの拡張[かくちょう]工事[こうじ]のため、山[やま]の道[みち]は通[とお]れなくなっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拡張", "label": "dictionary form"}, {"form": "拡張する", "label": "plain non-past"}, {"form": "拡張した", "label": "plain past"}, {"form": "拡張される", "label": "passive"}], "register": "neutral", "sense_fingerprint": "道路・建物・容量など具体的なものを大きく広げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拡張", "is_correct": true, "explanation": "「道路を拡張する工事」で、道幅を広げる動作に合う。ここに入るのはこの語だけ。"}, {"text": "作曲", "is_correct": false, "explanation": "「道路を作曲する工事」は成り立たない。"}, {"text": "配達", "is_correct": false, "explanation": "「道路を配達する工事」は文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "「道路を注文する工事」は意味をなさない。"}], "explanations": {"拡張": "「道路を拡張する工事」で、道幅を広げる動作に合う。ここに入るのはこの語だけ。", "作曲": "「道路を作曲する工事」は成り立たない。", "配達": "「道路を配達する工事」は文脈に合わない。", "注文": "「道路を注文する工事」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "拡張"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "閉店後、店員は床を拡張して、丁寧に掃除した。", "explanation": "ここは〈清掃〉の意味。汚れを落とすのは〈清掃〉で、〈拡張〉は大きさを広げる意味なので合わない。"}, {"text": "古い電球を拡張して、天井の明かりを変えた。", "explanation": "ここは〈交換〉の意味。古いものを新しいものに替えるのは〈交換〉で、〈拡張〉は広げる意味なので合わない。"}, {"text": "店の客が拡張して、昼には行列ができた。", "explanation": "ここは〈増加〉の意味。人の数が多くなるのは〈増加〉で、〈拡張〉は場所や設備を広げる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拡張", "is_correct": true, "explanation": "「塀を後ろへ動かして拡張したい」で、敷地を広げる意味に合う。ここに入るのはこの語だけ。"}, {"text": "録音", "is_correct": false, "explanation": "「塀を録音したい」は文脈に合わない。"}, {"text": "解説", "is_correct": false, "explanation": "「塀を解説したい」は成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「塀を翻訳したい」は意味をなさない。"}], "explanations": {"拡張": "「塀を後ろへ動かして拡張したい」で、敷地を広げる意味に合う。ここに入るのはこの語だけ。", "録音": "「塀を録音したい」は文脈に合わない。", "解説": "「塀を解説したい」は成り立たない。", "翻訳": "「塀を翻訳したい」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "拡張"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "倒れた木を拡張する工事のため、山の道は通れない。", "explanation": "ここは〈撤去〉の意味。倒れた木を取り除くのは〈撤去〉で、〈拡張〉は広げる意味なので合わない。"}, {"text": "食材を拡張するため、台所は一時使えなくなっている。", "explanation": "ここは〈消毒〉の意味。菌を殺すのは〈消毒〉で、〈拡張〉は広げる意味なので合わない。"}, {"text": "庭の草を拡張して、まとめて刈った。", "explanation": "ここは〈刈る〉の意味。草を切り取るのは〈刈る〉で、〈拡張〉は大きさや範囲を広げる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場の設備を拡張しると、生産量が増える。", "corrected_sentence": "工場の設備を拡張すると、生産量が増える。", "error_description": "「拡張する」に「と」を続けると「拡張すると」になる。「拡張しる」という形は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52325, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空港の滑走路の拡張で、来年から始まる。", "corrected_sentence": "空港の滑走路の拡張は、来年から始まる。", "error_description": "「拡張」に続けて主題を示すには「は」が正しい。「で」は手段や場所を表すため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "「受け入れ枠を拡張する」の対義語。受け入れ枠を縮めることに当たる。"}, {"text": "維持", "is_correct": false, "explanation": "「維持」は現状を保つ意味で、拡張の対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "「保存」は残しておく意味で、拡張の対義語ではない。"}, {"text": "固定", "is_correct": false, "explanation": "「固定」は動かないようにする意味で、拡張の対義語とは言えない。"}], "correct_answer": "縮小", "explanations": {"縮小": "「受け入れ枠を拡張する」の対義語。受け入れ枠を縮めることに当たる。", "維持": "「維持」は現状を保つ意味で、拡張の対義語ではない。", "保存": "「保存」は残しておく意味で、拡張の対義語ではない。", "固定": "「固定」は動かないようにする意味で、拡張の対義語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「権限が拡張された」の主語を示す格助詞。ここに入るのはこれだけ。"}, {"text": "を", "is_correct": false, "explanation": "「権限を拡張された」は受け身の主語にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示し、「権限で拡張された」は主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「権限より拡張された」は文が通らない。"}], "correct_answer": "が", "explanations": {"が": "「権限が拡張された」の主語を示す格助詞。ここに入るのはこれだけ。", "を": "「権限を拡張された」は受け身の主語にならず不自然。", "で": "「で」は手段を示し、「権限で拡張された」は主語を示せない。", "より": "「より」は比較を示すため、「権限より拡張された」は文が通らない。"}, "error_tags": {"を": "目的語マーカー", "で": "手段", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "「観測できる範囲の拡張」の対義語。範囲を縮めることに当たる。"}, {"text": "停止", "is_correct": false, "explanation": "「停止」は動きを止める意味で、拡張の対義語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "「安定」は変わらない状態を保つ意味で、拡張の対義語ではない。"}, {"text": "保留", "is_correct": false, "explanation": "「保留」は決めずに残す意味で、拡張の対義語ではない。"}], "correct_answer": "縮小", "explanations": {"縮小": "「観測できる範囲の拡張」の対義語。範囲を縮めることに当たる。", "停止": "「停止」は動きを止める意味で、拡張の対義語ではない。", "安定": "「安定」は変わらない状態を保つ意味で、拡張の対義語ではない。", "保留": "「保留」は決めずに残す意味で、拡張の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "範囲や能力を、今よりももっと大きく広げること。", "primary_collocate": null, "pronunciation": "かくちょう", "ipa": "kakɯtɕoː", "syllable_count": 4, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "拡張", "complexity_tier": "T5", "furigana": "微生物[びせいぶつ]の代謝[たいしゃ]作用[さよう]である発酵[はっこう]は、単[たん]なる保存[ほぞん]技法[ぎほう]の域[いき]を超[こ]え、主食[しゅしょく]の持[も]つ潜在[せんざい]能力[のうりょく]を飛躍的[ひやくてき]に拡張[かくちょう]する化学的[かがくてき]芸術[げいじゅつ]である。", "sentence_source": "mined"}, {"text": "会社は海外にも客を広げるため、事業の範囲を拡張することにした。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は海外[かいがい]にも客[きゃく]を広[ひろ]げるため、事業[じぎょう]の範囲[はんい]を拡張[かくちょう]することにした。", "sentence_source": "generated"}, {"text": "この追加ソフトを入れれば、アプリの機能を拡張できる。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "この追加[ついか]ソフトを入[い]れれば、アプリの機能[きのう]を拡張[かくちょう]できる。", "sentence_source": "generated"}, {"text": "学校は留学生の受け入れ枠を拡張し、より多くの生徒を迎えた。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "学校[がっこう]は留学生[りゅうがくせい]の受[う]け入[い]れ枠[わく]を拡張[かくちょう]し、より多[おお]くの生徒[せいと]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "彼は毎日本を読み、仕事で使える語彙の範囲を拡張していった。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "彼[かれ]は毎日[まいにち]本[ほん]を読[よ]み、仕事[しごと]で使[つか]える語彙[ごい]の範囲[はんい]を拡張[かくちょう]していった。", "sentence_source": "generated"}, {"text": "事業の拡張を急ぎすぎたせいで、資金が足りなくなった。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "事業[じぎょう]の拡張[かくちょう]を急[いそ]ぎすぎたせいで、資金[しきん]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "この制度は来年から、対象となる人の範囲が拡張される予定だ。", "target_word": "拡張", "complexity_tier": "T4", "furigana": "この制度[せいど]は来年[らいねん]から、対象[たいしょう]となる人[ひと]の範囲[はんい]が拡張[かくちょう]される予定[よてい]だ。", "sentence_source": "generated"}, {"text": "権限が拡張されたので、担当者は自分の判断で契約を決められる。", "target_word": "拡張", "complexity_tier": "T4", "furigana": "権限[けんげん]が拡張[かくちょう]されたので、担当者[たんとうしゃ]は自分[じぶん]の判断[はんだん]で契約[けいやく]を決[き]められる。", "sentence_source": "generated"}, {"text": "たくさん本を読むことは、ものの考え方の幅を拡張してくれる。", "target_word": "拡張", "complexity_tier": "T3", "furigana": "たくさん本[ほん]を読[よ]むことは、ものの考[かんが]え方[かた]の幅[はば]を拡張[かくちょう]してくれる。", "sentence_source": "generated"}, {"text": "研究チームは新しい装置で、観測できる範囲の拡張に成功した。", "target_word": "拡張", "complexity_tier": "T4", "furigana": "研究[けんきゅう]チームは新[あたら]しい装置[そうち]で、観測[かんそく]できる範囲[はんい]の拡張[かくちょう]に成功[せいこう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拡張", "label": "dictionary form"}, {"form": "拡張する", "label": "plain non-past"}, {"form": "拡張した", "label": "plain past"}, {"form": "拡張される", "label": "passive"}], "register": "neutral", "sense_fingerprint": "範囲・能力・機能などを抽象的に広げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拡張", "is_correct": true, "explanation": "「潜在能力を飛躍的に拡張する」は能力を大きく広げる意味で文脈に合う。ここに入るのはこの語だけ。"}, {"text": "作曲", "is_correct": false, "explanation": "「潜在能力を作曲する」は成り立たない。"}, {"text": "運搬", "is_correct": false, "explanation": "「潜在能力を運搬する」は意味をなさない。"}, {"text": "配達", "is_correct": false, "explanation": "「潜在能力を配達する」は文脈に合わない。"}], "explanations": {"拡張": "「潜在能力を飛躍的に拡張する」は能力を大きく広げる意味で文脈に合う。ここに入るのはこの語だけ。", "作曲": "「潜在能力を作曲する」は成り立たない。", "運搬": "「潜在能力を運搬する」は意味をなさない。", "配達": "「潜在能力を配達する」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "拡張"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食のあと、食器を拡張して洗った。", "explanation": "ここは〈洗う〉の意味。食器をきれいにするのは〈洗う〉で、〈拡張〉は範囲や能力を広げる意味なので合わない。"}, {"text": "会議は予定より十分拡張して終わった。", "explanation": "ここは〈延長〉の意味。時間を長くするのは〈延長〉で、〈拡張〉は範囲や能力を広げる意味なので時間には合わない。"}, {"text": "ラジオの音を拡張して、家族を起こした。", "explanation": "ここは〈増幅〉の意味。音を大きくして強めるのは〈増幅〉で、〈拡張〉は範囲や能力を広げる意味なので音には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拡張", "is_correct": true, "explanation": "「対象となる人の範囲が拡張される予定だ」で、範囲を広げる意味に合う。ここに入るのはこの語だけ。"}, {"text": "解説", "is_correct": false, "explanation": "「範囲が解説される」は成り立たない。"}, {"text": "洗浄", "is_correct": false, "explanation": "「範囲が洗浄される」は意味をなさない。"}, {"text": "注文", "is_correct": false, "explanation": "「範囲が注文される」は文脈に合わない。"}], "explanations": {"拡張": "「対象となる人の範囲が拡張される予定だ」で、範囲を広げる意味に合う。ここに入るのはこの語だけ。", "解説": "「範囲が解説される」は成り立たない。", "洗浄": "「範囲が洗浄される」は意味をなさない。", "注文": "「範囲が注文される」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "拡張"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "監督は選手の体重を拡張するため、毎朝たくさん食べさせた。", "explanation": "ここは〈増量〉の意味。体重を増やすのは〈増量〉で、〈拡張〉は範囲や能力を広げる意味なので体重には合わない。"}, {"text": "研究チームは鳥の声を拡張することに成功した。", "explanation": "ここは〈録音〉の意味。音を記録するのは〈録音〉で、〈拡張〉は範囲や能力を広げる意味なので合わない。"}, {"text": "研究チームは観測の誤差を拡張して、結果の疑問を解消した。", "explanation": "ここは〈解消〉の意味。問題や誤差をなくすのは〈解消〉で、〈拡張〉は広げる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "アプリの機能を拡張えば、作業が速くなる。", "corrected_sentence": "アプリの機能を拡張すれば、作業が速くなる。", "error_description": "「拡張する」の仮定形は「拡張すれば」が正しい。「拡張えば」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52326, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事業の拡張へ、多くの費用がかかる。", "corrected_sentence": "事業の拡張に、多くの費用がかかる。", "error_description": "「拡張」に続く助詞は「に」が正しい。「へ」は方向を表すため、費用がかかるという内容に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
