INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52327, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「細胞が集まって」の主語の「が」。「集まる」は自動詞なので主語を取る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「集まる」は目的語を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属を示す。「細胞の集まって」では動詞に続かない。"}, {"text": "や", "is_correct": false, "explanation": "「や」は名詞を並べる助詞で、動詞「集まって」には続かない。"}], "correct_answer": "が", "explanations": {"が": "「細胞が集まって」の主語の「が」。「集まる」は自動詞なので主語を取る。", "を": "「を」は目的語を示す。「集まる」は目的語を取らないので合わない。", "の": "「の」は所属を示す。「細胞の集まって」では動詞に続かない。", "や": "「や」は名詞を並べる助詞で、動詞「集まって」には続かない。"}, "error_tags": {"を": "目的語", "の": "連体", "や": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52327, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きものの体を作る、とても小さな部屋のようなものです。", "primary_collocate": null, "pronunciation": "さいぼう", "ipa": "saibo̞ː", "syllable_count": 4, "sentences": [{"text": "わたしたちの体は、小さな細胞がたくさん集まってできている。", "target_word": "細胞", "complexity_tier": "T2", "furigana": "わたしたちの体[からだ]は、小[ちい]さな細胞[さいぼう]がたくさん集[あつ]まってできている。", "sentence_source": "generated"}, {"text": "細胞はとても小さいので、目では見えない。", "target_word": "細胞", "complexity_tier": "T2", "furigana": "細胞[さいぼう]はとても小[ちい]さいので、目[め]では見[み]えない。", "sentence_source": "generated"}, {"text": "顕微鏡を使うと、細胞を拡大して見ることができる。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]を使[つか]うと、細胞[さいぼう]を拡大[かくだい]して見[み]ることができる。", "sentence_source": "generated"}, {"text": "ごはんを食べると、栄養が細胞に届いて元気になる。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "ごはんを食[た]べると、栄養[えいよう]が細胞[さいぼう]に届[とど]いて元気[げんき]になる。", "sentence_source": "generated"}, {"text": "けがをしても、細胞が増えて傷は少しずつ治っていく。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "けがをしても、細胞[さいぼう]が増[ふ]えて傷[きず]は少[すこ]しずつ治[なお]っていく。", "sentence_source": "generated"}, {"text": "木の葉も、たくさんの細胞でできている。", "target_word": "細胞", "complexity_tier": "T2", "furigana": "木[き]の葉[は]も、たくさんの細胞[さいぼう]でできている。", "sentence_source": "generated"}, {"text": "細胞の数が増えると、赤ちゃんは大きくなる。", "target_word": "細胞", "complexity_tier": "T2", "furigana": "細胞[さいぼう]の数[かず]が増[ふ]えると、赤[あか]ちゃんは大[おお]きくなる。", "sentence_source": "generated"}, {"text": "魚の体も人の体も、細胞が集まって作られている。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "魚[さかな]の体[からだ]も人[ひと]の体[からだ]も、細胞[さいぼう]が集[あつ]まって作[つく]られている。", "sentence_source": "generated"}, {"text": "理科の授業で、先生が細胞の絵を黒板にかいた。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、先生[せんせい]が細胞[さいぼう]の絵[え]を黒板[こくばん]にかいた。", "sentence_source": "generated"}, {"text": "細胞の一つ一つが、それぞれ大事な仕事をしている。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "細胞[さいぼう]の一[ひと]つ一[ひと]つが、それぞれ大事[だいじ]な仕事[しごと]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "細胞", "label": "dictionary form"}, {"form": "細胞の", "label": "genitive"}, {"form": "細胞が", "label": "subject"}], "register": "neutral", "sense_fingerprint": "生きものの体を作る小さな部屋のような単位(やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52327, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "細胞", "is_correct": true, "explanation": "生きものの体を作る小さな単位で、体が細胞の集まりであるという文脈に合う。"}, {"text": "氷", "is_correct": false, "explanation": "人の体は氷の集まりではない。氷は体を作る単位にならない。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらは植物の一部で、人の体を作る単位ではない。"}, {"text": "金属", "is_correct": false, "explanation": "体は金属でできていないので、金属は当てはまらない。"}], "explanations": {"細胞": "生きものの体を作る小さな単位で、体が細胞の集まりであるという文脈に合う。", "氷": "人の体は氷の集まりではない。氷は体を作る単位にならない。", "花びら": "花びらは植物の一部で、人の体を作る単位ではない。", "金属": "体は金属でできていないので、金属は当てはまらない。"}, "sentence_index": 0, "correct_answer": "細胞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家は細胞が三つあり、台所と居間がある。", "explanation": "ここは〈部屋〉の意味。家の部屋は細胞とは呼ばないので、この言い方は合わない。"}, {"text": "心臓は、血を全身に送り出す細胞で、胸の中央にある。", "explanation": "ここは〈器官〉の意味。心臓は一つの臓器なので、細胞ではなく器官と言う。"}, {"text": "空気は小さな細胞が飛び回っている。", "explanation": "ここは〈粒子〉の意味。空気中を飛び回る小さな粒は粒子で、体を作る細胞とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52327, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "細胞", "is_correct": true, "explanation": "「細胞の数」は体を作る細胞の数を指し、赤ちゃんが成長する文脈に合う。"}, {"text": "水", "is_correct": false, "explanation": "「水の数」は数が増えて成長する単位としては成り立たない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は数が増えて成長を表す単位ではないので、この文脈に合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "「鉄の数」は赤ちゃんの成長と結びつかない。"}], "explanations": {"細胞": "「細胞の数」は体を作る細胞の数を指し、赤ちゃんが成長する文脈に合う。", "水": "「水の数」は数が増えて成長する単位としては成り立たない。", "空気": "空気は数が増えて成長を表す単位ではないので、この文脈に合わない。", "鉄": "「鉄の数」は赤ちゃんの成長と結びつかない。"}, "sentence_index": 6, "correct_answer": "細胞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "時計の細胞の一つ一つが、それぞれ大事な仕事をしている。", "explanation": "ここは〈部品〉の意味。時計の部品は細胞とは言わないので合わない。"}, {"text": "ピアノの細胞は、一つ一つが音を出す。", "explanation": "ここは〈鍵盤〉の意味。ピアノで一つずつ音を出す部分は鍵盤と言い、細胞とは言わない。"}, {"text": "歯車の細胞の一つ一つが、それぞれ大事な仕事をしている。", "explanation": "ここは〈歯車〉の意味。歯車は機械の部品で、細胞とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52327, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人の体は、小さな細胞を集まってできている。", "corrected_sentence": "人の体は、小さな細胞が集まってできている。", "error_description": "「集まる」は自動詞なので、主語を「が」で示す。「細胞を」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52327, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "細胞を数が増えるのは、成長のしるしだ。", "corrected_sentence": "細胞の数が増えるのは、成長のしるしだ。", "error_description": "「増える」は自動詞なので、主語は「が」で示す。「細胞を数」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「細胞からできている」の材料・起源を示す「から」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「できている」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。材料を表す文脈では「細胞へできている」とならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示す。「細胞とできている」では材料の意味にならない。"}], "correct_answer": "から", "explanations": {"から": "「細胞からできている」の材料・起源を示す「から」。", "を": "「を」は目的語を示す。「できている」は目的語を取らないので合わない。", "へ": "「へ」は方向を示す。材料を表す文脈では「細胞へできている」とならない。", "と": "「と」は並列や共同を示す。「細胞とできている」では材料の意味にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「細胞の中」の所属を示す「の」。「中には」に自然につながる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所を示すが、「細胞に中には」では名詞同士の結びつきが不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「細胞を中には」では所属の関係を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。「細胞と中には」では所属の関係にならない。"}], "correct_answer": "の", "explanations": {"の": "「細胞の中」の所属を示す「の」。「中には」に自然につながる。", "に": "「に」は場所を示すが、「細胞に中には」では名詞同士の結びつきが不自然。", "を": "「を」は目的語を示す。「細胞を中には」では所属の関係を示せない。", "と": "「と」は並列を示す。「細胞と中には」では所属の関係にならない。"}, "error_tags": {"に": "場所", "を": "目的語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物の体を構成する最小の単位。植物や動物の体は多くの細胞からできている。", "primary_collocate": null, "pronunciation": "さいぼう", "ipa": "saibo̞ː", "syllable_count": 4, "sentences": [{"text": "植物の細胞には、ひとつずつ丈夫な壁がある。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の細胞[さいぼう]には、ひとつずつ丈夫[じょうぶ]な壁[かべ]がある。", "sentence_source": "generated"}, {"text": "植物も動物も、体は多くの細胞からできている。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]も動物[どうぶつ]も、体[からだ]は多[おお]くの細胞[さいぼう]からできている。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、玉ねぎの細胞がはっきり見えた。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で見[み]ると、玉[たま]ねぎの細胞[さいぼう]がはっきり見[み]えた。", "sentence_source": "generated"}, {"text": "皮膚の細胞は、毎日少しずつ新しく入れ替わっている。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "皮膚[ひふ]の細胞[さいぼう]は、毎日[まいにち]少[すこ]しずつ新[あたら]しく入[い]れ替[か]わっている。", "sentence_source": "generated"}, {"text": "細胞が分裂して増えることで、体は成長する。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "細胞[さいぼう]が分裂[ぶんれつ]して増[ふ]えることで、体[からだ]は成長[せいちょう]する。", "sentence_source": "generated"}, {"text": "赤血球は、全身に酸素を運ぶ役目を持つ細胞だ。", "target_word": "細胞", "complexity_tier": "T4", "furigana": "赤血球[せっけっきゅう]は、全身[ぜんしん]に酸素[さんそ]を運[はこ]ぶ役目[やくめ]を持[も]つ細胞[さいぼう]だ。", "sentence_source": "generated"}, {"text": "傷が治るのは、新しい細胞が作られるからだ。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "傷[きず]が治[なお]るのは、新[あたら]しい細胞[さいぼう]が作[つく]られるからだ。", "sentence_source": "generated"}, {"text": "細胞の中には、遺伝子の入っている核がある。", "target_word": "細胞", "complexity_tier": "T4", "furigana": "細胞[さいぼう]の中[なか]には、遺伝子[いでんし]の入[はい]っている核[かく]がある。", "sentence_source": "generated"}, {"text": "年を取ると、細胞の働きが少しずつ弱くなる。", "target_word": "細胞", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、細胞[さいぼう]の働[はたら]きが少[すこ]しずつ弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "人の命は、受精卵というたった一つの細胞から始まる。", "target_word": "細胞", "complexity_tier": "T4", "furigana": "人[ひと]の命[いのち]は、受精卵[じゅせいらん]というたった一[ひと]つの細胞[さいぼう]から始[はじ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "細胞", "label": "dictionary form"}, {"form": "細胞の", "label": "genitive"}, {"form": "細胞が", "label": "subject"}], "register": "neutral", "sense_fingerprint": "生物の体を作る最小単位(生物学の用語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "細胞", "is_correct": true, "explanation": "植物の細胞一つ一つを指し、壁を持つ体の単位として文に合う。"}, {"text": "組織", "is_correct": false, "explanation": "組織は細胞が集まった単位で、ひとつずつの壁を持つ単位ではないので、ここでは成り立たない。"}, {"text": "器官", "is_correct": false, "explanation": "「器官壁」とは言わない。細胞の外側を囲む壁の名前にならない。"}, {"text": "核", "is_correct": false, "explanation": "核は細胞の中の構造で、「核壁」とは言わない。細胞の外の壁を指せない。"}], "explanations": {"細胞": "植物の細胞一つ一つを指し、壁を持つ体の単位として文に合う。", "組織": "組織は細胞が集まった単位で、ひとつずつの壁を持つ単位ではないので、ここでは成り立たない。", "器官": "「器官壁」とは言わない。細胞の外側を囲む壁の名前にならない。", "核": "核は細胞の中の構造で、「核壁」とは言わない。細胞の外の壁を指せない。"}, "sentence_index": 0, "correct_answer": "細胞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "胃は食べ物を消化する細胞で、おなかの左側にある。", "explanation": "ここは〈器官〉の意味。胃は消化を担う臓器なので、細胞ではなく器官と言う。"}, {"text": "水は、水素と酸素が結びついた細胞だ。", "explanation": "ここは〈分子〉の意味。水素と酸素が結びついた水は分子で、体を作る細胞とは別物。"}, {"text": "皮膚は、表皮や真皮という細胞が重なってできている。", "explanation": "ここは〈組織〉の意味。表皮や真皮は層になった組織で、個々の細胞の単位ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "細胞", "is_correct": true, "explanation": "「新しい細胞」は傷が治る過程で作られる体の細胞を指し、文脈に合う。"}, {"text": "細菌", "is_correct": false, "explanation": "細菌は体の外から来る微生物で、傷が治る過程で作られるものではない。"}, {"text": "核", "is_correct": false, "explanation": "核は細胞の中の構造で、「新しい核が作られる」は傷の治りの説明にならない。"}, {"text": "病原体", "is_correct": false, "explanation": "病原体は病気の原因となる微生物で、傷が治る文脈とは合わない。"}], "explanations": {"細胞": "「新しい細胞」は傷が治る過程で作られる体の細胞を指し、文脈に合う。", "細菌": "細菌は体の外から来る微生物で、傷が治る過程で作られるものではない。", "核": "核は細胞の中の構造で、「新しい核が作られる」は傷の治りの説明にならない。", "病原体": "病原体は病気の原因となる微生物で、傷が治る文脈とは合わない。"}, "sentence_index": 6, "correct_answer": "細胞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "虫歯は、細胞が歯を溶かして起きる。", "explanation": "ここは〈細菌〉の意味。虫歯を起こすのは口の中の細菌で、体を作る細胞とは別物。"}, {"text": "鉄の細胞は、電子を失うと陽イオンになる。", "explanation": "ここは〈原子〉の意味。電子を失って陽イオンになるのは原子で、細胞は化学の単位ではない。"}, {"text": "氷の六角形は、水の細胞が規則正しく並んでできたものだ。", "explanation": "ここは〈結晶〉の意味。規則正しく並んだ固体の構造は結晶で、細胞とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "木も草も、体は多くの細胞をできている。", "corrected_sentence": "木も草も、体は多くの細胞からできている。", "error_description": "「できている」は材料を「から」で示す。「細胞を」の「を」は目的語なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52328, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "けがが治るのは、新しい細胞を作られるからだ。", "corrected_sentence": "けがが治るのは、新しい細胞が作られるからだ。", "error_description": "受け身の主語は「が」で示す。「新しい細胞を作られる」の「を」は能動の目的語なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入るのを阻む」の目的語を示す「を」。阻むは対象を「を」で取る。"}, {"text": "に", "is_correct": false, "explanation": "「入るのに阻む」は阻む対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。阻む対象を示さない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。阻むとは結びつかない。"}], "correct_answer": "を", "explanations": {"を": "「入るのを阻む」の目的語を示す「を」。阻むは対象を「を」で取る。", "に": "「入るのに阻む」は阻む対象にならない。", "で": "「で」は手段や場所を示す。阻む対象を示さない。", "へ": "「へ」は方向を示す。阻むとは結びつかない。"}, "error_tags": {"に": "対象・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入るのを阻むために」の「を」。阻む対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示す。阻む対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「入るのから阻む」は対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「入るのより阻む」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「入るのを阻むために」の「を」。阻む対象を示す。", "と": "「と」は並列や共同を示す。阻む対象にならない。", "から": "「から」は起点を示す。「入るのから阻む」は対象を示せない。", "より": "「より」は比較を示す。「入るのより阻む」は文が成り立たない。"}, "error_tags": {"と": "並列・共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが通るのを止めること。", "primary_collocate": null, "pronunciation": "はばむ", "ipa": "habamɯ", "syllable_count": 3, "sentences": [{"text": "岩が崩れて、川の流れを阻んだ。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "岩[いわ]が崩[くず]れて、川[かわ]の流[なが]れを阻[はば]んだ。", "sentence_source": "generated"}, {"text": "門の前に立って、知らない人が入るのを阻む。", "target_word": "阻む", "complexity_tier": "T3", "furigana": "門[もん]の前[まえ]に立[た]って、知[し]らない人[ひと]が入[はい]るのを阻[はば]む。", "sentence_source": "generated"}, {"text": "大きな荷物が通路を阻んでいて、誰も通れない。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "大[おお]きな荷物[にもつ]が通路[つうろ]を阻[はば]んでいて、誰[だれ]も通[とお]れない。", "sentence_source": "generated"}, {"text": "厚いカーテンが、外から入る光を阻んでくれる。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "厚[あつ]いカーテンが、外[そと]から入[はい]る光[ひかり]を阻[はば]んでくれる。", "sentence_source": "generated"}, {"text": "雪が道をふさぎ、車の通行を阻んだ。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "雪[ゆき]が道[みち]をふさぎ、車[くるま]の通行[つうこう]を阻[はば]んだ。", "sentence_source": "generated"}, {"text": "木の柵が、犬が庭から出るのを阻んでいる。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "木[き]の柵[さく]が、犬[いぬ]が庭[にわ]から出[で]るのを阻[はば]んでいる。", "sentence_source": "generated"}, {"text": "工事の車が入り口を阻み、客は店に入れなかった。", "target_word": "阻み", "complexity_tier": "T3", "furigana": "工事[こうじ]の車[くるま]が入[い]り口[ぐち]を阻[はば]み、客[きゃく]は店[みせ]に入[はい]れなかった。", "sentence_source": "generated"}, {"text": "防波堤は、波が町に入るのを阻むために造られた。", "target_word": "阻む", "complexity_tier": "T4", "furigana": "防波堤[ぼうはてい]は、波[なみ]が町[まち]に入[はい]るのを阻[はば]むために造[つく]られた。", "sentence_source": "generated"}, {"text": "高いビルが風を阻み、このあたりは静かだ。", "target_word": "阻み", "complexity_tier": "T3", "furigana": "高[たか]いビルが風[かぜ]を阻[はば]み、このあたりは静[しず]かだ。", "sentence_source": "generated"}, {"text": "警備員が男の前に立ち、中に入るのを阻んだ。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "警備員[けいびいん]が男[おとこ]の前[まえ]に立[た]ち、中[なか]に入[はい]るのを阻[はば]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻む", "label": "dictionary form"}, {"form": "阻まない", "label": "negative"}, {"form": "阻み", "label": "continuative"}, {"form": "阻んで", "label": "te-form"}, {"form": "阻んだ", "label": "plain past"}, {"form": "阻まれる", "label": "passive"}], "register": "formal", "sense_fingerprint": "人や物が通ったり入ったりするのを物理的に止める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻ん", "is_correct": true, "explanation": "「阻んだ」の語幹。川の流れを止める意味で、この文に入る。"}, {"text": "眺め", "is_correct": false, "explanation": "「眺める」は見る動詞で、流れを止める意味にならない。"}, {"text": "磨い", "is_correct": false, "explanation": "「磨く」は表面を磨く動詞で、流れには使わない。"}, {"text": "焼い", "is_correct": false, "explanation": "「焼く」は火で熱する動詞で、流れを止める文脈に合わない。"}], "explanations": {"阻ん": "「阻んだ」の語幹。川の流れを止める意味で、この文に入る。", "眺め": "「眺める」は見る動詞で、流れを止める意味にならない。", "磨い": "「磨く」は表面を磨く動詞で、流れには使わない。", "焼い": "「焼く」は火で熱する動詞で、流れを止める文脈に合わない。"}, "sentence_index": 0, "correct_answer": "阻ん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を阻んで歩いた。", "explanation": "阻むは通るのを止める意味で、荷物を持って歩く意味では使えない。"}, {"text": "窓を開けておくと、外から入る風を阻んで部屋が涼しくなる。", "explanation": "風を阻めば部屋は涼しくならず、窓を開ける文脈とも矛盾する。"}, {"text": "受付の人が客を阻んで、奥の部屋へ案内した。", "explanation": "阻むは進みを止める意味で、客を奥へ案内する文脈では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻み", "is_correct": true, "explanation": "連用形。入り口をふさいで客が入れなかった文脈に合う。"}, {"text": "掘り", "is_correct": false, "explanation": "「掘る」は地面を掘る動詞で、客が入れない文脈に合わない。"}, {"text": "結び", "is_correct": false, "explanation": "「結ぶ」は入り口をふさぐ意味にはならない。"}, {"text": "編み", "is_correct": false, "explanation": "「編む」は糸を編む動詞で、入り口には使わない。"}], "explanations": {"阻み": "連用形。入り口をふさいで客が入れなかった文脈に合う。", "掘り": "「掘る」は地面を掘る動詞で、客が入れない文脈に合わない。", "結び": "「結ぶ」は入り口をふさぐ意味にはならない。", "編み": "「編む」は糸を編む動詞で、入り口には使わない。"}, "sentence_index": 6, "correct_answer": "阻み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警備員が男の手を阻んだ。", "explanation": "阻むは通るのを止める意味で、手をつかむ動作には使えない。"}, {"text": "車は道を阻んで、歩行者に譲った。", "explanation": "阻むは進みを止める意味で、道を譲る文脈とは矛盾する。"}, {"text": "警備員が男の荷物を阻んで、中へ運んだ。", "explanation": "阻むは通り道をふさぐ意味で、荷物を運ぶ文脈では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土砂が崩れて、川の流れに阻んだ。", "corrected_sentence": "土砂が崩れて、川の流れを阻んだ。", "error_description": "阻むは対象を「を」で取る他動詞。「流れに阻んだ」の「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "阻む", "is_correct": true, "explanation": "辞書形。文を言い切る形で、この文の「阻む」に当たる。"}, {"text": "阻ん", "is_correct": false, "explanation": "過去形の語幹。「阻んだ」の形で、現在の文には合わない。"}, {"text": "阻まれ", "is_correct": false, "explanation": "受け身の連用形。能動の文には合わない。"}, {"text": "阻めば", "is_correct": false, "explanation": "仮定形。「阻めば」の後に主節が続かないと文が終わらない。"}], "correct_form": "阻む", "base_form": "阻む", "form_label": "辞書形", "sentence_index": 1, "explanations": {"阻む": "辞書形。文を言い切る形で、この文の「阻む」に当たる。", "阻ん": "過去形の語幹。「阻んだ」の形で、現在の文には合わない。", "阻まれ": "受け身の連用形。能動の文には合わない。", "阻めば": "仮定形。「阻めば」の後に主節が続かないと文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52329, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな看板が通路に阻み、誰も通れなかった。", "corrected_sentence": "大きな看板が通路を阻み、誰も通れなかった。", "error_description": "阻むは他動詞で、対象は「を」で示す。「通路に阻み」の「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "阻み", "is_correct": false, "explanation": "連用形。「阻むために」の前には続かない。"}, {"text": "阻んで", "is_correct": false, "explanation": "て形。目的を表す「ために」には続かない。"}, {"text": "阻む", "is_correct": true, "explanation": "辞書形。「ために」の前で使う形で、この文の「阻む」に当たる。"}, {"text": "阻めば", "is_correct": false, "explanation": "仮定形。「ために」の前には続かない。"}], "correct_form": "阻む", "base_form": "阻む", "form_label": "辞書形", "sentence_index": 7, "explanations": {"阻み": "連用形。「阻むために」の前には続かない。", "阻んで": "て形。目的を表す「ために」には続かない。", "阻む": "辞書形。「ために」の前で使う形で、この文の「阻む」に当たる。", "阻めば": "仮定形。「ために」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
