INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52330, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "進行や通過を妨げる。", "primary_collocate": null, "pronunciation": "はばむ", "ipa": "habamɯ", "syllable_count": 3, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "阻ま", "complexity_tier": "T5", "furigana": "例[たと]えば、穀物[こくもつ]や豆類[まめるい]を主食[しゅしょく]として摂取[せっしゅ]する際[さい]、その細胞壁[さいぼうへき]に阻[はば]まれた栄養[えいよう]は、生体[せいたい]利用率[りようりつ]が低[ひく]いという宿命[しゅくめい]を背負[せお]っている。", "sentence_source": "mined"}, {"text": "大雪が登山者の進路を阻んだ。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "大雪[おおゆき]が登山者[とざんしゃ]の進路[しんろ]を阻[はば]んだ。", "sentence_source": "generated"}, {"text": "深い川が、軍の前進を阻んでいた。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "深[ふか]い川[かわ]が、軍[ぐん]の前進[ぜんしん]を阻[はば]んでいた。", "sentence_source": "generated"}, {"text": "言葉の壁が、二人の交流を阻んでいる。", "target_word": "阻ん", "complexity_tier": "T3", "furigana": "言葉[ことば]の壁[かべ]が、二人[ふたり]の交流[こうりゅう]を阻[はば]んでいる。", "sentence_source": "generated"}, {"text": "強い風に阻まれて、船は港を出られなかった。", "target_word": "阻ま", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]に阻[はば]まれて、船[ふね]は港[みなと]を出[で]られなかった。", "sentence_source": "generated"}, {"text": "倒れた木が道を阻み、車は先へ進めなかった。", "target_word": "阻み", "complexity_tier": "T3", "furigana": "倒[たお]れた木[き]が道[みち]を阻[はば]み、車[くるま]は先[さき]へ進[すす]めなかった。", "sentence_source": "generated"}, {"text": "彼の成功を阻むものは、もう何もない。", "target_word": "阻む", "complexity_tier": "T3", "furigana": "彼[かれ]の成功[せいこう]を阻[はば]むものは、もう何[なに]もない。", "sentence_source": "generated"}, {"text": "デモの人々は、警官に行く手を阻まれた。", "target_word": "阻ま", "complexity_tier": "T4", "furigana": "デモの人々[ひとびと]は、警官[けいかん]に行[い]く手[て]を阻[はば]まれた。", "sentence_source": "generated"}, {"text": "資金不足が、計画の実現を阻む最大の原因だ。", "target_word": "阻む", "complexity_tier": "T4", "furigana": "資金[しきん]不足[ぶそく]が、計画[けいかく]の実現[じつげん]を阻[はば]む最大[さいだい]の原因[げんいん]だ。", "sentence_source": "generated"}, {"text": "この高い壁は、敵の侵入を阻むために作られた。", "target_word": "阻む", "complexity_tier": "T4", "furigana": "この高[たか]い壁[かべ]は、敵[てき]の侵入[しんにゅう]を阻[はば]むために作[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻む", "label": "dictionary form"}, {"form": "阻まない", "label": "negative"}, {"form": "阻み", "label": "continuative"}, {"form": "阻んで", "label": "te-form"}, {"form": "阻んだ", "label": "plain past"}, {"form": "阻まれる", "label": "passive"}], "register": "formal", "sense_fingerprint": "人や物の進行・実現を妨げて先へ進ませない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52330, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阻ま", "is_correct": true, "explanation": "「阻まれた」の語幹。細胞壁によって栄養が通れなかった意味で、この文に入る。"}, {"text": "進ま", "is_correct": false, "explanation": "「進む」は受け身にしない動詞で、「進まれた」の形はこの文脈に合わない。"}, {"text": "眠ら", "is_correct": false, "explanation": "「眠る」は細胞壁が栄養を眠らせる意味にはならず、文脈に合わない。"}, {"text": "咲か", "is_correct": false, "explanation": "「咲く」は花に使う動詞で、細胞壁の文脈には合わない。"}], "explanations": {"阻ま": "「阻まれた」の語幹。細胞壁によって栄養が通れなかった意味で、この文に入る。", "進ま": "「進む」は受け身にしない動詞で、「進まれた」の形はこの文脈に合わない。", "眠ら": "「眠る」は細胞壁が栄養を眠らせる意味にはならず、文脈に合わない。", "咲か": "「咲く」は花に使う動詞で、細胞壁の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "阻ま"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を阻んで、腕で支えた。", "explanation": "阻むは進みや通りを止める意味で、荷物を腕で支える意味では使えない。"}, {"text": "彼は計画を阻んで、着実に進めた。", "explanation": "阻むは計画を止める意味で、着実に進めるとは文脈が両立しない。"}, {"text": "彼の昇進を阻んで、みんなで祝った。", "explanation": "阻むは妨げる意味で、昇進を喜んで祝う文脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52330, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻む", "is_correct": true, "explanation": "「彼の成功を阻むもの」は成功を妨げる意味で、この文の流れに合う。"}, {"text": "投げる", "is_correct": false, "explanation": "「成功を投げる」は言い方として成り立たず、文脈に合わない。"}, {"text": "掘る", "is_correct": false, "explanation": "「成功を掘る」は不自然で、成功を妨げる意味にならない。"}, {"text": "焼く", "is_correct": false, "explanation": "「成功を焼く」は文脈に合わない。"}], "explanations": {"阻む": "「彼の成功を阻むもの」は成功を妨げる意味で、この文の流れに合う。", "投げる": "「成功を投げる」は言い方として成り立たず、文脈に合わない。", "掘る": "「成功を掘る」は不自然で、成功を妨げる意味にならない。", "焼く": "「成功を焼く」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "阻む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "親は子どもの成長を阻んで、そっと見守っている。", "explanation": "阻むは妨げる意味で、成長を見守る文脈とは合わない。"}, {"text": "彼は仕事を阻んで、そっと手伝ってくれた。", "explanation": "阻むは妨げる意味で、仕事を手伝う文脈では使えない。"}, {"text": "先生は生徒の意欲を阻んで、勉強を促した。", "explanation": "阻むは妨げる意味で、意欲を促す文脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52330, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猛吹雪が登山者の道を阻むだ。", "corrected_sentence": "猛吹雪が登山者の道を阻んだ。", "error_description": "過去の「た」はん音便で「阻んだ」となる。「阻むだ」は活用を誤っているので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "阻ん", "is_correct": true, "explanation": "過去形の語幹。「阻んだ」の形で、この文の過去形に当たる。"}, {"text": "阻む", "is_correct": false, "explanation": "辞書形。過去形の語幹ではないので、この文には入らない。"}, {"text": "阻み", "is_correct": false, "explanation": "連用形。過去形の「阻んだ」とは形が違う。"}, {"text": "阻まれ", "is_correct": false, "explanation": "受け身の連用形。能動の過去の文には合わない。"}], "correct_form": "阻ん", "base_form": "阻む", "form_label": "過去形の語幹", "sentence_index": 1, "explanations": {"阻ん": "過去形の語幹。「阻んだ」の形で、この文の過去形に当たる。", "阻む": "辞書形。過去形の語幹ではないので、この文には入らない。", "阻み": "連用形。過去形の「阻んだ」とは形が違う。", "阻まれ": "受け身の連用形。能動の過去の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52330, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の努力に阻むものは、もう何もない。", "corrected_sentence": "彼の努力を阻むものは、もう何もない。", "error_description": "阻むは他動詞で、対象は「を」で示す。「努力に阻む」の「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "阻ま", "is_correct": true, "explanation": "受け身の語幹。「阻まれた」の一部で、この文の受け身の過去形に当たる。"}, {"text": "阻まない", "is_correct": false, "explanation": "否定形。受け身の文には合わない。"}, {"text": "阻んで", "is_correct": false, "explanation": "て形。「阻まれた」の受け身の形とは違う。"}, {"text": "阻まれる", "is_correct": false, "explanation": "受け身の辞書形。過去形の語幹ではない。"}], "correct_form": "阻ま", "base_form": "阻む", "form_label": "受け身の語幹", "sentence_index": 7, "explanations": {"阻ま": "受け身の語幹。「阻まれた」の一部で、この文の受け身の過去形に当たる。", "阻まない": "否定形。受け身の文には合わない。", "阻んで": "て形。「阻まれた」の受け身の形とは違う。", "阻まれる": "受け身の辞書形。過去形の語幹ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大きなランドセルを背負って」で、背負う対象を目的語として示す。"}, {"text": "に", "is_correct": false, "explanation": "「ランドセルに背負って」は対象を示す形として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「ランドセルで背負って」は手段の意味になり、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「ランドセルと背負って」は並列の形で、背負う対象を示さない。"}], "correct_answer": "を", "explanations": {"を": "「大きなランドセルを背負って」で、背負う対象を目的語として示す。", "に": "「ランドセルに背負って」は対象を示す形として成り立たない。", "で": "「ランドセルで背負って」は手段の意味になり、文が通らない。", "と": "「ランドセルと背負って」は並列の形で、背負う対象を示さない。"}, "error_tags": {"に": "帰着点・対象", "で": "手段・場所", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「けが人を背負って」で、背負う対象を目的語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "「けが人へ背負って」は方向の意味になり、背負う対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「けが人より背負って」は比較の意味になり、文が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「けが人から背負って」は起点の意味になり、対象を示す文にならない。"}], "correct_answer": "を", "explanations": {"を": "「けが人を背負って」で、背負う対象を目的語として示す。", "へ": "「けが人へ背負って」は方向の意味になり、背負う対象を示せない。", "より": "「けが人より背負って」は比較の意味になり、文が通らない。", "から": "「けが人から背負って」は起点の意味になり、対象を示す文にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "重いものを背中にのせること。また、大変なことをじぶんでうけもつこと。", "primary_collocate": null, "pronunciation": "せおう", "ipa": "seoɯ", "syllable_count": 3, "sentences": [{"text": "父は重い荷物を背負って、駅まで歩いた。", "target_word": "背負って", "complexity_tier": "T3", "furigana": "父[ちち]は重[おも]い荷物[にもつ]を背負[せお]って、駅[えき]まで歩[ある]いた。", "sentence_source": "generated"}, {"text": "子どもは大きなランドセルを背負って学校へ行く。", "target_word": "背負って", "complexity_tier": "T3", "furigana": "子[こ]どもは大[おお]きなランドセルを背負[せお]って学校[がっこう]へ行[い]く。", "sentence_source": "generated"}, {"text": "祖母は昔、赤ちゃんを背負いながら畑仕事をしていた。", "target_word": "背負い", "complexity_tier": "T3", "furigana": "祖母[そぼ]は昔[むかし]、赤[あか]ちゃんを背負[せお]いながら畑仕事[はたけしごと]をしていた。", "sentence_source": "generated"}, {"text": "山登りでは、荷物をリュックに入れて背負うのが基本だ。", "target_word": "背負う", "complexity_tier": "T3", "furigana": "山登[やまのぼ]りでは、荷物[にもつ]をリュックに入[い]れて背負[せお]うのが基本[きほん]だ。", "sentence_source": "generated"}, {"text": "疲れた友達を背負って、山小屋まで運んだ。", "target_word": "背負って", "complexity_tier": "T3", "furigana": "疲[つか]れた友達[ともだち]を背負[せお]って、山小屋[やまごや]まで運[はこ]んだ。", "sentence_source": "generated"}, {"text": "彼は一人で家族の生活を背負っている。", "target_word": "背負って", "complexity_tier": "T3", "furigana": "彼[かれ]は一人[ひとり]で家族[かぞく]の生活[せいかつ]を背負[せお]っている。", "sentence_source": "generated"}, {"text": "重い米袋を背負ったら、足がふらふらした。", "target_word": "背負った", "complexity_tier": "T3", "furigana": "重[おも]い米袋[こめぶくろ]を背負[せお]ったら、足[あし]がふらふらした。", "sentence_source": "generated"}, {"text": "消防士は、けが人を背負って階段を下りた。", "target_word": "背負って", "complexity_tier": "T3", "furigana": "消防士[しょうぼうし]は、けが人[にん]を背負[せお]って階段[かいだん]を下[お]りた。", "sentence_source": "generated"}, {"text": "兄は大きな借金を背負って、毎日遅くまで働いている。", "target_word": "背負って", "complexity_tier": "T3", "furigana": "兄[あに]は大[おお]きな借金[しゃっきん]を背負[せお]って、毎日[まいにち]遅[おそ]くまで働[はたら]いている。", "sentence_source": "generated"}, {"text": "背負う荷物が軽いと、長い道でも楽に歩ける。", "target_word": "背負う", "complexity_tier": "T3", "furigana": "背負[せお]う荷物[にもつ]が軽[かる]いと、長[なが]い道[みち]でも楽[らく]に歩[ある]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "背負う", "label": "終止形"}, {"form": "背負わ", "label": "未然形"}, {"form": "背負い", "label": "連用形"}, {"form": "背負え", "label": "仮定形・命令形"}, {"form": "背負って", "label": "て形"}, {"form": "背負った", "label": "た形"}], "register": "neutral", "sense_fingerprint": "重いものを背中にのせて運ぶ、また大変なことを自分で引き受ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背負って", "is_correct": true, "explanation": "「重い荷物を背負って、駅まで歩いた」で、荷物を背中に負うという意味になる。"}, {"text": "語って", "is_correct": false, "explanation": "「重い荷物を語って」は意味が通らず、空欄に合わない。"}, {"text": "凍らせて", "is_correct": false, "explanation": "「重い荷物を凍らせて」は文脈に合わず、運ぶ動作にならない。"}, {"text": "叫んで", "is_correct": false, "explanation": "「重い荷物を叫んで」は成り立たず、空欄に入らない。"}], "explanations": {"背負って": "「重い荷物を背負って、駅まで歩いた」で、荷物を背中に負うという意味になる。", "語って": "「重い荷物を語って」は意味が通らず、空欄に合わない。", "凍らせて": "「重い荷物を凍らせて」は文脈に合わず、運ぶ動作にならない。", "叫んで": "「重い荷物を叫んで」は成り立たず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "背負って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍵を背負って、ドアを開けた。", "explanation": "鍵は背中に負うものではないので、ここは〈持つ〉の場面。背負うは使わない。"}, {"text": "子猫を背負って、やさしく撫でた。", "explanation": "ここは〈抱く〉の場面。子猫は背中に負う物ではなく、腕に抱いて撫でる場面なので背負うは合わない。"}, {"text": "筆箱を背負って、教室を出た。", "explanation": "ここは〈持ち歩く〉の場面。筆箱は背中に負う物ではなく、手で持って歩く物なので背負うは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背負った", "is_correct": true, "explanation": "「重い米袋を背負ったら、足がふらふらした」で、米袋を背中に負った結果を述べる。"}, {"text": "踊った", "is_correct": false, "explanation": "「重い米袋を踊った」は意味が通らず、空欄に入らない。"}, {"text": "磨いた", "is_correct": false, "explanation": "「重い米袋を磨いた」は文脈に合わず、足がふらふらする結果にならない。"}, {"text": "描いた", "is_correct": false, "explanation": "「重い米袋を描いた」は成り立たず、空欄に合わない。"}], "explanations": {"背負った": "「重い米袋を背負ったら、足がふらふらした」で、米袋を背中に負った結果を述べる。", "踊った": "「重い米袋を踊った」は意味が通らず、空欄に入らない。", "磨いた": "「重い米袋を磨いた」は文脈に合わず、足がふらふらする結果にならない。", "描いた": "「重い米袋を描いた」は成り立たず、空欄に合わない。"}, "sentence_index": 6, "correct_answer": "背負った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小さな窓を背負うと、部屋の中が見えやすくなる。", "explanation": "ここは〈取り付ける〉の場面。窓は背中に負う物ではないので、背負うは合わない。"}, {"text": "ポットを背負って、お茶を注いだ。", "explanation": "ここは〈傾ける〉の場面。ポットは背中に負う物ではないので、背負うは合わない。"}, {"text": "鍋を背負うと、料理が楽になる。", "explanation": "ここは〈運ぶ〉の場面。鍋は背中に負うものではなく、手で持って運ぶ道具なので背負うは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は重い買い物袋に背負って、家まで帰った。", "corrected_sentence": "母は重い買い物袋を背負って、家まで帰った。", "error_description": "「背負う」の対象は「を」で示す。「に」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "背負って", "is_correct": true, "explanation": "「大きなランドセルを背負って学校へ行く」の接続形。て形で動作を続けている。"}, {"text": "背負っ", "is_correct": false, "explanation": "「背負っ」は語形が途中で切れており、「学校へ行く」と続けられない。"}, {"text": "背負え", "is_correct": false, "explanation": "命令・仮定の形で、「学校へ行く」とつながらない。"}, {"text": "背負わ", "is_correct": false, "explanation": "未然形のため、後ろの「学校へ行く」と続けられない。"}], "correct_form": "背負って", "base_form": "背負う", "form_label": "て形", "sentence_index": 1, "explanations": {"背負って": "「大きなランドセルを背負って学校へ行く」の接続形。て形で動作を続けている。", "背負っ": "「背負っ」は語形が途中で切れており、「学校へ行く」と続けられない。", "背負え": "命令・仮定の形で、「学校へ行く」とつながらない。", "背負わ": "未然形のため、後ろの「学校へ行く」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52331, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は大きな借金を背負いて、毎年夜遅くまで働いている。", "corrected_sentence": "妹は大きな借金を背負って、毎年夜遅くまで働いている。", "error_description": "「背負う」のて形は「背負って」。「背負いて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "背負って", "is_correct": true, "explanation": "「けが人を背負って階段を下りた」の接続形。て形で動作をつないでいる。"}, {"text": "背負おう", "is_correct": false, "explanation": "意志を表す形で、「背負おう階段を下りた」と続かず、文が成り立たない。"}, {"text": "背負います", "is_correct": false, "explanation": "丁寧な言い方の形で、後ろの「階段を下りた」とつながらない。"}, {"text": "背負われ", "is_correct": false, "explanation": "受け身の連用形で、「背負われ」と続けると主体が入れ替わり、「階段を下りた」に自然につながらない。"}], "correct_form": "背負って", "base_form": "背負う", "form_label": "て形", "sentence_index": 7, "explanations": {"背負って": "「けが人を背負って階段を下りた」の接続形。て形で動作をつないでいる。", "背負おう": "意志を表す形で、「背負おう階段を下りた」と続かず、文が成り立たない。", "背負います": "丁寧な言い方の形で、後ろの「階段を下りた」とつながらない。", "背負われ": "受け身の連用形で、「背負われ」と続けると主体が入れ替わり、「階段を下りた」に自然につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52333, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "易", "is_correct": true, "explanation": "「容易」の意で、〈難〉の対義語として辞書に載る。することの困難さの反対を表す。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は湿り気がない状態を指し、〈難〉の対義語にはならない。"}, {"text": "厚み", "is_correct": false, "explanation": "厚みは物の厚さを指し、〈難〉の対義語にはならない。"}, {"text": "順調", "is_correct": false, "explanation": "順調は進み具合が良いことを指すが、〈難〉の対義語として辞書に並ばない。"}], "correct_answer": "易", "explanations": {"易": "「容易」の意で、〈難〉の対義語として辞書に載る。することの困難さの反対を表す。", "乾燥": "乾燥は湿り気がない状態を指し、〈難〉の対義語にはならない。", "厚み": "厚みは物の厚さを指し、〈難〉の対義語にはならない。", "順調": "順調は進み具合が良いことを指すが、〈難〉の対義語として辞書に並ばない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52333, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "易", "is_correct": true, "explanation": "「容易」の意で、〈難〉の対義語として辞書に載る。困難さの反対を表す。"}, {"text": "利便", "is_correct": false, "explanation": "利便は使いやすさを指し、〈難〉の対義語としては並ばない。"}, {"text": "快適", "is_correct": false, "explanation": "快適は心地よさを指し、困難さの反対とは言えない。"}, {"text": "活力", "is_correct": false, "explanation": "活力は元気の源を指し、〈難〉の対義語とはならない。"}], "correct_answer": "易", "explanations": {"易": "「容易」の意で、〈難〉の対義語として辞書に載る。困難さの反対を表す。", "利便": "利便は使いやすさを指し、〈難〉の対義語としては並ばない。", "快適": "快適は心地よさを指し、困難さの反対とは言えない。", "活力": "活力は元気の源を指し、〈難〉の対義語とはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52333, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事をするのがむずかしいこと。", "primary_collocate": null, "pronunciation": "なん", "ipa": "naɴ", "syllable_count": 2, "sentences": [{"text": "この仕事は、一人でやるには難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "この仕事[しごと]は、一人[ひとり]でやるには難[なん]がある。", "sentence_source": "generated"}, {"text": "新しい道は広いが、夜は暗くて、歩いて帰るのに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "新[あたら]しい道[みち]は広[ひろ]いが、夜[よる]は暗[くら]くて、歩[ある]いて帰[かえ]るのに難[なん]がある。", "sentence_source": "generated"}, {"text": "このアパートは便利だが、大きな家具を運び込むのに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "このアパートは便利[べんり]だが、大[おお]きな家具[かぐ]を運[はこ]び込[こ]むのに難[なん]がある。", "sentence_source": "generated"}, {"text": "彼の案は面白いが、予算内で実行するのに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "彼[かれ]の案[あん]は面白[おもしろ]いが、予算内[よさんない]で実行[じっこう]するのに難[なん]がある。", "sentence_source": "generated"}, {"text": "この本は、小さな子どもが読むには難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "この本[ほん]は、小[ちい]さな子[こ]どもが読[よ]むには難[なん]がある。", "sentence_source": "generated"}, {"text": "一日で全部覚えるのは、さすがに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "一日[いちにち]で全部[ぜんぶ]覚[おぼ]えるのは、さすがに難[なん]がある。", "sentence_source": "generated"}, {"text": "この店は料理はおいしいが、駅から遠くて行くのに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "この店[みせ]は料理[りょうり]はおいしいが、駅[えき]から遠[とお]くて行[い]くのに難[なん]がある。", "sentence_source": "generated"}, {"text": "雨の日に自転車で通うのは、難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]に自転車[じてんしゃ]で通[かよ]うのは、難[なん]がある。", "sentence_source": "generated"}, {"text": "この機械は、説明書が英語だけで使うのに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "この機械[きかい]は、説明書[せつめいしょ]が英語[えいご]だけで使[つか]うのに難[なん]がある。", "sentence_source": "generated"}, {"text": "山の上まで荷物を運ぶには、道が細くて難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]まで荷物[にもつ]を運[はこ]ぶには、道[みち]が細[ほそ]くて難[なん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "難", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かをするのがむずかしい、うまくいきにくい点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52333, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "難", "is_correct": true, "explanation": "「一人でやるには難がある」の「難」で、することの困難さを表す。"}, {"text": "色", "is_correct": false, "explanation": "「一人でやるには色がある」は意味が通らない。"}, {"text": "名", "is_correct": false, "explanation": "「一人でやるには名がある」は成り立たず、文の内容と合わない。"}, {"text": "数", "is_correct": false, "explanation": "「一人でやるには数がある」は意味が通らない。"}], "explanations": {"難": "「一人でやるには難がある」の「難」で、することの困難さを表す。", "色": "「一人でやるには色がある」は意味が通らない。", "名": "「一人でやるには名がある」は成り立たず、文の内容と合わない。", "数": "「一人でやるには数がある」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "難"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長年の難が報われて、やっと新しい家を建てた。", "explanation": "ここは〈苦労〉の意味。苦労が報われるの〈苦労〉に当たるが、〈難〉は報われる対象にはならないので、この文には合わない。"}, {"text": "その仕事には難を折ったが、思ったより早く終わった。", "explanation": "ここは〈骨〉の意味。骨を折る（力を尽くす）の〈骨〉に当たるが、〈難〉には折るという使い方がないので合わない。"}, {"text": "丁寧に仕上げるには難をかける必要がある。", "explanation": "ここは〈手間〉の意味。手間をかけるの〈手間〉に当たるが、〈難〉は作業に注ぎ込むものではないので、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52333, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "難", "is_correct": true, "explanation": "「行くのに難がある」の「難」で、行くことの困難さを表す。"}, {"text": "欠", "is_correct": false, "explanation": "「行くのに欠がある」は成り立たず、文の内容と合わない。"}, {"text": "盾", "is_correct": false, "explanation": "「行くのに盾がある」は意味が通らない。"}, {"text": "恐", "is_correct": false, "explanation": "「行くのに恐がある」は不自然で、困難さを表さない。"}], "explanations": {"難": "「行くのに難がある」の「難」で、行くことの困難さを表す。", "欠": "「行くのに欠がある」は成り立たず、文の内容と合わない。", "盾": "「行くのに盾がある」は意味が通らない。", "恐": "「行くのに恐がある」は不自然で、困難さを表さない。"}, "sentence_index": 6, "correct_answer": "難"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長く入院した母の難を見て、毎日病院に通った。", "explanation": "ここは〈面倒〉の意味。面倒を見るの〈面倒〉に当たるが、〈難〉は〈むずかしさ〉を指すので、人の世話をする意味にはならない。"}, {"text": "失敗の原因を追及され、部長から厳しい難を受けた。", "explanation": "ここは〈叱責〉の意味。物事を行う困難さを指す〈難〉では、責められる場面には使えない。"}, {"text": "作業の難が整って、工程は予定どおり進んだ。", "explanation": "ここは〈手筈〉の意味。手筈が整うの〈手筈〉に当たるが、〈難〉は整える準備の対象ではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
