INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52334, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事をするのが容易ではなく、手間や努力が必要なこと。", "primary_collocate": null, "pronunciation": "なん", "ipa": "naɴ", "syllable_count": 2, "sentences": [{"text": "しかし、この成分は消化されにくく、栄養を取り出すのに難がある。", "target_word": "難", "complexity_tier": "T5", "furigana": "しかし、この成分[せいぶん]は消化[しょうか]されにくく、栄養[えいよう]を取[と]り出[だ]すのに難[なん]がある。", "sentence_source": "generated"}, {"text": "この計画は、資金の確保に難があり、実現はまだ先になりそうだ。", "target_word": "難", "complexity_tier": "T4", "furigana": "この計画[けいかく]は、資金[しきん]の確保[かくほ]に難[なん]があり、実現[じつげん]はまだ先[さき]になりそうだ。", "sentence_source": "generated"}, {"text": "山奥の村では、冬の移動に難が多いため、食料を早めに蓄える。", "target_word": "難", "complexity_tier": "T3", "furigana": "山奥[やまおく]の村[むら]では、冬[ふゆ]の移動[いどう]に難[なん]が多[おお]いため、食料[しょくりょう]を早[はや]めに蓄[たくわ]える。", "sentence_source": "generated"}, {"text": "彼の文章は内容はよいが、読みやすさに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "彼[かれ]の文章[ぶんしょう]は内容[ないよう]はよいが、読[よ]みやすさに難[なん]がある。", "sentence_source": "generated"}, {"text": "外国で部屋を探すとき、言葉の壁が最大の難だった。", "target_word": "難", "complexity_tier": "T4", "furigana": "外国[がいこく]で部屋[へや]を探[さが]すとき、言葉[ことば]の壁[かべ]が最大[さいだい]の難[なん]だった。", "sentence_source": "generated"}, {"text": "実験を成功させるには、温度を一定に保つという難がある。", "target_word": "難", "complexity_tier": "T4", "furigana": "実験[じっけん]を成功[せいこう]させるには、温度[おんど]を一定[いってい]に保[たも]つという難[なん]がある。", "sentence_source": "generated"}, {"text": "新製品は性能は高いが、価格が高く、普及に難がある。", "target_word": "難", "complexity_tier": "T4", "furigana": "新製品[しんせいひん]は性能[せいのう]は高[たか]いが、価格[かかく]が高[たか]く、普及[ふきゅう]に難[なん]がある。", "sentence_source": "generated"}, {"text": "この方法は理屈では簡単だが、実行に難があると専門家は指摘した。", "target_word": "難", "complexity_tier": "T4", "furigana": "この方法[ほうほう]は理屈[りくつ]では簡単[かんたん]だが、実行[じっこう]に難[なん]があると専門家[せんもんか]は指摘[してき]した。", "sentence_source": "generated"}, {"text": "資料が古すぎて、調査を続けるには難が多かった。", "target_word": "難", "complexity_tier": "T3", "furigana": "資料[しりょう]が古[ふる]すぎて、調査[ちょうさ]を続[つづ]けるには難[なん]が多[おお]かった。", "sentence_source": "generated"}, {"text": "手順は単純でも、毎日続けるとなると、そこに難がある。", "target_word": "難", "complexity_tier": "T3", "furigana": "手順[てじゅん]は単純[たんじゅん]でも、毎日[まいにち]続[つづ]けるとなると、そこに難[なん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "難", "label": "基本形"}], "register": "written", "sense_fingerprint": "物事を行う上での困難さや、手間と努力を要する点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52334, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "難", "is_correct": true, "explanation": "「取り出すのに難がある」の「難」で、消化・抽出の困難さを表す。"}, {"text": "軽", "is_correct": false, "explanation": "「取り出すのに軽がある」は成り立たず、困難さを表せない。"}, {"text": "良", "is_correct": false, "explanation": "「取り出すのに良がある」は不自然で、この文脈に合わない。"}, {"text": "強", "is_correct": false, "explanation": "「取り出すのに強がある」は文脈に合わず、困難さを表さない。"}], "explanations": {"難": "「取り出すのに難がある」の「難」で、消化・抽出の困難さを表す。", "軽": "「取り出すのに軽がある」は成り立たず、困難さを表せない。", "良": "「取り出すのに良がある」は不自然で、この文脈に合わない。", "強": "「取り出すのに強がある」は文脈に合わず、困難さを表さない。"}, "sentence_index": 0, "correct_answer": "難"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長年の難が実って、店は大きくなった。", "explanation": "ここは〈苦労〉の意味。苦労が実るの〈苦労〉に当たる語だが、〈難〉は努力の果てに得る実りを表さないので、この文には合わない。"}, {"text": "この作業は難がかかるが、丁寧に仕上がった。", "explanation": "ここは〈手間〉の意味。手間がかかるの〈手間〉に当たるが、〈難〉は作業に費やす時間や労力そのものを指さないので、この言い方は成り立たない。"}, {"text": "この作業は難が折れるが、皆で協力してやり遂げた。", "explanation": "ここは〈骨〉の意味。骨が折れる（大変な努力を要する）の〈骨〉に当たるが、〈難〉は折れるものではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52334, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "難", "is_correct": true, "explanation": "「普及に難がある」の「難」で、普及の困難さを表す。"}, {"text": "欠", "is_correct": false, "explanation": "「普及に欠がある」は不自然で、この語を単独で目的語的に使うことはない。"}, {"text": "盾", "is_correct": false, "explanation": "「普及に盾がある」は意味が通らず、普及の困難を表さない。"}, {"text": "恐", "is_correct": false, "explanation": "「普及に恐がある」は成り立たず、文の内容と合わない。"}], "explanations": {"難": "「普及に難がある」の「難」で、普及の困難さを表す。", "欠": "「普及に欠がある」は不自然で、この語を単独で目的語的に使うことはない。", "盾": "「普及に盾がある」は意味が通らず、普及の困難を表さない。", "恐": "「普及に恐がある」は成り立たず、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "難"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は戦争の混乱の中で、幼い弟妹の難を見て暮らした。", "explanation": "ここは〈面倒〉の意味。面倒を見るの〈面倒〉に当たるが、〈難〉は〈むずかしさ〉を指すので、人の世話をする意味にはならない。"}, {"text": "失敗の原因を追及され、部長から厳しい難を受けた。", "explanation": "ここは〈叱責〉の意味。物事を行う困難さを指す〈難〉では、人から責められる場面には使えない。"}, {"text": "作業中に難が狂って、工程が一日遅れた。", "explanation": "ここは〈段取り〉の意味。段取りが狂うの〈段取り〉に当たるが、〈難〉は計画や順序を指さないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52334, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山道は、夜の運転を難がある。", "corrected_sentence": "山道は、夜の運転に難がある。", "error_description": "「～に難がある」の「に」が正しい。「を」を使うと、難が運転の目的語のように見えて文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52334, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この案は、実行に難を持つ。", "corrected_sentence": "この案は、実行に難がある。", "error_description": "「難がある」と言い、「難を持つ」とは言わない。動詞を「ある」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
