INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52335, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "どうしてもそうなること。", "primary_collocate": null, "pronunciation": "しゅくめい", "ipa": "ɕɯkɯmeː", "syllable_count": 4, "sentences": [{"text": "成功した店は、まねされる宿命にある。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "成功[せいこう]した店[みせ]は、まねされる宿命[しゅくめい]にある。", "sentence_source": "generated"}, {"text": "新しい技術は、いつか古くなって使われなくなる宿命だ。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]は、いつか古[ふる]くなって使[つか]われなくなる宿命[しゅくめい]だ。", "sentence_source": "generated"}, {"text": "人気者は、批判もされる宿命だと彼は笑った。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "人気者[にんきもの]は、批判[ひはん]もされる宿命[しゅくめい]だと彼[かれ]は笑[わら]った。", "sentence_source": "generated"}, {"text": "紙の本は湿気に弱く、長く置けば傷む宿命にある。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "紙[かみ]の本[ほん]は湿気[しっけ]に弱[よわ]く、長[なが]く置[お]けば傷[いた]む宿命[しゅくめい]にある。", "sentence_source": "generated"}, {"text": "花は咲けば散る宿命だからこそ、人は桜を美しいと思う。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "花[はな]は咲[さ]けば散[ち]る宿命[しゅくめい]だからこそ、人[ひと]は桜[さくら]を美[うつく]しいと思[おも]う。", "sentence_source": "generated"}, {"text": "有名になれば、私生活を見られる宿命からは逃れられない。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "有名[ゆうめい]になれば、私生活[しせいかつ]を見[み]られる宿命[しゅくめい]からは逃[のが]れられない。", "sentence_source": "generated"}, {"text": "先に走る者は風を受ける宿命で、後ろの選手は楽に走れる。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "先[さき]に走[はし]る者[もの]は風[かぜ]を受[う]ける宿命[しゅくめい]で、後[うし]ろの選手[せんしゅ]は楽[らく]に走[はし]れる。", "sentence_source": "generated"}, {"text": "成長した会社は、組織が大きくなって動きが遅くなる宿命がある。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "成長[せいちょう]した会社[かいしゃ]は、組織[そしき]が大[おお]きくなって動[うご]きが遅[おそ]くなる宿命[しゅくめい]がある。", "sentence_source": "generated"}, {"text": "鉄は空気に触れると、さびていく宿命だ。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "鉄[てつ]は空気[くうき]に触[ふ]れると、さびていく宿命[しゅくめい]だ。", "sentence_source": "generated"}, {"text": "食べ物は、時間が経てば味が落ちる宿命にある。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]は、時間[じかん]が経[た]てば味[あじ]が落[お]ちる宿命[しゅくめい]にある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿命", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "物事の性質上、必ずそうなってしまう成り行き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52335, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "「必ずそうなってしまう成り行き」の意味で、「まねされる宿命にある」に入る。"}, {"text": "手紙", "is_correct": false, "explanation": "「まねされる手紙にある」は意味が通らない。"}, {"text": "順番", "is_correct": false, "explanation": "「まねされる順番にある」は成り立たず、文の内容と合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「まねされる季節にある」は不自然で、必然を表さない。"}], "explanations": {"宿命": "「必ずそうなってしまう成り行き」の意味で、「まねされる宿命にある」に入る。", "手紙": "「まねされる手紙にある」は意味が通らない。", "順番": "「まねされる順番にある」は成り立たず、文の内容と合わない。", "季節": "「まねされる季節にある」は不自然で、必然を表さない。"}, "sentence_index": 0, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は長い迷いの末に、留学の宿命を固めた。", "explanation": "ここは〈決心〉の意味。決心を固めるの〈決心〉に当たるが、宿命は自分で決める性質のものではないので、この文には合わない。"}, {"text": "出先で思わぬ宿命に見舞われ、計画を変えた。", "explanation": "ここは〈ハプニング〉の語を入れ替えたもの。必然を表す宿命は、突発的な出来事の文には合わない。"}, {"text": "またとない宿命を逃してしまった。", "explanation": "ここは〈チャンス〉の語を入れ替えたもの。宿命は機会ではなく必然を表すので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52335, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "「風を受ける宿命」の意味で、必ずそうなる成り行きを表す。"}, {"text": "蓄え", "is_correct": false, "explanation": "「風を受ける蓄えで」は意味が通らない。"}, {"text": "手柄", "is_correct": false, "explanation": "「風を受ける手柄で」は不自然で、必然の文脈に合わない。"}, {"text": "風景", "is_correct": false, "explanation": "「風を受ける風景で」は成り立たず、文の内容と合わない。"}], "explanations": {"宿命": "「風を受ける宿命」の意味で、必ずそうなる成り行きを表す。", "蓄え": "「風を受ける蓄えで」は意味が通らない。", "手柄": "「風を受ける手柄で」は不自然で、必然の文脈に合わない。", "風景": "「風を受ける風景で」は成り立たず、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日の宿命が実って、大会で優勝した。", "explanation": "ここは〈努力〉の意味。努力が実るの〈努力〉に当たるが、宿命は避けられない成り行きを指し、成果として実るものではないので合わない。"}, {"text": "宿命に恵まれて、仕事が順調に進んだ。", "explanation": "ここは〈幸運〉の意味。幸運に恵まれるの〈幸運〉に当たるが、宿命は避けられない運命を指すので、ありがたい巡り合わせの文には合わない。"}, {"text": "念入りに宿命を整えたおかげで、発表はうまくいった。", "explanation": "ここは〈準備〉の意味。準備を整えるの〈準備〉に当たるが、宿命は整えるものではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52335, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械は、使い続ければ壊れる宿命をある。", "corrected_sentence": "この機械は、使い続ければ壊れる宿命にある。", "error_description": "「宿命にある」の「に」と「ある」が正しい。「を」を使うと「宿命をある」となり、文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52335, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い機械は、いつか止まる宿命を消す。", "corrected_sentence": "古い機械は、いつか止まる宿命にある。", "error_description": "「宿命にある」と言い、「宿命を消す」とは言わない。「を消す」を「にある」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「宿命を受け入れている」の「を」。宿命の直後に置いて目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「宿命が受け入れている」は主語と動詞が合わず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「宿命へ受け入れている」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を表すため、「宿命の受け入れている」は文として壊れる。"}], "correct_answer": "を", "explanations": {"を": "「宿命を受け入れている」の「を」。宿命の直後に置いて目的語を示す。", "が": "「宿命が受け入れている」は主語と動詞が合わず、意味が通らない。", "へ": "「へ」は方向を表すため、「宿命へ受け入れている」は成り立たない。", "の": "「の」は所属や修飾を表すため、「宿命の受け入れている」は文として壊れる。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生まれながらに決まっている、避けられない運命。", "primary_collocate": null, "pronunciation": "しゅくめい", "ipa": "ɕɯkɯmeː", "syllable_count": 4, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "例[たと]えば、穀物[こくもつ]や豆類[まめるい]を主食[しゅしょく]として摂取[せっしゅ]する際[さい]、その細胞壁[さいぼうへき]に阻[はば]まれた栄養[えいよう]は、生体[せいたい]利用率[りようりつ]が低[ひく]いという宿命[しゅくめい]を背負[せお]っている。", "sentence_source": "mined"}, {"text": "王家に生まれた彼は、国を継ぐ宿命を背負っていた。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "王家[おうけ]に生[う]まれた彼[かれ]は、国[くに]を継[つ]ぐ宿命[しゅくめい]を背負[せお]っていた。", "sentence_source": "generated"}, {"text": "二人は敵同士として戦う宿命にあったが、心の底ではお互いを尊敬していた。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "二人[ふたり]は敵同士[てきどうし]として戦[たたか]う宿命[しゅくめい]にあったが、心[こころ]の底[そこ]ではお互[たが]いを尊敬[そんけい]していた。", "sentence_source": "generated"}, {"text": "彼女は「これは私の宿命だ」と言って、家業の寺を継ぐことを決めた。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は「これは私[わたし]の宿命[しゅくめい]だ」と言[い]って、家業[かぎょう]の寺[てら]を継[つ]ぐことを決[き]めた。", "sentence_source": "generated"}, {"text": "生き物はみな、いつか死ぬ宿命を背負って生まれてくる。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "生[い]き物[もの]はみな、いつか死[し]ぬ宿命[しゅくめい]を背負[せお]って生[う]まれてくる。", "sentence_source": "generated"}, {"text": "長男に生まれた宿命を受け入れ、彼は故郷に戻った。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "長男[ちょうなん]に生[う]まれた宿命[しゅくめい]を受[う]け入[い]れ、彼[かれ]は故郷[こきょう]に戻[もど]った。", "sentence_source": "generated"}, {"text": "二人は宿命のライバルと呼ばれ、何十年も優勝を争ってきた。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "二人[ふたり]は宿命[しゅくめい]のライバルと呼[よ]ばれ、何十年[なんじゅうねん]も優勝[ゆうしょう]を争[あらそ]ってきた。", "sentence_source": "generated"}, {"text": "この島の人々は、台風と向き合って暮らす宿命を受け入れている。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "この島[しま]の人々[ひとびと]は、台風[たいふう]と向[む]き合[あ]って暮[く]らす宿命[しゅくめい]を受[う]け入[い]れている。", "sentence_source": "generated"}, {"text": "彼は医者の家に生まれた宿命から逃れようと、家を出て音楽の道に進んだ。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "彼[かれ]は医者[いしゃ]の家[いえ]に生[う]まれた宿命[しゅくめい]から逃[のが]れようと、家[いえ]を出[で]て音楽[おんがく]の道[みち]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "有名な家に生まれた子どもは、注目される宿命から逃れられない。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な家[いえ]に生[う]まれた子[こ]どもは、注目[ちゅうもく]される宿命[しゅくめい]から逃[のが]れられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿命", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "生まれつき定められていて逃れられない運命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "「生まれつき決まった避けられない運命」の意味で、「という宿命を背負っている」に入る。"}, {"text": "季節", "is_correct": false, "explanation": "「という季節を背負っている」は成り立たず、文の内容と合わない。"}, {"text": "順番", "is_correct": false, "explanation": "「という順番を背負っている」は意味が通らない。"}, {"text": "手順", "is_correct": false, "explanation": "「という手順を背負っている」は不自然で、運命の文脈に合わない。"}], "explanations": {"宿命": "「生まれつき決まった避けられない運命」の意味で、「という宿命を背負っている」に入る。", "季節": "「という季節を背負っている」は成り立たず、文の内容と合わない。", "順番": "「という順番を背負っている」は意味が通らない。", "手順": "「という手順を背負っている」は不自然で、運命の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は宿命に燃えて、新しい事業を立ち上げた。", "explanation": "ここは〈使命〉（果たすべき務め）の意味。使命に燃えるの〈使命〉に当たるが、宿命は避けられない運命を指すので、やる気を表す文には合わない。"}, {"text": "旅先で、宿命の看板が倒れ、予定を変えた。", "explanation": "ここは〈ハプニング〉の語を入れ替えたもの。看板が倒れる出来事に「宿命」は付かず、避けられない運命の意味では成り立たない。"}, {"text": "またとない宿命を逃してしまい、悔しかった。", "explanation": "ここは〈チャンス〉の語を入れ替えたもの。宿命は機会ではなく運命を表すので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "「宿命のライバル」の「宿命」で、生まれつき定まった巡り合わせの意味。"}, {"text": "地図", "is_correct": false, "explanation": "「地図のライバル」は意味が通らない。"}, {"text": "伝票", "is_correct": false, "explanation": "「伝票のライバル」は成り立たず、文の内容と合わない。"}, {"text": "献立", "is_correct": false, "explanation": "「献立のライバル」は不自然で、対戦の関係を表さない。"}], "explanations": {"宿命": "「宿命のライバル」の「宿命」で、生まれつき定まった巡り合わせの意味。", "地図": "「地図のライバル」は意味が通らない。", "伝票": "「伝票のライバル」は成り立たず、文の内容と合わない。", "献立": "「献立のライバル」は不自然で、対戦の関係を表さない。"}, "sentence_index": 6, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この祭りは三百年の宿命を持ち、地域の誇りになっている。", "explanation": "ここは〈伝統〉の語を入れ替えたもの。宿命は避けられない運命を表すので、代々続く慣わしの文には合わない。"}, {"text": "毎朝の散歩は宿命になっていて、雨の日も休まない。", "explanation": "ここは〈ルーティン〉の語を入れ替えたもの。習慣を指す文で、生まれつきの運命を表す宿命は合わない。"}, {"text": "試合の前に靴を左から履くのが、彼の宿命になっている。", "explanation": "ここは〈ジンクス〉の語を入れ替えたもの。験担ぎを指す文で、避けられない運命の宿命は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は一族の宿命を逃れられない。", "corrected_sentence": "彼は一族の宿命から逃れられない。", "error_description": "「逃れる」は「から」を取る。「宿命を逃れる」は誤りで、「宿命から逃れる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52336, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、生まれた宿命に背負って生きてきた。", "corrected_sentence": "彼は、生まれた宿命を背負って生きてきた。", "error_description": "「背負う」は「を」を取る。「宿命に背負う」は誤りで、「宿命を背負う」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
