INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52338, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "アミノ基をもつことを表す語。多く「アミノ酸」の形で使う。", "primary_collocate": null, "pronunciation": "あみの", "ipa": "amino", "syllable_count": 3, "sentences": [{"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "さらに、アミノ酸[さん]や有機酸[ゆうきさん]が複雑[ふくざつ]に絡[から]み合[あ]い、主食[しゅしょく]に奥深[おくぶか]い風味[ふうみ]と旨味[うまみ]の層[そう]を付与[ふよ]する。", "sentence_source": "mined"}, {"text": "体を作るたんぱく質は、約二十種類のアミノ酸が組み合わさってできている。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "体[からだ]を作[つく]るたんぱく質[しつ]は、約[やく]二十[にじゅう]種類[しゅるい]のアミノ酸[さん]が組[く]み合[あ]わさってできている。", "sentence_source": "generated"}, {"text": "卵には、人の体に必要なアミノ酸がバランスよく含まれている。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "卵[たまご]には、人[ひと]の体[からだ]に必要[ひつよう]なアミノ酸[さん]がバランスよく含[ふく]まれている。", "sentence_source": "generated"}, {"text": "アミノ酸のうち、体内で作れないものは食べ物から取らなければならない。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "アミノ酸[さん]のうち、体内[たいない]で作[つく]れないものは食[た]べ物[もの]から取[と]らなければならない。", "sentence_source": "generated"}, {"text": "昆布のうま味は、アミノ酸の一種であるグルタミン酸によるものだ。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "昆布[こんぶ]のうま味[あじ]は、アミノ酸[さん]の一種[いっしゅ]であるグルタミン酸[さん]によるものだ。", "sentence_source": "generated"}, {"text": "先生は黒板に、アミノ基の構造を図で書いて説明した。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に、アミノ基[き]の構造[こうぞう]を図[ず]で書[か]いて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "筋肉をつくるために、運動のあとにアミノ酸入りの飲料を飲む選手が多い。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "筋肉[きんにく]をつくるために、運動[うんどう]のあとにアミノ酸[さん]入[い]りの飲料[いんりょう]を飲[の]む選手[せんしゅ]が多[おお]い。", "sentence_source": "generated"}, {"text": "納豆は発酵のあいだにたんぱく質が分解され、アミノ酸が増える。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "納豆[なっとう]は発酵[はっこう]のあいだにたんぱく質[しつ]が分解[ぶんかい]され、アミノ酸[さん]が増[ふ]える。", "sentence_source": "generated"}, {"text": "このシャンプーはアミノ酸系の洗浄成分を使っているので、肌にやさしい。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "このシャンプーはアミノ酸系[さんけい]の洗浄[せんじょう]成分[せいぶん]を使[つか]っているので、肌[はだ]にやさしい。", "sentence_source": "generated"}, {"text": "髪の主成分であるケラチンも、アミノ酸がつながってできている。", "target_word": "アミノ", "complexity_tier": "T3", "furigana": "髪[かみ]の主成分[しゅせいぶん]であるケラチンも、アミノ酸[さん]がつながってできている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アミノ", "label": "基本形"}], "register": "科学用語", "sense_fingerprint": "アミノ基をもつ化合物を表す化学用語の語頭要素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28dcc40d-11f8-47e4-8cd3-df3fa8c0588d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52338, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アミノ", "is_correct": true, "explanation": "正解。「アミノ酸」の語頭要素で、空欄の後ろが「酸」と続くので「アミノ」が入る。"}, {"text": "グルコース", "is_correct": false, "explanation": "ブドウ糖を表す語。「グルコース酸」という語はなく、「〜酸や有機酸」の形に入らない。"}, {"text": "デンプン", "is_correct": false, "explanation": "多糖類を表す語。「デンプン酸」とは言わないので、「〜酸」の形に合わない。"}, {"text": "コラーゲン", "is_correct": false, "explanation": "たんぱく質の一種。「コラーゲン酸」とは言わないので、空欄に入らない。"}], "explanations": {"アミノ": "正解。「アミノ酸」の語頭要素で、空欄の後ろが「酸」と続くので「アミノ」が入る。", "グルコース": "ブドウ糖を表す語。「グルコース酸」という語はなく、「〜酸や有機酸」の形に入らない。", "デンプン": "多糖類を表す語。「デンプン酸」とは言わないので、「〜酸」の形に合わない。", "コラーゲン": "たんぱく質の一種。「コラーゲン酸」とは言わないので、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "アミノ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この果物にはアミノが多く含まれているので、風邪の予防に役立つ。", "explanation": "「アミノ」は単独では名詞にならず、「アミノ酸」の形でしか使わない。ここでは単独で成分名として置かれているため誤り。"}, {"text": "レバーにはアミノが豊富で、貧血の予防に役立つ。", "explanation": "「アミノ」は単独では名詞として使えず、「アミノ酸」の形で使うため、この文では誤り。"}, {"text": "この料理はアミノが少なくて、ヘルシーだ。", "explanation": "「アミノ」は単独で量を表す名詞にならず、「アミノ酸」の形で使うため誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52338, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アミノ", "is_correct": true, "explanation": "正解。「アミノ酸入り」の形で、空欄の後ろが「酸入り」と続く。"}, {"text": "プロテイン", "is_correct": false, "explanation": "たんぱく質を指す語。「プロテイン酸」とは言わないので、「〜酸入り」に合わない。"}, {"text": "スクロース", "is_correct": false, "explanation": "砂糖の主成分。「スクロース酸」という語はなく、ここには入らない。"}, {"text": "ビール", "is_correct": false, "explanation": "醸造酒の名前。「ビール酸」とは言わないので、空欄に合わない。"}], "explanations": {"アミノ": "正解。「アミノ酸入り」の形で、空欄の後ろが「酸入り」と続く。", "プロテイン": "たんぱく質を指す語。「プロテイン酸」とは言わないので、「〜酸入り」に合わない。", "スクロース": "砂糖の主成分。「スクロース酸」という語はなく、ここには入らない。", "ビール": "醸造酒の名前。「ビール酸」とは言わないので、空欄に合わない。"}, "sentence_index": 6, "correct_answer": "アミノ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスイカはアミノが多く、夏に食べると体がすっきりする。", "explanation": "「アミノ」は単独では成分名にならず、「アミノ酸」の形で使うため誤り。"}, {"text": "野菜にはアミノが多く、腸の調子を整える働きがある。", "explanation": "「アミノ」は単独では使えず、「アミノ酸」など「アミノ」を含む語の形で使うため誤り。"}, {"text": "海藻にはアミノが豊富で、骨の健康に役立つ。", "explanation": "「アミノ」だけでは成分名にならず、「アミノ酸」として使う語なので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52338, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このプロテインには、運動後に必要なアミノ酸を含まれている。", "corrected_sentence": "このプロテインには、運動後に必要なアミノ酸が含まれている。", "error_description": "「含まれる」の主語は含まれるもの（アミノ酸）なので助詞は「が」。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52338, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "たんぱく質の多くは、数十種類のアミノ酸を連なってできている。", "corrected_sentence": "たんぱく質の多くは、数十種類のアミノ酸が連なってできている。", "error_description": "「連なる」は自動詞なので「を」は取らない。アミノ酸が主語なので「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b0eb29-0183-45dd-894a-460755c131c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「フィチンの働き」で、名詞を修飾する連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞の目的語用。「フィチンを働き」では名詞同士がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すため、「フィチンに働き」では名詞がつながらず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「フィチンで働き」では名詞同士がつながらない。"}], "correct_answer": "の", "explanations": {"の": "「フィチンの働き」で、名詞を修飾する連体修飾の「の」。", "を": "「を」は動詞の目的語用。「フィチンを働き」では名詞同士がつながらない。", "に": "「に」は相手や場所を示すため、「フィチンに働き」では名詞がつながらず成り立たない。", "で": "「で」は手段や場所を示すため、「フィチンで働き」では名詞同士がつながらない。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の種や豆の中にあって、体に必要な栄養の吸い方をじゃまするもの。", "primary_collocate": null, "pronunciation": "ふぃちん", "ipa": "ɸitɕiɴ", "syllable_count": 3, "sentences": [{"text": "豆にはフィチンというものが入っていて、体が栄養を取り入れにくくなる。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "豆[まめ]にはフィチンというものが入[はい]っていて、体[からだ]が栄養[えいよう]を取[と]り入[い]れにくくなる。", "sentence_source": "generated"}, {"text": "フィチンは、米や麦の種の中にある成分だ。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "フィチンは、米[こめ]や麦[むぎ]の種[たね]の中[なか]にある成分[せいぶん]だ。", "sentence_source": "generated"}, {"text": "フィチンが多い食べ物ばかり食べると、鉄分が体に入りにくくなる。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "フィチンが多[おお]い食[た]べ物[もの]ばかり食[た]べると、鉄分[てつぶん]が体[からだ]に入[はい]りにくくなる。", "sentence_source": "generated"}, {"text": "フィチンは熱にあまり弱くないので、煮るだけではなかなか減らない。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "フィチンは熱[ねつ]にあまり弱[よわ]くないので、煮[に]るだけではなかなか減[へ]らない。", "sentence_source": "generated"}, {"text": "先生は「フィチンは栄養のじゃまをするけれど、悪いものではありません」と言った。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "先生[せんせい]は「フィチンは栄養[えいよう]のじゃまをするけれど、悪[わる]いものではありません」と言[い]った。", "sentence_source": "generated"}, {"text": "このサイトには、フィチンを減らす豆の料理方法が書いてある。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "このサイトには、フィチンを減[へ]らす豆[まめ]の料理方法[りょうりほうほう]が書[か]いてある。", "sentence_source": "generated"}, {"text": "ナッツにもフィチンが含まれているが、少量なら問題ない。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "ナッツにもフィチンが含[ふく]まれているが、少量[しょうりょう]なら問題[もんだい]ない。", "sentence_source": "generated"}, {"text": "母は、フィチンの働きを弱めるために、玄米を長い時間水につけた。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "母[はは]は、フィチンの働[はたら]きを弱[よわ]めるために、玄米[げんまい]を長[なが]い時間[じかん]水[みず]につけた。", "sentence_source": "generated"}, {"text": "弟は貧血なので、医者にフィチンの多い食べ物に気をつけるよう言われた。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "弟[おとうと]は貧血[ひんけつ]なので、医者[いしゃ]にフィチンの多[おお]い食[た]べ物[もの]に気[き]をつけるよう言[い]われた。", "sentence_source": "generated"}, {"text": "フィチンは植物にとって、種にリンをためておくための大切な成分だ。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "フィチンは植物[しょくぶつ]にとって、種[たね]にリンをためておくための大切[たいせつ]な成分[せいぶん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フィチン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "種や豆に入っていて、体が栄養を取り入れるのをじゃまするもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フィチン", "is_correct": true, "explanation": "「フィチンというもの」で、栄養の取り入れを妨げる成分を指す。"}, {"text": "ビタミン", "is_correct": false, "explanation": "ビタミンは体に必要な栄養素で、栄養の取り入れを妨げるものとして説明されないので合わない。"}, {"text": "カルシウム", "is_correct": false, "explanation": "カルシウムはミネラルの一種で、栄養の取り入れを邪魔する成分ではないので合わない。"}, {"text": "デンプン", "is_correct": false, "explanation": "デンプンは炭水化物で、栄養の取り入れを妨げる成分ではないので、この文脈に合わない。"}], "explanations": {"フィチン": "「フィチンというもの」で、栄養の取り入れを妨げる成分を指す。", "ビタミン": "ビタミンは体に必要な栄養素で、栄養の取り入れを妨げるものとして説明されないので合わない。", "カルシウム": "カルシウムはミネラルの一種で、栄養の取り入れを邪魔する成分ではないので合わない。", "デンプン": "デンプンは炭水化物で、栄養の取り入れを妨げる成分ではないので、この文脈に合わない。"}, "sentence_index": 0, "correct_answer": "フィチン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このフィチンは熱に弱いので、低温でゆっくり保存しておく。", "explanation": "ここは〈酵素〉の意味。フィチンは熱で働きを失う酵素ではなく、栄養の吸い方を邪魔する成分なので合わない。"}, {"text": "このお菓子は、フィチンを加えて香ばしい香りを強くしている。", "explanation": "ここは〈香料〉の意味。フィチンは香りを出す物質ではないので、香りづけには使えない。"}, {"text": "フィチンは油汚れをよく落とすので、食器洗いに使われている。", "explanation": "ここは〈洗剤〉の意味。フィチンは汚れを落とす道具ではなく、栄養の吸収を妨げる成分なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フィチン", "is_correct": true, "explanation": "「フィチンが含まれているが、少量なら問題ない」で、吸収を妨げる成分として使われている語。"}, {"text": "カロテン", "is_correct": false, "explanation": "カロテンは色素の一種で、ここで述べている吸収を妨げる成分を指さないので合わない。"}, {"text": "タンパク質", "is_correct": false, "explanation": "タンパク質は体を作る栄養素で、「少量なら問題ない」と注意される対象ではないので合わない。"}, {"text": "乳酸菌", "is_correct": false, "explanation": "乳酸菌は微生物で、ナッツに含まれる成分として述べる文脈に合わない。"}], "explanations": {"フィチン": "「フィチンが含まれているが、少量なら問題ない」で、吸収を妨げる成分として使われている語。", "カロテン": "カロテンは色素の一種で、ここで述べている吸収を妨げる成分を指さないので合わない。", "タンパク質": "タンパク質は体を作る栄養素で、「少量なら問題ない」と注意される対象ではないので合わない。", "乳酸菌": "乳酸菌は微生物で、ナッツに含まれる成分として述べる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "フィチン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このにんじんは、フィチンで鮮やかなオレンジ色になっている。", "explanation": "ここは〈色素〉の意味。フィチンは色をつける物質ではないので、色の説明には合わない。"}, {"text": "フィチンは腸を整えるので、毎日の食事で少しずつ摂るとよい。", "explanation": "ここは〈食物繊維〉の意味。フィチンは腸を整える成分ではなく、種にリンを蓄える成分なので合わない。"}, {"text": "フィチンは、砂糖の代わりに使える甘味料として市販されている。", "explanation": "ここは〈甘味料〉の意味。フィチンは甘みを出す物質ではなく、砂糖の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "フィチンを雑穀の種にも多く含まれている。", "corrected_sentence": "フィチンは雑穀の種にも多く含まれている。", "error_description": "「含まれている」の主語になるため、フィチンには「は」が正しい。「を」は目的語の助詞で誤り（正しい形：フィチンは雑穀の種にも多く含まれている）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52339, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "フィチンは熱に強いので、ゆでただけでは減りにくかい。", "corrected_sentence": "フィチンは熱に強いので、ゆでただけでは減りにくい。", "error_description": "「減りにくい」は動詞「減る」の連用形＋「にくい」の形。「減りにくかい」は活用の誤りで、正しい形は「減りにくい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「フィチンが多く含まれている」で、フィチンは「含まれる」の主語なので「が」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語用。ここは受け身の「含まれる」なので主語の「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「フィチンへ多く」と続かず、「含まれる」の文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「フィチンから多く含まれている」と続かず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「フィチンが多く含まれている」で、フィチンは「含まれる」の主語なので「が」。", "を": "「を」は他動詞の目的語用。ここは受け身の「含まれる」なので主語の「が」が必要。", "へ": "方向の「へ」は「フィチンへ多く」と続かず、「含まれる」の文脈に合わない。", "から": "起点の「から」は「フィチンから多く含まれている」と続かず、不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の種子や穀物などに含まれる化合物で、体内でミネラル（鉄や亜鉛など）の吸収を妨げる働きをする成分。アクやえぐみの原因となることもある。", "primary_collocate": null, "pronunciation": "ふぃちん", "ipa": "ɸitɕiɴ", "syllable_count": 3, "sentences": [{"text": "しかし、微生物の営みを経ることで、難消化性の成分は低分子化され、栄養価が劇的に向上するのみならず、フィチンなどの抗栄養因子も分解される。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "しかし、微生物[びせいぶつ]の営[いとな]みを経[へ]ることで、難消化性[なんしょうかせい]の成分[せいぶん]は低分子化[ていぶんしか]され、栄養価[えいようか]が劇的[げきてき]に向上[こうじょう]するのみならず、フィチンなどの抗栄養因子[こうえいよういんし]も分解[ぶんかい]される。", "sentence_source": "generated"}, {"text": "玄米にはフィチンが多く含まれているため、食べ過ぎると鉄の吸収が悪くなることがある。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "玄米[げんまい]にはフィチンが多[おお]く含[ふく]まれているため、食[た]べ過[す]ぎると鉄[てつ]の吸収[きゅうしゅう]が悪[わる]くなることがある。", "sentence_source": "generated"}, {"text": "豆を一晩水につけておくと、フィチンの一部が水に溶け出して減る。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "豆[まめ]を一晩[ひとばん]水[みず]につけておくと、フィチンの一部[いちぶ]が水[みず]に溶[と]け出[だ]して減[へ]る。", "sentence_source": "generated"}, {"text": "フィチンはミネラルと結びつくので、体が鉄や亜鉛を取り込みにくくなる。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "フィチンはミネラルと結[むす]びつくので、体[からだ]が鉄[てつ]や亜鉛[あえん]を取[と]り込[こ]みにくくなる。", "sentence_source": "generated"}, {"text": "発芽させた穀物は、フィチンが分解されて栄養を吸収しやすくなると言われている。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "発芽[はつが]させた穀物[こくもつ]は、フィチンが分解[ぶんかい]されて栄養[えいよう]を吸収[きゅうしゅう]しやすくなると言[い]われている。", "sentence_source": "generated"}, {"text": "栄養士は、貧血気味の人にフィチンを多く含む食品を摂りすぎないよう勧めた。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "栄養士[えいようし]は、貧血気味[ひんけつぎみ]の人[ひと]にフィチンを多[おお]く含[ふく]む食品[しょくひん]を摂[と]りすぎないよう勧[すす]めた。", "sentence_source": "generated"}, {"text": "豆のアクやえぐみは、フィチンなどの成分が原因の一つだと考えられている。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "豆[まめ]のアクやえぐみは、フィチンなどの成分[せいぶん]が原因[げんいん]の一[ひと]つだと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "フィチンは健康に悪い成分だと思われがちだが、抗酸化作用を持つという研究もある。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "フィチンは健康[けんこう]に悪[わる]い成分[せいぶん]だと思[おも]われがちだが、抗酸化作用[こうさんかさよう]を持[も]つという研究[けんきゅう]もある。", "sentence_source": "generated"}, {"text": "パンを発酵させる過程で、フィチンは酵素によって少しずつ分解される。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "パンを発酵[はっこう]させる過程[かてい]で、フィチンは酵素[こうそ]によって少[すこ]しずつ分解[ぶんかい]される。", "sentence_source": "generated"}, {"text": "穀物に含まれるフィチンの量は、品種や育った環境によって大きく異なる。", "target_word": "フィチン", "complexity_tier": "T3", "furigana": "穀物[こくもつ]に含[ふく]まれるフィチンの量[りょう]は、品種[ひんしゅ]や育[そだ]った環境[かんきょう]によって大[おお]きく異[こと]なる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フィチン", "label": "基本形"}], "register": "専門的・書き言葉", "sense_fingerprint": "穀物や豆に含まれ、鉄や亜鉛などミネラルの吸収を妨げる成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フィチン", "is_correct": true, "explanation": "「フィチンなどの抗栄養因子」で、ミネラルの吸収を妨げる成分の名前。"}, {"text": "ビタミンC", "is_correct": false, "explanation": "ビタミンCは体に必要な栄養素で、抗栄養因子として挙げられないので合わない。"}, {"text": "デンプン", "is_correct": false, "explanation": "「デンプン酸」という名称はなく、抗栄養因子の名前として文脈に合わない。"}, {"text": "カロテン", "is_correct": false, "explanation": "カロテンは色素の一種で、抗栄養因子の名称として使われる語ではないので合わない。"}], "explanations": {"フィチン": "「フィチンなどの抗栄養因子」で、ミネラルの吸収を妨げる成分の名前。", "ビタミンC": "ビタミンCは体に必要な栄養素で、抗栄養因子として挙げられないので合わない。", "デンプン": "「デンプン酸」という名称はなく、抗栄養因子の名前として文脈に合わない。", "カロテン": "カロテンは色素の一種で、抗栄養因子の名称として使われる語ではないので合わない。"}, "sentence_index": 0, "correct_answer": "フィチン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このフィチンは、でんぷんを糖に分解する働きがある。", "explanation": "ここは〈酵素〉の意味。フィチンは分解する酵素ではなく、ミネラルの吸収を妨げる成分なので合わない。"}, {"text": "この菓子は、砂糖の代わりにフィチンで甘さをつけている。", "explanation": "ここは〈甘味料〉の意味。フィチンは甘みを出す物質ではないので、砂糖の代わりにはならない。"}, {"text": "フィチンは体内で作れないので、毎日の食事から摂る必要がある。", "explanation": "ここは〈ビタミン〉の意味。フィチンは体に必要な栄養素ではなく、食事から摂るべき対象ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フィチン", "is_correct": true, "explanation": "「フィチンなどの成分」で、アクやえぐみの原因として挙げられる成分名。"}, {"text": "ビタミンC", "is_correct": false, "explanation": "ビタミンCは栄養素で、えぐみの原因としては考えられていないので文脈に合わない。"}, {"text": "カルシウム", "is_correct": false, "explanation": "カルシウムはミネラルの一種で、えぐみやアクの原因成分としては挙げられない。"}, {"text": "乳酸菌", "is_correct": false, "explanation": "乳酸菌は微生物で、豆のアクやえぐみを生む成分として説明されるものではない。"}], "explanations": {"フィチン": "「フィチンなどの成分」で、アクやえぐみの原因として挙げられる成分名。", "ビタミンC": "ビタミンCは栄養素で、えぐみの原因としては考えられていないので文脈に合わない。", "カルシウム": "カルシウムはミネラルの一種で、えぐみやアクの原因成分としては挙げられない。", "乳酸菌": "乳酸菌は微生物で、豆のアクやえぐみを生む成分として説明されるものではない。"}, "sentence_index": 6, "correct_answer": "フィチン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このにんじんは、フィチンで鮮やかなオレンジ色になっている。", "explanation": "ここは〈色素〉の意味。フィチンは色をつける物質ではないので、色の説明には合わない。"}, {"text": "フィチンは腸を整えるので、毎日の食事で少しずつ摂るとよい。", "explanation": "ここは〈食物繊維〉の意味。フィチンは腸を整える成分ではなく、ミネラルの吸収を妨げるものなので合わない。"}, {"text": "この紅茶は、フィチンでさわやかな香りを足している。", "explanation": "ここは〈香料〉の意味。フィチンは香りを出す物質ではないので、香りづけには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ぬかには、フィチンを多く含まれているので、精製していない穀物は鉄の吸収を妨げやすい。", "corrected_sentence": "ぬかには、フィチンが多く含まれているので、精製していない穀物は鉄の吸収を妨げやすい。", "error_description": "「含まれる」は受け身で、フィチンは主語にあたるため「が」が正しい。「を」は誤り（正しい形：フィチンが多く含まれている）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52340, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "フィチンは水に溶けやすいので、長く水につけると減るやすい。", "corrected_sentence": "フィチンは水に溶けやすいので、長く水につけると減りやすい。", "error_description": "「減る」の連用形「減り」に「やすい」を付けた形が正しい。「減るやすい」は活用の誤り（正しい形：減りやすい）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
