INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52341, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「叶える」は他動詞なので、目的語「夢」に「を」が付く。"}, {"text": "の", "is_correct": false, "explanation": "「夢の叶える手伝い」の「の」は名詞同士をつなぐ助詞で、動詞の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「夢へ叶える」の「へ」は方向を表し、叶える対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「夢より叶える」の「より」は比較を表し、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「叶える」は他動詞なので、目的語「夢」に「を」が付く。", "の": "「夢の叶える手伝い」の「の」は名詞同士をつなぐ助詞で、動詞の目的語を示せない。", "へ": "「夢へ叶える」の「へ」は方向を表し、叶える対象にはならない。", "より": "「夢より叶える」の「より」は比較を表し、目的語を示せない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52341, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "やりたいことや願いを、本当にそうなるようにする。", "primary_collocate": null, "pronunciation": "かなえる", "ipa": "kanaeɾɯ", "syllable_count": 4, "sentences": [{"text": "ぼくは、サッカー選手になる願いを叶えたい。", "target_word": "叶えたい", "complexity_tier": "T3", "furigana": "ぼくは、サッカー選手[せんしゅ]になる願[ねが]いを叶[かな]えたい。", "sentence_source": "generated"}, {"text": "友だちは、犬を飼うという夢を叶えた。", "target_word": "叶えた", "complexity_tier": "T3", "furigana": "友[とも]だちは、犬[いぬ]を飼[か]うという夢[ゆめ]を叶[かな]えた。", "sentence_source": "generated"}, {"text": "母は、旅行に行きたいという私の願いを叶えてくれた。", "target_word": "叶えて", "complexity_tier": "T3", "furigana": "母[はは]は、旅行[りょこう]に行[い]きたいという私[わたし]の願[ねが]いを叶[かな]えてくれた。", "sentence_source": "generated"}, {"text": "魔法で願いを叶えてもらえるなら、空を飛びたい。", "target_word": "叶えて", "complexity_tier": "T3", "furigana": "魔法[まほう]で願[ねが]いを叶[かな]えてもらえるなら、空[そら]を飛[と]びたい。", "sentence_source": "generated"}, {"text": "毎日練習すれば、やりたいことを叶えることができる。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]すれば、やりたいことを叶[かな]えることができる。", "sentence_source": "generated"}, {"text": "彼女は歌手になる夢を叶えるため、毎晩歌の練習をしている。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歌手[かしゅ]になる夢[ゆめ]を叶[かな]えるため、毎晩[まいばん]歌[うた]の練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "祖父は、世界一周旅行という長年の望みを叶えて、うれしそうだった。", "target_word": "叶えて", "complexity_tier": "T3", "furigana": "祖父[そふ]は、世界一周旅行[せかいいっしゅうりょこう]という長年[ながねん]の望[のぞ]みを叶[かな]えて、うれしそうだった。", "sentence_source": "generated"}, {"text": "先生が、クラスのみんなの夢を叶える手伝いをしてくれた。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "先生[せんせい]が、クラスのみんなの夢[ゆめ]を叶[かな]える手伝[てつだ]いをしてくれた。", "sentence_source": "generated"}, {"text": "兄は小さいころからの望みを叶えて、パイロットになった。", "target_word": "叶えて", "complexity_tier": "T3", "furigana": "兄[あに]は小[ちい]さいころからの望[のぞ]みを叶[かな]えて、パイロットになった。", "sentence_source": "generated"}, {"text": "夢を叶えるまで、あきらめずにがんばろう。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "夢[ゆめ]を叶[かな]えるまで、あきらめずにがんばろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "叶える", "label": "辞書形"}, {"form": "叶え", "label": "連用形"}, {"form": "叶えない", "label": "否定形"}, {"form": "叶えた", "label": "過去形"}, {"form": "叶えて", "label": "て形"}, {"form": "叶えれば", "label": "仮定形"}, {"form": "叶えられる", "label": "可能形"}, {"form": "叶えよう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "やりたいことや願いを、実際にその通りにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52341, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叶えたい", "is_correct": true, "explanation": "希望を表す「叶えたい」で、「〜を叶えたい。」と文を言い切れる。"}, {"text": "叶えれば", "is_correct": false, "explanation": "仮定形は「〜れば」と続く形で、「。」で文が終わらない。"}, {"text": "叶え", "is_correct": false, "explanation": "連用形は文を途中で切る形で、「。」で終えると文が成り立たない。"}, {"text": "叶えられ", "is_correct": false, "explanation": "可能形の連用形は文を途中で切る形で、文末に置くと成り立たない。"}], "explanations": {"叶えたい": "希望を表す「叶えたい」で、「〜を叶えたい。」と文を言い切れる。", "叶えれば": "仮定形は「〜れば」と続く形で、「。」で文が終わらない。", "叶え": "連用形は文を途中で切る形で、「。」で終えると文が成り立たない。", "叶えられ": "可能形の連用形は文を途中で切る形で、文末に置くと成り立たない。"}, "sentence_index": 0, "correct_answer": "叶えたい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三年かけて、ついに卒業論文を叶えた。", "explanation": "ここは〈完成させる〉の意味。論文は完成させるもので、〈叶える〉は願いや希望を実現させる意味なので合わない。"}, {"text": "昨日受けた恩を、今日ようやく叶えた。", "explanation": "ここは〈返す〉の意味。恩は返すもので、〈叶える〉は願いに使うので合わない。"}, {"text": "彼は難しいゲームを一週間で叶えた。", "explanation": "ここは〈攻略する〉の意味。ゲームは攻略するもので、〈叶える〉は願いに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52341, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叶えて", "is_correct": true, "explanation": "て形で「叶えて、うれしそうだった」と後ろへ続けられる。"}, {"text": "叶えよう", "is_correct": false, "explanation": "意志形は「叶えよう、うれしそうだった」と続かず、文が成り立たない。"}, {"text": "叶えろ", "is_correct": false, "explanation": "命令形は言い切りの形で、「叶えろ、うれしそう」と文が続かない。"}, {"text": "叶えます", "is_correct": false, "explanation": "丁寧形を普通体の文に混ぜると不自然で、「叶えます、うれしそう」は文が成り立たない。"}], "explanations": {"叶えて": "て形で「叶えて、うれしそうだった」と後ろへ続けられる。", "叶えよう": "意志形は「叶えよう、うれしそうだった」と続かず、文が成り立たない。", "叶えろ": "命令形は言い切りの形で、「叶えろ、うれしそう」と文が続かない。", "叶えます": "丁寧形を普通体の文に混ぜると不自然で、「叶えます、うれしそう」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "叶えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は大会で三つの金メダルを叶えた。", "explanation": "ここは〈獲得する〉の意味。メダルは獲得するもので、〈叶える〉は願いに使うので合わない。"}, {"text": "彼は夜間の講座を叶えて、春に修了証を受け取った。", "explanation": "ここは〈修了する〉の意味。講座は修了するもので、〈叶える〉は願いや希望に使うので合わない。"}, {"text": "彼は親から託された責任を叶えた。", "explanation": "ここは〈果たす〉の意味。責任は果たすもので、〈叶える〉は願いや希望に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52341, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ぼくは、いつか海外で働くという願いが叶えたい。", "corrected_sentence": "ぼくは、いつか海外で働くという願いを叶えたい。", "error_description": "「叶えたい」は他動詞なので、目的語「願い」に「を」が付く。「願いが叶えたい」の「が」が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "叶えた", "is_correct": true, "explanation": "過去形で「夢を叶えた」と、実現した事実を述べる。"}, {"text": "叶えない", "is_correct": false, "explanation": "否定形では「夢を叶えない」となり、夢を実現したという文と逆の意味になる。"}, {"text": "叶えたかった", "is_correct": false, "explanation": "「叶えたかった」は実現を望んでいたという意味になり、実現した事実を述べる文と合わない。"}, {"text": "叶えて", "is_correct": false, "explanation": "て形では「夢を叶えて。」と文が途中で切れ、文が成り立たない。"}], "correct_form": "叶えた", "base_form": "叶える", "form_label": "過去形", "sentence_index": 1, "explanations": {"叶えた": "過去形で「夢を叶えた」と、実現した事実を述べる。", "叶えない": "否定形では「夢を叶えない」となり、夢を実現したという文と逆の意味になる。", "叶えたかった": "「叶えたかった」は実現を望んでいたという意味になり、実現した事実を述べる文と合わない。", "叶えて": "て形では「夢を叶えて。」と文が途中で切れ、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52341, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、ぼくの夢を叶えくれた。", "corrected_sentence": "先生は、ぼくの夢を叶えてくれた。", "error_description": "「〜てくれた」の「て」が抜けている。「叶えくれた」は文法的に誤りで、正しくは「叶えてくれた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "叶える", "is_correct": true, "explanation": "辞書形で「夢を叶える手伝い」と名詞を修飾し、先生が行った手伝いの内容を表す。"}, {"text": "叶えた", "is_correct": false, "explanation": "過去形の「叶えた手伝い」は既に実現した手伝いを指し、これから行う内容を表さない。"}, {"text": "叶えなかった", "is_correct": false, "explanation": "「叶えなかった手伝い」は実現させなかった手伝いの意味になり、先生の行為と合わない。"}, {"text": "叶えたい", "is_correct": false, "explanation": "希望形の「叶えたい手伝い」は話し手の希望の意味になり、先生の行為を表さない。"}], "correct_form": "叶える", "base_form": "叶える", "form_label": "辞書形", "sentence_index": 7, "explanations": {"叶える": "辞書形で「夢を叶える手伝い」と名詞を修飾し、先生が行った手伝いの内容を表す。", "叶えた": "過去形の「叶えた手伝い」は既に実現した手伝いを指し、これから行う内容を表さない。", "叶えなかった": "「叶えなかった手伝い」は実現させなかった手伝いの意味になり、先生の行為と合わない。", "叶えたい": "希望形の「叶えたい手伝い」は話し手の希望の意味になり、先生の行為を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「叶える」は他動詞なので、目的語「夢」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」は自動詞「叶う」の主語を示す。他動詞「叶える」には付かない。"}, {"text": "に", "is_correct": false, "explanation": "「夢に叶える」の「に」は、叶える対象を示す「を」の代わりにはならない。"}, {"text": "で", "is_correct": false, "explanation": "「夢で叶える」の「で」は手段・場所を表し、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「叶える」は他動詞なので、目的語「夢」に「を」が付く。", "が": "主格の「が」は自動詞「叶う」の主語を示す。他動詞「叶える」には付かない。", "に": "「夢に叶える」の「に」は、叶える対象を示す「を」の代わりにはならない。", "で": "「夢で叶える」の「で」は手段・場所を表し、目的語を示せない。"}, "error_tags": {"が": "主格（自動詞「叶う」の主語）", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "希望や目標を実現する。思いどおりの状態にする。", "primary_collocate": null, "pronunciation": "かなえる", "ipa": "kanaeɾɯ", "syllable_count": 4, "sentences": [{"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "単[たん]なるエネルギー源[げん]に過[す]ぎなかった穀物[こくもつ]が、生命[せいめい]の維持[いじ]と豊[ゆた]かな食体験[しょくたいけん]を同時[どうじ]に叶[かな]える食文化[しょくぶんか]へと昇華[しょうか]される。", "sentence_source": "mined"}, {"text": "彼は長年の夢を叶えるために、仕事をやめて留学した。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "彼[かれ]は長年[ながねん]の夢[ゆめ]を叶[かな]えるために、仕事[しごと]をやめて留学[りゅうがく]した。", "sentence_source": "generated"}, {"text": "家族が健康に過ごせるようにという願いを叶えてほしいと、神社で祈った。", "target_word": "叶えて", "complexity_tier": "T3", "furigana": "家族[かぞく]が健康[けんこう]に過[す]ごせるようにという願[ねが]いを叶[かな]えてほしいと、神社[じんじゃ]で祈[いの]った。", "sentence_source": "generated"}, {"text": "努力を続けた姉は、ついに医者になる夢を叶えた。", "target_word": "叶えた", "complexity_tier": "T3", "furigana": "努力[どりょく]を続[つづ]けた姉[あね]は、ついに医者[いしゃ]になる夢[ゆめ]を叶[かな]えた。", "sentence_source": "generated"}, {"text": "この旅行プランは、客の細かい希望まで叶える、特別なサービスだ。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "この旅行[りょこう]プランは、客[きゃく]の細[こま]かい希望[きぼう]まで叶[かな]える、特別[とくべつ]なサービスだ。", "sentence_source": "generated"}, {"text": "社長は、社員全員の望みを叶えることはできないと正直に話した。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、社員全員[しゃいんぜんいん]の望[のぞ]みを叶[かな]えることはできないと正直[しょうじき]に話[はな]した。", "sentence_source": "generated"}, {"text": "子どもの頃の目標を叶えた今も、彼女はさらに高い夢を追っている。", "target_word": "叶えた", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]の目標[もくひょう]を叶[かな]えた今[いま]も、彼女[かのじょ]はさらに高[たか]い夢[ゆめ]を追[お]っている。", "sentence_source": "generated"}, {"text": "資金が足りず、自分の店を持つという夢を叶えられなかった。", "target_word": "叶えられ", "complexity_tier": "T3", "furigana": "資金[しきん]が足[た]りず、自分[じぶん]の店[みせ]を持[も]つという夢[ゆめ]を叶[かな]えられなかった。", "sentence_source": "generated"}, {"text": "広い庭がほしいという両親の希望は、新しい家に移ってようやく叶った。", "target_word": "叶った", "complexity_tier": "T3", "furigana": "広[ひろ]い庭[にわ]がほしいという両親[りょうしん]の希望[きぼう]は、新[あたら]しい家[いえ]に移[うつ]ってようやく叶[かな]った。", "sentence_source": "generated"}, {"text": "夢を叶える人は、小さな努力をやめずに続ける人だと思う。", "target_word": "叶える", "complexity_tier": "T3", "furigana": "夢[ゆめ]を叶[かな]える人[ひと]は、小[ちい]さな努力[どりょく]をやめずに続[つづ]ける人[ひと]だと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "叶える", "label": "辞書形"}, {"form": "叶え", "label": "連用形"}, {"form": "叶えない", "label": "否定形"}, {"form": "叶えた", "label": "過去形"}, {"form": "叶えて", "label": "て形"}, {"form": "叶えれば", "label": "仮定形"}, {"form": "叶えられる", "label": "可能形"}, {"form": "叶えよう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "夢・願い・希望・目標などを実際に実現させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叶える", "is_correct": true, "explanation": "「食文化」を修飾する辞書形で、「同時に叶える食文化」と名詞に続く。正しい形。"}, {"text": "叶えよう", "is_correct": false, "explanation": "意志形は名詞を直接修飾できず、「叶えよう食文化」は成り立たない。"}, {"text": "叶えろ", "is_correct": false, "explanation": "命令形は言い切りの形で、名詞を修飾できないので文が成り立たない。"}, {"text": "叶えれば", "is_correct": false, "explanation": "仮定形は「〜れば」と続く条件節で、名詞を修飾する形ではない。"}], "explanations": {"叶える": "「食文化」を修飾する辞書形で、「同時に叶える食文化」と名詞に続く。正しい形。", "叶えよう": "意志形は名詞を直接修飾できず、「叶えよう食文化」は成り立たない。", "叶えろ": "命令形は言い切りの形で、名詞を修飾できないので文が成り立たない。", "叶えれば": "仮定形は「〜れば」と続く条件節で、名詞を修飾する形ではない。"}, "sentence_index": 0, "correct_answer": "叶える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は重い責任を叶えて、会社を守り抜いた。", "explanation": "ここは〈果たす〉の意味。責任は果たすものなので、〈叶える〉（願いや希望を実現させる）とは合わない。"}, {"text": "この応募は、条件を叶えれば受け付けられる。", "explanation": "ここは〈満たす〉の意味。条件は満たすもので、〈叶える〉は願いや希望に使うので合わない。"}, {"text": "事故の原因を調べて、ついに問題を叶えた。", "explanation": "ここは〈解決する〉の意味。問題は解決するもので、〈叶える〉は願いや夢に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叶えた", "is_correct": true, "explanation": "連体修飾の過去形で、「目標を叶えた今」と達成した時点を指す。"}, {"text": "叶え", "is_correct": false, "explanation": "連用形では「叶え今も」と名詞を修飾できず、文が続かない。"}, {"text": "叶えろ", "is_correct": false, "explanation": "命令形は言い切りの形で、「今も」の前に置いて修飾できない。"}, {"text": "叶えられ", "is_correct": false, "explanation": "可能形の連用形では「叶えられ今も」と続けられず、文が成り立たない。"}], "explanations": {"叶えた": "連体修飾の過去形で、「目標を叶えた今」と達成した時点を指す。", "叶え": "連用形では「叶え今も」と名詞を修飾できず、文が続かない。", "叶えろ": "命令形は言い切りの形で、「今も」の前に置いて修飾できない。", "叶えられ": "可能形の連用形では「叶えられ今も」と続けられず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "叶えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大会で金メダルを叶えた。", "explanation": "ここは〈獲得する〉の意味。メダルは獲得するもので、〈叶える〉は願いや希望を実現させる意味なので合わない。"}, {"text": "彼は三年かけて、ついに長編小説を叶えた。", "explanation": "ここは〈完成させる〉の意味。小説は完成させるもので、〈叶える〉は願いに使うので合わない。"}, {"text": "彼女は夜間の講座を叶えて、資格を取った。", "explanation": "ここは〈修了する〉の意味。講座は修了するもので、〈叶える〉は願いや希望に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は子どもの頃の夢に叶えるために、毎日練習している。", "corrected_sentence": "彼女は子どもの頃の夢を叶えるために、毎日練習している。", "error_description": "「叶える」は他動詞なので目的語に「を」を取る。「夢に叶える」の「に」が誤りで、正しくは「夢を叶える」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "叶える", "is_correct": true, "explanation": "「夢を叶えるために」の辞書形。「ために」の前は動詞の辞書形で目的を表す。"}, {"text": "叶えて", "is_correct": false, "explanation": "て形は「ために」と続かず、文が成り立たない。"}, {"text": "叶えれば", "is_correct": false, "explanation": "仮定形は「叶えれば」と条件を表すので、「ために」の目的の文脈に合わない。"}, {"text": "叶えよう", "is_correct": false, "explanation": "意志形では「叶えようために」となり、「ために」の前に置けない。"}], "correct_form": "叶える", "base_form": "叶える", "form_label": "辞書形", "sentence_index": 1, "explanations": {"叶える": "「夢を叶えるために」の辞書形。「ために」の前は動詞の辞書形で目的を表す。", "叶えて": "て形は「ために」と続かず、文が成り立たない。", "叶えれば": "仮定形は「叶えれば」と条件を表すので、「ために」の目的の文脈に合わない。", "叶えよう": "意志形では「叶えようために」となり、「ために」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52342, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は小さいころの夢を叶えてあとも、さらに努力を続けている。", "corrected_sentence": "彼は小さいころの夢を叶えたあとも、さらに努力を続けている。", "error_description": "「〜あとも」の前には過去の連体形「叶えた」が必要。「叶えて」は誤りで、正しくは「叶えたあとも」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "叶えられ", "is_correct": true, "explanation": "可能形の連用形で、「叶えられなかった」（実現できなかった）を作る。"}, {"text": "叶えた", "is_correct": false, "explanation": "「叶えたなかった」は活用が成り立たず、文として誤り。"}, {"text": "叶えない", "is_correct": false, "explanation": "「叶えないなかった」は二重否定になり、文として成り立たない。"}, {"text": "叶えたい", "is_correct": false, "explanation": "希望形では「叶えたいなかった」となり、文が成り立たない。"}], "correct_form": "叶えられ", "base_form": "叶える", "form_label": "可能形（連用形）", "sentence_index": 7, "explanations": {"叶えられ": "可能形の連用形で、「叶えられなかった」（実現できなかった）を作る。", "叶えた": "「叶えたなかった」は活用が成り立たず、文として誤り。", "叶えない": "「叶えないなかった」は二重否定になり、文として成り立たない。", "叶えたい": "希望形では「叶えたいなかった」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「番号を付与する」の目的語を示す「を」。付与される対象が番号であることを表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「番号が付与した」では番号が主語になり、付与する側と対象の関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「番号で付与した」は手段の意味になり、付与の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「番号へ付与した」は方向を表すが、付与の対象は「を」で示す。"}], "correct_answer": "を", "explanations": {"を": "「番号を付与する」の目的語を示す「を」。付与される対象が番号であることを表す。正解。", "が": "「番号が付与した」では番号が主語になり、付与する側と対象の関係が成り立たない。", "で": "「番号で付与した」は手段の意味になり、付与の目的語を示せない。", "へ": "「番号へ付与した」は方向を表すが、付与の対象は「を」で示す。"}, "error_tags": {"が": "主語を示す助詞（目的語ではない）", "で": "手段を示す助詞", "へ": "方向を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「コインを付与する」の目的語を示す「を」。運営側が参加者にコインを割り当てることを表す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「コインに付与する」は付与される対象を「に」で示すことができない。"}, {"text": "と", "is_correct": false, "explanation": "「コインと付与する」は並列の意味になり、付与の目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「コインから付与する」は起点を示すので、割り当てる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「コインを付与する」の目的語を示す「を」。運営側が参加者にコインを割り当てることを表す。正解。", "に": "「コインに付与する」は付与される対象を「に」で示すことができない。", "と": "「コインと付与する」は並列の意味になり、付与の目的語を示せない。", "から": "「コインから付与する」は起点を示すので、割り当てる対象を表せない。"}, "error_tags": {"に": "対象・相手を示す助詞（目的語ではない）", "と": "並列を示す助詞", "から": "起点を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "番号・点数・特典などを対象に割り当てて与えること。", "primary_collocate": null, "pronunciation": "ふよ", "ipa": "ɸɯjo", "syllable_count": 2, "sentences": [{"text": "この機能は、写真に日付を付与する。", "target_word": "付与", "complexity_tier": "T3", "furigana": "この機能[きのう]は、写真[しゃしん]に日付[ひづけ]を付与[ふよ]する。", "sentence_source": "generated"}, {"text": "担当者は各ファイルに番号を付与した。", "target_word": "付与", "complexity_tier": "T3", "furigana": "担当者[たんとうしゃ]は各[かく]ファイルに番号[ばんごう]を付与[ふよ]した。", "sentence_source": "generated"}, {"text": "店では、買い物のたびにポイントを付与している。", "target_word": "付与", "complexity_tier": "T3", "furigana": "店[みせ]では、買[か]い物[もの]のたびにポイントを付与[ふよ]している。", "sentence_source": "generated"}, {"text": "研究者は、すべてのデータにIDを付与した。", "target_word": "付与", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、すべてのデータにIDを付与[ふよ]した。", "sentence_source": "generated"}, {"text": "登録した人には、特典が付与される。", "target_word": "付与", "complexity_tier": "T3", "furigana": "登録[とうろく]した人[ひと]には、特典[とくてん]が付与[ふよ]される。", "sentence_source": "generated"}, {"text": "図書館は新しい本に、分類番号を付与して棚に並べる。", "target_word": "付与", "complexity_tier": "T3", "furigana": "図書館[としょかん]は新[あたら]しい本[ほん]に、分類[ぶんるい]番号[ばんごう]を付与[ふよ]して棚[たな]に並[なら]べる。", "sentence_source": "generated"}, {"text": "会員には、毎月ボーナスの点数が付与される。", "target_word": "付与", "complexity_tier": "T3", "furigana": "会員[かいいん]には、毎月[まいつき]ボーナスの点数[てんすう]が付与[ふよ]される。", "sentence_source": "generated"}, {"text": "運営側は、参加者全員にコインを付与すると発表した。", "target_word": "付与", "complexity_tier": "T3", "furigana": "運営側[うんえいがわ]は、参加者[さんかしゃ]全員[ぜんいん]にコインを付与[ふよ]すると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "画像に説明の文字を付与するソフトを使っている。", "target_word": "付与", "complexity_tier": "T3", "furigana": "画像[がぞう]に説明[せつめい]の文字[もじ]を付与[ふよ]するソフトを使[つか]っている。", "sentence_source": "generated"}, {"text": "新入社員にも、メールアドレスが付与された。", "target_word": "付与", "complexity_tier": "T3", "furigana": "新入[しんにゅう]社員[しゃいん]にも、メールアドレスが付与[ふよ]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付与", "label": "基本形"}, {"form": "付与する", "label": "辞書形"}, {"form": "付与した", "label": "過去形"}, {"form": "付与される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "番号・点数・特典などを対象に足して与えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付与", "is_correct": true, "explanation": "ここは「写真に日付を付与する」で、機能が日付を写真に割り当てる意味。正解。"}, {"text": "破損", "is_correct": false, "explanation": "「日付を破損する」は意味が通らない。日付は壊される対象ではない。"}, {"text": "撮影", "is_correct": false, "explanation": "「日付を撮影する」は成り立たない。撮影は人や風景など写す対象に使う。"}, {"text": "辞退", "is_correct": false, "explanation": "「日付を辞退する」は不自然。辞退は申し出を断る意味で、日付は対象にならない。"}], "explanations": {"付与": "ここは「写真に日付を付与する」で、機能が日付を写真に割り当てる意味。正解。", "破損": "「日付を破損する」は意味が通らない。日付は壊される対象ではない。", "撮影": "「日付を撮影する」は成り立たない。撮影は人や風景など写す対象に使う。", "辞退": "「日付を辞退する」は不自然。辞退は申し出を断る意味で、日付は対象にならない。"}, "sentence_index": 0, "correct_answer": "付与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の一言が私に大きな不安を付与した。", "explanation": "ここは〈与える〉の意味。付与は番号・点数・特典などを割り当てる語で、人の感情や影響には使わないので不自然。"}, {"text": "彼はスープに塩を付与した。", "explanation": "ここは〈入れる〉の意味。料理に調味料を入れる行為は入れると言い、付与は番号や権利などを割り当てる場合に使う語なので合わない。"}, {"text": "友達の誕生日に、プレゼントを付与した。", "explanation": "ここは〈贈る〉の意味。品物を相手に渡す行為は贈ると言い、付与は番号や権利などを割り当てる語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付与", "is_correct": true, "explanation": "ここは「毎月ボーナスの点数が付与される」で、会員に点数を割り当てる意味。正解。"}, {"text": "販売", "is_correct": false, "explanation": "「点数が販売される」は意味が通らない。点数は売買の対象ではない。"}, {"text": "返品", "is_correct": false, "explanation": "「点数が返品される」は不自然。返品は買った品物を戻すことで、点数には使わない。"}, {"text": "製造", "is_correct": false, "explanation": "「点数が製造される」は成り立たない。点数は作られる対象ではない。"}], "explanations": {"付与": "ここは「毎月ボーナスの点数が付与される」で、会員に点数を割り当てる意味。正解。", "販売": "「点数が販売される」は意味が通らない。点数は売買の対象ではない。", "返品": "「点数が返品される」は不自然。返品は買った品物を戻すことで、点数には使わない。", "製造": "「点数が製造される」は成り立たない。点数は作られる対象ではない。"}, "sentence_index": 6, "correct_answer": "付与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキに飾りを付与した。", "explanation": "ここは〈添える〉の意味。ケーキに飾りを添えるのは自然だが、付与は制度・点数などを割り当てる語で、飾りには使わない。"}, {"text": "手紙に気持ちを付与した。", "explanation": "ここは〈込める〉の意味。気持ちを手紙に込めるのは自然だが、付与は割り当てる意味なので合わない。"}, {"text": "患者に手術を付与した。", "explanation": "ここは〈施す〉の意味。手術や処置を施すと言い、付与は手術を割り当てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大会では、優勝者に賞金に付与する。", "corrected_sentence": "大会では、優勝者に賞金を付与する。", "error_description": "付与は「〜を付与する」と目的語に「を」を取る。ここは「に」になっており、目的語を示す助詞が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52343, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会員には、新しいIDが付与した。", "corrected_sentence": "会員には、新しいIDが付与された。", "error_description": "付与は受け身の「付与される・付与された」で使う。主語のIDは付与されるものなので、能動の「付与した」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
