INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52344, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事に何かを加えて、それを持たせること。", "primary_collocate": null, "pronunciation": "ふよ", "ipa": "ɸɯjo", "syllable_count": 2, "sentences": [{"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "付与", "complexity_tier": "T4", "furigana": "さらに、アミノ酸[さん]や有機酸[ゆうきさん]が複雑[ふくざつ]に絡[から]み合[あ]い、主食[しゅしょく]に奥深[おくぶか]い風味[ふうみ]と旨味[うまみ]の層[そう]を付与[ふよ]する。", "sentence_source": "mined"}, {"text": "新しい機能を付与することで、製品の価値が高まった。", "target_word": "付与", "complexity_tier": "T3", "furigana": "新[あたら]しい機能[きのう]を付与[ふよ]することで、製品[せいひん]の価値[かち]が高[たか]まった。", "sentence_source": "generated"}, {"text": "会社は社員に、一定の権限を付与している。", "target_word": "付与", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]に、一定[いってい]の権限[けんげん]を付与[ふよ]している。", "sentence_source": "generated"}, {"text": "職人は木の皿に漆を塗り、防水の性質を付与した。", "target_word": "付与", "complexity_tier": "T3", "furigana": "職人[しょくにん]は木[き]の皿[さら]に漆[うるし]を塗[ぬ]り、防水[ぼうすい]の性質[せいしつ]を付与[ふよ]した。", "sentence_source": "generated"}, {"text": "監督は主人公に、複雑な過去を付与して物語を深めた。", "target_word": "付与", "complexity_tier": "T3", "furigana": "監督[かんとく]は主人公[しゅじんこう]に、複雑[ふくざつ]な過去[かこ]を付与[ふよ]して物語[ものがたり]を深[ふか]めた。", "sentence_source": "generated"}, {"text": "学校は優秀な生徒に、特別な資格を付与する。", "target_word": "付与", "complexity_tier": "T3", "furigana": "学校[がっこう]は優秀[ゆうしゅう]な生徒[せいと]に、特別[とくべつ]な資格[しかく]を付与[ふよ]する。", "sentence_source": "generated"}, {"text": "加工によって、この布には汚れにくい性質が付与される。", "target_word": "付与", "complexity_tier": "T3", "furigana": "加工[かこう]によって、この布[ぬの]には汚[よご]れにくい性質[せいしつ]が付与[ふよ]される。", "sentence_source": "generated"}, {"text": "新しい法律は、市民に調査を求める権利を付与した。", "target_word": "付与", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]は、市民[しみん]に調査[ちょうさ]を求[もと]める権利[けんり]を付与[ふよ]した。", "sentence_source": "generated"}, {"text": "開発者はアプリに、位置情報を記録する働きを付与した。", "target_word": "付与", "complexity_tier": "T3", "furigana": "開発者[かいはつしゃ]はアプリに、位置[いち]情報[じょうほう]を記録[きろく]する働[はたら]きを付与[ふよ]した。", "sentence_source": "generated"}, {"text": "店は商品に、手作りという特別な意味を付与して売っている。", "target_word": "付与", "complexity_tier": "T3", "furigana": "店[みせ]は商品[しょうひん]に、手作[てづく]りという特別[とくべつ]な意味[いみ]を付与[ふよ]して売[う]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付与", "label": "基本形"}, {"form": "付与する", "label": "辞書形"}, {"form": "付与した", "label": "過去形"}, {"form": "付与される", "label": "受身形"}, {"form": "付与しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "物事に性質・権限・意味などを加えて持たせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52344, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付与", "is_correct": true, "explanation": "「層を付与する」で、風味や性質を加えて持たせる意味に合う。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分を飛ばす意味で、風味の層には合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かす意味で、風味の層には合わない。"}, {"text": "洗浄", "is_correct": false, "explanation": "汚れを洗い落とす意味で、風味の層とは結びつかない。"}], "explanations": {"付与": "「層を付与する」で、風味や性質を加えて持たせる意味に合う。", "乾燥": "水分を飛ばす意味で、風味の層には合わない。", "解凍": "凍ったものを溶かす意味で、風味の層には合わない。", "洗浄": "汚れを洗い落とす意味で、風味の層とは結びつかない。"}, "sentence_index": 0, "correct_answer": "付与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は話に冗談を付与して、場を和ませた。", "explanation": "ここは〈付け足す〉の意味。話に冗談を加えるとは言うが、付与とは言わない。"}, {"text": "料理に花を付与して、見た目を華やかにした。", "explanation": "ここは〈添える〉の意味。料理に花を添えるとは言うが、花を付与するとは言わない。"}, {"text": "説明に一言付与した。", "explanation": "ここは〈付け足す〉の意味。一言を付け足すとは言うが、付与とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52344, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付与", "is_correct": true, "explanation": "「性質が付与される」で、特徴を新たに与えられる意味に合う。"}, {"text": "漂白", "is_correct": false, "explanation": "色を抜く意味で、性質の説明には当てはまらない。"}, {"text": "分解", "is_correct": false, "explanation": "成分に分ける意味で、性質が分解されるとは言わない。"}, {"text": "溶解", "is_correct": false, "explanation": "液体に溶かす意味で、性質には合わない。"}], "explanations": {"付与": "「性質が付与される」で、特徴を新たに与えられる意味に合う。", "漂白": "色を抜く意味で、性質の説明には当てはまらない。", "分解": "成分に分ける意味で、性質が分解されるとは言わない。", "溶解": "液体に溶かす意味で、性質には合わない。"}, "sentence_index": 6, "correct_answer": "付与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "メニューに新しい料理を付与した。", "explanation": "ここは〈追加〉の意味。料理を加えるは追加と言い、付与とは言わない。"}, {"text": "在庫を付与して、売り切れを防いだ。", "explanation": "ここは〈補充〉の意味。足りない分を補うは補充と言い、付与とは言わない。"}, {"text": "絵に付与をして仕上げた。", "explanation": "ここは〈色付け〉の意味。絵に色を付けるは色付けと言い、付与とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52344, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は若い住民で、地域の運営に関わる権限を付与した。", "corrected_sentence": "町は若い住民に、地域の運営に関わる権限を付与した。", "error_description": "権限を受ける相手は「に」で示す。「で」は誤りで、正しくは「若い住民に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52344, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大会の出場者には、特別なバッジが付与られている。", "corrected_sentence": "大会の出場者には、特別なバッジが付与されている。", "error_description": "付与は「する」を付けるサ変動詞なので、受身は「付与される」。「付与られる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「媒体の一つ」と、全体の中の一つであることを示す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「媒体を一つだ」は目的語にならず、「一つだ」と続かないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「媒体に一つだ」は位置や方向を示し、所属を表せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「媒体へ一つだ」は方向を示し、「一つだ」と結べないので合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「媒体の一つ」と、全体の中の一つであることを示す「の」。", "を": "「媒体を一つだ」は目的語にならず、「一つだ」と続かないので合わない。", "に": "「媒体に一つだ」は位置や方向を示し、所属を表せないので合わない。", "へ": "「媒体へ一つだ」は方向を示し、「一つだ」と結べないので合わない。"}, "error_tags": {"を": "目的格", "に": "位置・方向格", "へ": "方向格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「媒体は、レコードからCDへと変わってきた」と、話題の主語を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「媒体を、変わってきた」は変化の主体を示せず、目的語としても成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「媒体と、変わってきた」は並列や引用になり、主語にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「媒体の、変わってきた」は「の」の後に述語が続かず、主語として成り立たないので合わない。"}], "correct_answer": "は", "explanations": {"は": "正解。「媒体は、レコードからCDへと変わってきた」と、話題の主語を示す「は」。", "を": "「媒体を、変わってきた」は変化の主体を示せず、目的語としても成り立たない。", "と": "「媒体と、変わってきた」は並列や引用になり、主語にはならないので合わない。", "の": "「媒体の、変わってきた」は「の」の後に述語が続かず、主語として成り立たないので合わない。"}, "error_tags": {"を": "目的格", "と": "並列・引用", "の": "連体格（主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かをその中に入れたり、その上にのせたりするもののことです。", "primary_collocate": null, "pronunciation": "ばいたい", "ipa": "baitai", "syllable_count": 4, "sentences": [{"text": "このデータは、どんな媒体に保存してもいいです。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "このデータは、どんな媒体[ばいたい]に保存[ほぞん]してもいいです。", "sentence_source": "generated"}, {"text": "CDは音楽を入れるための媒体の一つだ。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "CDは音楽[おんがく]を入[い]れるための媒体[ばいたい]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "古い媒体は読み取れないので、新しいものにうつした。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "古[ふる]い媒体[ばいたい]は読[よ]み取[と]れないので、新[あたら]しいものにうつした。", "sentence_source": "generated"}, {"text": "紙は、文字を書きのせる最も身近な媒体です。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "紙[かみ]は、文字[もじ]を書[か]きのせる最[もっと]も身近[みぢか]な媒体[ばいたい]です。", "sentence_source": "generated"}, {"text": "動画を残すなら、容量の大きい媒体を選んでください。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "動画[どうが]を残[のこ]すなら、容量[ようりょう]の大[おお]きい媒体[ばいたい]を選[えら]んでください。", "sentence_source": "generated"}, {"text": "昔は、文字を石や木の板などの媒体に刻んだ。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "昔[むかし]は、文字[もじ]を石[いし]や木[き]の板[いた]などの媒体[ばいたい]に刻[きざ]んだ。", "sentence_source": "generated"}, {"text": "媒体が壊れると、中のデータも消えてしまう。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "媒体[ばいたい]が壊[こわ]れると、中[なか]のデータも消[き]えてしまう。", "sentence_source": "generated"}, {"text": "音を記録する媒体は、レコードからCDへと変わってきた。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "音[おと]を記録[きろく]する媒体[ばいたい]は、レコードからCDへと変[か]わってきた。", "sentence_source": "generated"}, {"text": "この媒体は軽いので、持ち運びにとても便利だ。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "この媒体[ばいたい]は軽[かる]いので、持[も]ち運[はこ]びにとても便利[べんり]だ。", "sentence_source": "generated"}, {"text": "写真を保存する媒体が足りなくなったので、買い足した。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "写真[しゃしん]を保存[ほぞん]する媒体[ばいたい]が足[た]りなくなったので、買[か]い足[た]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒体", "label": "基本形"}], "register": "中立", "sense_fingerprint": "情報や音などを入れたりのせたりして運ぶもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "媒体", "is_correct": true, "explanation": "正解。「どんな媒体に保存する」と、データを記録する物として合う。"}, {"text": "通路", "is_correct": false, "explanation": "「通路に保存する」は、データを入れて記録する物として成り立たない。"}, {"text": "寝具", "is_correct": false, "explanation": "「寝具に保存する」は意味が通らず、データの保存先として合わない。"}, {"text": "花束", "is_correct": false, "explanation": "「花束に保存する」は、データの記録先として不自然で文脈に合わない。"}], "explanations": {"媒体": "正解。「どんな媒体に保存する」と、データを記録する物として合う。", "通路": "「通路に保存する」は、データを入れて記録する物として成り立たない。", "寝具": "「寝具に保存する」は意味が通らず、データの保存先として合わない。", "花束": "「花束に保存する」は、データの記録先として不自然で文脈に合わない。"}, "sentence_index": 0, "correct_answer": "媒体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は両社の交渉で、媒体の役を務めた。", "explanation": "ここは〈仲介〉の意味。媒体は情報や音を入れて運ぶ物で、人が間に立つことには使わないので合わない。"}, {"text": "彼は会社の媒体として、毎日営業に回っている。", "explanation": "ここは〈職業〉の意味。媒体は物を入れたり運んだりするもので、仕事や役職は指さないので合わない。"}, {"text": "この家具は、丈夫な木の媒体で作られている。", "explanation": "ここは〈材料〉の意味。媒体は物を入れたりのせたりして運ぶ物で、作る素材の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媒体", "is_correct": true, "explanation": "正解。壊れると中のデータも消える、データを入れる物として合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が壊れる」は意味をなさず、データが消える文脈に合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "「食欲が壊れる」は言わず、データの保存と結びつかない。"}, {"text": "音色", "is_correct": false, "explanation": "「音色が壊れる」は不自然で、データを入れる物としても合わない。"}], "explanations": {"媒体": "正解。壊れると中のデータも消える、データを入れる物として合う。", "天気": "「天気が壊れる」は意味をなさず、データが消える文脈に合わない。", "食欲": "「食欲が壊れる」は言わず、データの保存と結びつかない。", "音色": "「音色が壊れる」は不自然で、データを入れる物としても合わない。"}, "sentence_index": 6, "correct_answer": "媒体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その町へ行く媒体はバスしかない。", "explanation": "ここは〈手段〉の意味。媒体は物を入れたりのせたりして運ぶ物で、移動の方法は指さないので合わない。"}, {"text": "この廊下は、二つの建物をつなぐ媒体だ。", "explanation": "ここは〈通路〉の意味。媒体は物を入れたり運んだりするもので、人が行き来する通り道には使わないので合わない。"}, {"text": "大工は、釘を打つための媒体を道具箱に一つずつ並べた。", "explanation": "ここは〈道具〉の意味。媒体は入れたりのせたりする物で、作業に使う器具は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大切な写真は、丈夫な媒体を保存しておきたい。", "corrected_sentence": "大切な写真は、丈夫な媒体に保存しておきたい。", "error_description": "「保存する」は「〜に保存する」で保存先を示す。「媒体を保存」は誤りで、正しくは「媒体に保存する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52345, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い媒体が壊れられてしまうと、写真も消えてしまう。", "corrected_sentence": "古い媒体が壊れてしまうと、写真も消えてしまう。", "error_description": "「壊れる」は自動詞で、受け身や可能の形「壊れられる」は使えない。正しくは「壊れてしまう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ふく」の対象を示す目的語の「を」。正しい。"}, {"text": "に", "is_correct": false, "explanation": "「液体に」は受け手や場所を示すが、「ふく」の対象にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「液体へふいた」は不自然で合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す「と」。「液体とふいた」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ふく」の対象を示す目的語の「を」。正しい。", "に": "「液体に」は受け手や場所を示すが、「ふく」の対象にはならないので合わない。", "へ": "方向を表す「へ」。「液体へふいた」は不自然で合わない。", "と": "並列や相手を表す「と」。「液体とふいた」は文として成り立たない。"}, "error_tags": {"に": "受け手・場所", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「白い液体」を主語として示す「が」。「液体が勢いよく飛び出した」で正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」。「液体で飛び出した」は意味が不自然で合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる相手がないので成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「液体の勢いよく飛び出した」は主語を作れず合わない。"}], "correct_answer": "が", "explanations": {"が": "「白い液体」を主語として示す「が」。「液体が勢いよく飛び出した」で正しい。", "で": "手段を表す「で」。「液体で飛び出した」は意味が不自然で合わない。", "より": "比較の「より」。比べる相手がないので成り立たない。", "の": "連体修飾の「の」。「液体の勢いよく飛び出した」は主語を作れず合わない。"}, "error_tags": {"で": "手段", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水のように、形が決まっていないで、流れるもの。", "primary_collocate": null, "pronunciation": "えきたい", "ipa": "ekitai", "syllable_count": 4, "sentences": [{"text": "コップに入った透明な液体は、水ではなくお酢だった。", "target_word": "液体", "complexity_tier": "T2", "furigana": "コップに入[はい]った透明[とうめい]な液体[えきたい]は、水[みず]ではなくお酢[す]だった。", "sentence_source": "generated"}, {"text": "床にこぼれた液体をふいたが、べたべたしていた。", "target_word": "液体", "complexity_tier": "T2", "furigana": "床[ゆか]にこぼれた液体[えきたい]をふいたが、べたべたしていた。", "sentence_source": "generated"}, {"text": "薬は粉ではなく液体のほうが、子どもには飲みやすい。", "target_word": "液体", "complexity_tier": "T3", "furigana": "薬[くすり]は粉[こな]ではなく液体[えきたい]のほうが、子[こ]どもには飲[の]みやすい。", "sentence_source": "generated"}, {"text": "液体の洗剤は少ない量でよく泡立つ。", "target_word": "液体", "complexity_tier": "T3", "furigana": "液体[えきたい]の洗剤[せんざい]は少[すく]ない量[りょう]でよく泡立[あわだ]つ。", "sentence_source": "generated"}, {"text": "瓶を逆さにしたら、中の液体がゆっくり流れ出てきた。", "target_word": "液体", "complexity_tier": "T3", "furigana": "瓶[びん]を逆[さか]さにしたら、中[なか]の液体[えきたい]がゆっくり流[なが]れ出[で]てきた。", "sentence_source": "generated"}, {"text": "傷口から出る液体は、きれいなガーゼで押さえた。", "target_word": "液体", "complexity_tier": "T3", "furigana": "傷口[きずぐち]から出[で]る液体[えきたい]は、きれいなガーゼで押[お]さえた。", "sentence_source": "generated"}, {"text": "飛行機に液体を持ち込むときは、小さい容器に入れなければならない。", "target_word": "液体", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]に液体[えきたい]を持[も]ち込[こ]むときは、小[ちい]さい容器[ようき]に入[い]れなければならない。", "sentence_source": "generated"}, {"text": "缶を開けると、白い液体が勢いよく飛び出した。", "target_word": "液体", "complexity_tier": "T2", "furigana": "缶[かん]を開[あ]けると、白[しろ]い液体[えきたい]が勢[いきお]いよく飛[と]び出[だ]した。", "sentence_source": "generated"}, {"text": "その液体は熱いので、さめてから飲んだほうがいい。", "target_word": "液体", "complexity_tier": "T2", "furigana": "その液体[えきたい]は熱[あつ]いので、さめてから飲[の]んだほうがいい。", "sentence_source": "generated"}, {"text": "魚のにおいがする茶色い液体が、袋の底にたまっていた。", "target_word": "液体", "complexity_tier": "T3", "furigana": "魚[さかな]のにおいがする茶色[ちゃいろ]い液体[えきたい]が、袋[ふくろ]の底[そこ]にたまっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "液体", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水のように流れる、日常生活で目にする正体のはっきりしないものや飲み物・薬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "「透明な液体」は容器の中身を指し、「水ではなくお酢だった」がその中身を説明している。"}, {"text": "瓶", "is_correct": false, "explanation": "瓶は容器であり、中身がお酢だったという説明と結びつかないので合わない。"}, {"text": "栓", "is_correct": false, "explanation": "栓は容器のふたで、中身の正体を説明する語として合わない。"}, {"text": "缶", "is_correct": false, "explanation": "缶は容器で、「透明な缶」が中身の説明にならないので合わない。"}], "explanations": {"液体": "「透明な液体」は容器の中身を指し、「水ではなくお酢だった」がその中身を説明している。", "瓶": "瓶は容器であり、中身がお酢だったという説明と結びつかないので合わない。", "栓": "栓は容器のふたで、中身の正体を説明する語として合わない。", "缶": "缶は容器で、「透明な缶」が中身の説明にならないので合わない。"}, "sentence_index": 0, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の土に液体を植えて、芽が出るのを待った。", "explanation": "ここは〈種〉の意味。土に植えて芽が出るのを待つのは種で、液体は植えるものではないので合わない。"}, {"text": "鍋の底に、液体のかたまりが残っていた。", "explanation": "ここは〈固形〉の意味。かたまりとして残るのは固形で、液体はかたまりにならないので合わない。"}, {"text": "窓を開けると、外から楽しそうな液体が聞こえてきた。", "explanation": "ここは〈音〉の意味。外から聞こえてくるのは音で、液体は聞こえるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "飛行機に持ち込む対象で、小さい容器に入れる必要があるのは液体。"}, {"text": "刃物", "is_correct": false, "explanation": "刃物は小さい容器に入れて持ち込む対象ではなく、この文脈に合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電池を小さい容器に入れる必要はなく、持ち込み制限の文脈に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は容器に入れる対象ではないので、この文脈に合わない。"}], "explanations": {"液体": "飛行機に持ち込む対象で、小さい容器に入れる必要があるのは液体。", "刃物": "刃物は小さい容器に入れて持ち込む対象ではなく、この文脈に合わない。", "電池": "電池を小さい容器に入れる必要はなく、持ち込み制限の文脈に合わない。", "靴": "靴は容器に入れる対象ではないので、この文脈に合わない。"}, "sentence_index": 6, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "排水口に、長い液体がからまっていた。", "explanation": "ここは〈髪の毛〉の意味。排水口にからまるのは髪の毛で、液体はからまらないので合わない。"}, {"text": "鍋から白い液体が立ちのぼった。", "explanation": "ここは〈湯気〉の意味。白く立ちのぼるのは湯気で、液体は立ちのぼらないので合わない。"}, {"text": "砂浜の液体が風に舞った。", "explanation": "ここは〈粒〉の意味。風に舞うのは細かい粒で、液体は風に舞わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テーブルから液体を床に落ちて、ぬれてしまった。", "corrected_sentence": "テーブルから液体が床に落ちて、ぬれてしまった。", "error_description": "「落ちる」は主語を取る自動詞なので、主語の「液体」には「が」を使う。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52347, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その液体で熱いから、少しさましてから飲むほうがいい。", "corrected_sentence": "その液体は熱いから、少しさましてから飲むほうがいい。", "error_description": "「で」は名詞につく断定の形で、形容詞「熱い」の前には置けない。話題の液体は「は」で主題として示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
