INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52348, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "結果や変化の先を示す「に」。「液体にする」で状態の変化を表すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「液体がすると」は「する」と結びつかず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」。「液体ですると」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「液体のすると」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "結果や変化の先を示す「に」。「液体にする」で状態の変化を表すので正しい。", "が": "主語の「が」。「液体がすると」は「する」と結びつかず成り立たない。", "で": "手段を表す「で」。「液体ですると」は文として成り立たない。", "の": "連体修飾の「の」。「液体のすると」は文として成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52348, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物質の状態の一つで、形が決まっておらず、容器の形に合わせて変形し、流れる性質を持つもの。", "primary_collocate": null, "pronunciation": "えきたい", "ipa": "ekitai", "syllable_count": 4, "sentences": [{"text": "理科の時間に、液体の性質について学んだ。", "target_word": "液体", "complexity_tier": "T2", "furigana": "理科[りか]の時間[じかん]に、液体[えきたい]の性質[せいしつ]について学[まな]んだ。", "sentence_source": "generated"}, {"text": "水は温度が下がると固体になり、上がると気体になるが、その間は液体である。", "target_word": "液体", "complexity_tier": "T4", "furigana": "水[みず]は温度[おんど]が下[さ]がると固体[こたい]になり、上[あ]がると気体[きたい]になるが、その間[あいだ]は液体[えきたい]である。", "sentence_source": "generated"}, {"text": "液体は決まった形がなく、入れ物に合わせて形が変わる。", "target_word": "液体", "complexity_tier": "T3", "furigana": "液体[えきたい]は決[き]まった形[かたち]がなく、入[い]れ物[もの]に合[あ]わせて形[かたち]が変[か]わる。", "sentence_source": "generated"}, {"text": "理科の実験で、青い液体と赤い液体を混ぜると色が変わった。", "target_word": "液体", "complexity_tier": "T3", "furigana": "理科[りか]の実験[じっけん]で、青[あお]い液体[えきたい]と赤[あか]い液体[えきたい]を混[ま]ぜると色[いろ]が変[か]わった。", "sentence_source": "generated"}, {"text": "液体は気体と違って、圧縮してもほとんど体積が変わらない。", "target_word": "液体", "complexity_tier": "T4", "furigana": "液体[えきたい]は気体[きたい]と違[ちが]って、圧縮[あっしゅく]してもほとんど体積[たいせき]が変[か]わらない。", "sentence_source": "generated"}, {"text": "冷凍庫に入れた液体は、ゆっくり凍って固体になった。", "target_word": "液体", "complexity_tier": "T3", "furigana": "冷凍庫[れいとうこ]に入[い]れた液体[えきたい]は、ゆっくり凍[こお]って固体[こたい]になった。", "sentence_source": "generated"}, {"text": "水銀は、室温で液体である珍しい金属だ。", "target_word": "液体", "complexity_tier": "T4", "furigana": "水銀[すいぎん]は、室温[しつおん]で液体[えきたい]である珍[めずら]しい金属[きんぞく]だ。", "sentence_source": "generated"}, {"text": "窒素を冷やして液体にすると、ものを一瞬で凍らせる冷却材として使える。", "target_word": "液体", "complexity_tier": "T4", "furigana": "窒素[ちっそ]を冷[ひ]やして液体[えきたい]にすると、ものを一瞬[いっしゅん]で凍[こお]らせる冷却材[れいきゃくざい]として使[つか]える。", "sentence_source": "generated"}, {"text": "液体が沸騰すると、気体になって空気中に出ていく。", "target_word": "液体", "complexity_tier": "T4", "furigana": "液体[えきたい]が沸騰[ふっとう]すると、気体[きたい]になって空気中[くうきちゅう]に出[で]ていく。", "sentence_source": "generated"}, {"text": "コップに注いだ液体は、傾けても表面が常に水平を保つ。", "target_word": "液体", "complexity_tier": "T4", "furigana": "コップ[こっぷ]に注[そそ]いだ液体[えきたい]は、傾[かたむ]けても表面[ひょうめん]が常[つね]に水平[すいへい]を保[たも]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "液体", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "固体・気体と並ぶ物質の三態の一つという科学的な意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "「理科の時間に、液体の性質について学んだ」の「液体」。物質の三態の一つを表す語。"}, {"text": "樽", "is_correct": false, "explanation": "樽は酒を入れる容器で、物質の性質を学ぶ対象ではないので合わない。"}, {"text": "品種", "is_correct": false, "explanation": "ブドウなどの種類を指す語で、理科で学ぶ性質とは合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指す語で、理科で学ぶ物質の性質とは合わない。"}], "explanations": {"液体": "「理科の時間に、液体の性質について学んだ」の「液体」。物質の三態の一つを表す語。", "樽": "樽は酒を入れる容器で、物質の性質を学ぶ対象ではないので合わない。", "品種": "ブドウなどの種類を指す語で、理科で学ぶ性質とは合わない。", "天候": "天気の状態を指す語で、理科で学ぶ物質の性質とは合わない。"}, "sentence_index": 0, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷凍庫で冷やした食品は、形が変わらない液体になった。", "explanation": "ここは〈固体〉の意味。形が変わらずに固まるのは固体で、液体は形が決まっていないので合わない。"}, {"text": "窓を開けて、部屋の液体を入れ替えた。", "explanation": "ここは〈空気〉の意味。部屋の空気を入れ替える文で、液体は空気の代わりにならない。"}, {"text": "鍋のふたを開けると、熱い液体が白く立ちのぼった。", "explanation": "ここは〈蒸気〉の意味。白く立ちのぼるのは蒸気で、容器の中の液体とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "液体", "is_correct": true, "explanation": "室温で水銀は液体である。物質の状態として正しい語。"}, {"text": "鉱物", "is_correct": false, "explanation": "「鉱物」は物質の種類を表し、室温での状態を表す語ではないので合わない。"}, {"text": "合金", "is_correct": false, "explanation": "「合金」は複数の金属を混ぜたものを指し、水銀の室温での状態とは合わない。"}, {"text": "結晶", "is_correct": false, "explanation": "「結晶」は規則正しく並んだ固体の形を指し、室温で水銀が結晶だとは言えない。"}], "explanations": {"液体": "室温で水銀は液体である。物質の状態として正しい語。", "鉱物": "「鉱物」は物質の種類を表し、室温での状態を表す語ではないので合わない。", "合金": "「合金」は複数の金属を混ぜたものを指し、水銀の室温での状態とは合わない。", "結晶": "「結晶」は規則正しく並んだ固体の形を指し、室温で水銀が結晶だとは言えない。"}, "sentence_index": 6, "correct_answer": "液体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬の朝、池の表面に液体が一面に張って、子どもたちが上を滑って遊んだ。", "explanation": "ここは〈氷〉の意味。池に張って上を滑って遊べるのは氷で、液体は滑れる面にならないので合わない。"}, {"text": "コーヒーに入れた液体は、スプーンでかき混ぜても溶けずに底に沈んだ。", "explanation": "ここは〈粉〉の意味。溶けずに底に沈むのは粉で、この文脈の液体には合わないので不正解。"}, {"text": "煙突から黒い液体が上がっている。", "explanation": "ここは〈煙〉の意味。煙突から立ちのぼるのは煙で、液体は上へ立ちのぼらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷やすと液体を固体になる。", "corrected_sentence": "冷やすと液体が固体になる。", "error_description": "「なる」は変化を表し、変わるものを主語として「が」で示す。「液体を」は目的語の「を」なので誤り。「液体が固体になる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬品は、液体な状態で保管する必要がある。", "corrected_sentence": "この薬品は、液体の状態で保管する必要がある。", "error_description": "名詞の「液体」は「の」で「状態」につなぐ。「液体な」は形容動詞の語尾なので、名詞の「液体」には使えず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「注文した」の対象を示す目的語の「を」。正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「ワインが注文した」は主語が合わず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ワインに注文した」は注文の対象を示せず、合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」。「ワインで注文した」は不自然で合わない。"}], "correct_answer": "を", "explanations": {"を": "「注文した」の対象を示す目的語の「を」。正しい。", "が": "主語の「が」。「ワインが注文した」は主語が合わず成り立たない。", "に": "「ワインに注文した」は注文の対象を示せず、合わない。", "で": "手段を表す「で」。「ワインで注文した」は不自然で合わない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作っている」の対象を示す目的語の「を」。正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「ワインへ作る」は作る対象を示せず、合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す「と」。「ワインと作る」は作る対象にならず、合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「ワインより作る」は比べる相手がなく成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「作っている」の対象を示す目的語の「を」。正しい。", "へ": "方向を表す「へ」。「ワインへ作る」は作る対象を示せず、合わない。", "と": "並列や相手を表す「と」。「ワインと作る」は作る対象にならず、合わない。", "より": "比較の「より」。「ワインより作る」は比べる相手がなく成り立たない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ぶどうからつくられる、のむもの。", "primary_collocate": null, "pronunciation": "わいん", "ipa": "waiɴ", "syllable_count": 3, "sentences": [{"text": "ワインはぶどうから作るお酒だ。", "target_word": "ワイン", "complexity_tier": "T1", "furigana": "ワインはぶどうから作[つく]るお酒[さけ]だ。", "sentence_source": "generated"}, {"text": "姉はレストランでワインを注文した。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "姉[あね]はレストランでワインを注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "白いワインは魚の料理によく合う。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "白[しろ]いワインは魚[さかな]の料理[りょうり]によく合[あ]う。", "sentence_source": "generated"}, {"text": "パーティーで、みんなワインのグラスを持っていた。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "パーティーで、みんなワインのグラスを持[も]っていた。", "sentence_source": "generated"}, {"text": "日本でも、山梨県でおいしいワインが作られている。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "日本[にほん]でも、山梨県[やまなしけん]でおいしいワインが作[つく]られている。", "sentence_source": "generated"}, {"text": "彼はワインが好きで、家に何本も置いている。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "彼[かれ]はワインが好[す]きで、家[いえ]に何本[なんぼん]も置[お]いている。", "sentence_source": "generated"}, {"text": "ワインを飲みすぎて、次の朝は頭が痛かった。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "ワインを飲[の]みすぎて、次[つぎ]の朝[あさ]は頭[あたま]が痛[いた]かった。", "sentence_source": "generated"}, {"text": "祖父は庭のぶどうで、自分でワインを作っている。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]のぶどうで、自分[じぶん]でワインを作[つく]っている。", "sentence_source": "generated"}, {"text": "子どもはワインを飲んではいけない。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "子[こ]どもはワインを飲[の]んではいけない。", "sentence_source": "generated"}, {"text": "このワインは安いのに、味がしっかりしている。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "このワインは安[やす]いのに、味[あじ]がしっかりしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ワイン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ぶどうから作るお酒。食事やパーティーで飲む身近な飲み物としてのワイン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ワイン", "is_correct": true, "explanation": "ぶどうから作るお酒はワイン。文の説明と一致する。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳はぶどうから作らず、お酒でもないので合わない。"}, {"text": "麦茶", "is_correct": false, "explanation": "麦茶はお酒ではないので、「お酒だ」という文に合わない。"}, {"text": "醤油", "is_correct": false, "explanation": "醤油はお酒ではなく、ぶどうから作るものでもないので合わない。"}], "explanations": {"ワイン": "ぶどうから作るお酒はワイン。文の説明と一致する。", "牛乳": "牛乳はぶどうから作らず、お酒でもないので合わない。", "麦茶": "麦茶はお酒ではないので、「お酒だ」という文に合わない。", "醤油": "醤油はお酒ではなく、ぶどうから作るものでもないので合わない。"}, "sentence_index": 0, "correct_answer": "ワイン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ワインはパンに塗って食べる。", "explanation": "ここは〈ジャム〉の意味。パンに塗って食べるのはジャムで、ワインは塗るものではないので合わない。"}, {"text": "ワインは塩で漬けて、数日置くとおいしくなる。", "explanation": "ここは〈漬物〉の意味。塩で漬けて置いておく食品は漬物で、ワインは漬けないので合わない。"}, {"text": "ワインは歯ブラシにつけて使う。", "explanation": "ここは〈歯磨き粉〉の意味。歯ブラシにつけて使うのは歯磨き粉で、ワインは口に入れる飲み物なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ワイン", "is_correct": true, "explanation": "飲みすぎて頭が痛くなる飲み物はワイン。文と一致する。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は飲むものではなく、飲みすぎて頭が痛いという文に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は飲むものではなく、この文脈に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は飲むものではなく、この文脈に合わない。"}], "explanations": {"ワイン": "飲みすぎて頭が痛くなる飲み物はワイン。文と一致する。", "石鹸": "石鹸は飲むものではなく、飲みすぎて頭が痛いという文に合わない。", "紙": "紙は飲むものではなく、この文脈に合わない。", "砂": "砂は飲むものではなく、この文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ワイン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このワインは、泡立てて汚れを落とす。", "explanation": "ここは〈洗剤〉の意味。汚れを落とすために泡立てて使うのは洗剤で、ワインは汚れを落とす道具ではないので合わない。"}, {"text": "このワインは、生地が薄くて肌触りがいい。", "explanation": "ここは〈布〉の意味。生地や肌触りを語るのは布で、飲み物のワインには合わない。"}, {"text": "このワインは、木目が美しくて光沢がある。", "explanation": "ここは〈木材〉の意味。木目を語るのは木材で、ワインには木目がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕食の後、ワインが飲むことにしている。", "corrected_sentence": "夕食の後、ワインを飲むことにしている。", "error_description": "「飲む」は目的語を取る動詞なので、ワインには「を」を使う。「が」は主語の印なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52349, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このワインに、とても香りが高い。", "corrected_sentence": "このワインは、とても香りが高い。", "error_description": "香りを語る話題として「は」で主題を示す必要がある。「に」は場所や対象を示すため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
