INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52350, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題を示す「は」。「ワインは飲まないことにした」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「ワインが飲まない」は主語と述語が合わず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を表す「に」。「ワインに飲まない」は飲む対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」。「ワインで飲まない」は不自然で合わない。"}], "correct_answer": "は", "explanations": {"は": "話題を示す「は」。「ワインは飲まないことにした」で正しい。", "が": "主語の「が」。「ワインが飲まない」は主語と述語が合わず成り立たない。", "に": "場所や相手を表す「に」。「ワインに飲まない」は飲む対象を示せない。", "で": "手段を表す「で」。「ワインで飲まない」は不自然で合わない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52350, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ブドウを発酵させて作ったアルコール飲料。", "primary_collocate": null, "pronunciation": "わいん", "ipa": "waiɴ", "syllable_count": 3, "sentences": [{"text": "ワインは、ブドウの果汁を発酵させて作られる。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "ワインは、ブドウ[ぶどう]の果汁[かじゅう]を発酵[はっこう]させて作[つく]られる。", "sentence_source": "generated"}, {"text": "ワインは、ブドウの品種によって味が大きく変わる。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "ワインは、ブドウ[ぶどう]の品種[ひんしゅ]によって味[あじ]が大きく変[か]わる。", "sentence_source": "generated"}, {"text": "夕食のとき、父はいつもワインを一杯だけ飲む。", "target_word": "ワイン", "complexity_tier": "T2", "furigana": "夕食[ゆうしょく]のとき、父[ちち]はいつもワインを一杯[いっぱい]だけ飲[の]む。", "sentence_source": "generated"}, {"text": "このワインはぶどうの香りが強くて、とても飲みやすい。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "このワインはぶどうの香[かお]りが強[つよ]くて、とても飲[の]みやすい。", "sentence_source": "generated"}, {"text": "友だちの誕生日に、おいしいワインを贈ることにした。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "友[とも]だちの誕生日[たんじょうび]に、おいしいワインを贈[おく]ることにした。", "sentence_source": "generated"}, {"text": "ワインは長い間ねかせると、味がまろやかになる。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "ワインは長[なが]い間[あいだ]ねかせると、味[あじ]がまろやかになる。", "sentence_source": "generated"}, {"text": "肉料理に合うワインを、店員さんに選んでもらった。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "肉[にく]料理[りょうり]に合[あ]うワインを、店員[てんいん]さんに選[えら]んでもらった。", "sentence_source": "generated"}, {"text": "運転する予定があるので、ワインは飲まないことにした。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "運転[うんてん]する予定[よてい]があるので、ワインは飲[の]まないことにした。", "sentence_source": "generated"}, {"text": "母は料理にワインを少し入れて、肉をやわらかくする。", "target_word": "ワイン", "complexity_tier": "T3", "furigana": "母[はは]は料理[りょうり]にワインを少[すこ]し入[い]れて、肉[にく]をやわらかくする。", "sentence_source": "generated"}, {"text": "フランスへ旅行したとき、ワインを作る農園を見学した。", "target_word": "ワイン", "complexity_tier": "T4", "furigana": "フランスへ旅行[りょこう]したとき、ワインを作[つく]る農園[のうえん]を見学[けんがく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ワイン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ブドウを発酵させて作る酒。産地・品種・味わいが語られる飲み物としてのワイン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52350, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ワイン", "is_correct": true, "explanation": "ブドウの果汁を発酵させて作られる飲み物はワイン。"}, {"text": "農園", "is_correct": false, "explanation": "農園はブドウを育てる場所で、発酵させて作られるものではないので合わない。"}, {"text": "樽", "is_correct": false, "explanation": "樽は酒を貯蔵する容器で、発酵させて作られるものではないので合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指す語で、発酵させて作られるものではないので合わない。"}], "explanations": {"ワイン": "ブドウの果汁を発酵させて作られる飲み物はワイン。", "農園": "農園はブドウを育てる場所で、発酵させて作られるものではないので合わない。", "樽": "樽は酒を貯蔵する容器で、発酵させて作られるものではないので合わない。", "天候": "天気の状態を指す語で、発酵させて作られるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "ワイン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このワインは大粒で、一粒ずつもぎ取って食べられる。", "explanation": "ここは〈ぶどう〉の意味。大粒で一粒ずつ食べるのは果実で、飲み物のワインには合わない。"}, {"text": "このワインは汚れがよく落ちる。", "explanation": "ここは〈洗剤〉の意味。汚れを落とすのは洗剤の役割で、飲み物のワインには合わない。"}, {"text": "このワインは咳を止める効果がある。", "explanation": "ここは〈薬〉の意味。咳を止める効果は薬の役割で、飲み物のワインには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52350, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ワイン", "is_correct": true, "explanation": "肉料理に合わせて選んでもらう飲み物はワイン。"}, {"text": "氷", "is_correct": false, "explanation": "氷は肉料理に合わせて店員に選んでもらうものではない。"}, {"text": "小麦粉", "is_correct": false, "explanation": "小麦粉は料理の材料で、肉料理に合わせて選んでもらう対象ではない。"}, {"text": "寒天", "is_correct": false, "explanation": "寒天は食材で、肉料理に合わせて店員が選ぶ対象ではない。"}], "explanations": {"ワイン": "肉料理に合わせて選んでもらう飲み物はワイン。", "氷": "氷は肉料理に合わせて店員に選んでもらうものではない。", "小麦粉": "小麦粉は料理の材料で、肉料理に合わせて選んでもらう対象ではない。", "寒天": "寒天は食材で、肉料理に合わせて店員が選ぶ対象ではない。"}, "sentence_index": 6, "correct_answer": "ワイン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このワインは、大豆から作る調味料だ。", "explanation": "ここは〈醤油〉の意味。大豆から作る調味料は醤油で、ぶどうから作る酒のワインとは合わない。"}, {"text": "ワインは白くて粒状で、スプーンですくって使う。", "explanation": "ここは〈砂糖〉の意味。白い粒状で、すくって使う食品は砂糖で、飲み物のワインには合わない。"}, {"text": "ワインは、お湯で数分蒸らすとおいしく飲める。", "explanation": "ここは〈紅茶〉の意味。お湯で蒸らして飲むのは紅茶で、ワインはお湯で蒸らさないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52350, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父の日に、ワインが贈ることにした。", "corrected_sentence": "父の日に、ワインを贈ることにした。", "error_description": "「贈る」は目的語を取る動詞なので、ワインには「を」を使う。「が」は主語の印なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52350, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は仕事があるので、ワインに飲まないことにした。", "corrected_sentence": "明日は仕事があるので、ワインは飲まないことにした。", "error_description": "「ワイン」を話題として示す「は」が必要。「に」は場所や相手を表すもので、飲む対象は示せないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「テロのこと」で、テロについての事柄を示す「の」。"}, {"text": "が", "is_correct": false, "explanation": "「テロがこと」は「こと」に続けると不自然で、知る対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「テロでことを知り」は手段の「で」になり、テロの内容を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「テロへこと」は方向の「へ」で、内容を指す「こと」とつながらない。"}], "correct_answer": "の", "explanations": {"の": "「テロのこと」で、テロについての事柄を示す「の」。", "が": "「テロがこと」は「こと」に続けると不自然で、知る対象を表せない。", "で": "「テロでことを知り」は手段の「で」になり、テロの内容を示せない。", "へ": "「テロへこと」は方向の「へ」で、内容を指す「こと」とつながらない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "わるいことをするために、人をこわがらせること。", "primary_collocate": null, "pronunciation": "てろ", "ipa": "teɾo", "syllable_count": 2, "sentences": [{"text": "悪い人たちがテロを起こして、町の人はとても不安になった。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "悪(わる)い人(ひと)たちがテロを起(お)こして、町(まち)の人(ひと)はとても不安(ふあん)になった。", "sentence_source": "generated"}, {"text": "ニュースでテロのことを知り、母は旅行を取りやめた。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "ニュースでテロのことを知(し)り、母(はは)は旅行(りょこう)を取(と)りやめた。", "sentence_source": "generated"}, {"text": "テロは人をこわがらせるための悪い行いで、どんな理由があっても許されない。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "テロは人(ひと)をこわがらせるための悪(わる)い行(おこな)いで、どんな理由(りゆう)があっても許(ゆる)されない。", "sentence_source": "generated"}, {"text": "学校では、テロが起きたときの逃げ方を先生が教えてくれた。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "学校(がっこう)では、テロが起(お)きたときの逃(に)げ方(かた)を先生(せんせい)が教(おし)えてくれた。", "sentence_source": "generated"}, {"text": "映画の悪者は、街でテロをして人々をおどそうとした。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "映画(えいが)の悪者(わるもの)は、街(まち)でテロをして人々(ひとびと)をおどそうとした。", "sentence_source": "generated"}, {"text": "駅に警察官が多いのは、テロを防ぐためだ。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "駅(えき)に警察官(けいさつかん)が多(おお)いのは、テロを防(ふせ)ぐためだ。", "sentence_source": "generated"}, {"text": "テロの話を聞いた妹は、こわくて夜眠れなかった。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "テロの話(はなし)を聞(き)いた妹(いもうと)は、こわくて夜(よる)眠(ねむ)れなかった。", "sentence_source": "generated"}, {"text": "世界中の人が、テロのない平和な毎日を願っている。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "世界中(せかいじゅう)の人(ひと)が、テロのない平和(へいわ)な毎日(まいにち)を願(ねが)っている。", "sentence_source": "generated"}, {"text": "外国で起きたテロで、日本人が巻き込まれたと聞いて心配になった。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "外国(がいこく)で起(お)きたテロで、日本人(にほんじん)が巻(ま)き込(こ)まれたと聞(き)いて心配(しんぱい)になった。", "sentence_source": "generated"}, {"text": "テロをした犯人は、すぐに警察に捕まった。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "テロをした犯人(はんにん)は、すぐに警察(けいさつ)に捕(つか)まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テロ", "label": "基本形"}, {"form": "テロの", "label": "連体形（の）"}, {"form": "テロを", "label": "格助詞（を）"}, {"form": "テロで", "label": "格助詞（で）"}], "register": "neutral", "sense_fingerprint": "悪い目的で人をこわがらせる行い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: こわがら (Zipf 1.87)']::text[], 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テロ", "is_correct": true, "explanation": "「テロを起こす」で、人をこわがらせる悪事を指すので文に合う。"}, {"text": "相談", "is_correct": false, "explanation": "「相談を起こす」は言わず、悪い人たちの行為として文が成り立たない。"}, {"text": "勉強", "is_correct": false, "explanation": "「勉強を起こす」は結びつかず、町の人が不安になる行為にならない。"}, {"text": "料理", "is_correct": false, "explanation": "「料理を起こす」は言わず、不安になる文脈に合わない。"}], "explanations": {"テロ": "「テロを起こす」で、人をこわがらせる悪事を指すので文に合う。", "相談": "「相談を起こす」は言わず、悪い人たちの行為として文が成り立たない。", "勉強": "「勉強を起こす」は結びつかず、町の人が不安になる行為にならない。", "料理": "「料理を起こす」は言わず、不安になる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "テロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は遅刻の理由を聞かれて、とっさにテロをついた。", "explanation": "ここは〈うそ〉の意味。テロは人をこわがらせる行為で、事実と違うことを言う意味では使わない。"}, {"text": "手品師は舞台の上で、次々とテロを見せて観客を驚かせた。", "explanation": "ここは〈手品〉の意味。テロは悪い目的で人を恐怖に陥れる行為で、観客を楽しませる芸には使わない。"}, {"text": "友だちと海に行き、砂でテロを作って遊んだ。", "explanation": "ここは〈砂の造形〉の意味。テロは人を恐怖に陥れる行為で、砂で作る形には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テロ", "is_correct": true, "explanation": "「テロの話」で、妹がこわくなった内容として文脈に合う。"}, {"text": "遠足", "is_correct": false, "explanation": "遠足は楽しい行事で、こわくて夜眠れない文脈に合わない。"}, {"text": "算数", "is_correct": false, "explanation": "算数の話では恐怖を感じる流れにならず、文の意味が通らない。"}, {"text": "駅伝", "is_correct": false, "explanation": "駅伝の話で夜眠れなくなる理由がなく、不自然。"}], "explanations": {"テロ": "「テロの話」で、妹がこわくなった内容として文脈に合う。", "遠足": "遠足は楽しい行事で、こわくて夜眠れない文脈に合わない。", "算数": "算数の話では恐怖を感じる流れにならず、文の意味が通らない。", "駅伝": "駅伝の話で夜眠れなくなる理由がなく、不自然。"}, "sentence_index": 6, "correct_answer": "テロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちは冗談めかしてテロを言い、みんなを笑わせた。", "explanation": "ここは〈冗談〉の意味。テロは人をこわがらせる悪い目的の行為で、笑わせる冗談には使わない。"}, {"text": "朝、先生にテロをすると、先生も笑顔で返した。", "explanation": "ここは〈挨拶〉の意味。テロは悪い目的の脅しなので、朝の挨拶には使わない。"}, {"text": "占い師は、お客さんの手相を見てテロをした。", "explanation": "ここは〈占い〉の意味。テロは人をこわがらせる悪事で、手相を見て判断する占いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "悪い人たちは、町でテロに起こそうとしていた。", "corrected_sentence": "悪い人たちは、町でテロを起こそうとしていた。", "error_description": "「起こす」は「を」で目的語を取るので「テロを起こす」が正しい。「テロに起こす」は助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52351, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "テロな計画を立てた男が、昨日警察に捕まった。", "corrected_sentence": "テロの計画を立てた男が、昨日警察に捕まった。", "error_description": "「テロ」は名詞なので、名詞に続く「の」で「テロの計画」とする。「テロな計画」は形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「テロの被害者」で、テロによって生じた被害者を結ぶ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「テロを被害者」は目的語の形になり、名詞同士を結べず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「テロに被害者」は被害者を修飾する関係にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「テロへ被害者」は方向を表す「へ」で、被害の原因を示す関係にならない。"}], "correct_answer": "の", "explanations": {"の": "「テロの被害者」で、テロによって生じた被害者を結ぶ「の」。", "を": "「テロを被害者」は目的語の形になり、名詞同士を結べず文が成り立たない。", "に": "「テロに被害者」は被害者を修飾する関係にならず、不自然。", "へ": "「テロへ被害者」は方向を表す「へ」で、被害の原因を示す関係にならない。"}, "error_tags": {"を": "目的語", "に": "相手・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「過去のテロの記憶」で、テロに関する記憶であることを示す「の」。"}, {"text": "が", "is_correct": false, "explanation": "「テロが記憶」は主語の形になり、記憶と結びつかず意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「テロで記憶」は手段・原因の「で」になるが、記憶の内容を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「テロより記憶」は比較の形になり、文の流れに合わない。"}], "correct_answer": "の", "explanations": {"の": "「過去のテロの記憶」で、テロに関する記憶であることを示す「の」。", "が": "「テロが記憶」は主語の形になり、記憶と結びつかず意味が通らない。", "で": "「テロで記憶」は手段・原因の「で」になるが、記憶の内容を示せない。", "より": "「テロより記憶」は比較の形になり、文の流れに合わない。"}, "error_tags": {"が": "主語", "で": "手段・原因", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "政治的な目的を達成するために、暴力や脅しを使って人々を恐怖に陥れる行為。", "primary_collocate": null, "pronunciation": "てろ", "ipa": "teɾo", "syllable_count": 2, "sentences": [{"text": "政府はテロを許さないという姿勢を、国民の前で改めて示した。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "政府(せいふ)はテロを許(ゆる)さないという姿勢(しせい)を、国民(こくみん)の前(まえ)で改(あらた)めて示(しめ)した。", "sentence_source": "generated"}, {"text": "駅で起きたテロの被害者のために、多くの人が花を供えた。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "駅(えき)で起(お)きたテロの被害者(ひがいしゃ)のために、多(おお)くの人(ひと)が花(はな)を供(そな)えた。", "sentence_source": "generated"}, {"text": "テロは政治的な主張を通すために民間人を狙うので、国際社会から強く非難される。", "target_word": "テロ", "complexity_tier": "T4", "furigana": "テロは政治的(せいじてき)な主張(しゅちょう)を通(とお)すために民間人(みんかんじん)を狙(ねら)うので、国際社会(こくさいしゃかい)から強(つよ)く非難(ひなん)される。", "sentence_source": "generated"}, {"text": "空港では、テロを防ぐために荷物の検査が厳しくなった。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "空港(くうこう)では、テロを防(ふせ)ぐために荷物(にもつ)の検査(けんさ)が厳(きび)しくなった。", "sentence_source": "generated"}, {"text": "首都で起きた爆破がテロだと断定されるまでに、数日かかった。", "target_word": "テロ", "complexity_tier": "T4", "furigana": "首都(しゅと)で起(お)きた爆破(ばくは)がテロだと断定(だんてい)されるまでに、数日(すうじつ)かかった。", "sentence_source": "generated"}, {"text": "各国の首脳は、テロに屈しない決意を共同声明で表明した。", "target_word": "テロ", "complexity_tier": "T4", "furigana": "各国(かっこく)の首脳(しゅのう)は、テロに屈(くっ)しない決意(けつい)を共同声明(きょうどうせいめい)で表明(ひょうめい)した。", "sentence_source": "generated"}, {"text": "彼は新聞記者として、テロが社会に与えた恐怖を取材してきた。", "target_word": "テロ", "complexity_tier": "T3", "furigana": "彼(かれ)は新聞記者(しんぶんきしゃ)として、テロが社会(しゃかい)に与(あた)えた恐怖(きょうふ)を取材(しゅざい)してきた。", "sentence_source": "generated"}, {"text": "過去のテロの記憶があるため、この国では大きな行事の警備が特に厳重だ。", "target_word": "テロ", "complexity_tier": "T4", "furigana": "過去(かこ)のテロの記憶(きおく)があるため、この国(くに)では大(おお)きな行事(ぎょうじ)の警備(けいび)が特(とく)に厳重(げんじゅう)だ。", "sentence_source": "generated"}, {"text": "専門家は、テロの背景にある貧困や対立にも目を向けるべきだと述べた。", "target_word": "テロ", "complexity_tier": "T4", "furigana": "専門家(せんもんか)は、テロの背景(はいけい)にある貧困(ひんこん)や対立(たいりつ)にも目(め)を向(む)けるべきだと述(の)べた。", "sentence_source": "generated"}, {"text": "国連は、テロを根絶するための新しい条約について話し合っている。", "target_word": "テロ", "complexity_tier": "T4", "furigana": "国連(こくれん)は、テロを根絶(こんぜつ)するための新(あたら)しい条約(じょうやく)について話(はな)し合(あ)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テロ", "label": "基本形"}, {"form": "テロの", "label": "連体形（の）"}, {"form": "テロを", "label": "格助詞（を）"}, {"form": "テロに", "label": "格助詞（に）"}], "register": "neutral", "sense_fingerprint": "政治的目的のための暴力による恐怖の行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テロ", "is_correct": true, "explanation": "政府が許さないと述べている対象として、政治目的の暴力行為を指すので文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨は自然現象で、政府が「許さない」対象にはならず、文が成り立たない。"}, {"text": "外交", "is_correct": false, "explanation": "外交は政府の活動そのもので、「許さない」対象として文が成り立たない。"}, {"text": "税制", "is_correct": false, "explanation": "税制は政策の枠組みで、「許さない」と結びつかず不自然。"}], "explanations": {"テロ": "政府が許さないと述べている対象として、政治目的の暴力行為を指すので文に合う。", "雨": "雨は自然現象で、政府が「許さない」対象にはならず、文が成り立たない。", "外交": "外交は政府の活動そのもので、「許さない」対象として文が成り立たない。", "税制": "税制は政策の枠組みで、「許さない」と結びつかず不自然。"}, "sentence_index": 0, "correct_answer": "テロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は週末、台所でテロを焼いて家族に配った。", "explanation": "ここは〈料理〉の意味。テロは人を恐怖に陥れる行為で、食べ物を作る話には使わない。"}, {"text": "子どもたちは夜、近所の家のチャイムを鳴らして逃げるテロをしていた。", "explanation": "ここは〈いたずら〉の意味。テロは政治目的の暴力行為で、子どもの悪ふざけには使わない。"}, {"text": "台風が過ぎたあと、テロで家が何軒も流された。", "explanation": "ここは〈災害〉の意味。テロは人為的な暴力行為なので、自然災害の被害には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テロ", "is_correct": true, "explanation": "記者が取材してきた対象で、社会に恐怖を与えた行為なので文脈に合う。"}, {"text": "繁栄", "is_correct": false, "explanation": "繁栄は社会に恐怖を与えるものではなく、恐怖の取材という文脈と合わない。"}, {"text": "謙遜", "is_correct": false, "explanation": "謙遜は個人の態度を表し、社会に恐怖を与える対象にならない。"}, {"text": "豊作", "is_correct": false, "explanation": "豊作は農業の出来を指し、恐怖の取材と結びつかない。"}], "explanations": {"テロ": "記者が取材してきた対象で、社会に恐怖を与えた行為なので文脈に合う。", "繁栄": "繁栄は社会に恐怖を与えるものではなく、恐怖の取材という文脈と合わない。", "謙遜": "謙遜は個人の態度を表し、社会に恐怖を与える対象にならない。", "豊作": "豊作は農業の出来を指し、恐怖の取材と結びつかない。"}, "sentence_index": 6, "correct_answer": "テロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空き巣は玄関の鍵を壊し、テロをして現金だけを盗んでいった。", "explanation": "ここは〈窃盗〉の意味。テロは政治目的で人々を恐怖に陥れる行為で、こっそり金品を盗むことには使わない。"}, {"text": "兄と弟はテロを始めて、リビングで大声を上げた。", "explanation": "ここは〈喧嘩〉の意味。テロは計画的で政治的な暴力行為で、家族の口げんかには使わない。"}, {"text": "職場の同僚が、新人に対してテロを続け、やめさせようとした。", "explanation": "ここは〈嫌がらせ〉の意味。テロは大勢を恐怖に陥れる行為で、個人への嫌がらせには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の周辺では、テロが警戒して見回りが増やされた。", "corrected_sentence": "駅の周辺では、テロを警戒して見回りが増やされた。", "error_description": "「警戒する」の対象は「テロ」なので「テロを警戒して」が正しい。「テロが警戒して」は「テロ」を警戒の主体にしてしまう誤りで、助詞「が」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52352, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港では、テロな行為を防ぐために検査が続けられている。", "corrected_sentence": "港では、テロ的な行為を防ぐために検査が続けられている。", "error_description": "「テロ」は名詞なので「テロ的な」と形容動詞の形にする必要がある。「テロな」は形が不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「気象の変化」で、気象の中身として変化を示す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「気象を変化が激しい」は目的語の形にならず、「変化が激しい」と結べない。"}, {"text": "に", "is_correct": false, "explanation": "「気象に変化が激しい」は帰着や対象として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「気象へ変化が激しい」は方向を表すが、変化の主体として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「気象の変化」で、気象の中身として変化を示す「の」。", "を": "「気象を変化が激しい」は目的語の形にならず、「変化が激しい」と結べない。", "に": "「気象に変化が激しい」は帰着や対象として意味が通らない。", "へ": "「気象へ変化が激しい」は方向を表すが、変化の主体として成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「気象のニュース」で、気象に関するニュースを示す「の」。"}, {"text": "が", "is_correct": false, "explanation": "「気象がニュースを見て」は主語になるが、ニュースを見る主体として文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「気象でニュースを見て」は手段として不自然で、ニュースの内容を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「気象からニュースを見て」は起点を表すが、ニュースの種類を示す働きができない。"}], "correct_answer": "の", "explanations": {"の": "「気象のニュース」で、気象に関するニュースを示す「の」。", "が": "「気象がニュースを見て」は主語になるが、ニュースを見る主体として文が成り立たない。", "で": "「気象でニュースを見て」は手段として不自然で、ニュースの内容を示せない。", "から": "「気象からニュースを見て」は起点を表すが、ニュースの種類を示す働きができない。"}, "error_tags": {"が": "主語", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "天気や空のようすのことです。", "primary_collocate": null, "pronunciation": "きしょう", "ipa": "kiɕoː", "syllable_count": 3, "sentences": [{"text": "今日は気象が不安定なので、出かけるときは傘を持っていこう。", "target_word": "気象", "complexity_tier": "T3", "furigana": "今日[きょう]は気象[きしょう]が不安定[ふあんてい]なので、出[で]かけるときは傘[かさ]を持[も]っていこう。", "sentence_source": "generated"}, {"text": "気象の変化が激しいから、上着を一枚持って行くといい。", "target_word": "気象", "complexity_tier": "T3", "furigana": "気象[きしょう]の変化[へんか]が激[はげ]しいから、上着[うわぎ]を一枚[いちまい]持[も]って行[い]くといい。", "sentence_source": "generated"}, {"text": "朝から気象の状態が悪く、運動会は中止になった。", "target_word": "気象", "complexity_tier": "T3", "furigana": "朝[あさ]から気象[きしょう]の状態[じょうたい]が悪[わる]く、運動会[うんどうかい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "山に行く日は、気象をよく調べてから家を出る。", "target_word": "気象", "complexity_tier": "T3", "furigana": "山[やま]に行[い]く日[ひ]は、気象[きしょう]をよく調[しら]べてから家[いえ]を出[で]る。", "sentence_source": "generated"}, {"text": "海の近くは気象が変わりやすく、晴れていても急に雨が降る。", "target_word": "気象", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くは気象[きしょう]が変[か]わりやすく、晴[は]れていても急[きゅう]に雨[あめ]が降[ふ]る。", "sentence_source": "generated"}, {"text": "この島は気象が穏やかで、一年中旅行しやすい。", "target_word": "気象", "complexity_tier": "T3", "furigana": "この島[しま]は気象[きしょう]が穏[おだ]やかで、一年中[いちねんじゅう]旅行[りょこう]しやすい。", "sentence_source": "generated"}, {"text": "気象の状態が悪いと、船も飛行機も遅れることがある。", "target_word": "気象", "complexity_tier": "T3", "furigana": "気象[きしょう]の状態[じょうたい]が悪[わる]いと、船[ふね]も飛行機[ひこうき]も遅[おく]れることがある。", "sentence_source": "generated"}, {"text": "気象のニュースを見て、明日の服を決める。", "target_word": "気象", "complexity_tier": "T3", "furigana": "気象[きしょう]のニュースを見[み]て、明日[あした]の服[ふく]を決[き]める。", "sentence_source": "generated"}, {"text": "急な気象の変化に、観光客は驚いた様子だった。", "target_word": "気象", "complexity_tier": "T3", "furigana": "急[きゅう]な気象[きしょう]の変化[へんか]に、観光客[かんこうきゃく]は驚[おどろ]いた様子[ようす]だった。", "sentence_source": "generated"}, {"text": "気象に合わせて、畑の作業の予定を変える。", "target_word": "気象", "complexity_tier": "T3", "furigana": "気象[きしょう]に合[あ]わせて、畑[はたけ]の作業[さぎょう]の予定[よてい]を変[か]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気象", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "晴れ・雨・曇りなど、その日の天気や空のようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気象", "is_correct": true, "explanation": "「不安定」な天気を指し、傘を持つ判断に合う。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶は飲み物で、天気が不安定だから傘を持つ文脈に合わない。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は家具で、天気の話とはつながらない。"}, {"text": "小説", "is_correct": false, "explanation": "小説は文芸作品で、傘を持つ判断と結びつかない。"}], "explanations": {"気象": "「不安定」な天気を指し、傘を持つ判断に合う。", "紅茶": "紅茶は飲み物で、天気が不安定だから傘を持つ文脈に合わない。", "本棚": "本棚は家具で、天気の話とはつながらない。", "小説": "小説は文芸作品で、傘を持つ判断と結びつかない。"}, "sentence_index": 0, "correct_answer": "気象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食のために、市場で気象を買ってきた。", "explanation": "ここは〈食材〉の意味。気象は天気などのようすで、買える物ではないので合わない。"}, {"text": "引っ越しの前日、気象を片付けて荷物をまとめた。", "explanation": "ここは〈部屋〉の意味。気象は天気などのようすで、片付ける対象にはならない。"}, {"text": "祖母は気象が重く、三週間入院している。", "explanation": "ここは〈病気〉の意味。気象は天気などのようすで、病状の重さとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気象", "is_correct": true, "explanation": "「状態が悪い」天気を指し、船や飛行機の遅れの原因として自然。"}, {"text": "天井", "is_correct": false, "explanation": "天井の状態が悪くても船や飛行機が遅れる理由にならず、文が成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布の状態と船・飛行機の遅れは結びつかない。"}, {"text": "切手", "is_correct": false, "explanation": "切手の状態は船や飛行機の遅れと関係がなく、不自然。"}], "explanations": {"気象": "「状態が悪い」天気を指し、船や飛行機の遅れの原因として自然。", "天井": "天井の状態が悪くても船や飛行機が遅れる理由にならず、文が成り立たない。", "財布": "財布の状態と船・飛行機の遅れは結びつかない。", "切手": "切手の状態は船や飛行機の遅れと関係がなく、不自然。"}, "sentence_index": 6, "correct_answer": "気象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美術館では、有名な気象を三点展示している。", "explanation": "ここは〈作品〉の意味。気象は天気などのようすで、展示する対象にはならない。"}, {"text": "父の気象は百八十センチもあり、ドアに頭をぶつけそうだ。", "explanation": "ここは〈身長〉の意味。気象は天気などのようすで、人の背の高さは表せない。"}, {"text": "来月から気象を増やすため、毎日少しずつ積み立てている。", "explanation": "ここは〈貯金〉の意味。気象は天気などのようすで、お金を増やす対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "気象を変化に注意して、山歩きを楽しもう。", "corrected_sentence": "気象の変化に注意して、山歩きを楽しもう。", "error_description": "「気象の変化」は「の」で名詞をつなぐ。「気象を変化」は目的語にできず、助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52355, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "気象が荒れなので、山のハイキングは中止になった。", "corrected_sentence": "気象が荒れたので、山のハイキングは中止になった。", "error_description": "「荒れる」の過去形「荒れた」で「ので」に続ける。「荒れな」は活用の形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「山の気象は」で、話題として山の気象を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「気象を変わりやすい」は目的語の形にならず、「変わりやすい」と結べない。"}, {"text": "に", "is_correct": false, "explanation": "「気象に変わりやすい」は状態を説明する文脈になく、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「気象で変わりやすい」は手段・原因の形になるが、変わりやすい主語として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「山の気象は」で、話題として山の気象を示す「は」。", "を": "「気象を変わりやすい」は目的語の形にならず、「変わりやすい」と結べない。", "に": "「気象に変わりやすい」は状態を説明する文脈になく、意味が通らない。", "で": "「気象で変わりやすい」は手段・原因の形になるが、変わりやすい主語として成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手・対象", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「異常な気象が続く」で、気象を主語として続くことを表す「が」。"}, {"text": "と", "is_correct": false, "explanation": "「気象と続く」は並列の「と」が「続く」に接続せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「気象より続く」は比較の形で、主語の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「気象へ続く」は方向を表すが、天気が続く対象として不自然。"}], "correct_answer": "が", "explanations": {"が": "「異常な気象が続く」で、気象を主語として続くことを表す「が」。", "と": "「気象と続く」は並列の「と」が「続く」に接続せず、文が成り立たない。", "より": "「気象より続く」は比較の形で、主語の関係が成り立たない。", "へ": "「気象へ続く」は方向を表すが、天気が続く対象として不自然。"}, "error_tags": {"と": "並列", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "天気や気温、風などの自然のようす。", "primary_collocate": null, "pronunciation": "きしょう", "ipa": "kiɕoː", "syllable_count": 3, "sentences": [{"text": "ワインという液体媒体において、テロワールは単なる気象・地質学的変数の集合体ではなく、地質学的記憶が液相内に結晶化した記号系として機能する。", "target_word": "気象", "complexity_tier": "T3", "furigana": "ワインという液体[えきたい]媒体[ばいたい]において、テロワールは単[たん]なる気象[きしょう]・地質学的[ちしつがくてき]変数[へんすう]の集合体[しゅうごうたい]ではなく、地質学的[ちしつがくてき]記憶[きおく]が液相[えきそう]内[ない]に結晶化[けっしょうか]した記号系[きごうけい]として機能[きのう]する。", "sentence_source": "mined"}, {"text": "山の気象は変わりやすいので、登る前に必ず予報を確認する。", "target_word": "気象", "complexity_tier": "T3", "furigana": "山[やま]の気象[きしょう]は変[か]わりやすいので、登[のぼ]る前[まえ]に必[かなら]ず予報[よほう]を確認[かくにん]する。", "sentence_source": "generated"}, {"text": "この観測所では、気温や風などの気象を毎日記録している。", "target_word": "気象", "complexity_tier": "T3", "furigana": "この観測所[かんそくじょ]では、気温[きおん]や風[かぜ]などの気象[きしょう]を毎日[まいにち]記録[きろく]している。", "sentence_source": "generated"}, {"text": "気象が急変したため、予定していた船は出港を見合わせた。", "target_word": "気象", "complexity_tier": "T3", "furigana": "気象[きしょう]が急変[きゅうへん]したため、予定[よてい]していた船[ふね]は出港[しゅっこう]を見合[みあ]わせた。", "sentence_source": "generated"}, {"text": "農家にとって、雨や日照などの気象は収穫量を左右する大きな要素だ。", "target_word": "気象", "complexity_tier": "T3", "furigana": "農家[のうか]にとって、雨[あめ]や日照[にっしょう]などの気象[きしょう]は収穫量[しゅうかくりょう]を左右[さゆう]する大[おお]きな要素[ようそ]だ。", "sentence_source": "generated"}, {"text": "砂漠では昼夜の気温差が大きく、気象の変化が激しい。", "target_word": "気象", "complexity_tier": "T3", "furigana": "砂漠[さばく]では昼夜[ちゅうや]の気温差[きおんさ]が大[おお]きく、気象[きしょう]の変化[へんか]が激[はげ]しい。", "sentence_source": "generated"}, {"text": "彼は気象を研究する学者で、毎年各地の風の動きを調べている。", "target_word": "気象", "complexity_tier": "T3", "furigana": "彼[かれ]は気象[きしょう]を研究[けんきゅう]する学者[がくしゃ]で、毎年[まいとし]各地[かくち]の風[かぜ]の動[うご]きを調[しら]べている。", "sentence_source": "generated"}, {"text": "異常な気象が続くと、野菜の値段が上がることがある。", "target_word": "気象", "complexity_tier": "T3", "furigana": "異常[いじょう]な気象[きしょう]が続[つづ]くと、野菜[やさい]の値段[ねだん]が上[あ]がることがある。", "sentence_source": "generated"}, {"text": "気象の長期的な変化を知るには、百年分の記録が必要だ。", "target_word": "気象", "complexity_tier": "T3", "furigana": "気象[きしょう]の長期的[ちょうきてき]な変化[へんか]を知[し]るには、百年分[ひゃくねんぶん]の記録[きろく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "飛行機は、気象の状態によって飛ぶ道が変わる。", "target_word": "気象", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は、気象[きしょう]の状態[じょうたい]によって飛[と]ぶ道[みち]が変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気象", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "気温・風・雨など、大気中で起こる自然現象の全体的なようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: テロワール (Zipf 1.81)']::text[], 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気象", "is_correct": true, "explanation": "「単なる気象・地質学的変数」の一つとして、天気や気温など自然のようすを指すので文に合う。"}, {"text": "香り", "is_correct": false, "explanation": "香りは風味の要素で、テロワールを構成する気象・地質学的変数の並びには入らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は視覚的な特徴で、気象・地質学的変数の列挙とは合わない。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は感覚の一種で、気象・地質学的変数ではないので文脈に合わない。"}], "explanations": {"気象": "「単なる気象・地質学的変数」の一つとして、天気や気温など自然のようすを指すので文に合う。", "香り": "香りは風味の要素で、テロワールを構成する気象・地質学的変数の並びには入らない。", "色彩": "色彩は視覚的な特徴で、気象・地質学的変数の列挙とは合わない。", "味覚": "味覚は感覚の一種で、気象・地質学的変数ではないので文脈に合わない。"}, "sentence_index": 0, "correct_answer": "気象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は気象が激しく、すぐに人と口論になる。", "explanation": "ここは〈気性〉の意味。気象は天気などのようすなので、人の性格を表す文には合わない。"}, {"text": "この山は気象が高く、頂上にはいつも雪が積もっている。", "explanation": "ここは〈標高〉の意味。気象は天気などのようすで、山の高さは表せないので合わない。"}, {"text": "森には珍しい気象が多く住んでいて、観察が楽しい。", "explanation": "ここは〈生物〉の意味。気象は天気などのようすで、生き物を指さないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気象", "is_correct": true, "explanation": "「研究する」対象で、風の動きを調べる内容と結びつく。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は研究対象になりにくく、風の動きを調べる文脈と合わない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔は表情で、風の動きを調べる研究と結びつかない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は研究対象として風の動きの文脈と合わず、不自然。"}], "explanations": {"気象": "「研究する」対象で、風の動きを調べる内容と結びつく。", "寝息": "寝息は研究対象になりにくく、風の動きを調べる文脈と合わない。", "笑顔": "笑顔は表情で、風の動きを調べる研究と結びつかない。", "足音": "足音は研究対象として風の動きの文脈と合わず、不自然。"}, "sentence_index": 6, "correct_answer": "気象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池は気象が深く、子どもは近づくことを禁じられている。", "explanation": "ここは〈水深〉の意味。気象は天気などのようすで、池の深さは表せないので合わない。"}, {"text": "この建物は気象が古く、階段を上がるたびに床がきしむ。", "explanation": "ここは〈建物〉の意味。気象は天気などのようすなので、建物の古さは表せない。"}, {"text": "会議の気象が十人を超えたので、部屋を広げることになった。", "explanation": "ここは〈人数〉の意味。気象は天気などのようすで、人の数は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は気象を詳しく、週末の天気をよく当てる。", "corrected_sentence": "彼女は気象に詳しく、週末の天気をよく当てる。", "error_description": "「詳しい」は「〜に詳しい」と「に」で結ぶ。「気象を詳しく」は助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52356, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "気象が悪化すれ、フェリーは欠航することがある。", "corrected_sentence": "気象が悪化すると、フェリーは欠航することがある。", "error_description": "条件を表す「悪化すると」か「悪化すれば」が必要で、「悪化すれ」は活用が不完全で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「液相から」は起点を表し、液相から固相へ変わるという文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "「液相を固相へ変わる」は、変わるという自動詞に目的語の「を」が続き、文が成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「液相まで固相へと変わる」は限界を表し、変化の起点を示す文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「液相の固相へ変わる」は名詞どうしを結ぶ形で、変化の文として成立しない。"}], "correct_answer": "から", "explanations": {"から": "「液相から」は起点を表し、液相から固相へ変わるという文の流れに合う。", "を": "「液相を固相へ変わる」は、変わるという自動詞に目的語の「を」が続き、文が成り立たない。", "まで": "「液相まで固相へと変わる」は限界を表し、変化の起点を示す文に合わない。", "の": "「液相の固相へ変わる」は名詞どうしを結ぶ形で、変化の文として成立しない。"}, "error_tags": {"から": "起点", "を": "対象", "まで": "限界", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「液相の割合」の「の」は所属を表し、液相の割合が増えたという文として自然。"}, {"text": "が", "is_correct": false, "explanation": "「液相が割合は」と続くと主語が二つ並び、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「液相へ割合は」は方向の「へ」が割合の増加とつながらず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「液相より割合は」は比較の「より」が文に合わず、割合が増える流れにならない。"}], "correct_answer": "の", "explanations": {"の": "「液相の割合」の「の」は所属を表し、液相の割合が増えたという文として自然。", "が": "「液相が割合は」と続くと主語が二つ並び、意味が通らない。", "へ": "「液相へ割合は」は方向の「へ」が割合の増加とつながらず、意味が通らない。", "より": "「液相より割合は」は比較の「より」が文に合わず、割合が増える流れにならない。"}, "error_tags": {"の": "所属", "が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "液体の状態にある相。気相や固相と区別される。", "primary_collocate": null, "pronunciation": "えきそう", "ipa": "ekisoː", "syllable_count": 4, "sentences": [{"text": "ワインという液体媒体において、テロワールは単なる気象・地質学的変数の集合体ではなく、地質学的記憶が液相内に結晶化した記号系として機能する。", "target_word": "液相", "complexity_tier": "T3", "furigana": "ワインという液体[えきたい]媒体[ばいたい]において、テロワールは単[たん]なる気象[きしょう]・地質学的[ちしつがくてき]変数[へんすう]の集合体[しゅうごうたい]ではなく、地質学的[ちしつがくてき]記憶[きおく]が液相[えきそう]内[ない]に結晶化[けっしょうか]した記号系[きごうけい]として機能[きのう]する。", "sentence_source": "mined"}, {"text": "水は温度が下がると、液相から固相へと変わる。", "target_word": "液相", "complexity_tier": "T3", "furigana": "水[みず]は温度[おんど]が下[さ]がると、液相[えきそう]から固相[こそう]へと変[か]わる。", "sentence_source": "generated"}, {"text": "この実験では、気相と液相の間で物質がどう移るかを調べた。", "target_word": "液相", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、気相[きそう]と液相[えきそう]の間[あいだ]で物質[ぶっしつ]がどう移[うつ]るかを調[しら]べた。", "sentence_source": "generated"}, {"text": "混合物を加熱すると、液相の成分が先に蒸発して気相に移る。", "target_word": "液相", "complexity_tier": "T3", "furigana": "混合物[こんごうぶつ]を加熱[かねつ]すると、液相[えきそう]の成分[せいぶん]が先[さき]に蒸発[じょうはつ]して気相[きそう]に移[うつ]る。", "sentence_source": "generated"}, {"text": "液相の温度が百度に達すると、水は沸騰を始める。", "target_word": "液相", "complexity_tier": "T3", "furigana": "液相[えきそう]の温度[おんど]が百度[ひゃくど]に達[たっ]すると、水[みず]は沸騰[ふっとう]を始[はじ]める。", "sentence_source": "generated"}, {"text": "状態図は、圧力と温度によって液相が存在する範囲を示している。", "target_word": "液相", "complexity_tier": "T3", "furigana": "状態図[じょうたいず]は、圧力[あつりょく]と温度[おんど]によって液相[えきそう]が存在[そんざい]する範囲[はんい]を示[しめ]している。", "sentence_source": "generated"}, {"text": "液相では分子が自由に動けるが、固相では位置がほぼ決まっている。", "target_word": "液相", "complexity_tier": "T3", "furigana": "液相[えきそう]では分子[ぶんし]が自由[じゆう]に動[うご]けるが、固相[こそう]では位置[いち]がほぼ決[き]まっている。", "sentence_source": "generated"}, {"text": "氷がすべて溶けるまで、液相の割合は少しずつ増え続けた。", "target_word": "液相", "complexity_tier": "T3", "furigana": "氷[こおり]がすべて溶[と]けるまで、液相[えきそう]の割合[わりあい]は少[すこ]しずつ増[ふ]え続[つづ]けた。", "sentence_source": "generated"}, {"text": "液相の割合が増えるにつれて、合金は柔らかくなった。", "target_word": "液相", "complexity_tier": "T3", "furigana": "液相[えきそう]の割合[わりあい]が増[ふ]えるにつれて、合金[ごうきん]は柔[やわ]らかくなった。", "sentence_source": "generated"}, {"text": "油と水は混ざらず、二つの液相に分かれたままだった。", "target_word": "液相", "complexity_tier": "T3", "furigana": "油[あぶら]と水[みず]は混[ま]ざらず、二[ふた]つの液相[えきそう]に分[わ]かれたままだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "液相", "label": "基本形"}], "register": "technical", "sense_fingerprint": "物質の三態のうち、気相・固相と区別される液体の状態（相）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: テロワール (Zipf 1.81)']::text[], 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "液相", "is_correct": true, "explanation": "「液相内に結晶化」は、記憶が液体の中で固まるという場所を表し、文脈に合う。"}, {"text": "変数", "is_correct": false, "explanation": "「変数内に結晶化した」は意味が通らず、変数は結晶化する場所にならない。"}, {"text": "電流", "is_correct": false, "explanation": "「電流内に結晶化した」は電流を場所とする意味になり、成り立たない。"}, {"text": "分類", "is_correct": false, "explanation": "「分類内に結晶化した」は、分類が結晶化の場になるとは言えず、文の流れに合わない。"}], "explanations": {"液相": "「液相内に結晶化」は、記憶が液体の中で固まるという場所を表し、文脈に合う。", "変数": "「変数内に結晶化した」は意味が通らず、変数は結晶化する場所にならない。", "電流": "「電流内に結晶化した」は電流を場所とする意味になり、成り立たない。", "分類": "「分類内に結晶化した」は、分類が結晶化の場になるとは言えず、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "液相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コップに液相を注いで、そのまま一口飲んだ。", "explanation": "ここは〈液体〉の意味。液相は物質の状態（相）を指す語で、飲み物そのものを指す語ではないので、コップの中身には合わない。"}, {"text": "氷は液相だから、手で握っても形が崩れない。", "explanation": "ここは〈固体〉の意味。液相は液体の状態を指すので、形を保つ固い氷には使えない。"}, {"text": "このテレビは液相の画面が鮮やかだ。", "explanation": "ここは〈液晶〉の意味。液晶は画面に使う材料の名で、液相は物質の三態の一つを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "液相", "is_correct": true, "explanation": "「液相では分子が自由に動ける」は、液体の状態で分子が動きやすいという意味になり、文脈に合う。"}, {"text": "強度", "is_correct": false, "explanation": "「強度では分子が自由に動ける」は、強さは分子が動く場所を表さず、意味が通らない。"}, {"text": "速度", "is_correct": false, "explanation": "「速度では分子が自由に動ける」は、速さは場所を表す語ではないので成り立たない。"}, {"text": "電圧", "is_correct": false, "explanation": "「電圧では分子が自由に動ける」は、電圧が分子の動く場を示さず、文として不自然になる。"}], "explanations": {"液相": "「液相では分子が自由に動ける」は、液体の状態で分子が動きやすいという意味になり、文脈に合う。", "強度": "「強度では分子が自由に動ける」は、強さは分子が動く場所を表さず、意味が通らない。", "速度": "「速度では分子が自由に動ける」は、速さは場所を表す語ではないので成り立たない。", "電圧": "「電圧では分子が自由に動ける」は、電圧が分子の動く場を示さず、文として不自然になる。"}, "sentence_index": 6, "correct_answer": "液相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ペンの先から液相が一粒落ちた。", "explanation": "ここは〈液滴〉の意味。ペン先から落ちる液体の一粒は液滴と言い、液相は物質の状態を指すので合わない。"}, {"text": "この薬は、水に溶けた液相を一滴ずつ量って飲む。", "explanation": "ここは〈溶液〉の意味。溶かした液全体を指すのが溶液で、状態を表す液相とは意味が違うので合わない。"}, {"text": "コップの液相が、口のすぐ下まで上がってきた。", "explanation": "ここは〈液面〉の意味。上がってくるのは液体の表面の高さなので液面と言う。物質の状態を表す液相では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この実験では、液相へ固相へと変わる様子を観察した。", "corrected_sentence": "この実験では、液相から固相へと変わる様子を観察した。", "error_description": "「液相」に続く助詞は起点を示す「から」が正しい。「へ」は到達点を示すので、変化の起点には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52358, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実験では、液相に分子が自由に動く様子を観察した。", "corrected_sentence": "実験では、液相で分子が自由に動く様子を観察した。", "error_description": "動作が行われる場所を表すには「で」が正しい。「に」は到達点や存在の場所を示すため、動く様子の場所としては不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "ここは『聞く』の相手を示す『に』。ソムリエに尋ねる相手を表す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、ソムリエは『聞く』の目的語にならないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すが、ソムリエを聞く主語にすると文の意味が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞を修飾するが、ここではソムリエを修飾する語がなく文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "ここは『聞く』の相手を示す『に』。ソムリエに尋ねる相手を表す。", "を": "『を』は目的語を示すが、ソムリエは『聞く』の目的語にならないので合わない。", "が": "『が』は主語を示すが、ソムリエを聞く主語にすると文の意味が崩れる。", "の": "『の』は名詞を修飾するが、ここではソムリエを修飾する語がなく文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "ここは存在を示す『いる』の主語を示す『が』。親切なソムリエが店にいることを表す。"}, {"text": "に", "is_correct": false, "explanation": "『に』は存在の場所を示すが、ソムリエは場所ではないので『いる』と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すが、『いる』には合わず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すが、『いる』の主語を示す役にはならない。"}], "correct_answer": "が", "explanations": {"が": "ここは存在を示す『いる』の主語を示す『が』。親切なソムリエが店にいることを表す。", "に": "『に』は存在の場所を示すが、ソムリエは場所ではないので『いる』と結びつかない。", "へ": "『へ』は方向を示すが、『いる』には合わず文が成り立たない。", "から": "『から』は起点を示すが、『いる』の主語を示す役にはならない。"}, "error_tags": {"に": "存在場所", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ワインの専門家で、おいしいワインをえらぶお手伝いをする人。", "primary_collocate": null, "pronunciation": "そむりえ", "ipa": "somɯɾie", "syllable_count": 4, "sentences": [{"text": "ソムリエは、ワインにくわしい人です。", "target_word": "ソムリエ", "complexity_tier": "T2", "furigana": "ソムリエは、ワインにくわしい人[ひと]です。", "sentence_source": "generated"}, {"text": "私はソムリエに、おいしい白ワインのおすすめを聞きました。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "私(わたし)はソムリエに、おいしい白(しろ)ワインのおすすめを聞(き)きました。", "sentence_source": "generated"}, {"text": "姉はソムリエになるために、毎日ワインの勉強をしている。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "姉[あね]はソムリエになるために、毎日[まいにち]ワインの勉強[べんきょう]をしている。", "sentence_source": "generated"}, {"text": "ワインの種類が多すぎて選べなかったので、ソムリエに助けてもらった。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "ワインの種類[しゅるい]が多[おお]すぎて選[えら]べなかったので、ソムリエに助[たす]けてもらった。", "sentence_source": "generated"}, {"text": "あのソムリエは、お客さんの好みを聞いてからワインを選んでくれる。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "あのソムリエは、お客[きゃく]さんの好[この]みを聞[き]いてからワインを選[えら]んでくれる。", "sentence_source": "generated"}, {"text": "祖父の誕生日に、ソムリエがすすめた赤ワインを買った。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "祖父[そふ]の誕生日[たんじょうび]に、ソムリエがすすめた赤[あか]ワインを買[か]った。", "sentence_source": "generated"}, {"text": "ソムリエに勧められると、ワインがもっと楽しくなる。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "ソムリエに勧[すす]められると、ワインがもっと楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "駅の近くのイタリア料理店には、親切なソムリエがいる。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くのイタリア料理店[りょうりてん]には、親切[しんせつ]なソムリエがいる。", "sentence_source": "generated"}, {"text": "初めてのワインバーで、ソムリエが飲みやすい一杯を選んでくれた。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "初[はじ]めてのワインバーで、ソムリエが飲[の]みやすい一杯[いっぱい]を選[えら]んでくれた。", "sentence_source": "generated"}, {"text": "ソムリエを目指す学生が、ワインの名前を毎晩覚えている。", "target_word": "ソムリエ", "complexity_tier": "T4", "furigana": "ソムリエを目指[めざ]す学生[がくせい]が、ワインの名前[なまえ]を毎晩[まいばん]覚[おぼ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ソムリエ", "label": "基本形"}, {"form": "ソムリエたち", "label": "複数"}], "register": "標準", "sense_fingerprint": "ワインにくわしく、客のワイン選びを手伝う人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ソムリエ", "is_correct": true, "explanation": "ここは『ワインにくわしい人』を指す主語。その説明に当たるのは専門家のソムリエ。"}, {"text": "ブドウ", "is_correct": false, "explanation": "ブドウは果物で、ワインにくわしい人ではない。"}, {"text": "栓抜き", "is_correct": false, "explanation": "栓抜きは道具で、人ではないので主語にならない。"}, {"text": "ボトル", "is_correct": false, "explanation": "ボトルは容器で、ワインにくわしい人にはならない。"}], "explanations": {"ソムリエ": "ここは『ワインにくわしい人』を指す主語。その説明に当たるのは専門家のソムリエ。", "ブドウ": "ブドウは果物で、ワインにくわしい人ではない。", "栓抜き": "栓抜きは道具で、人ではないので主語にならない。", "ボトル": "ボトルは容器で、ワインにくわしい人にはならない。"}, "sentence_index": 0, "correct_answer": "ソムリエ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この蔵のソムリエは、ブドウを何年も寝かせて、香りの強い赤ワインを造った。", "explanation": "ここは〈醸造家〉の意味。ソムリエはワインを造るのではなく、選ぶ助言をする人なので合わない。"}, {"text": "ソムリエは毎朝、店の床を掃除してから、商品の棚を並べ直す。", "explanation": "ここは〈店員〉の意味。ソムリエは売り場の作業ではなく、ワインを選ぶ助言をする専門家なので合わない。"}, {"text": "この絵のソムリエは、筆づかいを見て本物かどうかを判定した。", "explanation": "ここは〈鑑定士〉の意味。ソムリエはワインの助言をする人で、絵の真贋は判定しないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ソムリエ", "is_correct": true, "explanation": "ここは『〜に勧められる』の勧める主体。ワインを勧める専門家はソムリエ。"}, {"text": "ラベル", "is_correct": false, "explanation": "ラベルは瓶に貼る紙で、人に勧める主体にはならない。"}, {"text": "グラス", "is_correct": false, "explanation": "グラスは器で、人に勧める主体にはならない。"}, {"text": "コルク", "is_correct": false, "explanation": "コルクは栓で、人に勧める主体にはならない。"}], "explanations": {"ソムリエ": "ここは『〜に勧められる』の勧める主体。ワインを勧める専門家はソムリエ。", "ラベル": "ラベルは瓶に貼る紙で、人に勧める主体にはならない。", "グラス": "グラスは器で、人に勧める主体にはならない。", "コルク": "コルクは栓で、人に勧める主体にはならない。"}, "sentence_index": 6, "correct_answer": "ソムリエ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブドウ農家のソムリエは、畑の土を毎朝確かめて、水やりの量を決めた。", "explanation": "ここは〈栽培者〉の意味。ソムリエはブドウを育てる人ではなく、ワインを選ぶ助言をするので合わない。"}, {"text": "ソムリエは厨房で、魚を三枚におろして、すぐ皿に盛りつけた。", "explanation": "ここは〈料理人〉の意味。ソムリエは料理を作らず、料理に合うワインを勧める人なので合わない。"}, {"text": "ソムリエは燃え盛る建物に入って、逃げ遅れた住人を救助した。", "explanation": "ここは〈消防士〉の意味。ソムリエはワインの助言をする専門家で、救助はしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は、ソムリエを相談して、家族の誕生日に合うワインを選んでもらった。", "corrected_sentence": "父は、ソムリエに相談して、家族の誕生日に合うワインを選んでもらった。", "error_description": "助詞の誤り：『相談する』は相手を『に』で示すため、『ソムリエを』は誤り。正しくは『ソムリエに相談して』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52359, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、ソムリエが勧めて白ワインを毎月取り寄せている。", "corrected_sentence": "祖母は、ソムリエが勧めた白ワインを毎月取り寄せている。", "error_description": "活用形の誤り：『勧めた』は名詞『白ワイン』を修飾する連体形が必要なのに、連用形『勧めて』を使った。正しくは『ソムリエが勧めた白ワイン』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ここは主題の『は』。ソムリエを話題にして、その人が行った行為を述べる。"}, {"text": "を", "is_correct": false, "explanation": "『すすめる』の目的語は『赤ワイン』で、ソムリエに『を』を付けると文の役割が合わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すが、ソムリエは手段ではないので文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や共同の相手を示すが、ここには並べる相手がなく、文の主題も示されない。"}], "correct_answer": "は", "explanations": {"は": "ここは主題の『は』。ソムリエを話題にして、その人が行った行為を述べる。", "を": "『すすめる』の目的語は『赤ワイン』で、ソムリエに『を』を付けると文の役割が合わない。", "で": "『で』は手段や場所を示すが、ソムリエは手段ではないので文が成り立たない。", "と": "『と』は並列や共同の相手を示すが、ここには並べる相手がなく、文の主題も示されない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "ここは『合わせて、出した』の主語を示す『が』。ソムリエが行った行為を表す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、ソムリエは出す対象ではなく、目的語が二つになって文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すが、ここでは起点を表す語がなく、主語の役割が合わない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞を修飾するため、ソムリエの後に続けると文の述語と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "ここは『合わせて、出した』の主語を示す『が』。ソムリエが行った行為を表す。", "を": "『を』は目的語を示すが、ソムリエは出す対象ではなく、目的語が二つになって文が成り立たない。", "から": "『から』は起点を示すが、ここでは起点を表す語がなく、主語の役割が合わない。", "の": "『の』は名詞を修飾するため、ソムリエの後に続けると文の述語と結びつかない。"}, "error_tags": {"を": "目的語", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "レストランなどで、ワインの選び方や料理との組み合わせについて助言する専門家。", "primary_collocate": null, "pronunciation": "そむりえ", "ipa": "somɯɾie", "syllable_count": 4, "sentences": [{"text": "熟練したソムリエは、香りだけで料理との相性を言い当てる。", "target_word": "ソムリエ", "complexity_tier": "T5", "furigana": "熟練[じゅくれん]したソムリエは、香[かお]りだけで料理[りょうり]との相性[あいしょう]を言[い]い当[あ]てる。", "sentence_source": "generated"}, {"text": "このレストランのソムリエは、肉料理に合う赤ワインを三本すすめてくれた。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "このレストランのソムリエは、肉料理[にくりょうり]に合[あ]う赤[あか]ワインを三本[さんぼん]すすめてくれた。", "sentence_source": "generated"}, {"text": "料理が魚なので、ソムリエに相談して軽い白ワインを選んだ。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "料理[りょうり]が魚[さかな]なので、ソムリエに相談[そうだん]して軽[かる]い白[しろ]ワインを選[えら]んだ。", "sentence_source": "generated"}, {"text": "ソムリエの説明が丁寧で、初めてでも安心してワインを注文できた。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "ソムリエの説明[せつめい]が丁寧[ていねい]で、初[はじ]めてでも安心[あんしん]してワインを注文[ちゅうもん]できた。", "sentence_source": "generated"}, {"text": "彼は十年間ホテルで働いたあと、ソムリエの資格を取った。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "彼[かれ]は十年間[じゅうねんかん]ホテルで働[はたら]いたあと、ソムリエの資格[しかく]を取[と]った。", "sentence_source": "generated"}, {"text": "予算を伝えると、ソムリエは値段のわりに味のよい一本を教えてくれた。", "target_word": "ソムリエ", "complexity_tier": "T4", "furigana": "予算[よさん]を伝[つた]えると、ソムリエは値段[ねだん]のわりに味[あじ]のよい一本[いっぽん]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "ソムリエはチーズの塩気を考えて、少し甘めのワインを提案した。", "target_word": "ソムリエ", "complexity_tier": "T4", "furigana": "ソムリエはチーズの塩気[しおけ]を考[かんが]えて、少[すこ]し甘[あま]めのワインを提案[ていあん]した。", "sentence_source": "generated"}, {"text": "店のソムリエがコース料理に合わせて、一皿ごとに違うワインを出した。", "target_word": "ソムリエ", "complexity_tier": "T4", "furigana": "店[みせ]のソムリエがコース料理[りょうり]に合[あ]わせて、一皿[ひとさら]ごとに違[ちが]うワインを出[だ]した。", "sentence_source": "generated"}, {"text": "ワインに詳しくないので、メニューを見る前にソムリエへ質問した。", "target_word": "ソムリエ", "complexity_tier": "T3", "furigana": "ワインに詳[くわ]しくないので、メニューを見[み]る前[まえ]にソムリエへ質問[しつもん]した。", "sentence_source": "generated"}, {"text": "有名なソムリエの助言を聞いてから、客は注文を変えた。", "target_word": "ソムリエ", "complexity_tier": "T4", "furigana": "有名[ゆうめい]なソムリエの助言[じょげん]を聞[き]いてから、客[きゃく]は注文[ちゅうもん]を変[か]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ソムリエ", "label": "基本形"}, {"form": "ソムリエたち", "label": "複数"}], "register": "標準", "sense_fingerprint": "レストランでワイン選びや料理との相性を助言する専門職", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ソムリエ", "is_correct": true, "explanation": "ここは香りから料理との相性を言い当てる主語。その主体になれるのは人のソムリエだけ。"}, {"text": "ワイン", "is_correct": false, "explanation": "ワインは選ばれる対象で、相性を言い当てる主語にはならない。"}, {"text": "コルク", "is_correct": false, "explanation": "コルクは瓶の栓で、相性を言い当てる主体にはならない。"}, {"text": "ラベル", "is_correct": false, "explanation": "ラベルは情報を示す紙で、相性を言い当てる主語にはならない。"}], "explanations": {"ソムリエ": "ここは香りから料理との相性を言い当てる主語。その主体になれるのは人のソムリエだけ。", "ワイン": "ワインは選ばれる対象で、相性を言い当てる主語にはならない。", "コルク": "コルクは瓶の栓で、相性を言い当てる主体にはならない。", "ラベル": "ラベルは情報を示す紙で、相性を言い当てる主語にはならない。"}, "sentence_index": 0, "correct_answer": "ソムリエ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あのバーのソムリエは、注文を受けてカクテルを混ぜてくれた。", "explanation": "ここは〈バーテンダー〉の意味。ソムリエはワインの助言をする人で、カクテルを混ぜる役ではないので合わない。"}, {"text": "この店のソムリエは、肉を焼く温度を細かく確かめて、ステーキを仕上げた。", "explanation": "ここは〈料理人〉の意味。ソムリエは料理を作らず、料理に合うワインを選ぶ助言をするので合わない。"}, {"text": "ソムリエは熱い皿を両手で席まで運び、テーブルに並べてくれた。", "explanation": "ここは〈給仕〉の意味。ソムリエは料理を運ぶ係ではなく、ワインを選ぶ助言をするので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ソムリエ", "is_correct": true, "explanation": "ここは塩気を考えて提案する主語。提案する主体は人のソムリエ。"}, {"text": "グラス", "is_correct": false, "explanation": "グラスは器で、塩気を考えて提案する主体にはならない。"}, {"text": "ボトル", "is_correct": false, "explanation": "ボトルは容器で、料理を考えてワインを提案することはない。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房は場所で、提案の主語にはならない。"}], "explanations": {"ソムリエ": "ここは塩気を考えて提案する主語。提案する主体は人のソムリエ。", "グラス": "グラスは器で、塩気を考えて提案する主体にはならない。", "ボトル": "ボトルは容器で、料理を考えてワインを提案することはない。", "厨房": "厨房は場所で、提案の主語にはならない。"}, "sentence_index": 6, "correct_answer": "ソムリエ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この蔵のソムリエは、樽の中で赤ワインを何年も熟成させた。", "explanation": "ここは〈醸造家〉の意味。ソムリエはワインを造る人ではなく、選び方を助言する人なので合わない。"}, {"text": "この店のソムリエは、毎月の売上を計算して、スタッフのシフトを決めた。", "explanation": "ここは〈店長〉の意味。ソムリエは店の運営を担当せず、ワインの助言をするので合わない。"}, {"text": "ソムリエは工場の機械を点検して、不良品を見つけた。", "explanation": "ここは〈検査員〉の意味。ソムリエはワインの助言をする専門家で、機械の点検はしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、ソムリエを勧められた甘口のワインを気に入った。", "corrected_sentence": "祖母は、ソムリエに勧められた甘口のワインを気に入った。", "error_description": "助詞の誤り：『勧める』は勧める相手を『に』で示すため、『ソムリエを』は誤り。正しくは『ソムリエに勧められた』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52360, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ソムリエを目指し友人が、毎週末に試飲会へ通っている。", "corrected_sentence": "ソムリエを目指す友人が、毎週末に試飲会へ通っている。", "error_description": "活用形の誤り：『目指す』は名詞『友人』を修飾する連体形が必要なのに、連用形『目指し』を使った。正しくは『ソムリエを目指す友人』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「鉱物は〜ものだ」と主題を示し、文の骨格になる。"}, {"text": "を", "is_correct": false, "explanation": "「とれる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "「鉱物に〜ものだ」は主題にならず、不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "「鉱物から〜」は起点となり、文の骨格が崩れる。"}], "correct_answer": "は", "explanations": {"は": "「鉱物は〜ものだ」と主題を示し、文の骨格になる。", "を": "「とれる」は自動詞なので、目的語の「を」は取れない。", "に": "「鉱物に〜ものだ」は主題にならず、不自然になる。", "から": "「鉱物から〜」は起点となり、文の骨格が崩れる。"}, "error_tags": {"を": "対格（自動詞と不一致）", "に": "位置（主題と不一致）", "から": "起点（骨格が崩れる）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「鉱物を、布でふいた」で、ふく動作の目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「鉱物が布でふいた」では鉱物がふく主体になり、意味が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「鉱物で布でふく」は手段の「で」と重なり、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「鉱物へ布でふく」は方向として成立せず、動作の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「鉱物を、布でふいた」で、ふく動作の目的語になる。", "が": "「鉱物が布でふいた」では鉱物がふく主体になり、意味が崩れる。", "で": "「鉱物で布でふく」は手段の「で」と重なり、不自然になる。", "へ": "「鉱物へ布でふく」は方向として成立せず、動作の対象にならない。"}, "error_tags": {"が": "主格（動作主と不一致）", "で": "手段（重複で不自然）", "へ": "方向（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面からとれる石のようなものです。", "primary_collocate": null, "pronunciation": "こうぶつ", "ipa": "koːbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "山で鉱物を集めて、家の棚にならべている。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "山[やま]で鉱物[こうぶつ]を集[あつ]めて、家[いえ]の棚[たな]にならべている。", "sentence_source": "generated"}, {"text": "鉱物は地面の下からとれる、石のようなものだ。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "鉱物[こうぶつ]は地面[じめん]の下[した]からとれる、石[いし]のようなものだ。", "sentence_source": "generated"}, {"text": "弟は光る鉱物が好きで、石の図鑑をよく読んでいる。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "弟[おとうと]は光[ひか]る鉱物[こうぶつ]が好[す]きで、石[いし]の図鑑[ずかん]をよく読[よ]んでいる。", "sentence_source": "generated"}, {"text": "この町は昔、鉱物がたくさんとれたので有名だった。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "この町[まち]は昔[むかし]、鉱物[こうぶつ]がたくさんとれたので有名[ゆうめい]だった。", "sentence_source": "generated"}, {"text": "川の近くで、きれいな色の鉱物を見つけた。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くで、きれいな色[いろ]の鉱物[こうぶつ]を見[み]つけた。", "sentence_source": "generated"}, {"text": "鉱物は水に入れても、野菜のようには育たない。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "鉱物[こうぶつ]は水[みず]に入[い]れても、野菜[やさい]のようには育[そだ]たない。", "sentence_source": "generated"}, {"text": "先生は、黒い鉱物を机の上に置いて見せてくれた。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "先生[せんせい]は、黒[くろ]い鉱物[こうぶつ]を机[つくえ]の上[うえ]に置[お]いて見[み]せてくれた。", "sentence_source": "generated"}, {"text": "買ったばかりの鉱物を、やわらかい布でそっとふいた。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "買[か]ったばかりの鉱物[こうぶつ]を、やわらかい布[ぬの]でそっとふいた。", "sentence_source": "generated"}, {"text": "博物館では、めずらしい鉱物をガラスの箱の中で見られる。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、めずらしい鉱物[こうぶつ]をガラスの箱[はこ]の中[なか]で見[み]られる。", "sentence_source": "generated"}, {"text": "鉱物の名前を覚えるために、毎日カードを見ている。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "鉱物[こうぶつ]の名前[なまえ]を覚[おぼ]えるために、毎日[まいにち]カードを見[み]ている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鉱物", "label": "基本形"}], "register": "中立（やさしい話し言葉）", "sense_fingerprint": "地面からとれる、石のようなもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉱物", "is_correct": true, "explanation": "山で集めて棚に並べるのは鉱物の標本として自然に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "山で砂糖を集めて棚に並べる状況は不自然で、文脈に合わない。"}, {"text": "電池", "is_correct": false, "explanation": "山で電池を集める状況は成立せず、この文と合わない。"}, {"text": "豆腐", "is_correct": false, "explanation": "山で豆腐を集めて並べるのは成立しない。"}], "explanations": {"鉱物": "山で集めて棚に並べるのは鉱物の標本として自然に合う。", "砂糖": "山で砂糖を集めて棚に並べる状況は不自然で、文脈に合わない。", "電池": "山で電池を集める状況は成立せず、この文と合わない。", "豆腐": "山で豆腐を集めて並べるのは成立しない。"}, "sentence_index": 0, "correct_answer": "鉱物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このフライパンは、軽くて丈夫な鉱物で作られている。", "explanation": "ここは〈金属〉の意味。フライパンの材料は金属と言うのが普通で、鉱物は地中から採れた天然の固体を指すので合わない。"}, {"text": "この鉱物の町では、昔から大勢の人が働いていた。", "explanation": "ここは〈鉱山〉の意味。働く場所や町の名として言うのは鉱山で、鉱物は石の種類なので合わない。"}, {"text": "この町の山では、昔の生き物の鉱物が見つかった。", "explanation": "ここは〈化石〉の意味。生き物の跡は化石であって鉱物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉱物", "is_correct": true, "explanation": "黒い鉱物を机に置いて見せるという文脈に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は机に置いて見せられるものではなく、この文と合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は机に置けないので、「置いて見せる」の文脈に合わない。"}, {"text": "電波", "is_correct": false, "explanation": "電波は目に見える物ではなく、机に置いて見せることができない。"}], "explanations": {"鉱物": "黒い鉱物を机に置いて見せるという文脈に合う。", "音楽": "音楽は机に置いて見せられるものではなく、この文と合わない。", "天気": "天気は机に置けないので、「置いて見せる」の文脈に合わない。", "電波": "電波は目に見える物ではなく、机に置いて見せることができない。"}, "sentence_index": 6, "correct_answer": "鉱物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この指輪は、小さくてきれいな鉱物で飾られている。", "explanation": "ここは〈宝石〉の意味。指輪に飾るのは宝石で、鉱物は地面からとれた石のようなものを指すので合わない。"}, {"text": "冬の夜は、鉱物をストーブにくべて部屋を暖めた。", "explanation": "ここは〈石炭〉の意味。ストーブにくべるのは石炭で、鉱物とは言わないので合わない。"}, {"text": "ケーキの上に、砂糖の鉱物がきれいにのっていた。", "explanation": "ここは〈結晶〉の意味。ケーキにのる砂糖の粒は結晶で、鉱物とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海辺で、きれいな色の鉱物に見つけた。", "corrected_sentence": "海辺で、きれいな色の鉱物を見つけた。", "error_description": "「見つける」は他動詞なので目的語は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52363, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭で、赤い鉱物が見つけて父に見せた。", "corrected_sentence": "庭で、赤い鉱物を見つけて父に見せた。", "error_description": "「見つける」の目的語は「を」で示す。「が」を使うと鉱物が主語になり、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鉱物が展示されている」で、展示される物が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「展示されている」は受身なので、「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "「鉱物に展示されている」は述語と結びつかず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「鉱物から展示されている」は起点として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「鉱物が展示されている」で、展示される物が主語になる。", "を": "「展示されている」は受身なので、「を」は取れない。", "に": "「鉱物に展示されている」は述語と結びつかず、意味が通らない。", "から": "「鉱物から展示されている」は起点として意味が通らない。"}, "error_tags": {"を": "対格（受身と不一致）", "に": "位置（述語と不一致）", "から": "起点（意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「鉱物の収集」と名詞を続ける連体修飾の「の」。"}, {"text": "で", "is_correct": false, "explanation": "「鉱物で収集が趣味」は手段の意味になり、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「鉱物へ収集」は方向として成立せず、名詞と結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "「鉱物より収集」は比較の意味になり、この文の意味に合わない。"}], "correct_answer": "の", "explanations": {"の": "「鉱物の収集」と名詞を続ける連体修飾の「の」。", "で": "「鉱物で収集が趣味」は手段の意味になり、文が崩れる。", "へ": "「鉱物へ収集」は方向として成立せず、名詞と結びつかない。", "より": "「鉱物より収集」は比較の意味になり、この文の意味に合わない。"}, "error_tags": {"で": "手段（意味が通らない）", "へ": "方向（名詞と不一致）", "より": "比較（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地中や地表から採れる、無機質で天然の固体。多くの場合、結晶構造を持つ。", "primary_collocate": null, "pronunciation": "こうぶつ", "ipa": "koːbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "砂を水で洗うと、重い鉱物の粒が底にたまる。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "砂[すな]を水[みず]で洗[あら]うと、重[おも]い鉱物[こうぶつ]の粒[つぶ]が底[そこ]にたまる。", "sentence_source": "generated"}, {"text": "この博物館には、世界各地で採れた鉱物が展示されている。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]には、世界各地[せかいかくち]で採[と]れた鉱物[こうぶつ]が展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "水晶は代表的な鉱物で、きれいな結晶の形をしている。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "水晶[すいしょう]は代表的[だいひょうてき]な鉱物[こうぶつ]で、きれいな結晶[けっしょう]の形[かたち]をしている。", "sentence_source": "generated"}, {"text": "鉱物は生き物ではないので、成長の仕方が植物とはまったく違う。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "鉱物[こうぶつ]は生[い]き物[もの]ではないので、成長[せいちょう]の仕方[しかた]が植物[しょくぶつ]とはまったく違[ちが]う。", "sentence_source": "generated"}, {"text": "理科の授業で、いろいろな鉱物の硬さを比べる実験をした。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、いろいろな鉱物[こうぶつ]の硬[かた]さを比[くら]べる実験[じっけん]をした。", "sentence_source": "generated"}, {"text": "この山地は鉱物が豊富なため、昔から採掘がさかんだった。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "この山地[さんち]は鉱物[こうぶつ]が豊富[ほうふ]なため、昔[むかし]から採掘[さいくつ]がさかんだった。", "sentence_source": "generated"}, {"text": "岩石は、複数の鉱物が集まってできている。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "岩石[がんせき]は、複数[ふくすう]の鉱物[こうぶつ]が集[あつ]まってできている。", "sentence_source": "generated"}, {"text": "兄は鉱物の収集が趣味で、週末はよく石を探しに川へ出かける。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "兄[あに]は鉱物[こうぶつ]の収集[しゅうしゅう]が趣味[しゅみ]で、週末[しゅうまつ]はよく石[いし]を探[さが]しに川[かわ]へ出[で]かける。", "sentence_source": "generated"}, {"text": "地質学者は、顕微鏡で鉱物の結晶構造を詳しく調べた。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "地質学者[ちしつがくしゃ]は、顕微鏡[けんびきょう]で鉱物[こうぶつ]の結晶構造[けっしょうこうぞう]を詳[くわ]しく調[しら]べた。", "sentence_source": "generated"}, {"text": "温泉水に溶け込んだ鉱物が、湯の色を白く濁らせている。", "target_word": "鉱物", "complexity_tier": "T3", "furigana": "温泉水[おんせんすい]に溶[と]け込[こ]んだ鉱物[こうぶつ]が、湯[ゆ]の色[いろ]を白[しろ]く濁[にご]らせている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鉱物", "label": "基本形"}, {"form": "鉱物的", "label": "派生形（〜的）"}], "register": "中立（やや書き言葉・科学的）", "sense_fingerprint": "科学的な意味での、天然の無機質な結晶性の固体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉱物", "is_correct": true, "explanation": "重い鉱物の粒は水の中で沈み、底にたまるので文に合う。"}, {"text": "機械", "is_correct": false, "explanation": "重い機械の粒という言い方は成立せず、この文と合わない。"}, {"text": "電池", "is_correct": false, "explanation": "重い電池の粒は成立せず、底にたまる文脈にも合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽には粒がなく、水で洗って底にたまる文と合わない。"}], "explanations": {"鉱物": "重い鉱物の粒は水の中で沈み、底にたまるので文に合う。", "機械": "重い機械の粒という言い方は成立せず、この文と合わない。", "電池": "重い電池の粒は成立せず、底にたまる文脈にも合わない。", "音楽": "音楽には粒がなく、水で洗って底にたまる文と合わない。"}, "sentence_index": 0, "correct_answer": "鉱物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鍋は、軽くて丈夫な鉱物でできている。", "explanation": "ここは〈金属〉の意味。鍋などの材料は金属と言うのが普通で、鉱物は地中から採れた天然の固体を指すので合わない。"}, {"text": "この鉱物では、昔から銅がたくさん採れていた。", "explanation": "ここは〈鉱山〉の意味。採掘地を「〜では」で言うのは鉱山で、鉱物は石の種類を表すので場所には使わない。"}, {"text": "ビンの底には、砂糖の鉱物がきれいに並んでいた。", "explanation": "ここは〈結晶〉の意味。砂糖の粒は結晶と呼び、鉱物は無機質の天然の固体なので、砂糖には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉱物", "is_correct": true, "explanation": "「複数の鉱物が集まって」岩石を作るという文脈に合う。"}, {"text": "生物", "is_correct": false, "explanation": "岩石は生物が集まってできるものではないので、この文と矛盾する。"}, {"text": "植物", "is_correct": false, "explanation": "岩石は植物が集まってできるものではないので、この文に合わない。"}, {"text": "細胞", "is_correct": false, "explanation": "岩石は細胞でできていないので、「集まってできている」と合わない。"}], "explanations": {"鉱物": "「複数の鉱物が集まって」岩石を作るという文脈に合う。", "生物": "岩石は生物が集まってできるものではないので、この文と矛盾する。", "植物": "岩石は植物が集まってできるものではないので、この文に合わない。", "細胞": "岩石は細胞でできていないので、「集まってできている」と合わない。"}, "sentence_index": 6, "correct_answer": "鉱物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "指輪の鉱物がきらきらと光っていた。", "explanation": "ここは〈宝石〉の意味。指輪に飾る磨いた石は宝石と言い、鉱物は採れたままの天然の固体を指すので合わない。"}, {"text": "冬は、鉱物をストーブにくべて部屋を暖めた。", "explanation": "ここは〈石炭〉の意味。燃料として燃やすのは石炭で、鉱物とは言わないので合わない。"}, {"text": "この地層からは、恐竜の鉱物が見つかった。", "explanation": "ここは〈化石〉の意味。恐竜の遺骸は鉱物ではなく化石なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究所では、新しく見つかった鉱物が分析している。", "corrected_sentence": "この研究所では、新しく見つかった鉱物を分析している。", "error_description": "「分析する」は他動詞なので、目的語を「を」で示す。ここで「が」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52364, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このトンネルでは、大量の鉱物に採掘されてきた。", "corrected_sentence": "このトンネルでは、大量の鉱物が採掘されてきた。", "error_description": "「採掘される」の対象は主語「が」で示す。「に」は動作主のように読まれ、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「結晶ができる」の「が」は、できたものを主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「結晶をできる」は目的語では成り立たず、「できる」と結べないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、結晶ができる先を示さないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「結晶とできる」は並列や引用の意味になり、文として成り立たないので合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「結晶ができる」の「が」は、できたものを主語として示す。", "を": "「結晶をできる」は目的語では成り立たず、「できる」と結べないので合わない。", "へ": "方向の「へ」は、結晶ができる先を示さないので合わない。", "と": "「結晶とできる」は並列や引用の意味になり、文として成り立たないので合わない。"}, "error_tags": {"を": "目的格（できるに不適合）", "へ": "方向格", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かたくて、きれいな形をした小さな石のようなものです。", "primary_collocate": null, "pronunciation": "けっしょう", "ipa": "kessʲoː", "syllable_count": 4, "sentences": [{"text": "雪の結晶を虫めがねで見ると、きれいな形をしている。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "雪[ゆき]の結晶[けっしょう]を虫[むし]めがねで見[み]ると、きれいな形[かたち]をしている。", "sentence_source": "generated"}, {"text": "塩を水にとかして置くと、小さな結晶ができる。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "塩[しお]を水[みず]にとかして置[お]くと、小[ちい]さな結晶[けっしょう]ができる。", "sentence_source": "generated"}, {"text": "砂糖の結晶が、容器の底にたくさん付いていた。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "砂糖[さとう]の結晶[けっしょう]が、容器[ようき]の底[そこ]にたくさん付[つ]いていた。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、結晶は角ばった形をしている。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で見[み]ると、結晶[けっしょう]は角[かど]ばった形[かたち]をしている。", "sentence_source": "generated"}, {"text": "理科の実験で、ミョウバンの結晶を作った。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "理科[りか]の実験[じっけん]で、ミョウバンの結晶[けっしょう]を作[つく]った。", "sentence_source": "generated"}, {"text": "洞窟の壁には、白く光る結晶が並んでいた。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の壁[かべ]には、白[しろ]く光[ひか]る結晶[けっしょう]が並[なら]んでいた。", "sentence_source": "generated"}, {"text": "この結晶は硬いので、手で割ることはできない。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "この結晶[けっしょう]は硬[かた]いので、手[て]で割[わ]ることはできない。", "sentence_source": "generated"}, {"text": "水が冷えて、窓ガラスに氷の結晶ができた。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "水[みず]が冷[ひ]えて、窓[まど]ガラスに氷[こおり]の結晶[けっしょう]ができた。", "sentence_source": "generated"}, {"text": "宝石も、もとは地面の中でできた結晶だ。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "宝石[ほうせき]も、もとは地面[じめん]の中[なか]でできた結晶[けっしょう]だ。", "sentence_source": "generated"}, {"text": "ゆっくり冷やすほど、結晶は大きく育つ。", "target_word": "結晶", "complexity_tier": "T3", "furigana": "ゆっくり冷[ひ]やすほど、結晶[けっしょう]は大[おお]きく育[そだ]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結晶", "label": "基本形"}], "register": "中立", "sense_fingerprint": "規則正しい形をした小さくて硬い固体、クリスタル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 虫めがね (Zipf 1.44)']::text[], '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結晶", "is_correct": true, "explanation": "正解。雪の小さな固体で、虫めがねで見ると形がきれいに見える「結晶」が合う。"}, {"text": "溶液", "is_correct": false, "explanation": "「雪の溶液」は成り立たず、虫めがねで見る形の話とも合わない。"}, {"text": "洗剤", "is_correct": false, "explanation": "「雪の洗剤」は意味をなさず、形を見る文脈に合わない。"}, {"text": "布", "is_correct": false, "explanation": "「雪の布」は成り立たず、雪の形を見る文脈に合わない。"}], "explanations": {"結晶": "正解。雪の小さな固体で、虫めがねで見ると形がきれいに見える「結晶」が合う。", "溶液": "「雪の溶液」は成り立たず、虫めがねで見る形の話とも合わない。", "洗剤": "「雪の洗剤」は意味をなさず、形を見る文脈に合わない。", "布": "「雪の布」は成り立たず、雪の形を見る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "結晶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この結晶は指で形を変えられるほど柔らかく、子どもの工作に使える。", "explanation": "指で形を変えられるほど柔らかいことは、規則正しく並んだかたい固体の結晶とは合わない。"}, {"text": "この結晶は細胞の集まりでできていて、とても柔らかい。", "explanation": "細胞が集まってできた生体組織は、規則正しく並んだ固体の結晶とは別物なので合わない。"}, {"text": "彼女の結晶は、頬をつたって静かに落ちた。", "explanation": "頬をつたって静かに落ちることは、固くて規則正しく並んだ結晶の性質に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結晶", "is_correct": true, "explanation": "正解。硬くて手で割れないという性質を持つ、固体の「結晶」が合う。"}, {"text": "溶液", "is_correct": false, "explanation": "溶液は液体で硬くないため、「硬いので割れない」とは結びつかない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は気体で、硬さも固体の性質もないので合わない。"}, {"text": "綿", "is_correct": false, "explanation": "綿は柔らかい繊維で、硬いという前提に合わない。"}], "explanations": {"結晶": "正解。硬くて手で割れないという性質を持つ、固体の「結晶」が合う。", "溶液": "溶液は液体で硬くないため、「硬いので割れない」とは結びつかない。", "煙": "煙は気体で、硬さも固体の性質もないので合わない。", "綿": "綿は柔らかい繊維で、硬いという前提に合わない。"}, "sentence_index": 6, "correct_answer": "結晶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この結晶は、ふわふわに焼けていて口当たりがいい。", "explanation": "焼いてふわふわにする菓子は、固い固体の結晶とは結びつかないので合わない。"}, {"text": "この結晶は細い糸を編んで作られていて、やわらかい。", "explanation": "細い糸を編んで作るものは、規則正しく並んだ固体の結晶とは別物なので合わない。"}, {"text": "この結晶は、じっくり煮込むと味がよく染みる。", "explanation": "煮込んで味がしみる料理は、味を含む固体の結晶とは結びつかないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "塩の結晶を、水の中で規則正しく並んでいる。", "corrected_sentence": "塩の結晶が、水の中で規則正しく並んでいる。", "error_description": "「並ぶ」は自動詞で、主語を「が」で示す。「を」は誤りで、正しくは「結晶が並んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52365, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝、窓に氷の結晶がつけていた。", "corrected_sentence": "寒い朝、窓に氷の結晶がついていた。", "error_description": "「つく」は自動詞で「結晶がついていた」と言う。「つける」は他動詞で、この文では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ものの輪郭」と名詞を続ける連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「ものを輪郭しか見えなかった」は目的語にならず、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「ものに輪郭しか見えなかった」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「ものから輪郭しか見えなかった」は起点として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「ものの輪郭」と名詞を続ける連体修飾の「の」。", "を": "「ものを輪郭しか見えなかった」は目的語にならず、文が崩れる。", "に": "「ものに輪郭しか見えなかった」は意味が通らない。", "から": "「ものから輪郭しか見えなかった」は起点として意味が通らない。"}, "error_tags": {"を": "対格（目的語にならない）", "に": "位置（意味が通らない）", "から": "起点（意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「輪郭がきれいな葉を選んで」で、きれいだと形容される対象が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「選んで」の前にすでに「を」の目的語があるため、「を」を重ねると不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「輪郭へきれいな葉を選んで」は方向として意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「輪郭よりきれいな葉を選んで」は比較の意味になり、文が崩れる。"}], "correct_answer": "が", "explanations": {"が": "「輪郭がきれいな葉を選んで」で、きれいだと形容される対象が主語になる。", "を": "「選んで」の前にすでに「を」の目的語があるため、「を」を重ねると不自然になる。", "へ": "「輪郭へきれいな葉を選んで」は方向として意味が通らない。", "より": "「輪郭よりきれいな葉を選んで」は比較の意味になり、文が崩れる。"}, "error_tags": {"を": "対格（目的語が重なり不自然）", "へ": "方向（意味が通らない）", "より": "比較（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もののかたちの、まわりの線のこと。", "primary_collocate": null, "pronunciation": "りんかく", "ipa": "ɾiŋkaku", "syllable_count": 4, "sentences": [{"text": "絵を描くときは、まず輪郭を鉛筆でかく。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "絵[え]を描[か]くときは、まず輪郭[りんかく]を鉛筆[えんぴつ]でかく。", "sentence_source": "generated"}, {"text": "暗い部屋では、ものの輪郭しか見えなかった。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]では、ものの輪郭[りんかく]しか見[み]えなかった。", "sentence_source": "generated"}, {"text": "月の輪郭が雲の間からはっきり見えた。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "月[つき]の輪郭[りんかく]が雲[くも]の間[あいだ]からはっきり見[み]えた。", "sentence_source": "generated"}, {"text": "輪郭だけの絵に、色をぬって完成させた。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "輪郭[りんかく]だけの絵[え]に、色[いろ]をぬって完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "兄は黒いペンで、動物の輪郭をなぞった。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "兄[あに]は黒[くろ]いペンで、動物[どうぶつ]の輪郭[りんかく]をなぞった。", "sentence_source": "generated"}, {"text": "雨のせいで、向こうの建物の輪郭がぼやけている。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "雨[あめ]のせいで、向[む]こうの建物[たてもの]の輪郭[りんかく]がぼやけている。", "sentence_source": "generated"}, {"text": "子どもたちは手の輪郭を紙に写して、遊んでいた。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "子[こ]どもたちは手[て]の輪郭[りんかく]を紙[かみ]に写[うつ]して、遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "輪郭がきれいな葉を選んで、ノートにはった。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "輪郭[りんかく]がきれいな葉[は]を選[えら]んで、ノートにはった。", "sentence_source": "generated"}, {"text": "この地図は、島の輪郭がとても分かりやすい。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "この地図[ちず]は、島[しま]の輪郭[りんかく]がとても分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "夜の山は黒くて、輪郭の線だけが空に残っていた。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "夜[よる]の山[やま]は黒[くろ]くて、輪郭[りんかく]の線[せん]だけが空[そら]に残[のこ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輪郭", "label": "基本形"}], "register": "中立（やさしい話し言葉）", "sense_fingerprint": "ものの形のまわりを囲む線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輪郭", "is_correct": true, "explanation": "「まず輪郭を鉛筆でかく」で、絵の形を囲む線を指し文脈に合う。"}, {"text": "音", "is_correct": false, "explanation": "「まず音を鉛筆でかく」は成立せず、絵を描く文脈に合わない。"}, {"text": "味", "is_correct": false, "explanation": "「まず味を鉛筆でかく」は成立せず、絵を描く文脈に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「まず値段を鉛筆でかく」は成立せず、絵を描く文脈に合わない。"}], "explanations": {"輪郭": "「まず輪郭を鉛筆でかく」で、絵の形を囲む線を指し文脈に合う。", "音": "「まず音を鉛筆でかく」は成立せず、絵を描く文脈に合わない。", "味": "「まず味を鉛筆でかく」は成立せず、絵を描く文脈に合わない。", "値段": "「まず値段を鉛筆でかく」は成立せず、絵を描く文脈に合わない。"}, "sentence_index": 0, "correct_answer": "輪郭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお茶は、ほろ苦い輪郭がある。", "explanation": "ここは〈味〉の意味。ほろ苦いと言うのは味で、形の線を表す輪郭は味には使わない。"}, {"text": "この文章は、ていねいな輪郭で書かれている。", "explanation": "ここは〈言葉〉の意味。文章を書くのは言葉で、輪郭は形の線なので文章は書けない。"}, {"text": "夕焼けの空が、赤い輪郭に染まった。", "explanation": "ここは〈色〉の意味。空が染まるのは色で、輪郭は形の線なので染まることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輪郭", "is_correct": true, "explanation": "「手の輪郭を紙に写す」で、手の形を囲む線を写す意味になる。"}, {"text": "色", "is_correct": false, "explanation": "「手の色を紙に写す」は意味が通らず、形を写す文脈に合わない。"}, {"text": "名前", "is_correct": false, "explanation": "手に名前はなく、「手の名前を紙に写す」は成立しない。"}, {"text": "声", "is_correct": false, "explanation": "「手の声を紙に写す」は成立せず、この文の意味が通らない。"}], "explanations": {"輪郭": "「手の輪郭を紙に写す」で、手の形を囲む線を写す意味になる。", "色": "「手の色を紙に写す」は意味が通らず、形を写す文脈に合わない。", "名前": "手に名前はなく、「手の名前を紙に写す」は成立しない。", "声": "「手の声を紙に写す」は成立せず、この文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "輪郭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理店は、落ち着いた輪郭で人気がある。", "explanation": "ここは〈雰囲気〉の意味。店の感じは雰囲気と言い、輪郭は形の線なので人気の理由にはならない。"}, {"text": "説明会で、新商品の輪郭を配った。", "explanation": "ここは〈概要〉の意味。配れるのは新商品の概要で、輪郭は形の線なので配れない。"}, {"text": "この本を読んで、輪郭を友だちに話した。", "explanation": "ここは〈感想〉の意味。話すのは感想で、輪郭は形の線なので話題にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は赤いペンで、花の輪郭に なぞった。", "corrected_sentence": "姉は赤いペンで、花の輪郭をなぞった。", "error_description": "「なぞる」は他動詞なので、目的語を「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52367, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この写真は、遠くの山の輪郭をとても分かりやすい。", "corrected_sentence": "この写真は、遠くの山の輪郭がとても分かりやすい。", "error_description": "「分かりやすい」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「輪郭がぼんやりと見えた」で、見える対象が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は自動詞なので、目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "「輪郭で見えた」は手段や場所として主語にならず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「輪郭から見えた」は起点として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「輪郭がぼんやりと見えた」で、見える対象が主語になる。", "を": "「見える」は自動詞なので、目的語の「を」は取れない。", "で": "「輪郭で見えた」は手段や場所として主語にならず、意味が通らない。", "から": "「輪郭から見えた」は起点として意味が通らない。"}, "error_tags": {"を": "対格（自動詞と不一致）", "で": "手段（主語にならない）", "から": "起点（意味が通らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「顔の輪郭がシャープ」で、形容される対象が主語になる。"}, {"text": "と", "is_correct": false, "explanation": "「顔の輪郭とシャープ」は並列にも述語にもならず、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「顔の輪郭へシャープ」は方向として意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「顔の輪郭にシャープ」は述語と結びつかず、不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「顔の輪郭がシャープ」で、形容される対象が主語になる。", "と": "「顔の輪郭とシャープ」は並列にも述語にもならず、文が崩れる。", "へ": "「顔の輪郭へシャープ」は方向として意味が通らない。", "に": "「顔の輪郭にシャープ」は述語と結びつかず、不自然になる。"}, "error_tags": {"と": "並列（述語と不一致）", "へ": "方向（意味が通らない）", "に": "位置（述語と不一致）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の外側の形を表す線や、その全体的な形。", "primary_collocate": null, "pronunciation": "りんかく", "ipa": "ɾiŋkaku", "syllable_count": 4, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "輪郭", "complexity_tier": "T4", "furigana": "熟練[じゅくれん]したソムリエは、グラス内[ない]で展開[てんかい]される鉱物的[こうぶつてき]な輪郭[りんかく]や土壌由来[どじょうゆらい]の複雑[ふくざつ]な香気構造[こうきこうぞう]を解読[かいどく]し、視覚[しかく]や嗅覚[きゅうかく]を超[こ]えた土地的[とちてき]コンテキストを味覚的[みかくてき]に再構成[さいこうせい]する。", "sentence_source": "mined"}, {"text": "霧の中で、遠くの山の輪郭がぼんやりと見えた。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "霧[きり]の中[なか]で、遠[とお]くの山[やま]の輪郭[りんかく]がぼんやりと見[み]えた。", "sentence_source": "generated"}, {"text": "画家はまず鉛筆で人物の輪郭を描き、そのあとで色をぬった。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "画家[がか]はまず鉛筆[えんぴつ]で人物[じんぶつ]の輪郭[りんかく]を描[えが]き、そのあとで色[いろ]をぬった。", "sentence_source": "generated"}, {"text": "夕日を背に立つ彼女は、輪郭だけが黒く浮かび上がっていた。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "夕日[ゆうひ]を背[せ]に立[た]つ彼女[かのじょ]は、輪郭[りんかく]だけが黒[くろ]く浮[う]かび上[あ]がっていた。", "sentence_source": "generated"}, {"text": "計画の輪郭はできたが、細かい部分はまだ決まっていない。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "計画[けいかく]の輪郭[りんかく]はできたが、細[こま]かい部分[ぶぶん]はまだ決[き]まっていない。", "sentence_source": "generated"}, {"text": "眼鏡を外すと、街の灯りの輪郭がにじんで見える。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "眼鏡[めがね]を外[はず]すと、街[まち]の灯[あか]りの輪郭[りんかく]がにじんで見[み]える。", "sentence_source": "generated"}, {"text": "この写真は画質が粗いので、建物の輪郭がはっきりしない。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "この写真[しゃしん]は画質[がしつ]が粗[あら]いので、建物[たてもの]の輪郭[りんかく]がはっきりしない。", "sentence_source": "generated"}, {"text": "彼は顔の輪郭がシャープなので、横顔がとても印象的だ。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "彼[かれ]は顔[かお]の輪郭[りんかく]がシャープなので、横顔[よこがお]がとても印象的[いんしょうてき]だ。", "sentence_source": "generated"}, {"text": "地図アプリで島の輪郭をなぞると、面積が自動で計算される。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "地図[ちず]アプリで島[しま]の輪郭[りんかく]をなぞると、面積[めんせき]が自動[じどう]で計算[けいさん]される。", "sentence_source": "generated"}, {"text": "事件の輪郭が見えてきたのは、三人目の証言を聞いたあとだった。", "target_word": "輪郭", "complexity_tier": "T3", "furigana": "事件[じけん]の輪郭[りんかく]が見[み]えてきたのは、三人目[さんにんめ]の証言[しょうげん]を聞[き]いたあとだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輪郭", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物の外側の形を表す線、また全体的なおおまかな形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輪郭", "is_correct": true, "explanation": "「鉱物的な輪郭」として、形を囲む線を表し文脈に合う。"}, {"text": "時間", "is_correct": false, "explanation": "「鉱物的な時間」は意味が通らず、形の線を表さない。"}, {"text": "会議", "is_correct": false, "explanation": "「鉱物的な会議」は意味が合わず、香りや味わいの文脈に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「鉱物的な値段」は、味わいと香りを語るこの文と合わない。"}], "explanations": {"輪郭": "「鉱物的な輪郭」として、形を囲む線を表し文脈に合う。", "時間": "「鉱物的な時間」は意味が通らず、形の線を表さない。", "会議": "「鉱物的な会議」は意味が合わず、香りや味わいの文脈に合わない。", "値段": "「鉱物的な値段」は、味わいと香りを語るこの文と合わない。"}, "sentence_index": 0, "correct_answer": "輪郭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは、いつまでも熱い輪郭を保っている。", "explanation": "ここは〈温度〉の意味。熱さは温度で、形の線を表す輪郭は保つものではないので合わない。"}, {"text": "この花は、ほのかな輪郭を漂わせている。", "explanation": "ここは〈香り〉の意味。香りは漂わせるもので、輪郭は形の線なので漂わせることはできない。"}, {"text": "鐘の輪郭が遠くまで響いた。", "explanation": "ここは〈音〉の意味。鐘の音は遠くまで響くが、輪郭は形の線なので響くことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輪郭", "is_correct": true, "explanation": "「建物の輪郭」が、形の線としてはっきりしないという文脈に合う。"}, {"text": "味", "is_correct": false, "explanation": "建物に味はなく、画質の話をしているこの文と合わない。"}, {"text": "香り", "is_correct": false, "explanation": "建物に香りはなく、写真の画質の話と合わない。"}, {"text": "体温", "is_correct": false, "explanation": "建物に体温はなく、この文の意味が通らない。"}], "explanations": {"輪郭": "「建物の輪郭」が、形の線としてはっきりしないという文脈に合う。", "味": "建物に味はなく、画質の話をしているこの文と合わない。", "香り": "建物に香りはなく、写真の画質の話と合わない。", "体温": "建物に体温はなく、この文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "輪郭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は、ずっしり重い輪郭がある。", "explanation": "ここは〈重さ〉の意味。ずっしり重いのは重さで、形の線の輪郭には重さがないので合わない。"}, {"text": "この店は、落ち着いた輪郭が人気だ。", "explanation": "ここは〈雰囲気〉の意味。店の感じは雰囲気と言い、輪郭は形の線なので人気の理由にはならない。"}, {"text": "初対面の彼女は、強い輪郭を残した。", "explanation": "ここは〈印象〉の意味。人に残るのは印象で、輪郭は形の線なので「残す」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の外、遠くの山の輪郭にぼんやり見えた。", "corrected_sentence": "窓の外、遠くの山の輪郭がぼんやり見えた。", "error_description": "「見える」の主語は「が」で示す。ここで「に」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地図は、川の輪郭をはっきり見えるので便利だ。", "corrected_sentence": "この地図は、川の輪郭がはっきり見えるので便利だ。", "error_description": "「見える」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」は「解読」を話題として示し、「解読は課題だった」の形で成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「解読を、課題だった」では「を」が目的語を示すだけで、主題を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「解読から、課題だった」は起点を示す「から」になり、課題の説明として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「解読へ、課題だった」は方向の「へ」になり、課題だったという文にならない。"}], "correct_answer": "は", "explanations": {"は": "「は」は「解読」を話題として示し、「解読は課題だった」の形で成り立つ。", "を": "「解読を、課題だった」では「を」が目的語を示すだけで、主題を示せない。", "から": "「解読から、課題だった」は起点を示す「から」になり、課題の説明として成り立たない。", "へ": "「解読へ、課題だった」は方向の「へ」になり、課題だったという文にならない。"}, "error_tags": {"を": "目的語", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "書いてあることや言っていることの意味を、よく考えて見つけること。", "primary_collocate": null, "pronunciation": "かいどく", "ipa": "kaidoku", "syllable_count": 4, "sentences": [{"text": "先生の短い言葉の裏にある意図を解読するのは難しい。", "target_word": "解読", "complexity_tier": "T3", "furigana": "先生[せんせい]の短[みじか]い言葉[ことば]の裏[うら]にある意図[いと]を解読[かいどく]するのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼の無口な態度を解読しようとして、一晩中悩んだ。", "target_word": "解読", "complexity_tier": "T3", "furigana": "彼[かれ]の無口[むくち]な態度[たいど]を解読[かいどく]しようとして、一晩中[ひとばんじゅう]悩[なや]んだ。", "sentence_source": "generated"}, {"text": "この詩は抽象的なので、読者が自分なりに解読するしかない。", "target_word": "解読", "complexity_tier": "T3", "furigana": "この詩[し]は抽象的[ちゅうしょうてき]なので、読者[どくしゃ]が自分[じぶん]なりに解読[かいどく]するしかない。", "sentence_source": "generated"}, {"text": "説明書の図が分かりにくく、解読に時間がかかった。", "target_word": "解読", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の図[ず]が分[わ]かりにくく、解読[かいどく]に時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "友人の遠回しなメッセージを解読して、本当の気持ちに気づいた。", "target_word": "解読", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の遠回[とおまわ]しなメッセージを解読[かいどく]して、本当[ほんとう]の気持[きも]ちに気[き]づいた。", "sentence_source": "generated"}, {"text": "医者の走り書きのメモは、解読するのに苦労する。", "target_word": "解読", "complexity_tier": "T3", "furigana": "医者[いしゃ]の走[はし]り書[が]きのメモは、解読[かいどく]するのに苦労[くろう]する。", "sentence_source": "generated"}, {"text": "古い地図の記号を解読すれば、宝の場所が分かるかもしれない。", "target_word": "解読", "complexity_tier": "T3", "furigana": "古[ふる]い地図[ちず]の記号[きごう]を解読[かいどく]すれば、宝[たから]の場所[ばしょ]が分[わ]かるかもしれない。", "sentence_source": "generated"}, {"text": "絵に隠された意味の解読は、美術の授業の課題だった。", "target_word": "解読", "complexity_tier": "T3", "furigana": "絵[え]に隠[かく]された意味[いみ]の解読[かいどく]は、美術[びじゅつ]の授業[じゅぎょう]の課題[かだい]だった。", "sentence_source": "generated"}, {"text": "子どもの片言の言葉を解読するのに、母親はずいぶん苦労した。", "target_word": "解読", "complexity_tier": "T3", "furigana": "子[こ]どもの片言[かたこと]の言葉[ことば]を解読[かいどく]するのに、母親[ははおや]はずいぶん苦労[くろう]した。", "sentence_source": "generated"}, {"text": "この小説の結末は、解読の仕方で印象が変わる。", "target_word": "解読", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]の結末[けつまつ]は、解読[かいどく]の仕方[しかた]で印象[いんしょう]が変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解読する", "label": "辞書形"}, {"form": "解読した", "label": "過去形"}, {"form": "解読して", "label": "て形"}, {"form": "解読できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "分かりにくい言葉・態度・文章の本当の意味をよく考えて読み取ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解読", "is_correct": true, "explanation": "「意図を解読する」は、言葉の裏にある気持ちを読み取る意味で文に合う。"}, {"text": "製造", "is_correct": false, "explanation": "「製造」は物を作ることで、意図には使わない。"}, {"text": "解凍", "is_correct": false, "explanation": "「解凍」は凍ったものを溶かすことで、意図とは合わない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、意図の読み取りには合わない。"}], "explanations": {"解読": "「意図を解読する」は、言葉の裏にある気持ちを読み取る意味で文に合う。", "製造": "「製造」は物を作ることで、意図には使わない。", "解凍": "「解凍」は凍ったものを溶かすことで、意図とは合わない。", "点火": "「点火」は火をつけることで、意図の読み取りには合わない。"}, "sentence_index": 0, "correct_answer": "解読"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷凍した魚を解読するのに、三時間かかった。", "explanation": "ここは〈解凍〉（凍ったものを溶かすこと）の意味。魚を解凍するのは解読とは言わない。"}, {"text": "雨漏りを解読するため、屋根を直した。", "explanation": "ここは〈解消〉（障害を取り除くこと）の意味。雨漏りは読み解く対象ではないので、解読とは合わない。"}, {"text": "社員を解読した。", "explanation": "ここは〈解雇〉（雇用を終わらせること）の意味。解読は文章などの意味を読み解くことで、社員を辞めさせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解読", "is_correct": true, "explanation": "「古い地図の記号を解読すれば」は、記号の読み解きが宝の場所につながる意味で合う。"}, {"text": "修繕", "is_correct": false, "explanation": "「修繕」は壊れたものを直すことで、記号には使わない。"}, {"text": "消灯", "is_correct": false, "explanation": "「消灯」は明かりを消すことで、記号とは結びつかない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、記号の読み解きには合わない。"}], "explanations": {"解読": "「古い地図の記号を解読すれば」は、記号の読み解きが宝の場所につながる意味で合う。", "修繕": "「修繕」は壊れたものを直すことで、記号には使わない。", "消灯": "「消灯」は明かりを消すことで、記号とは結びつかない。", "点火": "「点火」は火をつけることで、記号の読み解きには合わない。"}, "sentence_index": 6, "correct_answer": "解読"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府は議会を解読した。", "explanation": "ここは〈解散〉（議会などの集まりを終わりにすること）の意味。解読は文章などの意味を読み解くことで、議会を解散させる意味では使わない。"}, {"text": "古い家を解読する工事が始まった。", "explanation": "ここは〈解体〉（建物を取り壊すこと）の意味。解読は読み解く行為なので、建物を壊す工事には使わない。"}, {"text": "二国間の紛争を解読した。", "explanation": "ここは〈解決〉（争いを収めること）の意味。紛争を収めることは読み解くことではないので、解読とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人の遠回しな言い方の解読を時間がかかり、本当の気持ちは分からなかった。", "corrected_sentence": "友人の遠回しな言い方の解読に時間がかかり、本当の気持ちは分からなかった。", "error_description": "「時間がかかる」には「に」が付くので、解読の後は「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52369, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "記者は政府の声明を解読れて、記事にまとめた。", "corrected_sentence": "記者は政府の声明を解読して、記事にまとめた。", "error_description": "「解読する」は「解読して」と活用するので、「解読れて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
