INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52370, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "暗号や難しい文章などの意味を、手がかりをもとに読み解くこと。", "primary_collocate": null, "pronunciation": "かいどく", "ipa": "kaidoku", "syllable_count": 4, "sentences": [{"text": "難しい暗号の文章を、少しずつ解読して意味を見つけた。", "target_word": "解読", "complexity_tier": "T3", "furigana": "難[むずか]しい暗号[あんごう]の文章[ぶんしょう]を、少[すこ]しずつ解読[かいどく]して意味[いみ]を見[み]つけた。", "sentence_source": "generated"}, {"text": "考古学者は粘土板に刻まれた古代文字の解読に十年を費やした。", "target_word": "解読", "complexity_tier": "T3", "furigana": "考古学者[こうこがくしゃ]は粘土板[ねんどばん]に刻[きざ]まれた古代文字[こだいもじ]の解読[かいどく]に十年[じゅうねん]を費[ついや]した。", "sentence_source": "generated"}, {"text": "暗号の解読には、鍵になる単語を見つけることが欠かせない。", "target_word": "解読", "complexity_tier": "T3", "furigana": "暗号[あんごう]の解読[かいどく]には、鍵[かぎ]になる単語[たんご]を見[み]つけることが欠[か]かせない。", "sentence_source": "generated"}, {"text": "この手紙は字が古いので、解読するのに時間がかかった。", "target_word": "解読", "complexity_tier": "T3", "furigana": "この手紙[てがみ]は字[じ]が古[ふる]いので、解読[かいどく]するのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "戦時中の暗号を解読したチームの話が映画になった。", "target_word": "解読", "complexity_tier": "T3", "furigana": "戦時中[せんじちゅう]の暗号[あんごう]を解読[かいどく]したチームの話[はなし]が映画[えいが]になった。", "sentence_source": "generated"}, {"text": "難解な法律の条文を解読するのに、三日もかかった。", "target_word": "解読", "complexity_tier": "T3", "furigana": "難解[なんかい]な法律[ほうりつ]の条文[じょうぶん]を解読[かいどく]するのに、三日[みっか]もかかった。", "sentence_source": "generated"}, {"text": "古文書の解読が進み、江戸時代の町の様子が分かってきた。", "target_word": "解読", "complexity_tier": "T3", "furigana": "古文書[こもんじょ]の解読[かいどく]が進[すす]み、江戸時代[えどじだい]の町[まち]の様子[ようす]が分[わ]かってきた。", "sentence_source": "generated"}, {"text": "彼女は謎めいた詩の意味を、ひとつずつ手がかりをたどって解読した。", "target_word": "解読", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は謎[なぞ]めいた詩[し]の意味[いみ]を、ひとつずつ手[て]がかりをたどって解読[かいどく]した。", "sentence_source": "generated"}, {"text": "エジプトの象形文字は、ロゼッタストーンのおかげで解読できた。", "target_word": "解読", "complexity_tier": "T3", "furigana": "エジプトの象形文字[しょうけいもじ]は、ロゼッタストーンのおかげで解読[かいどく]できた。", "sentence_source": "generated"}, {"text": "暗号が複雑すぎて、専門家でも解読できなかった。", "target_word": "解読", "complexity_tier": "T3", "furigana": "暗号[あんごう]が複雑[ふくざつ]すぎて、専門家[せんもんか]でも解読[かいどく]できなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解読する", "label": "辞書形"}, {"form": "解読した", "label": "過去形"}, {"form": "解読して", "label": "て形"}, {"form": "解読できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "暗号・古代文字・難文など、手がかりから意味を読み解く作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: ロゼッタストーン (Zipf 1.73)']::text[], 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52370, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解読", "is_correct": true, "explanation": "「文章を解読して」は、難しい文の意味を読み解く意味で文に合う。"}, {"text": "修繕", "is_correct": false, "explanation": "「修繕」は壊れたものを直すことで、文章の解読には使わない。"}, {"text": "採掘", "is_correct": false, "explanation": "「採掘」は地中の資源を掘り出すことで、文章の意味を読むことには合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去」は取り除いて片付けることで、文章の意味を読み取る意味にはならない。"}], "explanations": {"解読": "「文章を解読して」は、難しい文の意味を読み解く意味で文に合う。", "修繕": "「修繕」は壊れたものを直すことで、文章の解読には使わない。", "採掘": "「採掘」は地中の資源を掘り出すことで、文章の意味を読むことには合わない。", "撤去": "「撤去」は取り除いて片付けることで、文章の意味を読み取る意味にはならない。"}, "sentence_index": 0, "correct_answer": "解読"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毒を飲んだので、病院で解読の治療を受けた。", "explanation": "ここは〈解毒〉（毒の作用を取り除くこと）の意味。解読は暗号や文章の意味を読み解くことなので、治療には使わない。"}, {"text": "父は携帯の契約を解読した。", "explanation": "ここは〈解約〉（契約をやめること）の意味。解読は暗号や文章を読み解くことで、契約を終わらせる意味では使わない。"}, {"text": "警察は遺体を解読した。", "explanation": "ここは〈解剖〉（遺体などを切り開いて調べること）の意味。解読は暗号や文章の意味を読み解くことで、遺体を調べる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52370, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解読", "is_correct": true, "explanation": "「古文書の解読が進む」は、文書の読み解き作業が進む意味で文脈に合う。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、古文書の作業の進行には使わない。"}, {"text": "消灯", "is_correct": false, "explanation": "「消灯」は明かりを消すことで、文書の作業とは合わない。"}, {"text": "出港", "is_correct": false, "explanation": "「出港」は船が港を離れることで、古文書には当てはまらない。"}], "explanations": {"解読": "「古文書の解読が進む」は、文書の読み解き作業が進む意味で文脈に合う。", "点火": "「点火」は火をつけることで、古文書の作業の進行には使わない。", "消灯": "「消灯」は明かりを消すことで、文書の作業とは合わない。", "出港": "「出港」は船が港を離れることで、古文書には当てはまらない。"}, "sentence_index": 6, "correct_answer": "解読"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームは会議を解読した。", "explanation": "ここは〈解散〉（集まりを終わりにすること）の意味。解読は暗号や文章の意味を読み解くことで、会議を終わりにする意味では使わない。"}, {"text": "渋滞を解読するため、道路を広げた。", "explanation": "ここは〈解消〉（障害を取り除くこと）の意味。渋滞は読み解く対象ではないので、解読とは合わない。"}, {"text": "市は夜間の規制を解読した。", "explanation": "ここは〈解除〉（決められていた規制や制限をなくすこと）の意味。解読は暗号や文章の意味を読み解くことで、規制をなくす意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52370, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暗号の解読を、専門家の協力が欠かせなかった。", "corrected_sentence": "暗号の解読に、専門家の協力が欠かせなかった。", "error_description": "「欠かせない」は「〜に欠かせない」の形で使うので、解読の後の助詞は「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52370, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は三日で暗号の解読を終わった。", "corrected_sentence": "彼は三日で暗号の解読を終えた。", "error_description": "「終わる」は自動詞で目的語の「を」を取れないため、他動詞の「終える」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「香気にさそわれて」で、「誘う」の受身の相手を示す「に」。文として自然。"}, {"text": "を", "is_correct": false, "explanation": "「誘われる」は「に」で相手を示すので、「香気を」では受身の文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「香気が誘われて」では、香気を誘う主体として自然につながらず、受身の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「香気へ誘われて」となり、受身の相手を示せない。"}], "correct_answer": "に", "explanations": {"に": "「香気にさそわれて」で、「誘う」の受身の相手を示す「に」。文として自然。", "を": "「誘われる」は「に」で相手を示すので、「香気を」では受身の文として成り立たない。", "が": "「香気が誘われて」では、香気を誘う主体として自然につながらず、受身の文として不自然。", "へ": "方向の「へ」では「香気へ誘われて」となり、受身の相手を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「米の香気が立ちのぼる」で、「立ちのぼる」の主語を示す「が」。文として自然に成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「香気で立ちのぼる」となり、香気が主語として立ちのぼる文にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「香気と立ちのぼる」となり、一つの述語に続かず文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「香気より立ちのぼる」となり、主語を示せず文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「米の香気が立ちのぼる」で、「立ちのぼる」の主語を示す「が」。文として自然に成り立つ。", "で": "手段の「で」では「香気で立ちのぼる」となり、香気が主語として立ちのぼる文にならない。", "と": "並列の「と」では「香気と立ちのぼる」となり、一つの述語に続かず文が成立しない。", "より": "比較の「より」では「香気より立ちのぼる」となり、主語を示せず文が成立しない。"}, "error_tags": {"で": "手段", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いいにおい", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "台所から、おいしそうな香気がただよってきた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "台所[だいどころ]から、おいしそうな香気[こうき]がただよってきた。", "sentence_source": "generated"}, {"text": "バラの香気にさそわれて、庭に出てみた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "バラの香気[こうき]にさそわれて、庭[にわ]に出[で]てみた。", "sentence_source": "generated"}, {"text": "新しい茶葉は、さわやかな香気がする。", "target_word": "香気", "complexity_tier": "T3", "furigana": "新[あたら]しい茶葉[ちゃば]は、さわやかな香気[こうき]がする。", "sentence_source": "generated"}, {"text": "コーヒーの香気で目が覚めた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "コーヒーの香気[こうき]で目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "雨上がりの森は、土と草の香気がして気持ちいい。", "target_word": "香気", "complexity_tier": "T3", "furigana": "雨上[あめあ]がりの森[もり]は、土[つち]と草[くさ]の香気[こうき]がして気持[きも]ちいい。", "sentence_source": "generated"}, {"text": "彼女が通ると、ほのかな香気が残った。", "target_word": "香気", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が通[とお]ると、ほのかな香気[こうき]が残[のこ]った。", "sentence_source": "generated"}, {"text": "この石けんは、上品な香気が人気だ。", "target_word": "香気", "complexity_tier": "T3", "furigana": "この石[せっ]けんは、上品[じょうひん]な香気[こうき]が人気[にんき]だ。", "sentence_source": "generated"}, {"text": "蒸したての餅から、米の香気が立ちのぼる。", "target_word": "香気", "complexity_tier": "T3", "furigana": "蒸[む]したての餅[もち]から、米[こめ]の香気[こうき]が立[た]ちのぼる。", "sentence_source": "generated"}, {"text": "窓を開けると、金木犀の香気が部屋に入ってきた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、金木犀[きんもくせい]の香気[こうき]が部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "香気の高い紅茶を、客にふるまった。", "target_word": "香気", "complexity_tier": "T3", "furigana": "香気[こうき]の高[たか]い紅茶[こうちゃ]を、客[きゃく]にふるまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "香気", "label": "基本形"}, {"form": "香気の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "花・茶・食べ物などから漂ってくる、心地よい良いにおい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香気", "is_correct": true, "explanation": "「おいしそうな香気がただよってきた」で、食べ物の良いにおいが漂う様子を表す。文脈に合う。"}, {"text": "臭気", "is_correct": false, "explanation": "臭気は悪いにおいを指すので、「おいしそうな」と矛盾する。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は味を感じる感覚で、においが「ただよってくる」ものではない。文として不自然。"}, {"text": "体臭", "is_correct": false, "explanation": "体臭は人の体から出るにおいで、「おいしそうな」台所の香りには合わない。"}], "explanations": {"香気": "「おいしそうな香気がただよってきた」で、食べ物の良いにおいが漂う様子を表す。文脈に合う。", "臭気": "臭気は悪いにおいを指すので、「おいしそうな」と矛盾する。", "味覚": "味覚は味を感じる感覚で、においが「ただよってくる」ものではない。文として不自然。", "体臭": "体臭は人の体から出るにおいで、「おいしそうな」台所の香りには合わない。"}, "sentence_index": 0, "correct_answer": "香気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゴミ袋の香気が台所に広がって、困った。", "explanation": "ここは〈臭気〉の意味。香気は好ましいにおいなので、ゴミ袋の悪臭には合わない。"}, {"text": "彼女の香気ある言葉は、会議の空気をやわらげた。", "explanation": "ここは〈品のよい雰囲気〉の比喩的な意味。教える語義（具体的な良いにおい）とは別の使い方で、においの意味では使えない。"}, {"text": "デパートで香気を一本買って、首につけた。", "explanation": "ここは〈香水〉の意味。香気は瓶入りの商品ではないので、一本と数えたり買ったりする語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香気", "is_correct": true, "explanation": "「上品な香気が人気だ」で、石けんの上品な良い香りが評判だという意味になる。文脈に合う。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は不快な音で、石けんの特徴として「上品な騒音が人気」とは言えない。"}, {"text": "汗", "is_correct": false, "explanation": "汗は体から出る水分で、石けんの特徴に使えない。「上品な汗」は文として不自然。"}, {"text": "静電気", "is_correct": false, "explanation": "静電気は電気の現象で、石けんの性質として「上品な静電気が人気」とは言えない。"}], "explanations": {"香気": "「上品な香気が人気だ」で、石けんの上品な良い香りが評判だという意味になる。文脈に合う。", "騒音": "騒音は不快な音で、石けんの特徴として「上品な騒音が人気」とは言えない。", "汗": "汗は体から出る水分で、石けんの特徴に使えない。「上品な汗」は文として不自然。", "静電気": "静電気は電気の現象で、石けんの性質として「上品な静電気が人気」とは言えない。"}, "sentence_index": 6, "correct_answer": "香気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日の訓練で、香気を鋭く鍛え上げた。", "explanation": "ここは〈嗅覚〉の意味。鍛えるのは嗅ぐ能力で、香気そのものを鋭く鍛えることはできない。"}, {"text": "鐘の香気が、遠くまで響いていった。", "explanation": "ここは〈音〉の意味。香気は響くものではないので、音に使う「響く」とは合わない。"}, {"text": "朝焼けの香気が、街をやさしく染めていった。", "explanation": "ここは〈色彩〉の意味。香気は目に見えないので、街を染める色にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭のバラから、やわらかな香気をただよってきた。", "corrected_sentence": "庭のバラから、やわらかな香気がただよってきた。", "error_description": "誤りは「香気を」（を）。正しくは「香気が」（が）。「ただよう」は自動詞で、香気が主語になるので「が」を使う。「を」は他動詞の目的語に使うので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52371, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨上がりの庭から、香気が漂いてくる。", "corrected_sentence": "雨上がりの庭から、香気が漂ってくる。", "error_description": "誤りは「漂いてくる」（活用）。正しくは「漂ってくる」。「漂う」は五段活用で、「て」に続くときは音便になり「漂って」となる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「香気が満ちていた」で、「満ちる」の主語を示す「が」。文として自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「満ちる」は目的語を取らない自動詞なので、「香気を満ちていた」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「香気と満ちていた」となり、述語に続かず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「香気へ満ちていた」となり、「満ちる」の主語として使えない。"}], "correct_answer": "が", "explanations": {"が": "「香気が満ちていた」で、「満ちる」の主語を示す「が」。文として自然に成り立つ。", "を": "「満ちる」は目的語を取らない自動詞なので、「香気を満ちていた」は成り立たない。", "と": "並列の「と」では「香気と満ちていた」となり、述語に続かず文が成立しない。", "へ": "方向の「へ」では「香気へ満ちていた」となり、「満ちる」の主語として使えない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「パンの香気が、店の外まで流れてきた」で、「流れてくる」の主語を示す「が」。文として成立する。"}, {"text": "で", "is_correct": false, "explanation": "手段・原因の「で」では「香気で流れてきた」となり、香気が主語として流れる文にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「香気より流れてきた」となり、主語を示せず文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では「香気の流れてきた」となり、述語が続かず文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「パンの香気が、店の外まで流れてきた」で、「流れてくる」の主語を示す「が」。文として成立する。", "で": "手段・原因の「で」では「香気で流れてきた」となり、香気が主語として流れる文にならない。", "より": "比較の「より」では「香気より流れてきた」となり、主語を示せず文が成立しない。", "の": "連体修飾の「の」では「香気の流れてきた」となり、述語が続かず文が成立しない。"}, "error_tags": {"で": "手段・原因", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物から出る、良い香りのこと。特に、食べ物や花などの複雑な香りを指すこともある。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "香気", "complexity_tier": "T4", "furigana": "熟練[じゅくれん]したソムリエは、グラス内[ない]で展開[てんかい]される鉱物的[こうぶつてき]な輪郭[りんかく]や土壌由来[どじょうゆらい]の複雑[ふくざつ]な香気構造[こうきこうぞう]を解読[かいどく]し、視覚[しかく]や嗅覚[きゅうかく]を超[こ]えた土地的[とちてき]コンテキストを味覚的[みかくてき]に再構成[さいこうせい]する。", "sentence_source": "mined"}, {"text": "森の中には、木々の香気が満ちていた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]には、木々[きぎ]の香気[こうき]が満[み]ちていた。", "sentence_source": "generated"}, {"text": "ワインから立ちのぼる香気に、思わず目を閉じた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "ワインから立[た]ちのぼる香気[こうき]に、思[おも]わず目[め]を閉[と]じた。", "sentence_source": "generated"}, {"text": "熟した桃は、甘い香気を放っている。", "target_word": "香気", "complexity_tier": "T3", "furigana": "熟[じゅく]した桃[もも]は、甘[あま]い香気[こうき]を放[はな]っている。", "sentence_source": "generated"}, {"text": "お茶を入れると、部屋じゅうに香気が広がった。", "target_word": "香気", "complexity_tier": "T3", "furigana": "お茶[ちゃ]を入[い]れると、部屋[へや]じゅうに香気[こうき]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "このチーズは、時間とともに複雑な香気が現れる。", "target_word": "香気", "complexity_tier": "T3", "furigana": "このチーズは、時間[じかん]とともに複雑[ふくざつ]な香気[こうき]が現[あらわ]れる。", "sentence_source": "generated"}, {"text": "春の庭は、花の香気に包まれていた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "春[はる]の庭[にわ]は、花[はな]の香気[こうき]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "焼きたてのパンの香気が、店の外まで流れてきた。", "target_word": "香気", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンの香気[こうき]が、店[みせ]の外[そと]まで流[なが]れてきた。", "sentence_source": "generated"}, {"text": "この蒸留酒は、樽の木に由来する香気が特徴だ。", "target_word": "香気", "complexity_tier": "T3", "furigana": "この蒸留酒[じょうりゅうしゅ]は、樽[たる]の木[き]に由来[ゆらい]する香気[こうき]が特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "香気の強い果物は、冷やしすぎると香りが弱まることがある。", "target_word": "香気", "complexity_tier": "T3", "furigana": "香気[こうき]の強[つよ]い果物[くだもの]は、冷[ひ]やしすぎると香[かお]りが弱[よわ]まることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "香気", "label": "基本形"}, {"form": "香気の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "ワイン・茶・花・食べ物などから立ちのぼる、複雑で奥行きのある良い香り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香気", "is_correct": true, "explanation": "文脈は複雑な香りの構造の話。ワインや食べ物から立ちのぼる良い香りを指す〈香気〉が入る。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の熱を指し、香りの構造とは言えない。文脈に合わない。"}, {"text": "臭気", "is_correct": false, "explanation": "臭気は悪いにおいを指すので、複雑で好ましい香りの構造には合わない。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は味を感じる感覚で、香りの構造を表さない。「味覚構造」は文として成り立たない。"}], "explanations": {"香気": "文脈は複雑な香りの構造の話。ワインや食べ物から立ちのぼる良い香りを指す〈香気〉が入る。", "体温": "体温は体の熱を指し、香りの構造とは言えない。文脈に合わない。", "臭気": "臭気は悪いにおいを指すので、複雑で好ましい香りの構造には合わない。", "味覚": "味覚は味を感じる感覚で、香りの構造を表さない。「味覚構造」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "香気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゴミ置き場から香気が漂ってきて、思わず鼻をつまんだ。", "explanation": "ここは〈臭気〉の意味。香気は良いにおいを指すので、ゴミの悪臭には合わない。"}, {"text": "彼の香気ある文章は、読む人の心を静かに打った。", "explanation": "ここは〈品のよい雰囲気〉の比喩的な意味。教える語義（具体的な良いにおい）とは別の使い方なので、においの意味では誤り。"}, {"text": "朝起きると、自分の口の香気が気になった。", "explanation": "ここは〈口臭〉の意味。香気は好ましいにおいを指すので、口から出る不快なにおいには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香気", "is_correct": true, "explanation": "「花の香気に包まれていた」で、花から立ちのぼる良い香りに包まれた様子を表す。文脈に合う。"}, {"text": "約束", "is_correct": false, "explanation": "約束は包まれるものではなく、「花の約束に包まれていた」は文に合わない。"}, {"text": "静電気", "is_correct": false, "explanation": "静電気は電気の現象で、花に「包まれる」ものではない。文脈に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は食品で、花の様子を表す語として「花の砂糖に包まれていた」とは言えない。"}], "explanations": {"香気": "「花の香気に包まれていた」で、花から立ちのぼる良い香りに包まれた様子を表す。文脈に合う。", "約束": "約束は包まれるものではなく、「花の約束に包まれていた」は文に合わない。", "静電気": "静電気は電気の現象で、花に「包まれる」ものではない。文脈に合わない。", "砂糖": "砂糖は食品で、花の様子を表す語として「花の砂糖に包まれていた」とは言えない。"}, "sentence_index": 6, "correct_answer": "香気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "香気を一本買って、通勤のときに首につけている。", "explanation": "ここは〈香水〉の意味。香気はにおいそのもので、瓶に入って一本と数える商品ではないので合わない。"}, {"text": "彼は毎朝、香気を鍛えるために練習している。", "explanation": "ここは〈嗅覚〉の意味。鍛えられるのは嗅ぐ能力で、香気そのものを鍛えることはできない。"}, {"text": "夕焼けの香気が、空をゆっくり染めていった。", "explanation": "ここは〈色彩〉の意味。香気は目に見えないので、空を染める色にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けると、庭じゅうに香気を広がった。", "corrected_sentence": "窓を開けると、庭じゅうに香気が広がった。", "error_description": "誤りは「香気を」（を）。正しくは「香気が」（が）。「広がる」は自動詞なので、香気は主語として「が」で示す。「を」は他動詞の目的語に使うので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52372, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺の鉢から、やさしい香気が漂いてくる。", "corrected_sentence": "窓辺の鉢から、やさしい香気が漂ってくる。", "error_description": "誤りは「漂いてくる」（活用）。正しくは「漂ってくる」。「漂う」は五段活用で、「て」に続くときは音便になり「漂って」となる。香気の述語に関わる活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「嗅覚が強い」で、強いという性質の主語を示す。犬の性質の説明として自然。"}, {"text": "を", "is_correct": false, "explanation": "「嗅覚を強いので」は目的語になり、形容詞の主語として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「嗅覚に強いので」は不自然で、性質の主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「嗅覚と強いので」は並列を示し、形容詞の主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「嗅覚が強い」で、強いという性質の主語を示す。犬の性質の説明として自然。", "を": "「嗅覚を強いので」は目的語になり、形容詞の主語として成り立たない。", "に": "「嗅覚に強いので」は不自然で、性質の主語を示せない。", "と": "「嗅覚と強いので」は並列を示し、形容詞の主語として成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「嗅覚で見分ける」で、見分ける手段を示す。動物の感覚の説明として自然。"}, {"text": "を", "is_correct": false, "explanation": "「嗅覚を仲間や敵を見分ける」は「を」が二つ入って目的語が重なり、手段を示せず文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「嗅覚に仲間や敵を見分ける」は手段を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「嗅覚へ仲間や敵を見分ける」は方向を示し、手段の意味にならない。"}], "correct_answer": "で", "explanations": {"で": "「嗅覚で見分ける」で、見分ける手段を示す。動物の感覚の説明として自然。", "を": "「嗅覚を仲間や敵を見分ける」は「を」が二つ入って目的語が重なり、手段を示せず文として成り立たない。", "に": "「嗅覚に仲間や敵を見分ける」は手段を示せず、不自然。", "へ": "「嗅覚へ仲間や敵を見分ける」は方向を示し、手段の意味にならない。"}, "error_tags": {"を": "目的語の重複", "に": "場所・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "においを感じる力。", "primary_collocate": null, "pronunciation": "きゅうかく", "ipa": "kʲɯːkakɯ", "syllable_count": 4, "sentences": [{"text": "祖母は年をとって、嗅覚が弱くなったと言っている。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "祖母[そぼ]は年[とし]をとって、嗅覚[きゅうかく]が弱[よわ]くなったと言[い]っている。", "sentence_source": "generated"}, {"text": "犬は嗅覚が強いので、落とし物を見つけるのが得意だ。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "犬[いぬ]は嗅覚[きゅうかく]が強[つよ]いので、落[お]とし物[もの]を見[み]つけるのが得意[とくい]だ。", "sentence_source": "generated"}, {"text": "鼻の調子が悪くて、今日は嗅覚がまったく働かない。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "鼻[はな]の調子[ちょうし]が悪[わる]くて、今日[きょう]は嗅覚[きゅうかく]がまったく働[はたら]かない。", "sentence_source": "generated"}, {"text": "嗅覚のおかげで、パンが焼けるいい香りに気づいた。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "嗅覚[きゅうかく]のおかげで、パンが焼[や]けるいい香[かお]りに気[き]づいた。", "sentence_source": "generated"}, {"text": "猫も嗅覚が鋭く、食べ物が古いとすぐにわかる。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "猫[ねこ]も嗅覚[きゅうかく]が鋭[するど]く、食[た]べ物[もの]が古[ふる]いとすぐにわかる。", "sentence_source": "generated"}, {"text": "目を閉じたまま、嗅覚だけで果物の種類を当てるゲームをした。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "目[め]を閉[と]じたまま、嗅覚[きゅうかく]だけで果物[くだもの]の種類[しゅるい]を当[あ]てるゲームをした。", "sentence_source": "generated"}, {"text": "熱があるときは嗅覚が落ちて、カレーの香りも感じなかった。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "熱[ねつ]があるときは嗅覚[きゅうかく]が落[お]ちて、カレーの香[かお]りも感[かん]じなかった。", "sentence_source": "generated"}, {"text": "動物は嗅覚で仲間や敵を見分けることが多い。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "動物[どうぶつ]は嗅覚[きゅうかく]で仲間[なかま]や敵[てき]を見分[みわ]けることが多[おお]い。", "sentence_source": "generated"}, {"text": "赤ちゃんは嗅覚で母親を見分けると言われている。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは嗅覚[きゅうかく]で母親[ははおや]を見分[みわ]けると言[い]われている。", "sentence_source": "generated"}, {"text": "花粉症の季節は鼻水で嗅覚が鈍り、香水の香りもわかりにくい。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "花粉症[かふんしょう]の季節[きせつ]は鼻水[はなみず]で嗅覚[きゅうかく]が鈍[にぶ]り、香水[こうすい]の香[かお]りもわかりにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗅覚", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "鼻でにおいを感じる力。人や動物の日常的な感覚としての嗅覚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嗅覚", "is_correct": true, "explanation": "においを感じる力が弱くなる対象として自然で、祖母の話の文に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は弱くなるものではなく、「挨拶が弱くなった」は文に合わない。"}, {"text": "借金", "is_correct": false, "explanation": "借金は弱くなる対象ではなく、「借金が弱くなった」は文脈に合わない。"}, {"text": "約束", "is_correct": false, "explanation": "約束は弱くなるものではなく、「約束が弱くなった」は文に合わない。"}], "explanations": {"嗅覚": "においを感じる力が弱くなる対象として自然で、祖母の話の文に合う。", "挨拶": "挨拶は弱くなるものではなく、「挨拶が弱くなった」は文に合わない。", "借金": "借金は弱くなる対象ではなく、「借金が弱くなった」は文脈に合わない。", "約束": "約束は弱くなるものではなく、「約束が弱くなった」は文に合わない。"}, "sentence_index": 0, "correct_answer": "嗅覚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嗅覚のおかげで、パンが焼けるいい色に気づいた。", "explanation": "ここは〈視覚〉の意味。色は目で見て気づくもので、においを感じる嗅覚では合わない。"}, {"text": "嗅覚が部屋いっぱいに広がって、パンが焼けたとわかった。", "explanation": "ここは〈香り〉（漂うにおい）の意味。嗅覚はにおいを感じる力で、部屋に広がるにおいそのものは指さないので合わない。"}, {"text": "嗅覚のおかげで、パンが焼けた熱さに気づいた。", "explanation": "ここは〈触覚〉の意味。熱さは肌で感じるもので、においを感じる嗅覚では気づけないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗅覚", "is_correct": true, "explanation": "熱で感じにくくなる能力として自然で、カレーの香りが感じられない文に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は落ちるものではなく、「宿題が落ちて」は文の流れに合わない。"}, {"text": "休暇", "is_correct": false, "explanation": "休暇は落ちるものではなく、「休暇が落ちて」は文に合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は落ちるものではなく、「旅行が落ちて」は文脈に合わない。"}], "explanations": {"嗅覚": "熱で感じにくくなる能力として自然で、カレーの香りが感じられない文に合う。", "宿題": "宿題は落ちるものではなく、「宿題が落ちて」は文の流れに合わない。", "休暇": "休暇は落ちるものではなく、「休暇が落ちて」は文に合わない。", "旅行": "旅行は落ちるものではなく、「旅行が落ちて」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "嗅覚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "耳の病気で嗅覚が鈍り、電話の声も聞き取りにくい。", "explanation": "ここは〈聴覚〉の意味。声を聞き取る力は耳の働きで、嗅覚では表せないので合わない。"}, {"text": "年をとって嗅覚が落ち、昨日の約束も忘れてしまう。", "explanation": "ここは〈記憶力〉の意味。覚えておく力は嗅覚では言えないので合わない。"}, {"text": "昨年のけがで嗅覚が落ち、重い荷物が持てなくなった。", "explanation": "ここは〈腕力〉の意味。荷物を持ち上げる力は嗅覚では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は花粉症で嗅覚を鈍くなり、料理の香りがわからない。", "corrected_sentence": "父は花粉症で嗅覚が鈍くなり、料理の香りがわからない。", "error_description": "「鈍くなる」は主語に「が」を付けて使う。「嗅覚を」は目的語扱いになり誤りで、「嗅覚が鈍くなり」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52373, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は嗅覚に鋭くて、台所の焦げ臭さにもすぐ気づく。", "corrected_sentence": "叔父は嗅覚が鋭くて、台所の焦げ臭さにもすぐ気づく。", "error_description": "「鋭い」は主語に「が」を付けて使う。「嗅覚に」は誤りで、「嗅覚が鋭くて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「嗅覚を持っている」で、持つ対象を示す。犬が持つ能力として自然。"}, {"text": "が", "is_correct": false, "explanation": "「嗅覚が持っている」では嗅覚が持ち主になり、犬が持つという文の意味に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「嗅覚に持っている」は持つ対象を「に」で示せず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「嗅覚と持っている」は並列を示し、持つ対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「嗅覚を持っている」で、持つ対象を示す。犬が持つ能力として自然。", "が": "「嗅覚が持っている」では嗅覚が持ち主になり、犬が持つという文の意味に合わない。", "に": "「嗅覚に持っている」は持つ対象を「に」で示せず、不自然。", "と": "「嗅覚と持っている」は並列を示し、持つ対象にならない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "においを感じ取る感覚。鼻の粘膜にある嗅細胞によって空気中の化学物質を感知する能力。", "primary_collocate": null, "pronunciation": "きゅうかく", "ipa": "kʲɯːkakɯ", "syllable_count": 4, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "嗅覚", "complexity_tier": "T4", "furigana": "熟練[じゅくれん]したソムリエは、グラス内[ない]で展開[てんかい]される鉱物的[こうぶつてき]な輪郭[りんかく]や土壌由来[どじょうゆらい]の複雑[ふくざつ]な香気構造[こうきこうぞう]を解読[かいどく]し、視覚[しかく]や嗅覚[きゅうかく]を超[こ]えた土地的[とちてき]コンテキストを味覚的[みかくてき]に再構成[さいこうせい]する。", "sentence_source": "mined"}, {"text": "犬は人間よりはるかに鋭い嗅覚を持っているので、警察犬として働くことができる。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "犬[いぬ]は人間[にんげん]よりはるかに鋭[するど]い嗅覚[きゅうかく]を持[も]っているので、警察犬[けいさつけん]として働[はたら]くことができる。", "sentence_source": "generated"}, {"text": "嗅覚は鼻の奥にある嗅細胞が空気中の化学物質をとらえることで生まれる。", "target_word": "嗅覚", "complexity_tier": "T4", "furigana": "嗅覚[きゅうかく]は鼻[はな]の奥[おく]にある嗅細胞[きゅうさいぼう]が空気中[くうきちゅう]の化学物質[かがくぶっしつ]をとらえることで生[う]まれる。", "sentence_source": "generated"}, {"text": "風邪をひいて鼻が詰まると、嗅覚が鈍くなって料理の香りがわからなくなる。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいて鼻[はな]が詰[つ]まると、嗅覚[きゅうかく]が鈍[にぶ]くなって料理[りょうり]の香[かお]りがわからなくなる。", "sentence_source": "generated"}, {"text": "サメは優れた嗅覚で、遠くにいる獲物の血のにおいを感じ取る。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "サメは優[すぐ]れた嗅覚[きゅうかく]で、遠[とお]くにいる獲物[えもの]の血[ち]のにおいを感[かん]じ取[と]る。", "sentence_source": "generated"}, {"text": "嗅覚の研究が進み、においの受容体の仕組みが少しずつ解明されてきた。", "target_word": "嗅覚", "complexity_tier": "T4", "furigana": "嗅覚[きゅうかく]の研究[けんきゅう]が進[すす]み、においの受容体[じゅようたい]の仕組[しく]みが少[すこ]しずつ解明[かいめい]されてきた。", "sentence_source": "generated"}, {"text": "長年ワインを扱う彼は、嗅覚を鍛えるために毎朝いろいろな香りを試している。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "長年[ながねん]ワインを扱[あつか]う彼[かれ]は、嗅覚[きゅうかく]を鍛[きた]えるために毎朝[まいあさ]いろいろな香[かお]りを試[ため]している。", "sentence_source": "generated"}, {"text": "人間の嗅覚は、同じにおいが続くと慣れて感じにくくなる性質がある。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "人間[にんげん]の嗅覚[きゅうかく]は、同[おな]じにおいが続[つづ]くと慣[な]れて感[かん]じにくくなる性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "ガス漏れは、嗅覚で変なにおいに気づかないと見逃しやすい危険だ。", "target_word": "嗅覚", "complexity_tier": "T3", "furigana": "ガス漏[も]れは、嗅覚[きゅうかく]で変[へん]なにおいに気[き]づかないと見逃[みのが]しやすい危険[きけん]だ。", "sentence_source": "generated"}, {"text": "蛾のオスは、驚くほど敏感な嗅覚でメスが出す物質を探し当てる。", "target_word": "嗅覚", "complexity_tier": "T4", "furigana": "蛾[が]のオスは、驚[おどろ]くほど敏感[びんかん]な嗅覚[きゅうかく]でメスが出[だ]す物質[ぶっしつ]を探[さが]し当[あ]てる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗅覚", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "五感の一つ。鼻の嗅細胞が空気中の化学物質を感知してにおいを知る生理的な能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嗅覚", "is_correct": true, "explanation": "「視覚や嗅覚を超えた」の嗅覚で、感覚の能力を並べる文に合う。"}, {"text": "集中力", "is_correct": false, "explanation": "「視覚や集中力を超えた」では感覚と能力が並ばず、香りを読み取る文脈に合わない。"}, {"text": "体力", "is_correct": false, "explanation": "「視覚や体力を超えた」は感覚の並列にならず、香りの分析の文に合わない。"}, {"text": "記憶力", "is_correct": false, "explanation": "「視覚や記憶力を超えた」は感覚の並列にならず、味覚的に再構成する文脈に合わない。"}], "explanations": {"嗅覚": "「視覚や嗅覚を超えた」の嗅覚で、感覚の能力を並べる文に合う。", "集中力": "「視覚や集中力を超えた」では感覚と能力が並ばず、香りを読み取る文脈に合わない。", "体力": "「視覚や体力を超えた」は感覚の並列にならず、香りの分析の文に合わない。", "記憶力": "「視覚や記憶力を超えた」は感覚の並列にならず、味覚的に再構成する文脈に合わない。"}, "sentence_index": 0, "correct_answer": "嗅覚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理の嗅覚が部屋中に広がって、お腹が鳴った。", "explanation": "ここは〈香り〉（漂うにおい）の意味。嗅覚はにおいを感じ取る力で、部屋に広がるにおいそのものは指さないので合わない。"}, {"text": "眼鏡を忘れた日は嗅覚が悪くて、遠くの看板が読めなかった。", "explanation": "ここは〈視力〉の意味。嗅覚はにおいを感じる力で、文字や看板を見る力は表さないので合わない。"}, {"text": "この布は嗅覚がざらざらしていて、手で触ると少しちくちくする。", "explanation": "ここは〈感触〉の意味。手で触れて感じる肌ざわりは、においを感じる嗅覚では言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗅覚", "is_correct": true, "explanation": "鍛える対象として自然で、香りを試す練習の文に合う。"}, {"text": "約束", "is_correct": false, "explanation": "約束は鍛える対象ではなく、「約束を鍛えるために」は不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は鍛えられるものではなく、この文には合わない。"}, {"text": "借金", "is_correct": false, "explanation": "借金は鍛えるものではなく、文脈に合わない。"}], "explanations": {"嗅覚": "鍛える対象として自然で、香りを試す練習の文に合う。", "約束": "約束は鍛える対象ではなく、「約束を鍛えるために」は不自然。", "天気": "天気は鍛えられるものではなく、この文には合わない。", "借金": "借金は鍛えるものではなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "嗅覚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜道で遠くの足音を嗅覚で聞き分けた。", "explanation": "ここは〈聴覚〉の意味。足音を聞き分けるのは耳の働きで、嗅覚では合わない。"}, {"text": "彼は嗅覚が豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。嗅覚はにおいを感じる能力で、知っている情報の量は指さないので合わない。"}, {"text": "年をとって嗅覚が落ち、昨日の約束も忘れてしまう。", "explanation": "ここは〈記憶力〉の意味。覚えておく力は嗅覚では言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鼻の病気で嗅覚を鈍くなり、料理の香りがわからない。", "corrected_sentence": "鼻の病気で嗅覚が鈍くなり、料理の香りがわからない。", "error_description": "「鈍くなる」は主語に「が」を付けて使う。「嗅覚を」は目的語扱いになり誤りで、「嗅覚が鈍くなり」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52374, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は嗅覚に鋭く、遠くの焦げた匂いにもすぐ気づく。", "corrected_sentence": "祖父は嗅覚が鋭く、遠くの焦げた匂いにもすぐ気づく。", "error_description": "「鋭い」は主語に「が」を付けて使う。「嗅覚に」は誤りで、「嗅覚が鋭く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わからない」の主語を示す。「コンテキストがわからないと」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「わからない」は目的語を取らないので、「コンテキストをわからないと」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」では「わからない」の対象を示せず、「コンテキストにわからないと」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「わからない」に合わず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「わからない」の主語を示す。「コンテキストがわからないと」が自然。", "を": "「わからない」は目的語を取らないので、「コンテキストをわからないと」は不自然。", "に": "「に」では「わからない」の対象を示せず、「コンテキストにわからないと」は成り立たない。", "へ": "方向を示す「へ」は「わからない」に合わず、意味が通らない。"}, "error_tags": {"を": "目的語", "に": "場所・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知らない」の目的語を示す。「会話のコンテキストを知らない人」が自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や相手を示すので、「コンテキストと知らない人」は目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「コンテキストより知らない」となり意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「コンテキストの知らない人」は連体修飾として不自然で、「知らない」の目的を示せない。"}], "correct_answer": "を", "explanations": {"を": "「知らない」の目的語を示す。「会話のコンテキストを知らない人」が自然。", "と": "「と」は引用や相手を示すので、「コンテキストと知らない人」は目的語にならない。", "より": "比較の「より」では「コンテキストより知らない」となり意味が通らない。", "の": "「コンテキストの知らない人」は連体修飾として不自然で、「知らない」の目的を示せない。"}, "error_tags": {"と": "引用・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることのまわりにある、そのことをわかりやすくするためのじょうほうのこと。", "primary_collocate": null, "pronunciation": "こんてきすと", "ipa": "kontekisɯto", "syllable_count": 6, "sentences": [{"text": "知らない言葉が出てきたら、コンテキストから意味を考えてみよう。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "知[し]らない言葉[ことば]が出[で]てきたら、コンテキストから意味[いみ]を考[かんが]えてみよう。", "sentence_source": "generated"}, {"text": "コンテキストがわからないと、この文は何を言いたいのかつかめない。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "コンテキストがわからないと、この文[ぶん]は何[なに]を言[い]いたいのかつかめない。", "sentence_source": "generated"}, {"text": "先生は、物語のコンテキストを説明してから、問題を出した。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "先生[せんせい]は、物語[ものがたり]のコンテキストを説明[せつめい]してから、問題[もんだい]を出[だ]した。", "sentence_source": "generated"}, {"text": "前の話を聞いていなかったので、コンテキストがわからず困った。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "前[まえ]の話[はなし]を聞[き]いていなかったので、コンテキストがわからず困[こま]った。", "sentence_source": "generated"}, {"text": "その写真だけでは、コンテキストが足りなくて何があったのかわからない。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "その写真[しゃしん]だけでは、コンテキストが足[た]りなくて何[なに]があったのかわからない。", "sentence_source": "generated"}, {"text": "この「かける」は、コンテキストを見ると「電話をかける」の意味だとわかる。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "この「かける」は、コンテキストを見[み]ると「電話[でんわ]をかける」の意味[いみ]だとわかる。", "sentence_source": "generated"}, {"text": "メールの短い一文も、コンテキストがあれば誤解されにくい。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "メールの短[みじか]い一文[いちぶん]も、コンテキストがあれば誤解[ごかい]されにくい。", "sentence_source": "generated"}, {"text": "会話のコンテキストを知らない人が途中から聞くと、意味がつかみにくい。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "会話[かいわ]のコンテキストを知[し]らない人[ひと]が途中[とちゅう]から聞[き]くと、意味[いみ]がつかみにくい。", "sentence_source": "generated"}, {"text": "辞書の例文は、言葉のコンテキストを示してくれるので役に立つ。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "辞書[じしょ]の例文[れいぶん]は、言葉[ことば]のコンテキストを示[しめ]してくれるので役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "ニュースの一部だけを見ずに、コンテキストまで調べて判断したい。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "ニュースの一部[いちぶ]だけを見[み]ずに、コンテキストまで調[しら]べて判断[はんだん]したい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンテキスト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある事柄のまわりにあり、それを分かりやすくしてくれる情報や前後の話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンテキスト", "is_correct": true, "explanation": "まわりの情報で言葉の意味を考える手がかりを指し、「〜から意味を考える」が成り立つ。"}, {"text": "雨粒", "is_correct": false, "explanation": "空から落ちる水の粒で、「雨粒から意味を考える」は意味が通らない。"}, {"text": "段差", "is_correct": false, "explanation": "床の高低差を表し、「段差から意味を考える」は成り立たない。"}, {"text": "包丁", "is_correct": false, "explanation": "調理道具で、言葉の意味を考える手がかりにはならない。"}], "explanations": {"コンテキスト": "まわりの情報で言葉の意味を考える手がかりを指し、「〜から意味を考える」が成り立つ。", "雨粒": "空から落ちる水の粒で、「雨粒から意味を考える」は意味が通らない。", "段差": "床の高低差を表し、「段差から意味を考える」は成り立たない。", "包丁": "調理道具で、言葉の意味を考える手がかりにはならない。"}, "sentence_index": 0, "correct_answer": "コンテキスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋のコンテキストは、八畳ある。", "explanation": "ここは〈広さ〉の意味。部屋の広さは言えても、コンテキストは理解を助ける情報を指すので、面積には使わない。"}, {"text": "このシャツのコンテキストは、濃い青だ。", "explanation": "ここは〈色〉の意味。服の色は言えても、コンテキストは理解を助ける情報なので合わない。"}, {"text": "この本のコンテキストは、千円だ。", "explanation": "ここは〈値段〉の意味。本の値段はコンテキストとは言わず、定義にも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンテキスト", "is_correct": true, "explanation": "「〜があれば誤解されにくい」の主語として、わかりやすくする情報を指し意味が通る。"}, {"text": "筆箱", "is_correct": false, "explanation": "文房具入れで、メールの一文が誤解されにくいかどうかとは関係がない。"}, {"text": "霧", "is_correct": false, "explanation": "空気中の細かい水滴で、メールの誤解とは無関係で意味が通らない。"}, {"text": "絨毯", "is_correct": false, "explanation": "床に敷く布製品で、メールの誤解を防ぐ条件にはならない。"}], "explanations": {"コンテキスト": "「〜があれば誤解されにくい」の主語として、わかりやすくする情報を指し意味が通る。", "筆箱": "文房具入れで、メールの一文が誤解されにくいかどうかとは関係がない。", "霧": "空気中の細かい水滴で、メールの誤解とは無関係で意味が通らない。", "絨毯": "床に敷く布製品で、メールの誤解を防ぐ条件にはならない。"}, "sentence_index": 6, "correct_answer": "コンテキスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱のコンテキストは、五キロもある。", "explanation": "ここは〈重さ〉の意味。箱の重さは言えても、コンテキストは重さを表さないので合わない。"}, {"text": "この地域のコンテキストは、いつも夏だ。", "explanation": "ここは〈季節〉の意味。地域の季節は言えても、コンテキストは季節を指さないので合わない。"}, {"text": "彼の身長のコンテキストは、百八十センチだ。", "explanation": "ここは〈身長〉の意味。身長は数値で示すが、コンテキストは身長を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "言葉のコンテキストを示されていると、意味がつかみやすい。", "corrected_sentence": "言葉のコンテキストが示されていると、意味がつかみやすい。", "error_description": "「示される」の主語を示す「が」が正しい。「を」は誤りで、正しくは「コンテキストが示される」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52375, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小説のコンテキストを読むば、登場人物の気持ちがわかる。", "corrected_sentence": "小説のコンテキストを読めば、登場人物の気持ちがわかる。", "error_description": "誤りは「読むば」（活用）。正しくは「読めば」。「読む」の仮定形は「読めば」で、「読むば」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「読まない」の目的語を示す。「コンテキストを読まないと」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「読まない」は「に」を目的語に取らないので、「コンテキストに読まない」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「コンテキストの」は名詞を続ける形で、「読まない」の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や相手を示すので、「コンテキストと読まない」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「読まない」の目的語を示す。「コンテキストを読まないと」が自然。", "に": "「読まない」は「に」を目的語に取らないので、「コンテキストに読まない」は不自然。", "の": "「コンテキストの」は名詞を続ける形で、「読まない」の対象を示せない。", "と": "「と」は引用や相手を示すので、「コンテキストと読まない」は意味が通らない。"}, "error_tags": {"に": "場所・方向", "の": "連体修飾", "と": "引用・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を理解するために必要な、その物事を取り巻く状況や背景。", "primary_collocate": null, "pronunciation": "こんてきすと", "ipa": "kontekisɯto", "syllable_count": 6, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "コンテキスト", "complexity_tier": "T4", "furigana": "熟練[じゅくれん]したソムリエは、グラス内[ない]で展開[てんかい]される鉱物的[こうぶつてき]な輪郭[りんかく]や土壌由来[どじょうゆらい]の複雑[ふくざつ]な香気構造[こうきこうぞう]を解読[かいどく]し、視覚[しかく]や嗅覚[きゅうかく]を超[こ]えた土地的[とちてき]コンテキストを味覚的[みかくてき]に再構成[さいこうせい]する。", "sentence_source": "mined"}, {"text": "この言葉の意味は、前後のコンテキストを読まないと正しく理解できない。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "この言葉[ことば]の意味[いみ]は、前後[ぜんご]のコンテキストを読[よ]まないと正[ただ]しく理解[りかい]できない。", "sentence_source": "generated"}, {"text": "文の一部だけを切り取ると、元のコンテキストが失われて誤解を生む。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "文[ぶん]の一部[いちぶ]だけを切[き]り取[と]ると、元[もと]のコンテキストが失[うしな]われて誤解[ごかい]を生[う]む。", "sentence_source": "generated"}, {"text": "翻訳者は、原文のコンテキストに合わせて適切な訳語を選ぶ。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "翻訳者[ほんやくしゃ]は、原文[げんぶん]のコンテキストに合[あ]わせて適切[てきせつ]な訳語[やくご]を選[えら]ぶ。", "sentence_source": "generated"}, {"text": "同じ冗談でも、歴史的なコンテキストを知らない人には少しも面白くない。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "同[おな]じ冗談[じょうだん]でも、歴史的[れきしてき]なコンテキストを知[し]らない人[ひと]には少[すこ]しも面白[おもしろ]くない。", "sentence_source": "generated"}, {"text": "彼の発言は、会議の流れというコンテキストの中で見ると、決して批判ではなかった。", "target_word": "コンテキスト", "complexity_tier": "T4", "furigana": "彼[かれ]の発言[はつげん]は、会議[かいぎ]の流[なが]れというコンテキストの中[なか]で見[み]ると、決[けっ]して批判[ひはん]ではなかった。", "sentence_source": "generated"}, {"text": "引用するときは、コンテキストを無視して都合よく使ってはいけない。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "引用[いんよう]するときは、コンテキストを無視[むし]して都合[つごう]よく使[つか]ってはいけない。", "sentence_source": "generated"}, {"text": "作品を鑑賞するには、作者が生きた時代のコンテキストを知ることが大切だ。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "作品[さくひん]を鑑賞[かんしょう]するには、作者[さくしゃ]が生[い]きた時代[じだい]のコンテキストを知[し]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "AIは長い文章のコンテキストを踏まえて、次に来る言葉を予測する。", "target_word": "コンテキスト", "complexity_tier": "T4", "furigana": "AIは長[なが]い文章[ぶんしょう]のコンテキストを踏[ふ]まえて、次[つぎ]に来[く]る言葉[ことば]を予測[よそく]する。", "sentence_source": "generated"}, {"text": "文化的なコンテキストが違えば、同じ身振りでも意味が変わってしまう。", "target_word": "コンテキスト", "complexity_tier": "T3", "furigana": "文化的[ぶんかてき]なコンテキストが違[ちが]えば、同[おな]じ身振[みぶ]りでも意味[いみ]が変[か]わってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コンテキスト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "言葉や出来事の意味を理解する手がかりになる、前後関係・状況・背景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コンテキスト", "is_correct": true, "explanation": "土地の背景や状況を指し、「土地的〜を味覚的に再構成する」の対象として意味が通る。"}, {"text": "眠気", "is_correct": false, "explanation": "眠さを表す語で、土地の背景を味覚的に再構成するという文には入らない。"}, {"text": "足音", "is_correct": false, "explanation": "歩くときに出る音で、土地の背景を再構成の対象にする文には合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "人と交わす言葉のことで、「土地的挨拶を味覚的に再構成する」は意味をなさない。"}], "explanations": {"コンテキスト": "土地の背景や状況を指し、「土地的〜を味覚的に再構成する」の対象として意味が通る。", "眠気": "眠さを表す語で、土地の背景を味覚的に再構成するという文には入らない。", "足音": "歩くときに出る音で、土地の背景を再構成の対象にする文には合わない。", "挨拶": "人と交わす言葉のことで、「土地的挨拶を味覚的に再構成する」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "コンテキスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布のコンテキストは、ざらざらしている。", "explanation": "ここは〈感触〉の意味。手で触れた感じは布について言えても、コンテキストは理解のための背景を指すので合わない。"}, {"text": "店の中には、古い木の香りが漂う温かいコンテキストがあった。", "explanation": "ここは〈雰囲気〉の意味。場の空気は言えても、コンテキストは理解の背景を指すので合わない。"}, {"text": "彼の話し方には、どこか冷たいコンテキストがあった。", "explanation": "ここは〈印象〉の意味。人に受ける感じはコンテキストとは言わず、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コンテキスト", "is_correct": true, "explanation": "「〜を無視して」の対象として、理解の背景を指す唯一の語で意味が通る。"}, {"text": "指輪", "is_correct": false, "explanation": "装身具の指輪は、引用するときに無視して使う対象として意味が通らない。"}, {"text": "屋根", "is_correct": false, "explanation": "建物の一部で、引用の文脈を無視するという文には入らない。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、引用するときに無視する対象として不自然。"}], "explanations": {"コンテキスト": "「〜を無視して」の対象として、理解の背景を指す唯一の語で意味が通る。", "指輪": "装身具の指輪は、引用するときに無視して使う対象として意味が通らない。", "屋根": "建物の一部で、引用の文脈を無視するという文には入らない。", "窓": "建具で、引用するときに無視する対象として不自然。"}, "sentence_index": 6, "correct_answer": "コンテキスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このケーキのコンテキストは、卵と小麦粉だ。", "explanation": "ここは〈材料〉の意味。材料は作るときの原料で、理解の背景を指すコンテキストとは別物なので合わない。"}, {"text": "この箱のコンテキストは、食器だ。", "explanation": "ここは〈中身〉の意味。箱の中に入っているものはコンテキストとは言わないので合わない。"}, {"text": "この器のコンテキストは、丸い。", "explanation": "ここは〈形〉の意味。器の形は丸いと言えるが、コンテキストは形を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前後のコンテキスト読めば、意味がわかる。", "corrected_sentence": "前後のコンテキストを読めば、意味がわかる。", "error_description": "「読む」の目的語を示す「を」が抜けている。正しくは「コンテキストを読む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52376, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "文章のコンテキストに読むと、著者の本当の意図がわかる。", "corrected_sentence": "文章のコンテキストを読むと、著者の本当の意図がわかる。", "error_description": "「読む」は目的語に「を」を取る。「に」は誤りで、正しくは「コンテキストを読む」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52377, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「敏感で」の主語を示す。「味覚が敏感で」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「敏感」は目的語を取らないので、「味覚を敏感で」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」では「味覚で敏感」となり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、「味覚と敏感で」は主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「敏感で」の主語を示す。「味覚が敏感で」が自然。", "を": "「敏感」は目的語を取らないので、「味覚を敏感で」は不自然。", "で": "手段や場所の「で」では「味覚で敏感」となり、意味が通らない。", "と": "「と」は並列を示すので、「味覚と敏感で」は主語を示せない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
