INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52377, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "食べ物や飲み物の味を感じる力のことです。", "primary_collocate": null, "pronunciation": "みかく", "ipa": "mikakɯ", "syllable_count": 3, "sentences": [{"text": "味覚がおかしくて、今日は何を食べても味がしない。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "味覚[みかく]がおかしくて、今日[きょう]は何[なに]を食[た]べても味[あじ]がしない。", "sentence_source": "generated"}, {"text": "妹は味覚が敏感で、少しでも辛いと食べられない。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "妹[いもうと]は味覚[みかく]が敏感[びんかん]で、少[すこ]しでも辛[から]いと食[た]べられない。", "sentence_source": "generated"}, {"text": "舌は味覚を感じる大切な器官だ。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "舌[した]は味覚[みかく]を感[かん]じる大切[たいせつ]な器官[きかん]だ。", "sentence_source": "generated"}, {"text": "熱いスープを飲んで、一時的に味覚が麻痺してしまった。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "熱[あつ]いスープを飲[の]んで、一時的[いちじてき]に味覚[みかく]が麻痺[まひ]してしまった。", "sentence_source": "generated"}, {"text": "猫は人間より味覚が弱く、甘さをほとんど感じないそうだ。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "猫[ねこ]は人間[にんげん]より味覚[みかく]が弱[よわ]く、甘[あま]さをほとんど感[かん]じないそうだ。", "sentence_source": "generated"}, {"text": "味覚を育てるために、いろいろな食材を子どもに食べさせている。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "味覚[みかく]を育[そだ]てるために、いろいろな食材[しょくざい]を子[こ]どもに食[た]べさせている。", "sentence_source": "generated"}, {"text": "母は料理人だから味覚がよく、薄味か濃い味かすぐわかる。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "母[はは]は料理人[りょうりにん]だから味覚[みかく]がよく、薄味[うすあじ]か濃[こ]い味[あじ]かすぐわかる。", "sentence_source": "generated"}, {"text": "風邪が治って味覚がもどり、ご飯がおいしく感じられた。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "風邪[かぜ]が治[なお]って味覚[みかく]がもどり、ご飯[はん]がおいしく感[かん]じられた。", "sentence_source": "generated"}, {"text": "目隠しをして食べ物の名前を当て、味覚を試した。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "目隠[めかく]しをして食[た]べ物[もの]の名前[なまえ]を当[あ]て、味覚[みかく]を試[ため]した。", "sentence_source": "generated"}, {"text": "苦い薬も、味覚を感じにくくするゼリーに包むと飲みやすい。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "苦[にが]い薬[くすり]も、味覚[みかく]を感[かん]じにくくするゼリーに包[つつ]むと飲[の]みやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "味覚", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "舌で食べ物や飲み物の味を感じる力。日常的な感覚としての味覚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52377, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味覚", "is_correct": true, "explanation": "食べ物の味を感じる力を指し、「〜がおかしくて味がしない」の主語として意味が通る。"}, {"text": "扉", "is_correct": false, "explanation": "出入り口をふさぐ建具で、「扉がおかしくて味がしない」は意味が通らない。"}, {"text": "畳", "is_correct": false, "explanation": "床に敷く敷物で、食べ物の味がしないという文の主語にはならない。"}, {"text": "雲", "is_correct": false, "explanation": "空に浮かぶ水滴の集まりで、「雲がおかしくて味がしない」は成り立たない。"}], "explanations": {"味覚": "食べ物の味を感じる力を指し、「〜がおかしくて味がしない」の主語として意味が通る。", "扉": "出入り口をふさぐ建具で、「扉がおかしくて味がしない」は意味が通らない。", "畳": "床に敷く敷物で、食べ物の味がしないという文の主語にはならない。", "雲": "空に浮かぶ水滴の集まりで、「雲がおかしくて味がしない」は成り立たない。"}, "sentence_index": 0, "correct_answer": "味覚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この香水は味覚が強く、部屋に入るとすぐに匂う。", "explanation": "ここは〈嗅覚〉の意味。匂いを感じるのは嗅覚で、味覚は味を感じる力なので合わない。"}, {"text": "彼は味覚が鋭く、遠くの鈴の音まで聞き分ける。", "explanation": "ここは〈聴覚〉の意味。音を聞き分けるのは聴覚で、味覚は味を感じる力なので合わない。"}, {"text": "熱で味覚が上がり、体がだるい。", "explanation": "ここは〈体温〉の意味。熱が上がるのは体温で、味覚が上がるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52377, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味覚", "is_correct": true, "explanation": "「料理人だから味覚がよく」の主語として、味を感じる力を指し意味が通る唯一の語。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗浄に使う品で、料理人だから石鹸がよいという文は成り立たない。"}, {"text": "手袋", "is_correct": false, "explanation": "手を覆う防寒具や作業具で、料理人の能力を表す主語にはならない。"}, {"text": "屋根", "is_correct": false, "explanation": "建物の上部で、料理人だから屋根がよいという文には入らない。"}], "explanations": {"味覚": "「料理人だから味覚がよく」の主語として、味を感じる力を指し意味が通る唯一の語。", "石鹸": "洗浄に使う品で、料理人だから石鹸がよいという文は成り立たない。", "手袋": "手を覆う防寒具や作業具で、料理人の能力を表す主語にはならない。", "屋根": "建物の上部で、料理人だから屋根がよいという文には入らない。"}, "sentence_index": 6, "correct_answer": "味覚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紅茶は味覚が強い。", "explanation": "ここは〈味〉の意味。紅茶の味の強さは「味が強い」と言い、味覚は味を感じる力なので合わない。"}, {"text": "このお茶は味覚が高すぎる。", "explanation": "ここは〈温度〉の意味。お茶が熱すぎるとは言えるが、味覚に高低は言わないので合わない。"}, {"text": "このパンは味覚がしっかりしている。", "explanation": "ここは〈歯ごたえ〉の意味。噛んだ時の硬さは歯ごたえで、味覚では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52377, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は味覚に確かで、昔ながらの出汁の違いもすぐわかる。", "corrected_sentence": "祖父は味覚が確かで、昔ながらの出汁の違いもすぐわかる。", "error_description": "「確かだ」の主語を示す「が」が正しい。「に」は誤りで、正しくは「味覚が確かだ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52377, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい料理で味覚を食べると、いつもと違う発見がある。", "corrected_sentence": "新しい料理で味覚を試すと、いつもと違う発見がある。", "error_description": "「味覚」と結びつく動詞は「試す」。「食べる」は味覚を対象にできず、正しくは「味覚を試す」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鋭く」の主語を示す。「味覚が鋭く」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「鋭い」は目的語を取らないので、「味覚を鋭く」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「鋭い」に合わず、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「味覚の鋭く」は名詞のように続き、「鋭い」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「鋭く」の主語を示す。「味覚が鋭く」が自然。", "を": "「鋭い」は目的語を取らないので、「味覚を鋭く」は不自然。", "へ": "方向を示す「へ」は「鋭い」に合わず、意味が通らない。", "の": "「味覚の鋭く」は名詞のように続き、「鋭い」の主語を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「信頼している」の目的語を示す。「味覚を信頼している」が自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「味覚と信頼している」は目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「味覚より信頼している」となり意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は「味覚から信頼している」となり、信頼の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「信頼している」の目的語を示す。「味覚を信頼している」が自然。", "と": "「と」は並列や相手を示すので、「味覚と信頼している」は目的語にならない。", "より": "比較の「より」では「味覚より信頼している」となり意味が通らない。", "から": "起点を示す「から」は「味覚から信頼している」となり、信頼の対象を示せない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "食べ物や飲み物の味を感じる感覚や、その味に対する評価。", "primary_collocate": null, "pronunciation": "みかく", "ipa": "mikakɯ", "syllable_count": 3, "sentences": [{"text": "熟練したソムリエは、グラスの中で移り変わる酸味と渋味の釣り合いを見分ける、確かな味覚の持ち主だ。", "target_word": "味覚", "complexity_tier": "T4", "furigana": "熟練[じゅくれん]したソムリエは、グラスの中[なか]で移[うつ]り変[か]わる酸味[さんみ]と渋味[しぶみ]の釣[つ]り合[あ]いを見分[みわ]ける、確[たし]かな味覚[みかく]の持[も]ち主[ぬし]だ。", "sentence_source": "generated"}, {"text": "彼女は味覚が鋭く、料理に入った隠し味まで当てることができる。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は味覚[みかく]が鋭[するど]く、料理[りょうり]に入[はい]った隠[かく]し味[あじ]まで当[あ]てることができる。", "sentence_source": "generated"}, {"text": "子どものころに和食に親しむと、繊細な味覚が育つと言われている。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "子[こ]どものころに和食[わしょく]に親[したし]むと、繊細[せんさい]な味覚[みかく]が育[そだ]つと言[い]われている。", "sentence_source": "generated"}, {"text": "風邪で味覚が鈍くなり、好物のラーメンも味がしなかった。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "風邪[かぜ]で味覚[みかく]が鈍[にぶ]くなり、好物[こうぶつ]のラーメンも味[あじ]がしなかった。", "sentence_source": "generated"}, {"text": "人間の味覚は、甘味・酸味・塩味・苦味・うま味の五つを区別する。", "target_word": "味覚", "complexity_tier": "T4", "furigana": "人間[にんげん]の味覚[みかく]は、甘味[あまみ]・酸味[さんみ]・塩味[しおあじ]・苦味[にがみ]・うま味[み]の五[いつ]つを区別[くべつ]する。", "sentence_source": "generated"}, {"text": "父は味覚が保守的で、新しい料理にはなかなか手を出さない。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "父[ちち]は味覚[みかく]が保守的[ほしゅてき]で、新[あたら]しい料理[りょうり]にはなかなか手[て]を出[だ]さない。", "sentence_source": "generated"}, {"text": "舌にある味蕾が刺激を受けて、味覚として脳に伝わる。", "target_word": "味覚", "complexity_tier": "T4", "furigana": "舌[した]にある味蕾[みらい]が刺激[しげき]を受[う]けて、味覚[みかく]として脳[のう]に伝[つた]わる。", "sentence_source": "generated"}, {"text": "このシェフの味覚を信頼しているから、メニューの選択は任せたい。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "このシェフの味覚[みかく]を信頼[しんらい]しているから、メニューの選択[せんたく]は任[まか]せたい。", "sentence_source": "generated"}, {"text": "年をとると味覚が変わり、昔は苦手だった漬物が好きになった。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "年[とし]をとると味覚[みかく]が変[か]わり、昔[むかし]は苦手[にがて]だった漬物[つけもの]が好[す]きになった。", "sentence_source": "generated"}, {"text": "国によって味覚の好みが違うので、同じ料理でも評価が分かれる。", "target_word": "味覚", "complexity_tier": "T3", "furigana": "国[くに]によって味覚[みかく]の好[この]みが違[ちが]うので、同[おな]じ料理[りょうり]でも評価[ひょうか]が分[わ]かれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "味覚", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "舌で味を感じる感覚、およびその味の良し悪しを見分ける好みや評価の力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): ソムリエ (Zipf 3.22), 移り変わる (Zipf 2.64), 酸味 (Zipf 3.39), 釣り合い (Zipf 2.95), 見分ける (Zipf 3.34)','sentence 4 above tier T3: 5 words above tier T3 (max 3): 酸味 (Zipf 3.39), 塩味 (Zipf 3.16), 苦味 (Zipf 3.18), うま味 (Zipf 2.83), 五つ (Zipf 3.28)']::text[], 'a32b62e3-cca6-43af-a155-156010e398de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味覚", "is_correct": true, "explanation": "舌で味を感じる力を指し、「確かな味覚の持ち主」として文に収まる唯一の語。"}, {"text": "香り", "is_correct": false, "explanation": "においを指す語で、味の釣り合いを見分ける持ち主とは言えず文に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "建具の一つで、味の釣り合いを見分ける持ち主にはならない。"}, {"text": "挨拶", "is_correct": false, "explanation": "人と交わす言葉のことで、味を見分ける持ち主の表現としては成り立たない。"}], "explanations": {"味覚": "舌で味を感じる力を指し、「確かな味覚の持ち主」として文に収まる唯一の語。", "香り": "においを指す語で、味の釣り合いを見分ける持ち主とは言えず文に合わない。", "窓": "建具の一つで、味の釣り合いを見分ける持ち主にはならない。", "挨拶": "人と交わす言葉のことで、味を見分ける持ち主の表現としては成り立たない。"}, "sentence_index": 0, "correct_answer": "味覚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは味覚が濃いので、飲みごたえがある。", "explanation": "ここは〈味〉の意味。料理の味の濃さは「味が濃い」と言い、味覚は感じる力なので合わない。"}, {"text": "このワインは味覚の香りが豊かで、グラスを近づけると花の匂いが広がる。", "explanation": "ここは〈嗅覚〉の意味。香りや匂いを感じるのは嗅覚で、味覚は味を感じる力なので合わない。"}, {"text": "彼は音楽の味覚が鋭く、わずかな音程のずれも聞き分ける。", "explanation": "ここは〈聴覚〉の意味。音程を聞き分けるのは聴覚で、味覚では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味覚", "is_correct": true, "explanation": "「味覚として脳に伝わる」の主語として、感じる力を指し意味が通る唯一の語。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文章のことで、「手紙として脳に伝わる」は意味をなさない。"}, {"text": "旗", "is_correct": false, "explanation": "布でできた標識で、脳に伝わるという文には合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "建物の上部で、刺激が脳に伝わるという文には入らない。"}], "explanations": {"味覚": "「味覚として脳に伝わる」の主語として、感じる力を指し意味が通る唯一の語。", "手紙": "書いた文章のことで、「手紙として脳に伝わる」は意味をなさない。", "旗": "布でできた標識で、脳に伝わるという文には合わない。", "屋根": "建物の上部で、刺激が脳に伝わるという文には入らない。"}, "sentence_index": 6, "correct_answer": "味覚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このシェフは味覚が鋭く、皿の色合いの微妙な違いまで見分ける。", "explanation": "ここは〈視覚〉の意味。色合いを見分けるのは視覚で、味覚は味を感じる力なので合わない。"}, {"text": "指先の味覚で、布の厚さがわかる。", "explanation": "ここは〈触覚〉の意味。布の厚さを指で感じるのは触覚で、味覚では表せないので合わない。"}, {"text": "このパンは味覚がふわふわしている。", "explanation": "ここは〈食感〉の意味。ふわふわした感じは食感で、味覚は味を感じる力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は味覚に鋭く、わずかな違いも当てる。", "corrected_sentence": "彼は味覚が鋭く、わずかな違いも当てる。", "error_description": "「鋭い」の主語を示す「が」が正しい。「に」は誤りで、正しくは「味覚が鋭い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日いろいろな味を試して、味覚を塗ろう。", "corrected_sentence": "毎日いろいろな味を試して、味覚を磨こう。", "error_description": "「味覚」と結びつく動詞は「磨く」。「塗る」は誤りで、正しくは「味覚を磨く」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33beb785-c604-4cc1-84b7-c1a70f29357a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「区画が割り当てられている」の主語。割り当てられる側の区画が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「区画を割り当てられている」は受身文で区画を主語にできず、「を」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「区画と割り当てられている」は並列の「と」になり、割り当てられる主語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「区画の割り当てられている」は連体修飾になり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「区画が割り当てられている」の主語。割り当てられる側の区画が主語になる。", "を": "「区画を割り当てられている」は受身文で区画を主語にできず、「を」は成り立たない。", "と": "「区画と割り当てられている」は並列の「と」になり、割り当てられる主語を示せない。", "の": "「区画の割り当てられている」は連体修飾になり、主語を示せない。"}, "error_tags": {"を": "対象化", "と": "並列", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「危険な区画に入る」の「に」。入る場所を示す。"}, {"text": "の", "is_correct": false, "explanation": "「危険な区画の入るとき」は連体修飾の「の」になり、動詞「入る」の場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「危険な区画が入るとき」は区画を主語にする形で、人が入る場面と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「区画で入る」は場所の「で」が移動の動詞「入る」と結べず、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「危険な区画に入る」の「に」。入る場所を示す。", "の": "「危険な区画の入るとき」は連体修飾の「の」になり、動詞「入る」の場所を示せない。", "が": "「危険な区画が入るとき」は区画を主語にする形で、人が入る場面と合わない。", "で": "「区画で入る」は場所の「で」が移動の動詞「入る」と結べず、文として成り立たない。"}, "error_tags": {"の": "連体", "が": "主語", "で": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所をいくつかに分けた、一つ一つの場所。", "primary_collocate": null, "pronunciation": "くかく", "ipa": "kɯkakɯ", "syllable_count": 3, "sentences": [{"text": "市場は食品の区画と衣料品の区画に分かれていて、買い物しやすい。", "target_word": "区画", "complexity_tier": "T3", "furigana": "市場(いちば)は食品(しょくひん)の区画(くかく)と衣料品(いりょうひん)の区画(くかく)に分(わ)かれていて、買(か)い物(もの)しやすい。", "sentence_source": "generated"}, {"text": "この団地では、各家庭に庭の区画が割り当てられている。", "target_word": "区画", "complexity_tier": "T3", "furigana": "この団地(だんち)では、各家庭(かくかてい)に庭(にわ)の区画(くかく)が割(わ)り当(あ)てられている。", "sentence_source": "generated"}, {"text": "キャンプ場で、テントを張る区画を予約した。", "target_word": "区画", "complexity_tier": "T2", "furigana": "キャンプ場(じょう)で、テントを張(は)る区画(くかく)を予約(よやく)した。", "sentence_source": "generated"}, {"text": "駅前の区画は再開発のため、来月から立ち入りができなくなる。", "target_word": "区画", "complexity_tier": "T4", "furigana": "駅前(えきまえ)の区画(くかく)は再開発(さいかいはつ)のため、来月(らいげつ)から立(た)ち入(い)りができなくなる。", "sentence_source": "generated"}, {"text": "図書館の児童書の区画には、小さな椅子が並んでいる。", "target_word": "区画", "complexity_tier": "T3", "furigana": "図書館(としょかん)の児童書(じどうしょ)の区画(くかく)には、小(ちい)さな椅子(いす)が並(なら)んでいる。", "sentence_source": "generated"}, {"text": "墓地の区画は広さによって料金が違う。", "target_word": "区画", "complexity_tier": "T3", "furigana": "墓地(ぼち)の区画(くかく)は広(ひろ)さによって料金(りょうきん)が違(ちが)う。", "sentence_source": "generated"}, {"text": "市は住宅地の区画を整え、道路を新しく通した。", "target_word": "区画", "complexity_tier": "T3", "furigana": "市(し)は住宅地(じゅうたくち)の区画(くかく)を整(ととの)え、道路(どうろ)を新(あたら)しく通(とお)した。", "sentence_source": "generated"}, {"text": "工場の危険な区画に入るときは、ヘルメットをかぶらなければならない。", "target_word": "区画", "complexity_tier": "T3", "furigana": "工場(こうじょう)の危険(きけん)な区画(くかく)に入(はい)るときは、ヘルメットをかぶらなければならない。", "sentence_source": "generated"}, {"text": "田んぼの区画が小さい地域では、大きな機械が使いにくい。", "target_word": "区画", "complexity_tier": "T3", "furigana": "田(た)んぼの区画(くかく)が小(ちい)さい地域(ちいき)では、大(おお)きな機械(きかい)が使(つか)いにくい。", "sentence_source": "generated"}, {"text": "海の漁場を区画ごとに決めて、漁師が順番に使っている。", "target_word": "区画", "complexity_tier": "T4", "furigana": "海(うみ)の漁場(ぎょば)を区画(くかく)ごとに決(き)めて、漁師(りょうし)が順番(じゅんばん)に使(つか)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "区画", "label": "基本形"}, {"form": "区画ごと", "label": "ごと形"}], "register": "neutral", "sense_fingerprint": "ある場所を分けてできた、個々の場所やスペース", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区画", "is_correct": true, "explanation": "売り場を区切った一つ一つの場所を指し、「食品の区画と衣料品の区画」と自然に成り立つ。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は歌の言葉を指し、売り場の区切りを表さないため「食品の歌詞」は成り立たない。"}, {"text": "火山", "is_correct": false, "explanation": "火山は地形の一種を指し、市場の売り場の区切りとは結びつかない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は存続期間を指し、「食品の寿命と衣料品の寿命」は文の意味に合わない。"}], "explanations": {"区画": "売り場を区切った一つ一つの場所を指し、「食品の区画と衣料品の区画」と自然に成り立つ。", "歌詞": "歌詞は歌の言葉を指し、売り場の区切りを表さないため「食品の歌詞」は成り立たない。", "火山": "火山は地形の一種を指し、市場の売り場の区切りとは結びつかない。", "寿命": "寿命は存続期間を指し、「食品の寿命と衣料品の寿命」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "区画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新幹線は東京から大阪までの区画を、一度も止まらずに走る。", "explanation": "ここは〈区間〉の意味。区画は区切られた場所の区域を指し、路線上の区間には使わない。"}, {"text": "この本は全部で十の区画からなっている。", "explanation": "ここは〈節〉の意味。区画は場所の区切りを指し、文章の節には使わない。"}, {"text": "この家は区画が三つあり、それぞれを寝室にしている。", "explanation": "ここは〈部屋〉の意味。区画は区切られた土地や場所の区域を指し、建物の部屋には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区画", "is_correct": true, "explanation": "住宅地を区切った一つ一つの区域を指し、「住宅地の区画を整え」と自然に成り立つ。"}, {"text": "紙幣", "is_correct": false, "explanation": "紙幣は紙のお金を指し、住宅地を整える対象にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は小物を指し、住宅地の区域とは関係しないため文に合わない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の動きを指し、「住宅地の感情を整え」は意味が通らない。"}], "explanations": {"区画": "住宅地を区切った一つ一つの区域を指し、「住宅地の区画を整え」と自然に成り立つ。", "紙幣": "紙幣は紙のお金を指し、住宅地を整える対象にはならない。", "財布": "財布は小物を指し、住宅地の区域とは関係しないため文に合わない。", "感情": "感情は心の動きを指し、「住宅地の感情を整え」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "区画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この調査は、年齢の区画ごとに結果を集計している。", "explanation": "ここは〈区分〉の意味。区画は場所を区切った区域を指し、年齢などの分類には使わない。"}, {"text": "この図鑑には、虫の区画が千もあり、見つけにくい。", "explanation": "ここは〈種類〉の意味。区画は区切られた場所を指し、生き物の種類には使わない。"}, {"text": "この料理は、手順の区画ごとに材料を入れる。", "explanation": "ここは〈段階〉の意味。区画は場所の区切りを指し、手順の進み具合の区切りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の区画へ、駐輪場が作られている。", "corrected_sentence": "駅前の区画に、駐輪場が作られている。", "error_description": "正しくは「区画に作られている」。作られる場所は「に」で示す。「へ」は方向を表すので、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52379, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "住宅地の区画は、市によって整えた。", "corrected_sentence": "住宅地の区画は、市によって整えられた。", "error_description": "正しくは受身の「整えられた」。区画は整えられる側（主語）なので、能動の「整えた」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「区画に分けられ」の「に」。分ける結果の区切りを示す。"}, {"text": "が", "is_correct": false, "explanation": "「区画が分けられ」は区画を主語にする形になり、結果の対象を示せないので文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「区画と分けられ」は「AとBに分ける」の形と合わず、結果を示す「に」の代わりにならない。"}, {"text": "の", "is_correct": false, "explanation": "「四つの区画の分けられ」は連体修飾になり、受身の主語を示せない。"}], "correct_answer": "に", "explanations": {"に": "「区画に分けられ」の「に」。分ける結果の区切りを示す。", "が": "「区画が分けられ」は区画を主語にする形になり、結果の対象を示せないので文が成り立たない。", "と": "「区画と分けられ」は「AとBに分ける」の形と合わず、結果を示す「に」の代わりにならない。", "の": "「四つの区画の分けられ」は連体修飾になり、受身の主語を示せない。"}, "error_tags": {"が": "主語化", "と": "並列", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「区画に分けてある」の「に」。内部を分けた結果の区切りを示す。"}, {"text": "を", "is_correct": false, "explanation": "「区画を分けてある」は区画を分けられる対象にする形で、ここでは内部を区画に分けるという文の構造と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「区画の分けてある」は連体修飾の「の」になり、動詞「分けてある」の結果を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「区画より分けてある」は比較の「より」になり、分けた結果を示す用法と合わない。"}], "correct_answer": "に", "explanations": {"に": "「区画に分けてある」の「に」。内部を分けた結果の区切りを示す。", "を": "「区画を分けてある」は区画を分けられる対象にする形で、ここでは内部を区画に分けるという文の構造と合わない。", "の": "「区画の分けてある」は連体修飾の「の」になり、動詞「分けてある」の結果を示せない。", "より": "「区画より分けてある」は比較の「より」になり、分けた結果を示す用法と合わない。"}, "error_tags": {"を": "対象", "の": "連体", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "土地や地域などをいくつかに区切った一つ一つの区域。また、その区切り。", "primary_collocate": null, "pronunciation": "くかく", "ipa": "kɯkakɯ", "syllable_count": 3, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "区画", "complexity_tier": "T5", "furigana": "かかる感覚的(かんかくてき)知見(ちけん)の蓄積(ちくせき)は、単一(たんいつ)品種(ひんしゅ)を基準(きじゅん)とした旧来(きゅうらい)の分類(ぶんるい)体系(たいけい)を相対化(そうたいか)し、微細(びさい)な区画(くかく)ごとの個性(こせい)を階層的(かいそうてき)に位置(いち)づけるアペラシオンの概念(がいねん)を、より厳密(げんみつ)かつ動的(どうてき)なヒエラルキーへと昇華(しょうか)させ、ワインの価値(かち)評価(ひょうか)基準(きじゅん)そのものを哲学的(てつがくてき)かつ実践的(じっせんてき)に再定義(さいていぎ)しているのである。", "sentence_source": "mined"}, {"text": "農場は四つの区画に分けられ、それぞれ違う野菜が育てられている。", "target_word": "区画", "complexity_tier": "T3", "furigana": "農場(のうじょう)は四(よっ)つの区画(くかく)に分(わ)けられ、それぞれ違(ちが)う野菜(やさい)が育(そだ)てられている。", "sentence_source": "generated"}, {"text": "駐車場は区画ごとに番号がふってあるので、自分の車の場所がすぐ分かる。", "target_word": "区画", "complexity_tier": "T3", "furigana": "駐車場(ちゅうしゃじょう)は区画(くかく)ごとに番号(ばんごう)がふってあるので、自分(じぶん)の車(くるま)の場所(ばしょ)がすぐ分(わ)かる。", "sentence_source": "generated"}, {"text": "この町は道が碁盤の目のように走り、整然とした区画が続いている。", "target_word": "区画", "complexity_tier": "T4", "furigana": "この町(まち)は道(みち)が碁盤(ごばん)の目(め)のように走(はし)り、整然(せいぜん)とした区画(くかく)が続(つづ)いている。", "sentence_source": "generated"}, {"text": "古い区画には細い路地が多いが、新しい区画は道幅が広い。", "target_word": "区画", "complexity_tier": "T3", "furigana": "古(ふる)い区画(くかく)には細(ほそ)い路地(ろじ)が多(おお)いが、新(あたら)しい区画(くかく)は道幅(みちはば)が広(ひろ)い。", "sentence_source": "generated"}, {"text": "畑の区画を一つ借りて、週末だけ家庭菜園を楽しんでいる。", "target_word": "区画", "complexity_tier": "T3", "furigana": "畑(はたけ)の区画(くかく)を一(ひと)つ借(か)りて、週末(しゅうまつ)だけ家庭菜園(かていさいえん)を楽(たの)しんでいる。", "sentence_source": "generated"}, {"text": "展示会場は区画ごとにテーマが違うので、見たい展示を先に決めておくとよい。", "target_word": "区画", "complexity_tier": "T3", "furigana": "展示会場(てんじかいじょう)は区画(くかく)ごとにテーマが違(ちが)うので、見(み)たい展示(てんじ)を先(さき)に決(き)めておくとよい。", "sentence_source": "generated"}, {"text": "火事が広がらないよう、倉庫の内部は防火用の区画に分けてある。", "target_word": "区画", "complexity_tier": "T4", "furigana": "火事(かじ)が広(ひろ)がらないよう、倉庫(そうこ)の内部(ないぶ)は防火用(ぼうかよう)の区画(くかく)に分(わ)けてある。", "sentence_source": "generated"}, {"text": "分譲地の区画が決まり、買い手は好きな場所を選べるようになった。", "target_word": "区画", "complexity_tier": "T4", "furigana": "分譲地(ぶんじょうち)の区画(くかく)が決(き)まり、買(か)い手(て)は好(す)きな場所(ばしょ)を選(えら)べるようになった。", "sentence_source": "generated"}, {"text": "図面の上で、この区画だけが赤い線で囲まれている。", "target_word": "区画", "complexity_tier": "T3", "furigana": "図面(ずめん)の上(うえ)で、この区画(くかく)だけが赤(あか)い線(せん)で囲(かこ)まれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "区画", "label": "基本形"}, {"form": "区画ごと", "label": "ごと形"}], "register": "neutral", "sense_fingerprint": "土地や地域を区切ってできた個々の区域、またその区切りそのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: アペラシオン (Zipf 1.01)']::text[], '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区画", "is_correct": true, "explanation": "「微細な区画ごとの個性」は、土地や地域を区切った区域として自然に成り立つ。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の動きを指し、土地を区切った区域を表さないため「微細な感情ごと」は成り立たない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の温度を指し、区切られた場所を表せないため文に合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生き物や物の存続期間を指し、「微細な寿命ごと」は意味が通らない。"}], "explanations": {"区画": "「微細な区画ごとの個性」は、土地や地域を区切った区域として自然に成り立つ。", "感情": "感情は心の動きを指し、土地を区切った区域を表さないため「微細な感情ごと」は成り立たない。", "体温": "体温は人の体の温度を指し、区切られた場所を表せないため文に合わない。", "寿命": "寿命は生き物や物の存続期間を指し、「微細な寿命ごと」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "区画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新幹線は大阪から東京までの区画を、途中で止まらずに走り抜ける。", "explanation": "ここは〈区間〉の意味。区画は土地や場所を区切った区域を指し、路線上の区間には使わない。"}, {"text": "試験の区画は教科書の三章までと発表された。", "explanation": "ここは〈範囲〉の意味。区画は区切られた場所を指し、試験で扱う内容の広がりには使わない。"}, {"text": "この作文は、三つの区画に分けて書くと読みやすい。", "explanation": "ここは〈段落〉の意味。区画は場所の区切りを指し、文章の段落には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区画", "is_correct": true, "explanation": "「展示会場は区画ごとにテーマが違う」の区画。展示の場所を区切る単位として自然。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合を指し、展示を区切る単位にはならない。"}, {"text": "音色", "is_correct": false, "explanation": "音色は音の質を指し、会場を区切る単位として成り立たない。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ることを指し、「睡眠ごとにテーマが違う」は意味が通らない。"}], "explanations": {"区画": "「展示会場は区画ごとにテーマが違う」の区画。展示の場所を区切る単位として自然。", "湿度": "湿度は空気中の水分の割合を指し、展示を区切る単位にはならない。", "音色": "音色は音の質を指し、会場を区切る単位として成り立たない。", "睡眠": "睡眠は眠ることを指し、「睡眠ごとにテーマが違う」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "区画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この計算は、一つの区画を一キロとして行う。", "explanation": "ここは〈単位〉の意味。区画は区切られた場所を指し、長さや量の基準には使わない。"}, {"text": "この小説は全部で十の区画からできている。", "explanation": "ここは〈章〉の意味。区画は場所の区切りを指し、本の章には使わない。"}, {"text": "この詩は、一つ一つの区画が短くて読みやすい。", "explanation": "ここは〈行〉の意味。区画は場所を区切った区域を指し、詩の一行には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駐車場の区画を、それぞれ番号がふってある。", "corrected_sentence": "駐車場の区画には、それぞれ番号がふってある。", "error_description": "正しくは「区画には番号がふってある」。「番号がふってある」は場所を「に」で示すので、「を」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52380, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "住宅地を、道路で区画されている。", "corrected_sentence": "住宅地は道路で区画されている。", "error_description": "正しくは「住宅地は道路で区画されている」。受身文の主語は「は」で示し、「を」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「生徒の個性を大切にする」と、大切にする対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「大切にする」は「〜を」で対象を取るので、「個性に大切にする」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、大切にする対象を示さないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「個性と大切にする」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「生徒の個性を大切にする」と、大切にする対象を示す「を」。", "に": "「大切にする」は「〜を」で対象を取るので、「個性に大切にする」は成り立たない。", "へ": "方向の「へ」は、大切にする対象を示さないので合わない。", "と": "「と」は並列や引用を示し、「個性と大切にする」は文として成り立たない。"}, "error_tags": {"に": "位置・方向格", "へ": "方向格", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「個性がある」と、存在するものを主語として示す「が」。"}, {"text": "より", "is_correct": false, "explanation": "「個性よりある」は比較の基準を示すが、存在の文として成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「個性からある」は起点を示すが、「ある」の主語にはならないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「個性をある」は目的語として成り立たず、存在を表す文に合わないので合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「個性がある」と、存在するものを主語として示す「が」。", "より": "「個性よりある」は比較の基準を示すが、存在の文として成り立たないので合わない。", "から": "「個性からある」は起点を示すが、「ある」の主語にはならないので合わない。", "を": "「個性をある」は目的語として成り立たず、存在を表す文に合わないので合わない。"}, "error_tags": {"より": "比較格", "から": "起点格", "を": "目的格（ある に不適合）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "それぞれの人やものだけがもつ、ほかとはちがうところ。", "primary_collocate": null, "pronunciation": "こせい", "ipa": "koseː", "syllable_count": 3, "sentences": [{"text": "双子でも、性格や好みなど、一人ひとり個性がある。", "target_word": "個性", "complexity_tier": "T3", "furigana": "双子[ふたご]でも、性格[せいかく]や好[この]みなど、一人[ひとり]ひとり個性[こせい]がある。", "sentence_source": "generated"}, {"text": "この学校は、生徒の個性を大切にしています。", "target_word": "個性", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、生徒[せいと]の個性[こせい]を大切[たいせつ]にしています。", "sentence_source": "generated"}, {"text": "同じ制服を着ていても、それぞれの個性は消えない。", "target_word": "個性", "complexity_tier": "T3", "furigana": "同[おな]じ制服[せいふく]を着[き]ていても、それぞれの個性[こせい]は消[き]えない。", "sentence_source": "generated"}, {"text": "彼女の絵には、ほかの人にはない個性が出ている。", "target_word": "個性", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の絵[え]には、ほかの人[ひと]にはない個性[こせい]が出[で]ている。", "sentence_source": "generated"}, {"text": "個性を伸ばすために、好きなことを自由にやらせた。", "target_word": "個性", "complexity_tier": "T3", "furigana": "個性[こせい]を伸[の]ばすために、好[す]きなことを自由[じゆう]にやらせた。", "sentence_source": "generated"}, {"text": "犬も人間と同じで、一匹ごとに個性が違う。", "target_word": "個性", "complexity_tier": "T3", "furigana": "犬[いぬ]も人間[にんげん]と同[おな]じで、一匹[いっぴき]ごとに個性[こせい]が違[ちが]う。", "sentence_source": "generated"}, {"text": "みんなと同じ意見ばかりだと、個性がなくなってしまう。", "target_word": "個性", "complexity_tier": "T3", "furigana": "みんなと同[おな]じ意見[いけん]ばかりだと、個性[こせい]がなくなってしまう。", "sentence_source": "generated"}, {"text": "このお店のカレーには、他の店にはない個性がある。", "target_word": "個性", "complexity_tier": "T3", "furigana": "このお店[みせ]のカレーには、他[ほか]の店[みせ]にはない個性[こせい]がある。", "sentence_source": "generated"}, {"text": "先生は子どもの個性を見て、それぞれに合った教え方をする。", "target_word": "個性", "complexity_tier": "T3", "furigana": "先生[せんせい]は子[こ]どもの個性[こせい]を見[み]て、それぞれに合[あ]った教[おし]え方[かた]をする。", "sentence_source": "generated"}, {"text": "自分の個性を出したくて、髪型を変えた。", "target_word": "個性", "complexity_tier": "T3", "furigana": "自分[じぶん]の個性[こせい]を出[だ]したくて、髪型[かみがた]を変[か]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個性", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人やものそれぞれに固有の、他と違う特徴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個性", "is_correct": true, "explanation": "正解。一人ひとりに備わる、他とは違う特徴を表す「個性」が合う。"}, {"text": "天気", "is_correct": false, "explanation": "「一人ひとり天気がある」は成り立たず、性格や好みの文脈に合わない。"}, {"text": "足音", "is_correct": false, "explanation": "「一人ひとり足音がある」は性格や好みの話と結びつかず、不自然。"}, {"text": "地震", "is_correct": false, "explanation": "「一人ひとり地震がある」は意味をなさず、性格の話に合わない。"}], "explanations": {"個性": "正解。一人ひとりに備わる、他とは違う特徴を表す「個性」が合う。", "天気": "「一人ひとり天気がある」は成り立たず、性格や好みの文脈に合わない。", "足音": "「一人ひとり足音がある」は性格や好みの話と結びつかず、不自然。", "地震": "「一人ひとり地震がある」は意味をなさず、性格の話に合わない。"}, "sentence_index": 0, "correct_answer": "個性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は体格ではなく、特技として個性に恵まれていて、どんな楽器も弾きこなす。", "explanation": "個性は人やものの特徴を表す語で、特技や技能の意味では使わないので合わない。"}, {"text": "その会社は個性の利益を優先している。", "explanation": "個性は特徴を表す語で、「利益」と結びつかず、文として成り立たないので合わない。"}, {"text": "この部品は個性が高く、壊れにくい。", "explanation": "個性は特徴を表す語で、部品の出来のよさは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個性", "is_correct": true, "explanation": "正解。同じ意見ばかりだと失われる、一人ひとりの特徴として「個性」が合う。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息がなくなる」は意味が通らず、意見の話とは結びつかない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は意見の傾向と関係せず、「同じ意見ばかり」の文脈に合わない。"}, {"text": "駐車場", "is_correct": false, "explanation": "「駐車場がなくなる」は意見の話と関係せず、文脈に合わない。"}], "explanations": {"個性": "正解。同じ意見ばかりだと失われる、一人ひとりの特徴として「個性」が合う。", "寝息": "「寝息がなくなる」は意味が通らず、意見の話とは結びつかない。", "体温": "体温は意見の傾向と関係せず、「同じ意見ばかり」の文脈に合わない。", "駐車場": "「駐車場がなくなる」は意見の話と関係せず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "個性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は体格に恵まれていて、個性の強さで力が強い。", "explanation": "個性は特徴を表す語で、体の大きさや骨格は表さないので合わない。"}, {"text": "彼女は顔立ちが整っていて、個性も美しく整っている。", "explanation": "個性は内面や特徴を指す語で、顔の造りには使わないので合わない。"}, {"text": "この教科の個性が上がった。", "explanation": "個性は点数や評価の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同じ課題でも、解き方には生徒ごとの個性を表れる。", "corrected_sentence": "同じ課題でも、解き方には生徒ごとの個性が表れる。", "error_description": "「表れる」は自動詞で、主語の「個性」を「が」で示す。「を」は誤りで、正しくは「個性が表れる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52381, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "絵の具を混ぜても、描く人の個性は残られる。", "corrected_sentence": "絵の具を混ぜても、描く人の個性は残る。", "error_description": "「残る」は自動詞で、受け身の「残られる」は使えない。正しくは「個性は残る」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
