INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52383, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "むかしからある、今までと同じであること。", "primary_collocate": null, "pronunciation": "きゅうらい", "ipa": "kʲɯːrai", "syllable_count": 4, "sentences": [{"text": "祭りは旧来どおり、秋の最初の日曜日に行われた。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "祭(まつ)りは旧来(きゅうらい)どおり、秋(あき)の最初(さいしょ)の日曜日(にちようび)に行(おこな)われた。", "sentence_source": "generated"}, {"text": "店の味は旧来のままで、昔のお客さんが安心して通っている。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "店(みせ)の味(あじ)は旧来(きゅうらい)のままで、昔(むかし)のお客(きゃく)さんが安心(あんしん)して通(かよ)っている。", "sentence_source": "generated"}, {"text": "新しい方式は始まったが、細かい手続きは旧来どおりだ。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "新(あたら)しい方式(ほうしき)は始(はじ)まったが、細(こま)かい手続(てつづ)きは旧来(きゅうらい)どおりだ。", "sentence_source": "generated"}, {"text": "この村では、旧来の暮らし方が今も変わらず続いている。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "この村(むら)では、旧来(きゅうらい)の暮(く)らし方(かた)が今(いま)も変(か)わらず続(つづ)いている。", "sentence_source": "generated"}, {"text": "規則が変わっても、旧来の習わしを守る家は多い。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "規則(きそく)が変(か)わっても、旧来(きゅうらい)の習(なら)わしを守(まも)る家(いえ)は多(おお)い。", "sentence_source": "generated"}, {"text": "彼は旧来の習わしに従って、毎年同じ店で食事をする。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "彼(かれ)は旧来(きゅうらい)の習(なら)わしに従(したが)って、毎年(まいとし)同(おな)じ店(みせ)で食事(しょくじ)をする。", "sentence_source": "generated"}, {"text": "設備は旧来のものをそのまま使っているので、見た目が少し古い。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "設備(せつび)は旧来(きゅうらい)のものをそのまま使(つか)っているので、見(み)た目(め)が少(すこ)し古(ふる)い。", "sentence_source": "generated"}, {"text": "旧来の形を守る商店街は、今も朝市でにぎわっている。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "旧来(きゅうらい)の形(かたち)を守(まも)る商店街(しょうてんがい)は、今(いま)も朝市(あさいち)でにぎわっている。", "sentence_source": "generated"}, {"text": "道の名前は旧来の呼び方が残っていて、地元の人はそれで呼ぶ。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "道(みち)の名前(なまえ)は旧来(きゅうらい)の呼(よ)び方(かた)が残(のこ)っていて、地元(じもと)の人(ひと)はそれで呼(よ)ぶ。", "sentence_source": "generated"}, {"text": "仕組みを改めたといっても、実際は旧来と変わらない。", "target_word": "旧来", "complexity_tier": "T4", "furigana": "仕組(しく)みを改(あらた)めたといっても、実際(じっさい)は旧来(きゅうらい)と変(か)わらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "旧来", "label": "基本形"}, {"form": "旧来の", "label": "連体形"}, {"form": "旧来どおり", "label": "どおり形"}], "register": "neutral", "sense_fingerprint": "昔からあり、今までと変わらず同じであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52383, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧来", "is_correct": true, "explanation": "「旧来どおり」は今までと同じように、の意味になり、祭りが例年どおり行われた文脈に合う。"}, {"text": "乗客", "is_correct": false, "explanation": "「乗客どおり」は意味をなさず、祭りの様子を表せない。"}, {"text": "石炭", "is_correct": false, "explanation": "「石炭どおり」は意味をなさず、この文脈に入らない。"}, {"text": "海水", "is_correct": false, "explanation": "「海水どおり」は意味をなさず、祭りの説明として成り立たない。"}], "explanations": {"旧来": "「旧来どおり」は今までと同じように、の意味になり、祭りが例年どおり行われた文脈に合う。", "乗客": "「乗客どおり」は意味をなさず、祭りの様子を表せない。", "石炭": "「石炭どおり」は意味をなさず、この文脈に入らない。", "海水": "「海水どおり」は意味をなさず、祭りの説明として成り立たない。"}, "sentence_index": 0, "correct_answer": "旧来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の会見では、旧来の首相が新しい政策を発表した。", "explanation": "ここは〈元首相〉の意味。辞めた前の地位を指す語で、旧来は「今までと同じ」の意味なので合わない。"}, {"text": "この機械は旧来なので、部品がもう手に入らない。", "explanation": "ここは〈旧式〉の意味。機械の古さは「旧式」で表し、旧来は「今までと同じ」を表すので、機械には合わない。"}, {"text": "引っ越す前に、旧来の家の荷物を片付けた。", "explanation": "ここは〈旧居〉の意味。住んでいた家を指す語で、旧来は「今までと同じ」の意味なので、家には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52383, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧来", "is_correct": true, "explanation": "「旧来のもの」は今までと同じものを指し、設備がそのまま使われている文脈に合う。"}, {"text": "花粉", "is_correct": false, "explanation": "「花粉のもの」は意味をなさず、設備の説明にならない。"}, {"text": "紙吹雪", "is_correct": false, "explanation": "「紙吹雪のもの」は意味をなさず、設備を表す語として成り立たない。"}, {"text": "海水", "is_correct": false, "explanation": "「海水のもの」は意味をなさず、設備の説明として成り立たない。"}], "explanations": {"旧来": "「旧来のもの」は今までと同じものを指し、設備がそのまま使われている文脈に合う。", "花粉": "「花粉のもの」は意味をなさず、設備の説明にならない。", "紙吹雪": "「紙吹雪のもの」は意味をなさず、設備を表す語として成り立たない。", "海水": "「海水のもの」は意味をなさず、設備の説明として成り立たない。"}, "sentence_index": 6, "correct_answer": "旧来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "久しぶりに旧来と会って、学生時代の話をした。", "explanation": "ここは〈旧友〉の意味。昔の友人という人を指す語で、旧来は「今までと同じ」の意味なので、人には使えない。"}, {"text": "観光客は旧来を見に、遠くから訪れている。", "explanation": "ここは〈旧跡〉の意味。史跡を指す語で、旧来は「今までと同じ」を表すので、見物の対象にはならない。"}, {"text": "大学では旧来を読むのが好きだった。", "explanation": "ここは〈古典〉の意味。書物を指す語で、旧来は昔からの状態を表すため、本の名前には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52383, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この寺の儀式は旧来を同じだ。", "corrected_sentence": "この寺の儀式は旧来と同じだ。", "error_description": "「同じ」は「〜と同じ」の形で使うので「と」が必要。「を」は誤りで、正しくは「旧来と同じ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52383, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看板は旧来なままだが、中身は新しくなった。", "corrected_sentence": "看板は旧来のままだが、中身は新しくなった。", "error_description": "「旧来」は名詞なので、「なまま」ではなく「のまま」で続ける。「旧来なまま」は誤りで、正しくは「旧来のまま」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「旧来」と「やり方」を結ぶ連体修飾の「の」で、ここに必要。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「旧来をやり方に頼る」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」を続けると「旧来にやり方に」と格助詞が重なり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「旧来でやり方」では名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「旧来」と「やり方」を結ぶ連体修飾の「の」で、ここに必要。", "を": "「を」は目的語を示す。「旧来をやり方に頼る」では文が成り立たない。", "に": "「に」を続けると「旧来にやり方に」と格助詞が重なり、文が成り立たない。", "で": "「で」は手段や場所を示す。「旧来でやり方」では名詞を修飾できない。"}, "error_tags": {"を": "object_marker", "に": "dative_or_goal", "で": "means_or_location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「旧来」と「価値観」を結ぶ連体修飾の「の」で、ここに必要。"}, {"text": "に", "is_correct": false, "explanation": "「に」を続けると「旧来に価値観」となり、名詞を結べない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「旧来へ価値観」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「旧来で価値観に疑問」は名詞を結ぶ形として不自然。"}], "correct_answer": "の", "explanations": {"の": "「旧来」と「価値観」を結ぶ連体修飾の「の」で、ここに必要。", "に": "「に」を続けると「旧来に価値観」となり、名詞を結べない。", "へ": "「へ」は方向を示す。「旧来へ価値観」は文として成り立たない。", "で": "「で」は手段を示すが、「旧来で価値観に疑問」は名詞を結ぶ形として不自然。"}, "error_tags": {"に": "dative_or_goal", "へ": "direction", "で": "means_or_location"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これまでずっと続いてきた、昔からのやり方や考え方。従来。", "primary_collocate": null, "pronunciation": "きゅうらい", "ipa": "kʲɯːrai", "syllable_count": 4, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "旧来", "complexity_tier": "T5", "furigana": "かかる感覚的(かんかくてき)知見(ちけん)の蓄積(ちくせき)は、単一(たんいつ)品種(ひんしゅ)を基準(きじゅん)とした旧来(きゅうらい)の分類(ぶんるい)体系(たいけい)を相対化(そうたいか)し、微細(びさい)な区画(くかく)ごとの個性(こせい)を階層的(かいそうてき)に位置(いち)づけるアペラシオンの概念(がいねん)を、より厳密(げんみつ)かつ動的(どうてき)なヒエラルキーへと昇華(しょうか)させ、ワインの価値(かち)評価(ひょうか)基準(きじゅん)そのものを哲学的(てつがくてき)かつ実践的(じっせんてき)に再定義(さいていぎ)しているのである。", "sentence_source": "mined"}, {"text": "旧来のやり方に頼っていては、変化の速い市場で生き残れない。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "旧来(きゅうらい)のやり方(かた)に頼(たよ)っていては、変化(へんか)の速(はや)い市場(しじょう)で生(い)き残(のこ)れない。", "sentence_source": "generated"}, {"text": "新しい社長は、旧来の慣習を一つずつ見直していった。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "新(あたら)しい社長(しゃちょう)は、旧来(きゅうらい)の慣習(かんしゅう)を一(ひと)つずつ見直(みなお)していった。", "sentence_source": "generated"}, {"text": "この町には、旧来の考え方を大事にする人がまだ多い。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "この町(まち)には、旧来(きゅうらい)の考(かんが)え方(かた)を大事(だいじ)にする人(ひと)がまだ多(おお)い。", "sentence_source": "generated"}, {"text": "旧来の方法では時間がかかりすぎるため、別の手段を探すことにした。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "旧来(きゅうらい)の方法(ほうほう)では時間(じかん)がかかりすぎるため、別(べつ)の手段(しゅだん)を探(さが)すことにした。", "sentence_source": "generated"}, {"text": "彼の提案は、旧来の枠組みにとらわれない発想として高く評価された。", "target_word": "旧来", "complexity_tier": "T4", "furigana": "彼(かれ)の提案(ていあん)は、旧来(きゅうらい)の枠組(わくぐ)みにとらわれない発想(はっそう)として高(たか)く評価(ひょうか)された。", "sentence_source": "generated"}, {"text": "旧来の制度は現実に合わなくなり、ついに改正されることになった。", "target_word": "旧来", "complexity_tier": "T4", "furigana": "旧来(きゅうらい)の制度(せいど)は現実(げんじつ)に合(あ)わなくなり、ついに改正(かいせい)されることになった。", "sentence_source": "generated"}, {"text": "若い世代は旧来の価値観に疑問を持ち、自分たちの生き方を選んでいる。", "target_word": "旧来", "complexity_tier": "T4", "furigana": "若(わか)い世代(せだい)は旧来(きゅうらい)の価値観(かちかん)に疑問(ぎもん)を持(も)ち、自分(じぶん)たちの生(い)き方(かた)を選(えら)んでいる。", "sentence_source": "generated"}, {"text": "旧来の教え方に慣れた先生には、オンライン授業が難しかった。", "target_word": "旧来", "complexity_tier": "T3", "furigana": "旧来(きゅうらい)の教(おし)え方(かた)に慣(な)れた先生(せんせい)には、オンライン授業(じゅぎょう)が難(むずか)しかった。", "sentence_source": "generated"}, {"text": "その工場は旧来の技術を守りながら、新しい機械も少しずつ取り入れている。", "target_word": "旧来", "complexity_tier": "T4", "furigana": "その工場(こうじょう)は旧来(きゅうらい)の技術(ぎじゅつ)を守(まも)りながら、新(あたら)しい機械(きかい)も少(すこ)しずつ取(と)り入(い)れている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "旧来", "label": "基本形"}, {"form": "旧来の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "昔から続いてきたやり方・考え方・慣習(従来)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: アペラシオン (Zipf 1.01)']::text[], '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧来", "is_correct": true, "explanation": "「旧来の分類体系」は、これまで続いてきた昔からの分類を指し、文脈に合う。"}, {"text": "恋愛", "is_correct": false, "explanation": "「恋愛」は人の感情に関する語で、ワインの品種を基準とした分類体系とは結びつかない。"}, {"text": "乗客", "is_correct": false, "explanation": "「乗客」は人を指す語で、分類体系を修飾すると意味が成り立たない。"}, {"text": "祝日", "is_correct": false, "explanation": "「祝日」は暦上の休日を指し、分類体系の性質を表す語として使えない。"}], "explanations": {"旧来": "「旧来の分類体系」は、これまで続いてきた昔からの分類を指し、文脈に合う。", "恋愛": "「恋愛」は人の感情に関する語で、ワインの品種を基準とした分類体系とは結びつかない。", "乗客": "「乗客」は人を指す語で、分類体系を修飾すると意味が成り立たない。", "祝日": "「祝日」は暦上の休日を指し、分類体系の性質を表す語として使えない。"}, "sentence_index": 0, "correct_answer": "旧来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパソコンは旧来なので、動画の編集には向かない。", "explanation": "ここは〈旧式〉の意味。機械の古さは「旧式」で表し、旧来は昔からのやり方を指すので、パソコンには合わない。"}, {"text": "学生時代の旧来と、久しぶりに食事に行った。", "explanation": "ここは〈旧友〉の意味。人を指す語で、旧来は昔から続くやり方を表すため、人には使えない。"}, {"text": "この旧来は江戸時代の街並みを残していて、観光客が多い。", "explanation": "ここは〈旧跡〉の意味。史跡を指す語で、旧来は慣習を表すので、場所を示す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧来", "is_correct": true, "explanation": "「旧来の制度」は、これまでの制度を指し、現実に合わなくなるという文脈に合う。"}, {"text": "海水", "is_correct": false, "explanation": "「海水の制度」は意味をなさず、制度を修飾する語として成り立たない。"}, {"text": "花粉", "is_correct": false, "explanation": "「花粉の制度」は意味をなさず、制度の説明にならない。"}, {"text": "石炭", "is_correct": false, "explanation": "「石炭の制度」は意味をなさず、この文脈に入らない。"}], "explanations": {"旧来": "「旧来の制度」は、これまでの制度を指し、現実に合わなくなるという文脈に合う。", "海水": "「海水の制度」は意味をなさず、制度を修飾する語として成り立たない。", "花粉": "「花粉の制度」は意味をなさず、制度の説明にならない。", "石炭": "「石炭の制度」は意味をなさず、この文脈に入らない。"}, "sentence_index": 6, "correct_answer": "旧来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "久しぶりに旧来と会って、学生時代の話をした。", "explanation": "ここは〈旧友〉の意味。昔の友人という人を指す語で、旧来は昔からのやり方を表すので、人には使えない。"}, {"text": "観光客は旧来を見に、遠くから訪れている。", "explanation": "ここは〈旧跡〉の意味。史跡を指す語で、旧来は慣習を表すので、見に行く対象にはならない。"}, {"text": "私は書店で辞書の旧来を買った。", "explanation": "ここは〈旧版〉の意味。本の古い版を指す語で、旧来は昔からのやり方を表すため、辞書の版には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は旧来に味を守っている。", "corrected_sentence": "この店は旧来の味を守っている。", "error_description": "「旧来」は名詞なので、直後に連体修飾の「の」が必要。「に」は誤りで、正しくは「旧来の味」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52384, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若い職人は、旧来な製法を守りながら新しい味を生み出した。", "corrected_sentence": "若い職人は、旧来の製法を守りながら新しい味を生み出した。", "error_description": "「旧来」は名詞なので、「な」ではなく「の」で続ける。「旧来な」は誤りで、正しくは「旧来の製法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アペラシオンを見る」の目的語を示す「を」で、ここに必要。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所有や修飾を示す。「このアペラシオンの見れば」は動詞を続けられない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「このアペラシオンへ見れば」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。比較の対象がなく、「このアペラシオンより見れば」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「アペラシオンを見る」の目的語を示す「を」で、ここに必要。", "の": "「の」は所有や修飾を示す。「このアペラシオンの見れば」は動詞を続けられない。", "へ": "「へ」は方向を示す。「このアペラシオンへ見れば」は意味が通らない。", "より": "「より」は比較を示す。比較の対象がなく、「このアペラシオンより見れば」は不自然。"}, "error_tags": {"の": "possessive_modifier", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ワインのラベルに書いてある、そのワインがどこで作られたかを示す名前のことです。", "primary_collocate": null, "pronunciation": "あぺらしおん", "ipa": "apeɾaɕioɴ", "syllable_count": 6, "sentences": [{"text": "ワインのラベルに、アペラシオンが小さく書いてあります。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "ワインのラベルに、アペラシオンが小[ちい]さく書[か]いてあります。", "sentence_source": "generated"}, {"text": "このアペラシオンを見れば、ワインがどこで作られたかが分かります。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "このアペラシオンを見[み]れば、ワインがどこで作[つく]られたかが分[わ]かります。", "sentence_source": "generated"}, {"text": "母は産地を知りたくて、ラベルのアペラシオンを確かめました。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "母[はは]は産地[さんち]を知[し]りたくて、ラベルのアペラシオンを確[たし]かめました。", "sentence_source": "generated"}, {"text": "店員さんが、アペラシオンの読み方を教えてくれました。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "店員[てんいん]さんが、アペラシオンの読[よ]み方[かた]を教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "同じ品種でも、アペラシオンが違うと値段も変わります。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "同[おな]じ品種[ひんしゅ]でも、アペラシオンが違[ちが]うと値段[ねだん]も変[か]わります。", "sentence_source": "generated"}, {"text": "私はボルドーのアペラシオンが書かれたワインを買いました。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "私[わたし]はボルドーのアペラシオンが書[か]かれたワインを買[か]いました。", "sentence_source": "generated"}, {"text": "アペラシオンは、たいていラベルの真ん中に大きく書かれています。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "アペラシオンは、たいていラベルの真[ま]ん中[なか]に大[おお]きく書[か]かれています。", "sentence_source": "generated"}, {"text": "ラベルの文字が小さくて、アペラシオンがよく読めませんでした。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "ラベルの文字[もじ]が小[ちい]さくて、アペラシオンがよく読[よ]めませんでした。", "sentence_source": "generated"}, {"text": "父はアペラシオンを見て、このワインは南の地方のものだと言いました。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "父[ちち]はアペラシオンを見[み]て、このワインは南[みなみ]の地方[ちほう]のものだと言[い]いました。", "sentence_source": "generated"}, {"text": "初めてワインを選ぶときは、まずアペラシオンを見るといいですよ。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "初[はじ]めてワインを選[えら]ぶときは、まずアペラシオンを見[み]るといいですよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アペラシオン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ワインのラベルに書かれた産地を示す名前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アペラシオン", "is_correct": true, "explanation": "「ラベルにアペラシオンが書いてある」は、ワインの産地を示す名称が書かれているという意味で自然。"}, {"text": "海水", "is_correct": false, "explanation": "「ラベルに海水が書いてある」は意味をなさず、ワインのラベルの説明にならない。"}, {"text": "石炭", "is_correct": false, "explanation": "「ラベルに石炭が書いてある」は意味をなさず、この文脈に入らない。"}, {"text": "乗客", "is_correct": false, "explanation": "「ラベルに乗客が書いてある」は意味をなさず、ワインの説明として成り立たない。"}], "explanations": {"アペラシオン": "「ラベルにアペラシオンが書いてある」は、ワインの産地を示す名称が書かれているという意味で自然。", "海水": "「ラベルに海水が書いてある」は意味をなさず、ワインのラベルの説明にならない。", "石炭": "「ラベルに石炭が書いてある」は意味をなさず、この文脈に入らない。", "乗客": "「ラベルに乗客が書いてある」は意味をなさず、ワインの説明として成り立たない。"}, "sentence_index": 0, "correct_answer": "アペラシオン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ブドウ畑に、アペラシオンを植えた。", "explanation": "ここは〈苗木〉の意味。植えるのは木で、ワインの産地を示す名称のアペラシオンは植えられない。"}, {"text": "あの店長はアペラシオンだ。いつも親切に客の相談に乗る。", "explanation": "ここは〈店長〉の意味。人を指す語で、産地を示す名称のアペラシオンは人には使えない。"}, {"text": "今日のアペラシオンは、一日中晴れだった。", "explanation": "ここは〈天気〉の意味。空の状態を指す語で、ワインの名称であるアペラシオンは天候には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アペラシオン", "is_correct": true, "explanation": "「アペラシオンは…書かれています」は、ワインの産地を示す名称がラベルに載るという説明として自然。"}, {"text": "花粉", "is_correct": false, "explanation": "「花粉は…書かれています」は、ラベルの記載として意味をなさない。"}, {"text": "紙吹雪", "is_correct": false, "explanation": "「紙吹雪は…書かれています」は、ラベルの記載として成り立たない。"}, {"text": "恋愛", "is_correct": false, "explanation": "「恋愛は…書かれています」は、ラベルの記載として意味をなさない。"}], "explanations": {"アペラシオン": "「アペラシオンは…書かれています」は、ワインの産地を示す名称がラベルに載るという説明として自然。", "花粉": "「花粉は…書かれています」は、ラベルの記載として意味をなさない。", "紙吹雪": "「紙吹雪は…書かれています」は、ラベルの記載として成り立たない。", "恋愛": "「恋愛は…書かれています」は、ラベルの記載として意味をなさない。"}, "sentence_index": 6, "correct_answer": "アペラシオン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母からアペラシオンが届いて、とても嬉しかった。", "explanation": "ここは〈手紙〉の意味。届くのは文書や品物で、ワインの名称であるアペラシオンは届かない。"}, {"text": "封筒にアペラシオンを貼って、ポストに入れた。", "explanation": "ここは〈切手〉の意味。封筒に貼るのは切手で、産地を示す名称のアペラシオンは貼れない。"}, {"text": "今日はアペラシオンだから、みんなでお祝いをした。", "explanation": "ここは〈誕生日〉の意味。お祝いの対象となる日を指す語で、ワインの名称であるアペラシオンは日付にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このワインのアペラシオンに読むと、産地がすぐに分かる。", "corrected_sentence": "このワインのアペラシオンを読むと、産地がすぐに分かる。", "error_description": "「読む」の目的語を示すには「を」が必要。「に」は誤りで、正しくは「アペラシオンを読む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52385, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ラベルのアペラシオンを確かめでから、ワインを買った。", "corrected_sentence": "ラベルのアペラシオンを確かめてから、ワインを買った。", "error_description": "「確かめる」の連用形に続く接続は「確かめて」。「確かめで」は濁音化の誤りで、正しくは「確かめてから」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アペラシオンを名乗る」の目的語を示す「を」で、ここに必要。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「アペラシオンが名乗る」では、名乗る主体が文の意味と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所有や修飾を示す。「アペラシオンの名乗る」は動詞を続けられない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「アペラシオンへ名乗る」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「アペラシオンを名乗る」の目的語を示す「を」で、ここに必要。", "が": "「が」は主語を示す。「アペラシオンが名乗る」では、名乗る主体が文の意味と合わない。", "の": "「の」は所有や修飾を示す。「アペラシオンの名乗る」は動詞を続けられない。", "へ": "「へ」は方向を示す。「アペラシオンへ名乗る」は文として成り立たない。"}, "error_tags": {"が": "subject_marker", "の": "possessive_modifier", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ワインの産地や品質を保証するために、特定の地域や伝統的な製法に基づいて認定された名称や制度のこと。", "primary_collocate": null, "pronunciation": "あぺらしおん", "ipa": "apeɾaɕioɴ", "syllable_count": 6, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "アペラシオン", "complexity_tier": "T4", "furigana": "かかる感覚的[かんかくてき]知見[ちけん]の蓄積[ちくせき]は、単一[たんいつ]品種[ひんしゅ]を基準[きじゅん]とした旧来[きゅうらい]の分類[ぶんるい]体系[たいけい]を相対化[そうたいか]し、微細[びさい]な区画[くかく]ごとの個性[こせい]を階層的[かいそうてき]に位置[いち]づけるアペラシオンの概念[がいねん]を、より厳密[げんみつ]かつ動的[どうてき]なヒエラルキーへと昇華[しょうか]させ、ワインの価値[かち]評価[ひょうか]基準[きじゅん]そのものを哲学的[てつがくてき]かつ実践的[じっせんてき]に再定義[さいていぎ]しているのである。", "sentence_source": "mined"}, {"text": "このワインは、法律で定められたアペラシオンを名乗るために、厳しい検査に合格した。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "このワインは、法律[ほうりつ]で定[さだ]められたアペラシオンを名乗[なの]るために、厳[きび]しい検査[けんさ]に合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "フランスでは、アペラシオンの制度によって、ブドウの品種や収穫量まで細かく決められている。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "フランスでは、アペラシオンの制度[せいど]によって、ブドウの品種[ひんしゅ]や収穫量[しゅうかくりょう]まで細[こま]かく決[き]められている。", "sentence_source": "generated"}, {"text": "産地の名前を守るために、生産者たちはアペラシオンの認定を申請した。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "産地[さんち]の名前[なまえ]を守[まも]るために、生産者[せいさんしゃ]たちはアペラシオンの認定[にんてい]を申請[しんせい]した。", "sentence_source": "generated"}, {"text": "アペラシオンを取得したワインは、そうでないものより高い値段で売られることが多い。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "アペラシオンを取得[しゅとく]したワインは、そうでないものより高[たか]い値段[ねだん]で売[う]られることが多[おお]い。", "sentence_source": "generated"}, {"text": "新しいアペラシオンが認められ、この村のワインは国内外で注目されるようになった。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "新[あたら]しいアペラシオンが認[みと]められ、この村[むら]のワインは国内外[こくないがい]で注目[ちゅうもく]されるようになった。", "sentence_source": "generated"}, {"text": "伝統的な製法を守らないと、アペラシオンの資格を失うおそれがある。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "伝統的[でんとうてき]な製法[せいほう]を守[まも]らないと、アペラシオンの資格[しかく]を失[うしな]うおそれがある。", "sentence_source": "generated"}, {"text": "彼はアペラシオン制度の歴史について、大学で論文を書いた。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "彼[かれ]はアペラシオン制度[せいど]の歴史[れきし]について、大学[だいがく]で論文[ろんぶん]を書[か]いた。", "sentence_source": "generated"}, {"text": "同じ地域でも、アペラシオンが違えば、味の基準も違ってくる。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "同[おな]じ地域[ちいき]でも、アペラシオンが違[ちが]えば、味[あじ]の基準[きじゅん]も違[ちが]ってくる。", "sentence_source": "generated"}, {"text": "品質を保証する仕組みとして、アペラシオンは世界の多くの国で参考にされている。", "target_word": "アペラシオン", "complexity_tier": "T3", "furigana": "品質[ひんしつ]を保証[ほしょう]する仕組[しく]みとして、アペラシオンは世界[せかい]の多[おお]くの国[くに]で参考[さんこう]にされている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アペラシオン", "label": "基本形"}], "register": "formal", "sense_fingerprint": "ワインの産地・品質を保証する認定制度およびその認定名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アペラシオン", "is_correct": true, "explanation": "「位置づけるアペラシオンの概念」として、産地と品質を保証する認定制度を指し、文脈に合う。"}, {"text": "海水", "is_correct": false, "explanation": "「位置づける海水の概念」は意味をなさず、制度の説明にならない。"}, {"text": "石炭", "is_correct": false, "explanation": "「位置づける石炭の概念」は意味をなさず、ワインの文脈に合わない。"}, {"text": "紙吹雪", "is_correct": false, "explanation": "「位置づける紙吹雪の概念」は意味をなさず、この文脈に入らない。"}], "explanations": {"アペラシオン": "「位置づけるアペラシオンの概念」として、産地と品質を保証する認定制度を指し、文脈に合う。", "海水": "「位置づける海水の概念」は意味をなさず、制度の説明にならない。", "石炭": "「位置づける石炭の概念」は意味をなさず、ワインの文脈に合わない。", "紙吹雪": "「位置づける紙吹雪の概念」は意味をなさず、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "アペラシオン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このワインは、アペラシオンという品種のブドウで造られている。", "explanation": "ここは〈品種〉の意味。ブドウの種類を指す語で、認定制度を表すアペラシオンは品種名にはならない。"}, {"text": "あの杜氏はアペラシオンだ。毎年新しい味を生み出している。", "explanation": "ここは〈杜氏〉の意味。酒造りの職人を指す語で、認定制度のアペラシオンは人には当てはまらない。"}, {"text": "店でアペラシオンを一本買ってきた。", "explanation": "ここは〈ボトル〉の意味。瓶を数えて買うのであり、制度の名称であるアペラシオンは本数で数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アペラシオン", "is_correct": true, "explanation": "「アペラシオンの資格」は、産地と製法の基準を満たす認定の資格を指し、文脈に合う。"}, {"text": "祝日", "is_correct": false, "explanation": "「祝日の資格」は意味をなさず、認定制度の説明にならない。"}, {"text": "花粉", "is_correct": false, "explanation": "「花粉の資格」は意味をなさず、ワインの認定の文脈に合わない。"}, {"text": "石炭", "is_correct": false, "explanation": "「石炭の資格」は意味をなさず、この文脈に入らない。"}], "explanations": {"アペラシオン": "「アペラシオンの資格」は、産地と製法の基準を満たす認定の資格を指し、文脈に合う。", "祝日": "「祝日の資格」は意味をなさず、認定制度の説明にならない。", "花粉": "「花粉の資格」は意味をなさず、ワインの認定の文脈に合わない。", "石炭": "「石炭の資格」は意味をなさず、この文脈に入らない。"}, "sentence_index": 6, "correct_answer": "アペラシオン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "品質を保証する仕組みとして、アペラシオンは毎朝ブドウ畑を見回る。", "explanation": "ここは〈農家〉の意味。畑を見回るのは人で、認定制度のアペラシオンは行動しない。"}, {"text": "この電化製品には、アペラシオンが付いている。", "explanation": "ここは〈保証書〉の意味。電化製品の保証は保証書で示し、ワインの認定制度であるアペラシオンは当てはまらない。"}, {"text": "友人にアペラシオンを渡して、挨拶をした。", "explanation": "ここは〈名刺〉の意味。人に渡す紙を指す語で、認定制度のアペラシオンは手渡せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このワインは、アペラシオンを認定を受けるため、厳しい検査を受けた。", "corrected_sentence": "このワインは、アペラシオンの認定を受けるため、厳しい検査を受けた。", "error_description": "「認定」を修飾する「の」が必要。「を」だと「アペラシオンを認定を受ける」となり、文が成り立たない。正しくは「アペラシオンの認定」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52386, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "認定を受けた生産者は、アペラシオンを名乗らことができる。", "corrected_sentence": "認定を受けた生産者は、アペラシオンを名乗ることができる。", "error_description": "「名乗る」を名詞化するには「名乗ること」とする。「名乗らこと」は活用の誤りで、正しくは「名乗ることができる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作る」の目的語を示す「を」で、ヒエラルキーに直接付く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここで作るのは先生なので、ヒエラルキーに付くと文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「作る」の対象を「に」で示すのは不自然で、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「作る」の目的語にならず、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「作る」の目的語を示す「を」で、ヒエラルキーに直接付く。", "が": "「が」は主語を示すが、ここで作るのは先生なので、ヒエラルキーに付くと文が崩れる。", "に": "「作る」の対象を「に」で示すのは不自然で、文が通らない。", "へ": "方向を表す「へ」は「作る」の目的語にならず、文が通らない。"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作って遊ぶ」の対象を示す「を」で、ヒエラルキーに直接付く。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「作る」の対象を示せず、「ヒエラルキーに作る」は文が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、「作って」の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は作る対象を示せず、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「作って遊ぶ」の対象を示す「を」で、ヒエラルキーに直接付く。", "に": "「に」は「作る」の対象を示せず、「ヒエラルキーに作る」は文が通らない。", "の": "「の」は名詞どうしをつなぐもので、「作って」の目的語を示せない。", "へ": "方向を表す「へ」は作る対象を示せず、文が通らない。"}, "error_tags": {"に": "対象", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の上下の順番や、強いものから弱いものへの順序のこと。", "primary_collocate": null, "pronunciation": "ひえらるきー", "ipa": "çieɾaɾɯkiː", "syllable_count": 6, "sentences": [{"text": "食物連鎖では、強いものから弱いものへのヒエラルキーが決まっている。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "食物連鎖[しょくもつれんさ]では、強[つよ]いものから弱[よわ]いものへのヒエラルキーが決[き]まっている。", "sentence_source": "generated"}, {"text": "先生は、重要な順にヒエラルキーを作って説明してくれました。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "先生[せんせい]は、重要[じゅうよう]な順[じゅん]にヒエラルキーを作[つく]って説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "このゲームには、キャラクターの強さのヒエラルキーがあります。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "このゲームには、キャラクターの強[つよ]さのヒエラルキーがあります。", "sentence_source": "generated"}, {"text": "自然界のヒエラルキーでは、ライオンのほうがシマウマより上です。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "自然界[しぜんかい]のヒエラルキーでは、ライオンのほうがシマウマより上[うえ]です。", "sentence_source": "generated"}, {"text": "兄は、好きな食べ物のヒエラルキーを紙に書いていました。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "兄[あに]は、好[す]きな食[た]べ物[もの]のヒエラルキーを紙[かみ]に書[か]いていました。", "sentence_source": "generated"}, {"text": "人の欲求にはヒエラルキーがあり、食べることが一番下にあると言われます。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "人[ひと]の欲求[よっきゅう]にはヒエラルキーがあり、食[た]べることが一番[いちばん]下[した]にあると言[い]われます。", "sentence_source": "generated"}, {"text": "動物園で、サルのヒエラルキーについての話を聞きました。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]で、サルのヒエラルキーについての話[はなし]を聞[き]きました。", "sentence_source": "generated"}, {"text": "友達と、人気のあるお菓子のヒエラルキーを作って遊びました。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "友達[ともだち]と、人気[にんき]のあるお菓子[かし]のヒエラルキーを作[つく]って遊[あそ]びました。", "sentence_source": "generated"}, {"text": "この表は、国の力のヒエラルキーを示しています。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "この表[ひょう]は、国[くに]の力[ちから]のヒエラルキーを示[しめ]しています。", "sentence_source": "generated"}, {"text": "強さのヒエラルキーを知ると、動物の行動がよく分かります。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "強[つよ]さのヒエラルキーを知[し]ると、動物[どうぶつ]の行動[こうどう]がよく分[わ]かります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヒエラルキー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事の上下・強弱の順序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヒエラルキー", "is_correct": true, "explanation": "強いものから弱いものへの順序が「決まっている」の主語になり、その順序を指す語として合う。"}, {"text": "余韻", "is_correct": false, "explanation": "音や言葉が消えた後に残る響きのことで、食物連鎖の順序が決まるという文には合わない。"}, {"text": "独白", "is_correct": false, "explanation": "ひとりで話す言葉を表し、生き物どうしの強弱の順序が決まる文では成り立たない。"}, {"text": "迷宮", "is_correct": false, "explanation": "入り組んだ道を表し、食物連鎖の順序が決まるという内容には結びつかない。"}], "explanations": {"ヒエラルキー": "強いものから弱いものへの順序が「決まっている」の主語になり、その順序を指す語として合う。", "余韻": "音や言葉が消えた後に残る響きのことで、食物連鎖の順序が決まるという文には合わない。", "独白": "ひとりで話す言葉を表し、生き物どうしの強弱の順序が決まる文では成り立たない。", "迷宮": "入り組んだ道を表し、食物連鎖の順序が決まるという内容には結びつかない。"}, "sentence_index": 0, "correct_answer": "ヒエラルキー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は、ヒエラルキーを焼いて客に出す。", "explanation": "ここは〈料理〉の意味。ヒエラルキーは順序の仕組みで、焼いて食べられるものではない。"}, {"text": "この歌はヒエラルキーが速く、CDが売れた。", "explanation": "ここは〈テンポ〉の意味。ヒエラルキーは順序の仕組みで、曲の速さや拍子は指さない。"}, {"text": "このスープはヒエラルキーが濃くて、体が温まる。", "explanation": "ここは〈味の濃さ〉の意味。ヒエラルキーは物事の順序を指すので、料理の味の濃さを表す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヒエラルキー", "is_correct": true, "explanation": "「について話を聞く」の対象として、動物の強弱や順序の仕組みを指す語が入る。"}, {"text": "暗号", "is_correct": false, "explanation": "秘密の符号を表し、動物の話の対象としては文脈に合わない。"}, {"text": "献立", "is_correct": false, "explanation": "食事の組み立てを表し、サルの仕組みについての話には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表し、サルについての話の対象にはならない。"}], "explanations": {"ヒエラルキー": "「について話を聞く」の対象として、動物の強弱や順序の仕組みを指す語が入る。", "暗号": "秘密の符号を表し、動物の話の対象としては文脈に合わない。", "献立": "食事の組み立てを表し、サルの仕組みについての話には合わない。", "天気": "空模様を表し、サルについての話の対象にはならない。"}, "sentence_index": 6, "correct_answer": "ヒエラルキー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋はヒエラルキーの香りがして、落ち着く。", "explanation": "ここは〈香り〉の意味。ヒエラルキーは順序の仕組みで、匂いを表す語としては使わない。"}, {"text": "この体重計は、ヒエラルキーで正確に体重を量れる。", "explanation": "ここは〈測定の道具〉の意味。ヒエラルキーは仕組みの名前で、体重を量る器具にはならない。"}, {"text": "テレビのヒエラルキーを上げると、部屋中に音が響く。", "explanation": "ここは〈音量〉の意味。ヒエラルキーは物事の順序を指すので、音の大きさを上げ下げする量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食物連鎖では、強いものから弱いものへのヒエラルキーを、はっきり決まっている。", "corrected_sentence": "食物連鎖では、強いものから弱いものへのヒエラルキーが、はっきり決まっている。", "error_description": "「決まる」は主語を取るので、ヒエラルキーには「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52387, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強さのヒエラルキーの知ると、動物の行動がずっとよく分かります。", "corrected_sentence": "強さのヒエラルキーを知ると、動物の行動がずっとよく分かります。", "error_description": "「知る」は目的語に「を」を取るので、ヒエラルキーには「を」が正しい。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「残っている」の主語を示す「が」で、ヒエラルキーに直接付く。"}, {"text": "を", "is_correct": false, "explanation": "「残る」は目的語を取らない自動詞なので、「を」は文の骨格に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、「残っている」の主語を示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は主語にはならず、「残っている」と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「残っている」の主語を示す「が」で、ヒエラルキーに直接付く。", "を": "「残る」は目的語を取らない自動詞なので、「を」は文の骨格に合わない。", "の": "「の」は名詞どうしをつなぐもので、「残っている」の主語を示せず文が成り立たない。", "へ": "方向を表す「へ」は主語にはならず、「残っている」と結びつかない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「気にする」の目的語を示す「を」で、ヒエラルキーに直接付く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、ここは目的語の位置なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「気にする」は「に」を目的語に取らないので、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「〜と一緒に」などを表す「と」は、「気にする」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「気にする」の目的語を示す「を」で、ヒエラルキーに直接付く。", "が": "主語を示す「が」で、ここは目的語の位置なので合わない。", "に": "「気にする」は「に」を目的語に取らないので、文が通らない。", "と": "「〜と一緒に」などを表す「と」は、「気にする」の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "相手・対象", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "集団や組織の中で、上位と下位の関係がはっきりと分かれている仕組み。また、その順位づけ。", "primary_collocate": null, "pronunciation": "ひえらるきー", "ipa": "çieɾaɾɯkiː", "syllable_count": 6, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "ヒエラルキー", "complexity_tier": "T4", "furigana": "かかる感覚的[かんかくてき]知見[ちけん]の蓄積[ちくせき]は、単一[たんいつ]品種[ひんしゅ]を基準[きじゅん]とした旧来[きゅうらい]の分類[ぶんるい]体系[たいけい]を相対化[そうたいか]し、微細[びさい]な区画[くかく]ごとの個性[こせい]を階層的[かいそうてき]に位置[いち]づけるアペラシオンの概念[がいねん]を、より厳密[げんみつ]かつ動的[どうてき]なヒエラルキーへと昇華[しょうか]させ、ワインの価値[かち]評価[ひょうか]基準[きじゅん]そのものを哲学的[てつがくてき]かつ実践的[じっせんてき]に再定義[さいていぎ]しているのである。", "sentence_source": "mined"}, {"text": "この会社には、年齢によるヒエラルキーが強く残っている。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]には、年齢[ねんれい]によるヒエラルキーが強[つよ]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "軍隊は、厳格なヒエラルキーがあるからこそ、命令がすぐに伝わる。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "軍隊[ぐんたい]は、厳格[げんかく]なヒエラルキーがあるからこそ、命令[めいれい]がすぐに伝[つた]わる。", "sentence_source": "generated"}, {"text": "教室の中にも、人気によるヒエラルキーができてしまうことがある。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の中[なか]にも、人気[にんき]によるヒエラルキーができてしまうことがある。", "sentence_source": "generated"}, {"text": "新しい社長は、ヒエラルキーをなくして、誰もが自由に意見を言える職場を目指した。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "新[あたら]しい社長[しゃちょう]は、ヒエラルキーをなくして、誰[だれ]もが自由[じゆう]に意見[いけん]を言[い]える職場[しょくば]を目指[めざ]した。", "sentence_source": "generated"}, {"text": "動物の群れには、はっきりしたヒエラルキーが見られる。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の群[む]れには、はっきりしたヒエラルキーが見[み]られる。", "sentence_source": "generated"}, {"text": "ヒエラルキーの頂点に立つ人は、責任も重い。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "ヒエラルキーの頂点[ちょうてん]に立[た]つ人[ひと]は、責任[せきにん]も重[おも]い。", "sentence_source": "generated"}, {"text": "彼はヒエラルキーを気にせず、誰にでも同じように話しかける。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "彼[かれ]はヒエラルキーを気[き]にせず、誰[だれ]にでも同[おな]じように話[はな]しかける。", "sentence_source": "generated"}, {"text": "中世の社会は、王を頂点とするヒエラルキーで成り立っていた。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の社会[しゃかい]は、王[おう]を頂点[ちょうてん]とするヒエラルキーで成[な]り立[た]っていた。", "sentence_source": "generated"}, {"text": "組織のヒエラルキーが複雑すぎて、決定に時間がかかる。", "target_word": "ヒエラルキー", "complexity_tier": "T3", "furigana": "組織[そしき]のヒエラルキーが複雑[ふくざつ]すぎて、決定[けってい]に時間[じかん]がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヒエラルキー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "集団・組織内の上下関係の仕組みと順位づけ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヒエラルキー", "is_correct": true, "explanation": "「より厳密かつ動的な〜へと昇華させ」の対象として、集団の上下の仕組みを指すこの語が入る。"}, {"text": "寓話", "is_correct": false, "explanation": "寓話は教訓をもたせた作り話で、ワインの評価基準を昇華させる対象としては文が成り立たない。"}, {"text": "脱線", "is_correct": false, "explanation": "話が本筋から逸れることを表し、体系をより厳密に昇華させるという文脈に合わない。"}, {"text": "誤解", "is_correct": false, "explanation": "誤った理解を表し、より厳密で動的な基準へ昇華させる対象にはならない。"}], "explanations": {"ヒエラルキー": "「より厳密かつ動的な〜へと昇華させ」の対象として、集団の上下の仕組みを指すこの語が入る。", "寓話": "寓話は教訓をもたせた作り話で、ワインの評価基準を昇華させる対象としては文が成り立たない。", "脱線": "話が本筋から逸れることを表し、体系をより厳密に昇華させるという文脈に合わない。", "誤解": "誤った理解を表し、より厳密で動的な基準へ昇華させる対象にはならない。"}, "sentence_index": 0, "correct_answer": "ヒエラルキー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂漠の真ん中には、石で造られたヒエラルキーが今もそびえている。", "explanation": "ここは〈建造物〉の意味。ヒエラルキーは組織や集団の上下の仕組みを指し、石で造られたピラミッドのような建物は指さない。"}, {"text": "二人の歌声は、ヒエラルキーがぴったり合っている。", "explanation": "ここは〈音の調和〉の意味。ヒエラルキーは上下の仕組みなので、声や音がそろう（ハーモニー）ことは指さない。"}, {"text": "この池には、珍しいヒエラルキーの魚が泳いでいる。", "explanation": "ここは〈生き物の種類〉の意味。ヒエラルキーは組織の上下の仕組みで、魚の種類の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヒエラルキー", "is_correct": true, "explanation": "「〜の頂点に立つ人」の前に入り、集団の上下の仕組みを指す。"}, {"text": "寄り道", "is_correct": false, "explanation": "途中で立ち寄ることを表し、「頂点に立つ」という語とは結びつかない。"}, {"text": "残像", "is_correct": false, "explanation": "目に残る映像のことで、人が頂点に立つ話には合わない。"}, {"text": "哀愁", "is_correct": false, "explanation": "物悲しい感じを表し、「頂点に立つ人」の名詞として成り立たない。"}], "explanations": {"ヒエラルキー": "「〜の頂点に立つ人」の前に入り、集団の上下の仕組みを指す。", "寄り道": "途中で立ち寄ることを表し、「頂点に立つ」という語とは結びつかない。", "残像": "目に残る映像のことで、人が頂点に立つ話には合わない。", "哀愁": "物悲しい感じを表し、「頂点に立つ人」の名詞として成り立たない。"}, "sentence_index": 6, "correct_answer": "ヒエラルキー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地域では、ヒエラルキーを通じて近所の人と仲良くなる行事が多い。", "explanation": "ここは〈交流〉の意味。ヒエラルキーは上下の仕組みなので、人と人が親しくなる場面の説明には合わない。"}, {"text": "新しいカメラは、ヒエラルキーを使えば夜の写真もきれいに撮れる。", "explanation": "ここは〈技術・機能〉の意味。ヒエラルキーは道具や機能ではないので、写真の性能の話には使わない。"}, {"text": "夏休みは、家族と過ごすヒエラルキーがいちばん楽しい。", "explanation": "ここは〈時間〉の意味。ヒエラルキーは仕組みの名前で、過ごす時間を表す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社には、年齢によるヒエラルキーを今も強く残っている。", "corrected_sentence": "この会社には、年齢によるヒエラルキーが今も強く残っている。", "error_description": "「残る」は主語を取る自動詞なので、直前のヒエラルキーには「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52388, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ヒエラルキーを頂点に立つ人は、責任も重いと言われる。", "corrected_sentence": "ヒエラルキーの頂点に立つ人は、責任も重いと言われる。", "error_description": "「頂点」は「ヒエラルキー」に属することを示すので「の」が必要。「を」だと文の意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「哲学とは〜」の定義を示す「と」で、哲学に直接付く。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、文の述語を作れず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は定義を示す形にならず、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」は定義を述べる文に入らず、意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「哲学とは〜」の定義を示す「と」で、哲学に直接付く。", "の": "「の」は名詞どうしをつなぐもので、文の述語を作れず、文が成り立たない。", "へ": "方向を表す「へ」は定義を示す形にならず、文が通らない。", "で": "手段や場所を表す「で」は定義を述べる文に入らず、意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとの深い意味や、生き方について考えること。", "primary_collocate": null, "pronunciation": "てつがく", "ipa": "tetsɯɡakɯ", "syllable_count": 4, "sentences": [{"text": "夜空を見ていると、つい哲学をしたくなります。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "夜空[よぞら]を見[み]ていると、つい哲学[てつがく]をしたくなります。", "sentence_source": "generated"}, {"text": "哲学とは、ものごとの深い意味を考えることだと思います。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "哲学[てつがく]とは、ものごとの深[ふか]い意味[いみ]を考[かんが]えることだと思[おも]います。", "sentence_source": "generated"}, {"text": "兄は、生きる意味について哲学するのが好きです。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "兄[あに]は、生[い]きる意味[いみ]について哲学[てつがく]するのが好[す]きです。", "sentence_source": "generated"}, {"text": "友達と夜遅くまで、人生の意味について哲学しました。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "友達[ともだち]と夜遅[よふ]くまで、人生[じんせい]の意味[いみ]について哲学[てつがく]しました。", "sentence_source": "generated"}, {"text": "小さな子どもの質問は、ときどき哲学のようです。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "小[ちい]さな子[こ]どもの質問[しつもん]は、ときどき哲学[てつがく]のようです。", "sentence_source": "generated"}, {"text": "祖父は畑仕事をしながら、静かに哲学していました。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "祖父[そふ]は畑仕事[はたけしごと]をしながら、静[しず]かに哲学[てつがく]していました。", "sentence_source": "generated"}, {"text": "夜になると、彼は自分の生き方について哲学し始める。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "夜[よる]になると、彼[かれ]は自分[じぶん]の生[い]き方[かた]について哲学[てつがく]し始[はじ]める。", "sentence_source": "generated"}, {"text": "失敗したあとで、私は幸せとは何か、哲学するようになりました。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "失敗[しっぱい]したあとで、私[わたし]は幸[しあわ]せとは何[なに]か、哲学[てつがく]するようになりました。", "sentence_source": "generated"}, {"text": "散歩の時間は、私にとって哲学の時間です。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "散歩[さんぽ]の時間[じかん]は、私[わたし]にとって哲学[てつがく]の時間[じかん]です。", "sentence_source": "generated"}, {"text": "「なぜ生きるのか」と考えるのは、哲学の第一歩です。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "「なぜ生[い]きるのか」と考[かんが]えるのは、哲学[てつがく]の第一歩[だいいっぽ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "哲学", "label": "基本形"}, {"form": "哲学する", "label": "動詞形"}], "register": "neutral", "sense_fingerprint": "ものごとの意味や生き方について深く考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哲学", "is_correct": true, "explanation": "「つい〜をしたくなる」の対象として、夜空を見て考えたくなる行為を指す語が入る。"}, {"text": "帳簿", "is_correct": false, "explanation": "お金の記録を表す語で、夜空を見てしたくなる行為とは結びつかない。"}, {"text": "残業", "is_correct": false, "explanation": "仕事を遅くまで行うことで、夜空を見てしたくなる行為としては文が成り立たない。"}, {"text": "清算", "is_correct": false, "explanation": "お金や関係を整理することで、夜空を見て「したくなる」行為には合わない。"}], "explanations": {"哲学": "「つい〜をしたくなる」の対象として、夜空を見て考えたくなる行為を指す語が入る。", "帳簿": "お金の記録を表す語で、夜空を見てしたくなる行為とは結びつかない。", "残業": "仕事を遅くまで行うことで、夜空を見てしたくなる行為としては文が成り立たない。", "清算": "お金や関係を整理することで、夜空を見て「したくなる」行為には合わない。"}, "sentence_index": 0, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は近所の哲学をおもしろく話すのが好きだ。", "explanation": "ここは〈噂話〉の意味。哲学は物事の意味や生き方を考えることで、近所の噂を語る話題には使わない。"}, {"text": "彼は動物の哲学をたくさん知っていて、クイズで強い。", "explanation": "ここは〈雑学〉の意味。哲学は学問や考え方を指し、クイズに出る細かい知識には使わない。"}, {"text": "明日は、哲学が晴れるといいな。", "explanation": "ここは〈天気〉の意味。哲学は物事の意味や生き方を考えることで、天候の晴れ・曇りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哲学", "is_correct": true, "explanation": "「について〜し始める」の形で、生き方について深く考える行為を指す語が入る。"}, {"text": "収穫", "is_correct": false, "explanation": "作物を取り入れることで、生き方について「し始める」とは結びつかない。"}, {"text": "集計", "is_correct": false, "explanation": "数字をまとめることで、人生の生き方について「し始める」内容には合わない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届けることで、生き方について考え始めるという文には成り立たない。"}], "explanations": {"哲学": "「について〜し始める」の形で、生き方について深く考える行為を指す語が入る。", "収穫": "作物を取り入れることで、生き方について「し始める」とは結びつかない。", "集計": "数字をまとめることで、人生の生き方について「し始める」内容には合わない。", "配達": "品物を届けることで、生き方について考え始めるという文には成り立たない。"}, "sentence_index": 6, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行の準備では、まず哲学を見るのが第一歩です。", "explanation": "ここは〈地図〉の意味。哲学は見て確かめる地図のような物ではないので、準備の対象としては使わない。"}, {"text": "料理では、まず哲学を洗うのが第一歩です。", "explanation": "ここは〈食材〉の意味。哲学は洗う対象の食材ではないので、料理の下ごしらえの説明には使わない。"}, {"text": "試験勉強は、まず哲学を解くのが第一歩です。", "explanation": "ここは〈過去問〉の意味。哲学は問題集の問題ではないので、解く対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜空を見ていると、つい哲学へしたくなるものです。", "corrected_sentence": "夜空を見ていると、つい哲学をしたくなるものです。", "error_description": "「したくなる」は目的語に「を」を取るので、哲学には「を」が正しい。「へ」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52389, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると、彼は自分の生き方に哲学し始めることが多い。", "corrected_sentence": "夜になると、彼は自分の生き方について哲学し始めることが多い。", "error_description": "「哲学する」は話題を「について」で示すので、「生き方」には「について」が正しい。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「専攻している」の目的語を示す「を」で、哲学に直接付く。"}, {"text": "に", "is_correct": false, "explanation": "「専攻する」は「に」を目的語に取らないので、文が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここは専攻する対象の位置なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は専攻する対象を示せず、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「専攻している」の目的語を示す「を」で、哲学に直接付く。", "に": "「専攻する」は「に」を目的語に取らないので、文が通らない。", "が": "「が」は主語を示すが、ここは専攻する対象の位置なので合わない。", "へ": "方向を表す「へ」は専攻する対象を示せず、文が通らない。"}, "error_tags": {"に": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「比べる」の対象を示す「を」で、後ろの哲学に直接付く。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、「比べる」の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は比べる対象を示せず、文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を表す「より」は、比べる対象の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「比べる」の対象を示す「を」で、後ろの哲学に直接付く。", "の": "「の」は名詞どうしをつなぐもので、「比べる」の目的語を示せない。", "へ": "方向を表す「へ」は比べる対象を示せず、文が通らない。", "より": "比較の基準を表す「より」は、比べる対象の目的語にはならない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較の基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界や人生の根本的な原理や、ものの見方・考え方について深く探求する学問。また、そのような考え方。", "primary_collocate": null, "pronunciation": "てつがく", "ipa": "tetsɯɡakɯ", "syllable_count": 4, "sentences": [{"text": "この本は、人生の哲学を分かりやすく説明している。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "この本[ほん]は、人生[じんせい]の哲学[てつがく]を分[わ]かりやすく説明[せつめい]している。", "sentence_source": "generated"}, {"text": "彼は大学で西洋の哲学を専攻している。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で西洋[せいよう]の哲学[てつがく]を専攻[せんこう]している。", "sentence_source": "generated"}, {"text": "カントの哲学は難しいが、読む価値がある。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "カントの哲学[てつがく]は難[むずか]しいが、読[よ]む価値[かち]がある。", "sentence_source": "generated"}, {"text": "この会社の哲学は、客を第一に考えることだ。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の哲学[てつがく]は、客[きゃく]を第一[だいいち]に考[かんが]えることだ。", "sentence_source": "generated"}, {"text": "古代ギリシャの哲学は、現代の学問の土台になった。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "古代[こだい]ギリシャの哲学[てつがく]は、現代[げんだい]の学問[がくもん]の土台[どだい]になった。", "sentence_source": "generated"}, {"text": "哲学の授業では、「正義とは何か」という問いについて議論した。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "哲学[てつがく]の授業[じゅぎょう]では、「正義[せいぎ]とは何[なに]か」という問[と]いについて議論[ぎろん]した。", "sentence_source": "generated"}, {"text": "彼女は自分なりの哲学を持っていて、簡単には意見を変えない。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]なりの哲学[てつがく]を持[も]っていて、簡単[かんたん]には意見[いけん]を変[か]えない。", "sentence_source": "generated"}, {"text": "東洋の哲学と西洋の哲学を比べる研究が進んでいる。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "東洋[とうよう]の哲学[てつがく]と西洋[せいよう]の哲学[てつがく]を比[くら]べる研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "職人の仕事には、長年の経験から生まれた哲学がある。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "職人[しょくにん]の仕事[しごと]には、長年[ながねん]の経験[けいけん]から生[う]まれた哲学[てつがく]がある。", "sentence_source": "generated"}, {"text": "哲学を学ぶと、当たり前のことを疑う力が身につく。", "target_word": "哲学", "complexity_tier": "T3", "furigana": "哲学[てつがく]を学[まな]ぶと、当[あ]たり前[まえ]のことを疑[うたが]う力[ちから]が身[み]につく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "哲学", "label": "基本形"}, {"form": "哲学的", "label": "派生形（形状詞）"}], "register": "neutral", "sense_fingerprint": "根本原理を探る学問、またその人なりの根本的な考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e54716e-0c37-45e6-b095-32fa23d36ba1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哲学", "is_correct": true, "explanation": "「人生の〜を分かりやすく説明する」の対象として、人生の根本的な考え方を指すこの語が入る。"}, {"text": "郷愁", "is_correct": false, "explanation": "懐かしさを表す語で、人生の根本的な考え方を説明する文には合わない。"}, {"text": "寛容", "is_correct": false, "explanation": "心の広さを表す語で、人生の根本的な考え方を説明する文には合わない。"}, {"text": "嗜好", "is_correct": false, "explanation": "好みを表す語で、人生の考え方を説明する文脈には合わない。"}], "explanations": {"哲学": "「人生の〜を分かりやすく説明する」の対象として、人生の根本的な考え方を指すこの語が入る。", "郷愁": "懐かしさを表す語で、人生の根本的な考え方を説明する文には合わない。", "寛容": "心の広さを表す語で、人生の根本的な考え方を説明する文には合わない。", "嗜好": "好みを表す語で、人生の考え方を説明する文脈には合わない。"}, "sentence_index": 0, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は塩の代わりに哲学を料理に入れる。", "explanation": "ここは〈調味料〉の意味。哲学は学問や考え方を指し、料理に入れる材料ではない。"}, {"text": "彼は哲学の包丁を使い、どんな料理も見事に作る。", "explanation": "ここは〈道具〉の意味。哲学は学問や考え方を指し、包丁のような道具の名前としては使わない。"}, {"text": "彼は哲学のシューズを履いて、毎日十キロも走る。", "explanation": "ここは〈靴〉の意味。哲学は学問や考え方を指すので、靴のような身につける物は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哲学", "is_correct": true, "explanation": "「自分なりの〜を持つ」の対象として、生き方や物の見方の根本を指す語が入る。"}, {"text": "天候", "is_correct": false, "explanation": "空模様や気候を表し、人の意見を支える考え方の位置には入らない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表し、意見を変えないことを支える対象にはならない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝ているときに出す言葉で、「自分なりの〜を持つ」の対象としては成り立たない。"}], "explanations": {"哲学": "「自分なりの〜を持つ」の対象として、生き方や物の見方の根本を指す語が入る。", "天候": "空模様や気候を表し、人の意見を支える考え方の位置には入らない。", "食欲": "食べたい気持ちを表し、意見を変えないことを支える対象にはならない。", "寝言": "寝ているときに出す言葉で、「自分なりの〜を持つ」の対象としては成り立たない。"}, "sentence_index": 6, "correct_answer": "哲学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は哲学が多く、高級車に乗っている。", "explanation": "ここは〈収入〉の意味。哲学は考え方を指すので、お金の多さを表す語としては使わない。"}, {"text": "新幹線は哲学が速く、東京から大阪まで二時間半で着く。", "explanation": "ここは〈速度〉の意味。哲学は学問や考え方を指し、乗り物の速さには使わない。"}, {"text": "店は哲学が少なくなり、すぐに補充を頼んだ。", "explanation": "ここは〈在庫〉の意味。哲学は数えて補充する商品ではないので、この文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は大学で西洋の哲学に専攻していた。", "corrected_sentence": "彼は大学で西洋の哲学を専攻していた。", "error_description": "「専攻する」は目的語に「を」を取るので、哲学には「を」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52390, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哲学の学ぶと、当たり前のことを疑う力が自然と身につく。", "corrected_sentence": "哲学を学ぶと、当たり前のことを疑う力が自然と身につく。", "error_description": "「学ぶ」は目的語に「を」を取るので、哲学には「を」が正しい。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda8c11a-75b2-4a4b-9d5f-72e38898e36a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
