INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52391, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「三つの階層に分かれている」で、分かれた先の区分を示す。"}, {"text": "で", "is_correct": false, "explanation": "「三つの階層で分かれている」は手段や場所を示す「で」で、分かれる先の区分とは合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「階層より分かれている」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「階層の分かれている」は名詞修飾になり、述語「分かれている」が文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「三つの階層に分かれている」で、分かれた先の区分を示す。", "で": "「三つの階層で分かれている」は手段や場所を示す「で」で、分かれる先の区分とは合わない。", "より": "比較の助詞で、「階層より分かれている」は文が成り立たない。", "の": "「階層の分かれている」は名詞修飾になり、述語「分かれている」が文として成り立たない。"}, "error_tags": {"で": "手段・場所を示すが、分かれる先には合わない", "より": "比較の助詞で、区分には使えない", "の": "名詞修飾になり、述語が宙に浮く"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52391, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の段階や順序のこと。", "primary_collocate": null, "pronunciation": "かいそう", "ipa": "kaisoː", "syllable_count": 4, "sentences": [{"text": "組織は、社長から新入社員まで、いくつかの階層に分かれている。", "target_word": "階層", "complexity_tier": "T3", "furigana": "組織[そしき]は、社長[しゃちょう]から新入[しんにゅう]社員[しゃいん]まで、いくつかの階層[かいそう]に分[わ]かれている。", "sentence_source": "generated"}, {"text": "年収によって、人々をいくつかの階層に分ける調査がある。", "target_word": "階層", "complexity_tier": "T3", "furigana": "年収[ねんしゅう]によって、人々[ひとびと]をいくつかの階層[かいそう]に分[わ]ける調査[ちょうさ]がある。", "sentence_source": "generated"}, {"text": "フォルダの階層が深すぎて、ファイルが見つからない。", "target_word": "階層", "complexity_tier": "T3", "furigana": "フォルダの階層[かいそう]が深[ふか]すぎて、ファイルが見[み]つからない。", "sentence_source": "generated"}, {"text": "社会にはいろいろな階層があり、暮らし方も違う。", "target_word": "階層", "complexity_tier": "T3", "furigana": "社会[しゃかい]にはいろいろな階層[かいそう]があり、暮[く]らし方[かた]も違[ちが]う。", "sentence_source": "generated"}, {"text": "階層ごとに仕事の内容が決まっている。", "target_word": "階層", "complexity_tier": "T3", "furigana": "階層[かいそう]ごとに仕事[しごと]の内容[ないよう]が決[き]まっている。", "sentence_source": "generated"}, {"text": "情報を階層に分けて整理すると、探しやすくなる。", "target_word": "階層", "complexity_tier": "T3", "furigana": "情報[じょうほう]を階層[かいそう]に分[わ]けて整理[せいり]すると、探[さが]しやすくなる。", "sentence_source": "generated"}, {"text": "上の階層の人が決めたことを、下の階層に伝える。", "target_word": "階層", "complexity_tier": "T3", "furigana": "上[うえ]の階層[かいそう]の人[ひと]が決[き]めたことを、下[した]の階層[かいそう]に伝[つた]える。", "sentence_source": "generated"}, {"text": "このゲームは、難しさが三つの階層に分かれている。", "target_word": "階層", "complexity_tier": "T3", "furigana": "このゲームは、難[むずか]しさが三[みっ]つの階層[かいそう]に分[わ]かれている。", "sentence_source": "generated"}, {"text": "階層が上がるほど、責任も重くなる。", "target_word": "階層", "complexity_tier": "T3", "furigana": "階層[かいそう]が上[あ]がるほど、責任[せきにん]も重[おも]くなる。", "sentence_source": "generated"}, {"text": "大きな階層から小さな階層へ順に説明していく。", "target_word": "階層", "complexity_tier": "T3", "furigana": "大[おお]きな階層[かいそう]から小[ちい]さな階層[かいそう]へ順[じゅん]に説明[せつめい]していく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "階層", "label": "基本形"}], "register": "中立", "sense_fingerprint": "上下に重なった段階や順序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52391, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "階層", "is_correct": true, "explanation": "正解。組織の上下の段階を表す「階層」が入る。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は段階や順序を表さず、「いくつかの天気に分かれている」は文として成り立たない。"}, {"text": "音色", "is_correct": false, "explanation": "「音色」は音の質を指し、組織を分ける単位にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は感覚の状態で、組織の区分には使えない。"}], "explanations": {"階層": "正解。組織の上下の段階を表す「階層」が入る。", "天気": "「天気」は段階や順序を表さず、「いくつかの天気に分かれている」は文として成り立たない。", "音色": "「音色」は音の質を指し、組織を分ける単位にはならない。", "眠気": "「眠気」は感覚の状態で、組織の区分には使えない。"}, "sentence_index": 0, "correct_answer": "階層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピアノの階層を一音ずつ練習した。", "explanation": "ここは〈音階〉の意味。音の高さを順に並べたものは「音階」で表し、階層は組織や段階の上下に使うので合わない。"}, {"text": "このビルは十階層まである。", "explanation": "ここは建物の〈階〉の数え方の問題。建物の階数は「階」で数え、階層は上下の段階を表すので合わない。"}, {"text": "この急な階層は、登るのに一時間かかった。", "explanation": "ここは〈階段〉の意味。足で段を登る設備は「階段」で表し、階層は上下の区分を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52391, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "階層", "is_correct": true, "explanation": "正解。「上の階層」と対になり、「下の階層に伝える」と自然に続く。"}, {"text": "家計", "is_correct": false, "explanation": "「家計」は家庭のお金の管理を指し、伝える先の段階にはならない。"}, {"text": "湿度", "is_correct": false, "explanation": "「湿度」は空気の湿り具合で、組織の段階を表さない。"}, {"text": "合唱", "is_correct": false, "explanation": "「合唱」は歌の形式で、伝える先の段階にはならない。"}], "explanations": {"階層": "正解。「上の階層」と対になり、「下の階層に伝える」と自然に続く。", "家計": "「家計」は家庭のお金の管理を指し、伝える先の段階にはならない。", "湿度": "「湿度」は空気の湿り具合で、組織の段階を表さない。", "合唱": "「合唱」は歌の形式で、伝える先の段階にはならない。"}, "sentence_index": 6, "correct_answer": "階層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新しいパソコンは、処理速度の階層がとても高い。", "explanation": "ここは〈水準〉の意味。処理速度の高さは「水準」で表し、階層は組織や段階の上下に使うので合わない。"}, {"text": "会議室の席の階層を決めて座った。", "explanation": "ここは〈位置〉の意味。座る場所は「位置」で表し、階層は上下の段階を指すので合わない。"}, {"text": "二つの駅の階層は、三キロも離れている。", "explanation": "ここは〈距離〉の意味。離れている長さは「距離」で表し、階層は段階の上下を示すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52391, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "書類を階層を分けて保管すると、探しやすい。", "corrected_sentence": "書類を階層に分けて保管すると、探しやすい。", "error_description": "誤りは「階層を」の「を」。「分ける」は「〜を〜に分ける」の形で、分ける先は「に」で示す。したがって正しくは「階層に分けて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52391, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社の組織は、三つの階層に分けている。", "corrected_sentence": "この会社の組織は、三つの階層に分かれている。", "error_description": "誤りは動詞の形。「分けている」は他動詞で目的語が必要なのに、主語「組織は」だけで文が終わっている。主語が「組織」なので自動詞「分かれている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
