INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52393, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "とても冷たくて、こおってしまいそうなようす。", "primary_collocate": null, "pronunciation": "いてつく", "ipa": "itetsɯkɯ", "syllable_count": 4, "sentences": [{"text": "凍て付くような風が吹いて、耳が痛くなった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]くような風[かぜ]が吹[ふ]いて、耳[みみ]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "凍て付く朝、池の水はかちかちにこおっていた。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く朝[あさ]、池[いけ]の水[みず]はかちかちにこおっていた。", "sentence_source": "generated"}, {"text": "凍て付く夜道を、コートを着て急いで歩いた。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く夜道[よみち]を、コートを着[き]て急[いそ]いで歩[ある]いた。", "sentence_source": "generated"}, {"text": "外は凍て付く寒さなので、手袋を忘れないでください。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "外[そと]は凍[い]て付[つ]く寒[さむ]さなので、手袋[てぶくろ]を忘[わす]れないでください。", "sentence_source": "generated"}, {"text": "凍て付く川の水に手を入れたら、すぐ感覚がなくなった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く川[かわ]の水[みず]に手[て]を入[い]れたら、すぐ感覚[かんかく]がなくなった。", "sentence_source": "generated"}, {"text": "冬の山は凍て付く空気に包まれていた。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "冬[ふゆ]の山[やま]は凍[い]て付[つ]く空気[くうき]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "凍て付く寒さの中で、犬は小さく震えていた。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く寒[さむ]さの中[なか]で、犬[いぬ]は小[ちい]さく震[ふる]えていた。", "sentence_source": "generated"}, {"text": "凍て付くような冷たい水で、顔を洗った。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]くような冷[つめ]たい水[みず]で、顔[かお]を洗[あら]った。", "sentence_source": "generated"}, {"text": "凍て付く地面の上に、白い霜がおりている。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く地面[じめん]の上[うえ]に、白[しろ]い霜[しも]がおりている。", "sentence_source": "generated"}, {"text": "凍て付く北風の日は、家でじっとしていたい。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く北風[きたかぜ]の日[ひ]は、家[いえ]でじっとしていたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凍て付く", "label": "辞書形"}, {"form": "凍て付き", "label": "連用形"}, {"form": "凍て付いた", "label": "た形"}, {"form": "凍て付かない", "label": "ない形"}], "register": "文章語", "sense_fingerprint": "こおりそうなほど冷たい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52393, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。凍りそうなほど冷たい風の様子を表し、「風」を修飾する形に合う。"}, {"text": "焦げ付く", "is_correct": false, "explanation": "「焦げ付く」は焦げて張り付く意味で、風の様子には合わない。"}, {"text": "色褪せる", "is_correct": false, "explanation": "「色褪せる」は色が薄くなる意味で、風には使えない。"}, {"text": "煮詰める", "is_correct": false, "explanation": "「煮詰める」は煮て水分を減らす意味で、風の様子には合わない。"}], "explanations": {"凍て付く": "正解。凍りそうなほど冷たい風の様子を表し、「風」を修飾する形に合う。", "焦げ付く": "「焦げ付く」は焦げて張り付く意味で、風の様子には合わない。", "色褪せる": "「色褪せる」は色が薄くなる意味で、風には使えない。", "煮詰める": "「煮詰める」は煮て水分を減らす意味で、風の様子には合わない。"}, "sentence_index": 0, "correct_answer": "凍て付く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい企画は、会議で一気に凍て付いた。", "explanation": "ここは〈停滞する〉の意味。話が進まなくなる様子には「停滞する」を使い、凍て付くは寒さの様子を表すので合わない。"}, {"text": "夕方になって部屋が凍て付いてきた。", "explanation": "ここは〈冷える〉の意味。少し冷えた程度なら「冷える」を使い、凍て付くは凍るほどの寒さを指すので合わない。"}, {"text": "恐ろしい話を聞いて、体が凍て付いた。", "explanation": "ここは〈凍り付く〉の意味。恐怖で動けなくなる状態には「凍り付く」を使い、凍て付くは寒さによる様子を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52393, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。寒さを表す語として「寒さの中で」に続き、犬の震えの状況に合う。"}, {"text": "見つめる", "is_correct": false, "explanation": "「見つめる寒さ」は意味が通らず、寒さを修飾できない。"}, {"text": "押し付ける", "is_correct": false, "explanation": "「押し付ける寒さ」は文脈に合わず、寒さの程度を表さない。"}, {"text": "打ち明ける", "is_correct": false, "explanation": "「打ち明ける寒さ」は意味が通らず、寒さの修飾にならない。"}], "explanations": {"凍て付く": "正解。寒さを表す語として「寒さの中で」に続き、犬の震えの状況に合う。", "見つめる": "「見つめる寒さ」は意味が通らず、寒さを修飾できない。", "押し付ける": "「押し付ける寒さ」は文脈に合わず、寒さの程度を表さない。", "打ち明ける": "「打ち明ける寒さ」は意味が通らず、寒さの修飾にならない。"}, "sentence_index": 6, "correct_answer": "凍て付く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "食卓の熱いスープが凍て付いてしまった。", "explanation": "ここは〈冷める〉の意味。熱い物が温度を下げる変化には「冷める」を使い、凍て付くは寒さの様子なので合わない。"}, {"text": "日に当てたままの写真の色が凍て付いた。", "explanation": "ここは〈色褪せる〉の意味。色が薄くなる変化には「色褪せる」を使い、凍て付くは寒さの様子を表すので合わない。"}, {"text": "やかんのお湯が凍て付いた。", "explanation": "ここは〈沸く〉の意味。お湯が熱くなる変化には「沸く」を使い、凍て付くは寒さを表すので逆の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52393, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凍て付き朝、池の水は凍っていた。", "corrected_sentence": "凍て付く朝、池の水は凍っていた。", "error_description": "誤りは「凍て付き」（連用形）。名詞「朝」を修飾するには連体形「凍て付く」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。名詞「朝」を直接修飾する辞書形。"}, {"text": "凍て付き", "is_correct": false, "explanation": "連用形で、名詞「朝」を直接修飾できないので合わない。"}, {"text": "凍て付け", "is_correct": false, "explanation": "命令形で、名詞「朝」を修飾できないので合わない。"}, {"text": "凍て付かない", "is_correct": false, "explanation": "ない形になると寒くない朝の意味になり、文の内容に合わない。"}], "correct_form": "凍て付く", "base_form": "凍て付く", "form_label": "辞書形（名詞修飾）", "sentence_index": 1, "explanations": {"凍て付く": "正解。名詞「朝」を直接修飾する辞書形。", "凍て付き": "連用形で、名詞「朝」を直接修飾できないので合わない。", "凍て付け": "命令形で、名詞「朝」を修飾できないので合わない。", "凍て付かない": "ない形になると寒くない朝の意味になり、文の内容に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52393, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凍て付くの寒さの中で、子どもたちが遊んでいた。", "corrected_sentence": "凍て付く寒さの中で、子どもたちが遊んでいた。", "error_description": "誤りは「凍て付く」の直後に入った「の」。「凍て付く寒さ」と連体形で直接続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。「凍て付くような」の形で、冷たさを比喩的に表す辞書形。"}, {"text": "凍て付いて", "is_correct": false, "explanation": "て形は文を続ける形で、「ような」と結びつけて冷たい水を修飾することができないので合わない。"}, {"text": "凍て付け", "is_correct": false, "explanation": "命令形で、比況の「ような」に続かず、名詞「水」を修飾できないので合わない。"}, {"text": "凍て付こう", "is_correct": false, "explanation": "意志形で、「ような」と続けて冷たい水を修飾する形にはならないので合わない。"}], "correct_form": "凍て付く", "base_form": "凍て付く", "form_label": "辞書形（比況の修飾）", "sentence_index": 7, "explanations": {"凍て付く": "正解。「凍て付くような」の形で、冷たさを比喩的に表す辞書形。", "凍て付いて": "て形は文を続ける形で、「ような」と結びつけて冷たい水を修飾することができないので合わない。", "凍て付け": "命令形で、比況の「ような」に続かず、名詞「水」を修飾できないので合わない。", "凍て付こう": "意志形で、「ような」と続けて冷たい水を修飾する形にはならないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
