INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52394, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "非常に冷え込んで、物が凍ってしまうほど寒いこと。また、そのような寒さで心や体がこわばる様子。", "primary_collocate": null, "pronunciation": "いてつく", "ipa": "itetsɯkɯ", "syllable_count": 4, "sentences": [{"text": "真冬の朝、水道管が凍て付くほど冷え込んだ。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "真冬[まふゆ]の朝[あさ]、水道管[すいどうかん]が凍[い]て付[つ]くほど冷[ひ]え込[こ]んだ。", "sentence_source": "generated"}, {"text": "凍て付く寒さの中、体がこわばって動けなくなった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く寒[さむ]さの中[なか]、体[からだ]がこわばって動[うご]けなくなった。", "sentence_source": "generated"}, {"text": "凍て付く夜、窓ガラスにも氷がはりついた。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く夜[よる]、窓[まど]ガラスにも氷[こおり]がはりついた。", "sentence_source": "generated"}, {"text": "凍て付く冬の夜に外で待ったので、足の先までこわばった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く冬[ふゆ]の夜[よる]に外[そと]で待[ま]ったので、足[あし]の先[さき]までこわばった。", "sentence_source": "generated"}, {"text": "凍て付く湖の上を、渡り鳥が静かに飛んでいった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く湖[みずうみ]の上[うえ]を、渡[わた]り鳥[どり]が静[しず]かに飛[と]んでいった。", "sentence_source": "generated"}, {"text": "この地方では、凍て付く日が一月中ずっと続く。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "この地方[ちほう]では、凍[い]て付[つ]く日[ひ]が一月[いちがつ]中[じゅう]ずっと続[つづ]く。", "sentence_source": "generated"}, {"text": "凍て付く風のせいで、手がかじかんでペンが持てない。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く風[かぜ]のせいで、手[て]がかじかんでペンが持[も]てない。", "sentence_source": "generated"}, {"text": "凍て付く寒さで、車のドアも開かなくなった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く寒[さむ]さで、車[くるま]のドアも開[あ]かなくなった。", "sentence_source": "generated"}, {"text": "凍て付く吹雪の中、登山者の心は不安でこわばった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く吹雪[ふぶき]の中[なか]、登山者[とざんしゃ]の心[こころ]は不安[ふあん]でこわばった。", "sentence_source": "generated"}, {"text": "凍て付く冬の空気が、頬を刺すようだった。", "target_word": "凍て付く", "complexity_tier": "T3", "furigana": "凍[い]て付[つ]く冬[ふゆ]の空気[くうき]が、頬[ほお]を刺[さ]すようだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凍て付く", "label": "辞書形"}, {"form": "凍て付き", "label": "連用形"}, {"form": "凍て付いた", "label": "た形"}, {"form": "凍て付かない", "label": "ない形"}], "register": "文章語", "sense_fingerprint": "物が凍るほどの寒さ、寒さで体や心がこわばる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52394, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。物が凍るほど冷え込む様子を表し、「ほど冷え込んだ」と自然につながる。"}, {"text": "押し込む", "is_correct": false, "explanation": "「押し込む」は中へ押し入れる動作で、冷え込みの程度を表さない。"}, {"text": "焦げ付く", "is_correct": false, "explanation": "「焦げ付く」は焦げて張り付く意味で、冷え込みには使えない。"}, {"text": "色褪せる", "is_correct": false, "explanation": "「色褪せる」は色が薄くなる意味で、冷え込みの説明にはならない。"}], "explanations": {"凍て付く": "正解。物が凍るほど冷え込む様子を表し、「ほど冷え込んだ」と自然につながる。", "押し込む": "「押し込む」は中へ押し入れる動作で、冷え込みの程度を表さない。", "焦げ付く": "「焦げ付く」は焦げて張り付く意味で、冷え込みには使えない。", "色褪せる": "「色褪せる」は色が薄くなる意味で、冷え込みの説明にはならない。"}, "sentence_index": 0, "correct_answer": "凍て付く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱いお茶が凍て付いた。", "explanation": "ここは〈冷める〉の意味。熱い物が温度を下げる変化には「冷める」を使い、凍て付くは非常に冷たい寒さを指すので合わない。"}, {"text": "暖房で部屋が凍て付いた。", "explanation": "ここは〈温まる〉の意味。暖房で暖かくなる状態には「温まる」を使い、凍て付くは寒さの様子なので合わない。"}, {"text": "一日中歩いて、足が凍て付いた。", "explanation": "ここは〈疲れる〉の意味。歩き疲れには「疲れる」を使い、凍て付くは寒さによる様子を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52394, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。寒さの強さを表し、「風のせいで」に続いて手がかじかむ理由に合う。"}, {"text": "押し付ける", "is_correct": false, "explanation": "「押し付ける風」は意味が通らず、原因を表す語にならない。"}, {"text": "打ち明ける", "is_correct": false, "explanation": "「打ち明ける風」は文脈に合わず、手がかじかむ原因にならない。"}, {"text": "怠る", "is_correct": false, "explanation": "「怠る風」は意味が通らず、寒さの原因を表さない。"}], "explanations": {"凍て付く": "正解。寒さの強さを表し、「風のせいで」に続いて手がかじかむ理由に合う。", "押し付ける": "「押し付ける風」は意味が通らず、原因を表す語にならない。", "打ち明ける": "「打ち明ける風」は文脈に合わず、手がかじかむ原因にならない。", "怠る": "「怠る風」は意味が通らず、寒さの原因を表さない。"}, "sentence_index": 6, "correct_answer": "凍て付く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ミルクを飲んだ赤ちゃんは、すぐに凍て付いた。", "explanation": "ここは〈眠る〉の意味。眠りに落ちる状態には「眠る」を使い、凍て付くは寒さの様子を表すので合わない。"}, {"text": "夕方の空で太陽が凍て付いた。", "explanation": "ここは〈照る〉の意味。太陽が光を放つ様子には「照る」を使い、凍て付くは寒さを表すので合わない。"}, {"text": "鍋がぐつぐつ凍て付いた。", "explanation": "ここは〈煮える〉の意味。食材が熱で煮える様子には「煮える」を使い、凍て付くは寒さの様子なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52394, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "真夜中、凍て付き寒さで窓ガラスが割れた。", "corrected_sentence": "真夜中、凍て付く寒さで窓ガラスが割れた。", "error_description": "誤りは「凍て付き」（連用形）。名詞「寒さ」を修飾するには連体形「凍て付く」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。名詞「寒さ」を直接修飾する辞書形。"}, {"text": "凍て付き", "is_correct": false, "explanation": "連用形で、名詞「寒さ」を直接修飾できないので合わない。"}, {"text": "凍て付け", "is_correct": false, "explanation": "命令形で、名詞「寒さ」を修飾できないので合わない。"}, {"text": "凍て付かない", "is_correct": false, "explanation": "ない形になると寒くない意味になり、体がこわばる文脈に合わない。"}], "correct_form": "凍て付く", "base_form": "凍て付く", "form_label": "辞書形（名詞修飾）", "sentence_index": 1, "explanations": {"凍て付く": "正解。名詞「寒さ」を直接修飾する辞書形。", "凍て付き": "連用形で、名詞「寒さ」を直接修飾できないので合わない。", "凍て付け": "命令形で、名詞「寒さ」を修飾できないので合わない。", "凍て付かない": "ない形になると寒くない意味になり、体がこわばる文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52394, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凍て付くの寒さのせいで、字を書けない人もいた。", "corrected_sentence": "凍て付く寒さのせいで、字を書けない人もいた。", "error_description": "誤りは「凍て付く」の直後に入った「の」。連体形「凍て付く」は「寒さ」に直接続けるので、間に「の」は入らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "凍て付く", "is_correct": true, "explanation": "正解。名詞「寒さ」を直接修飾する辞書形で、「凍て付く寒さ」と続いて文が成り立つ。"}, {"text": "凍て付いて", "is_correct": false, "explanation": "て形は後ろの名詞「寒さ」を修飾できず、「凍て付いて寒さで」は文として続かない。"}, {"text": "凍て付けば", "is_correct": false, "explanation": "仮定形は「〜ば」で条件を表すため、名詞「寒さ」を修飾する形にはならない。"}, {"text": "凍て付け", "is_correct": false, "explanation": "命令形は相手に命じる形で、名詞「寒さ」を修飾する形として使えない。"}], "correct_form": "凍て付く", "base_form": "凍て付く", "form_label": "辞書形（名詞修飾）", "sentence_index": 7, "explanations": {"凍て付く": "正解。名詞「寒さ」を直接修飾する辞書形で、「凍て付く寒さ」と続いて文が成り立つ。", "凍て付いて": "て形は後ろの名詞「寒さ」を修飾できず、「凍て付いて寒さで」は文として続かない。", "凍て付けば": "仮定形は「〜ば」で条件を表すため、名詞「寒さ」を修飾する形にはならない。", "凍て付け": "命令形は相手に命じる形で、名詞「寒さ」を修飾する形として使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題を示す「は」。「室内は静かだ」と場所を主題にする。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」では、「室内を静かで」と文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す「に」では、「室内に静かで」と状態を述べる文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "移動の方向を示す「へ」では、静かだという状態を表せないので合わない。"}], "correct_answer": "は", "explanations": {"は": "話題を示す「は」。「室内は静かだ」と場所を主題にする。", "を": "目的語を示す「を」では、「室内を静かで」と文が成り立たない。", "に": "位置を示す「に」では、「室内に静かで」と状態を述べる文に合わない。", "へ": "移動の方向を示す「へ」では、静かだという状態を表せないので合わない。"}, "error_tags": {"を": "対象", "に": "位置・存在", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "へやのなか", "primary_collocate": null, "pronunciation": "しつない", "ipa": "ɕit͡sɯnai", "syllable_count": 4, "sentences": [{"text": "台風が近づいているので、今日は室内で過ごすことにした。", "target_word": "室内", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているので、今日[きょう]は室内[しつない]で過[す]ごすことにした。", "sentence_source": "generated"}, {"text": "室内は静かで、時計の音だけが聞こえた。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]は静[しず]かで、時計[とけい]の音[おと]だけが聞[き]こえた。", "sentence_source": "generated"}, {"text": "室内に入る前に、玄関で靴を脱いでください。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]に入[はい]る前[まえ]に、玄関[げんかん]で靴[くつ]を脱[ぬ]いでください。", "sentence_source": "generated"}, {"text": "室内の明かりが消えていたので、誰もいないと思った。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]の明[あ]かりが消[き]えていたので、誰[だれ]もいないと思[おも]った。", "sentence_source": "generated"}, {"text": "雪の日は室内でも上着を着ないと寒い。", "target_word": "室内", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は室内[しつない]でも上着[うわぎ]を着[き]ないと寒[さむ]い。", "sentence_source": "generated"}, {"text": "室内はきれいに片づいていて、ほこり一つなかった。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]はきれいに片[かた]づいていて、ほこり一[ひと]つなかった。", "sentence_source": "generated"}, {"text": "室内の空気が悪くなったので、窓を開けて換気した。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]の空気[くうき]が悪[わる]くなったので、窓[まど]を開[あ]けて換気[かんき]した。", "sentence_source": "generated"}, {"text": "外は暗いが、室内は電灯で明るい。", "target_word": "室内", "complexity_tier": "T3", "furigana": "外[そと]は暗[くら]いが、室内[しつない]は電灯[でんとう]で明[あか]るい。", "sentence_source": "generated"}, {"text": "室内で走ると危ないよ、と先生が注意した。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]で走[はし]ると危[あぶ]ないよ、と先生[せんせい]が注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "大きな家具を運び入れたら、室内がとても狭く感じられた。", "target_word": "室内", "complexity_tier": "T3", "furigana": "大[おお]きな家具[かぐ]を運[はこ]び入[い]れたら、室内[しつない]がとても狭[せま]く感[かん]じられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "室内", "label": "基本形"}], "register": "標準", "sense_fingerprint": "へやの中(外に対する内側)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 片づい (Zipf 1.86)']::text[], '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "室内", "is_correct": true, "explanation": "「今日は室内で過ごす」として文が通る唯一の語。部屋の内側を指す。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物で、過ごす場所にはならないので「手袋で過ごす」は合わない。"}, {"text": "朝焼け", "is_correct": false, "explanation": "空の現象で、過ごす場所にはならないので合わない。"}, {"text": "足音", "is_correct": false, "explanation": "音を表す語で、過ごす場所にはならないので合わない。"}], "explanations": {"室内": "「今日は室内で過ごす」として文が通る唯一の語。部屋の内側を指す。", "手袋": "身につける物で、過ごす場所にはならないので「手袋で過ごす」は合わない。", "朝焼け": "空の現象で、過ごす場所にはならないので合わない。", "足音": "音を表す語で、過ごす場所にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "室内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時計の室内には細かい歯車が並んでいる。", "explanation": "ここは〈内部〉の意味。時計の中身は〈内部〉と言い、〈室内〉は部屋の内側を指すので合わない。"}, {"text": "お腹の室内で何かが動いた。", "explanation": "ここは〈体内〉の意味。体の中は〈体内〉や〈中〉と言い、〈室内〉は部屋のことなので合わない。"}, {"text": "卵の殻の室内に黄身がある。", "explanation": "ここは〈内側〉の意味。殻は部屋ではないので、部屋の内側を指す〈室内〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "室内", "is_correct": true, "explanation": "「室内の空気が悪くなった」として文が通る唯一の語。"}, {"text": "歌声", "is_correct": false, "explanation": "声の音で、空気の範囲を示さないので「歌声の空気」は合わない。"}, {"text": "鼓動", "is_correct": false, "explanation": "体の拍動で、空気の範囲を示さないので合わない。"}, {"text": "雪解け", "is_correct": false, "explanation": "季節の現象で、空気の場所を表さないので「雪解けの空気」は合わない。"}], "explanations": {"室内": "「室内の空気が悪くなった」として文が通る唯一の語。", "歌声": "声の音で、空気の範囲を示さないので「歌声の空気」は合わない。", "鼓動": "体の拍動で、空気の範囲を示さないので合わない。", "雪解け": "季節の現象で、空気の場所を表さないので「雪解けの空気」は合わない。"}, "sentence_index": 6, "correct_answer": "室内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "島の室内に学校がある。", "explanation": "ここは〈内陸〉の意味。島の内側の陸地は〈内陸〉と言い、〈室内〉は部屋の内側を指すので合わない。"}, {"text": "森の室内では鹿が暮らしている。", "explanation": "ここは〈奥地〉の意味。森の奥の場所は〈奥地〉と言い、〈室内〉は部屋の内側なので合わない。"}, {"text": "壁の室内に風が入った。", "explanation": "ここは〈隙間〉の意味。壁のすき間は〈隙間〉と言い、〈室内〉は部屋の内側を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休日は室内が本を読んで過ごした。", "corrected_sentence": "休日は室内で本を読んで過ごした。", "error_description": "「過ごす」の場所は「で」で示す。「が」にすると室内が動作の主体になり、文が成り立たない。正しくは「室内で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52395, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の店は室内を照明で明るい。", "corrected_sentence": "夜の店は室内が照明で明るい。", "error_description": "室内の状態を述べる形容詞「明るい」の主語は「が」で示す。「を」にすると室内が目的語になり、状態を述べる文が成り立たない。正しくは「室内が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "動作の場所を示す「で」。「室内で遊ぶ」で、遊ぶ場所を表す。"}, {"text": "に", "is_correct": false, "explanation": "「室内に遊ぶ」は、遊ぶ行為の場所を示す形として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "遊ぶは対象を取らないので、「室内を遊ぶ」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "移動の方向を示す「へ」で、遊ぶ場所は表せないので合わない。"}], "correct_answer": "で", "explanations": {"で": "動作の場所を示す「で」。「室内で遊ぶ」で、遊ぶ場所を表す。", "に": "「室内に遊ぶ」は、遊ぶ行為の場所を示す形として成り立たない。", "を": "遊ぶは対象を取らないので、「室内を遊ぶ」は意味が通らない。", "へ": "移動の方向を示す「へ」で、遊ぶ場所は表せないので合わない。"}, "error_tags": {"に": "位置・存在", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "干す先の場所を示す「に」。「室内に干す」で、洗濯物を置く場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」では、室内が干す主体になり意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同の相手を示す「と」で、干す場所は表せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す「の」では、「室内の干している」と文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "干す先の場所を示す「に」。「室内に干す」で、洗濯物を置く場所を表す。", "が": "主語を示す「が」では、室内が干す主体になり意味が通らない。", "と": "並列や共同の相手を示す「と」で、干す場所は表せないので合わない。", "の": "所属や修飾を示す「の」では、「室内の干している」と文が成り立たない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "の": "修飾・所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家や建物の内側の空間。部屋の中。", "primary_collocate": null, "pronunciation": "しつない", "ipa": "ɕit͡sɯnai", "syllable_count": 4, "sentences": [{"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "室内", "complexity_tier": "T3", "furigana": "凛[りん]とした寒気[かんき]が窓[まど]ガラスを伝[つた]い、室内[しつない]の空気[くうき]を凍[い]てつかせようとしている。", "sentence_source": "mined"}, {"text": "雨が降り出したので、子どもたちは室内で遊ぶことにした。", "target_word": "室内", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]り出[だ]したので、子[こ]どもたちは室内[しつない]で遊[あそ]ぶことにした。", "sentence_source": "generated"}, {"text": "暖房をつけたばかりで、室内はまだ少し肌寒い。", "target_word": "室内", "complexity_tier": "T3", "furigana": "暖房[だんぼう]をつけたばかりで、室内[しつない]はまだ少[すこ]し肌寒[はださむ]い。", "sentence_source": "generated"}, {"text": "室内の温度が高すぎて、窓を開けて風を入れた。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]の温度[おんど]が高[たか]すぎて、窓[まど]を開[あ]けて風[かぜ]を入[い]れた。", "sentence_source": "generated"}, {"text": "外は猛暑だが、室内は冷房が効いて涼しい。", "target_word": "室内", "complexity_tier": "T3", "furigana": "外[そと]は猛暑[もうしょ]だが、室内[しつない]は冷房[れいぼう]が効[き]いて涼[すず]しい。", "sentence_source": "generated"}, {"text": "壁を白く塗り替えたので、室内がずいぶん明るくなった。", "target_word": "室内", "complexity_tier": "T3", "furigana": "壁[かべ]を白[しろ]く塗[ぬ]り替[か]えたので、室内[しつない]がずいぶん明[あか]るくなった。", "sentence_source": "generated"}, {"text": "犬を室内で飼うときは、床が滑らないように気をつけたい。", "target_word": "室内", "complexity_tier": "T3", "furigana": "犬[いぬ]を室内[しつない]で飼[か]うときは、床[ゆか]が滑[すべ]らないように気[き]をつけたい。", "sentence_source": "generated"}, {"text": "花粉がひどい日は、洗濯物を室内に干している。", "target_word": "室内", "complexity_tier": "T3", "furigana": "花粉[かふん]がひどい日[ひ]は、洗濯物[せんたくもの]を室内[しつない]に干[ほ]している。", "sentence_source": "generated"}, {"text": "停電になって、室内は急に真っ暗になった。", "target_word": "室内", "complexity_tier": "T3", "furigana": "停電[ていでん]になって、室内[しつない]は急[きゅう]に真[ま]っ暗[くら]になった。", "sentence_source": "generated"}, {"text": "室内の湿度が上がると、カビが生えやすくなる。", "target_word": "室内", "complexity_tier": "T3", "furigana": "室内[しつない]の湿度[しつど]が上[あ]がると、カビが生[は]えやすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "室内", "label": "基本形"}], "register": "標準", "sense_fingerprint": "建物や部屋の内側の空間(屋外に対する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 凍てつか (Zipf 1.03)']::text[], '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "室内", "is_correct": true, "explanation": "「室内の空気」として文が通る唯一の語。家や部屋の内側の空間を指す。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物なので、空気を凍てつかせる場所として「手袋の空気」とは言えず合わない。"}, {"text": "朝焼け", "is_correct": false, "explanation": "空の色の現象で、空気の範囲を示す語ではないので「朝焼けの空気」は成り立たない。"}, {"text": "足音", "is_correct": false, "explanation": "音を表す語で、空気の範囲を示さないので「足音の空気」は合わない。"}], "explanations": {"室内": "「室内の空気」として文が通る唯一の語。家や部屋の内側の空間を指す。", "手袋": "身につける物なので、空気を凍てつかせる場所として「手袋の空気」とは言えず合わない。", "朝焼け": "空の色の現象で、空気の範囲を示す語ではないので「朝焼けの空気」は成り立たない。", "足音": "音を表す語で、空気の範囲を示さないので「足音の空気」は合わない。"}, "sentence_index": 0, "correct_answer": "室内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖の室内では、大きな魚がゆったりと泳いでいる。", "explanation": "ここは〈水中〉の意味。湖は家や建物ではないので、建物や部屋の内側を指す〈室内〉とは言わない。"}, {"text": "エンジンの室内に異物が入り込み、故障の原因となった。", "explanation": "ここは〈内部〉の意味。機械の中身は〈内部〉と言い、〈室内〉は部屋や建物の内側を指すので合わない。"}, {"text": "表情には出さなかったが、心の室内ではとても驚いていた。", "explanation": "ここは〈内心〉の意味。心の中の気持ちは〈内心〉と言い、〈室内〉は部屋の内側を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "室内", "is_correct": true, "explanation": "「犬を室内で飼う」として自然に文が通る唯一の語。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の現象で、犬を飼う場所にはならないので合わない。"}, {"text": "雪解け", "is_correct": false, "explanation": "季節の現象で、犬を飼う場所にはならないので合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "声の音で、犬を飼う場所にはならないので合わない。"}], "explanations": {"室内": "「犬を室内で飼う」として自然に文が通る唯一の語。", "夕焼け": "空の現象で、犬を飼う場所にはならないので合わない。", "雪解け": "季節の現象で、犬を飼う場所にはならないので合わない。", "歌声": "声の音で、犬を飼う場所にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "室内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "瓶の室内にビー玉がたくさん入っている。", "explanation": "ここは〈中〉の意味。瓶は部屋ではないので、家や部屋の内側を指す〈室内〉とは言わない。"}, {"text": "薬の成分は胃の室内で溶けて、腸へ運ばれる。", "explanation": "ここは〈体内〉の意味。胃の中は〈体内〉と言い、〈室内〉は部屋の内側なので合わない。"}, {"text": "雲の室内に星が瞬いている。", "explanation": "ここは〈夜空〉の意味。星が瞬くのは夜空で、雲の内側は〈室内〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、家族と室内を過ごした。", "corrected_sentence": "寒い日は、家族と室内で過ごした。", "error_description": "「過ごす」は場所を表すとき「で」を取る。「を」にすると室内が目的語になり、不自然で誤り。正しくは「室内で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52396, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昼間は室内が明るいくて、窓を開けなくてもよい。", "corrected_sentence": "昼間は室内が明るくて、窓を開けなくてもよい。", "error_description": "形容詞「明るい」の連用形は「明るくて」。「明るいくて」は活用の誤りで、室内の状態を述べる部分が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52397, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暖気", "is_correct": true, "explanation": "寒気の対義語。あたたかい空気を指し、冷たい空気と対になる。"}, {"text": "夕立", "is_correct": false, "explanation": "夏の短い激しい雨を指し、寒気と対になる語ではない。"}, {"text": "花火", "is_correct": false, "explanation": "夜空に打ち上げる火を指し、寒さと対になる語ではない。"}, {"text": "木漏れ日", "is_correct": false, "explanation": "木の間からさす日の光を指し、寒気の対義語ではない。"}], "correct_answer": "暖気", "explanations": {"暖気": "寒気の対義語。あたたかい空気を指し、冷たい空気と対になる。", "夕立": "夏の短い激しい雨を指し、寒気と対になる語ではない。", "花火": "夜空に打ち上げる火を指し、寒さと対になる語ではない。", "木漏れ日": "木の間からさす日の光を指し、寒気の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
