INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52397, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "さむい くうき。からだを ふるえさせる くらい つめたい かんじ。", "primary_collocate": null, "pronunciation": "かんき", "ipa": "kaŋki", "syllable_count": 3, "sentences": [{"text": "窓を開けると、寒気が部屋に入ってきた。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、寒気[かんき]が部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "朝は寒気が強いので、厚いコートを着て出かけた。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "朝[あさ]は寒気[かんき]が強[つよ]いので、厚[あつ]いコートを着[き]て出[で]かけた。", "sentence_source": "generated"}, {"text": "寒気に震えながら、バスを待っていた。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "寒気[かんき]に震[ふる]えながら、バスを待[ま]っていた。", "sentence_source": "generated"}, {"text": "今夜は寒気が来るので、水道管が凍らないようにしてください。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "今夜[こんや]は寒気[かんき]が来[く]るので、水道管[すいどうかん]が凍[こお]らないようにしてください。", "sentence_source": "generated"}, {"text": "寒気が体にしみて、早く温かいお茶が飲みたくなった。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "寒気[かんき]が体[からだ]にしみて、早[はや]く温[あたた]かいお茶[ちゃ]が飲[の]みたくなった。", "sentence_source": "generated"}, {"text": "雪国では、冬になると寒気がとても厳しい。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "雪国[ゆきぐに]では、冬[ふゆ]になると寒気[かんき]がとても厳[きび]しい。", "sentence_source": "generated"}, {"text": "外に出たとたん、寒気が顔に当たって目が覚めた。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "外[そと]に出[で]たとたん、寒気[かんき]が顔[かお]に当[あ]たって目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "寒気の中で長く待ったせいで、手が真っ赤になった。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "寒気[かんき]の中[なか]で長[なが]く待[ま]ったせいで、手[て]が真[ま]っ赤[か]になった。", "sentence_source": "generated"}, {"text": "毛布を二枚かけても、床から上がる寒気は防げなかった。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "毛布[もうふ]を二枚[にまい]かけても、床[ゆか]から上[あ]がる寒気[かんき]は防[ふせ]げなかった。", "sentence_source": "generated"}, {"text": "天気予報によると、明日は大きな寒気が日本に近づく。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]によると、明日[あした]は大[おお]きな寒気[かんき]が日本[にほん]に近[ちか]づく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寒気", "label": "基本形"}], "register": "標準", "sense_fingerprint": "体が震えるほど冷たい空気や、その冷たさの感じ(かんきと読む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52397, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寒気", "is_correct": true, "explanation": "「窓を開けると、寒気が部屋に入ってきた」として文が通る唯一の語。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物で、部屋に入ってくる主語にはならないので合わない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝る場所で、部屋に入ってくる主語にはならないので合わない。"}, {"text": "鼓動", "is_correct": false, "explanation": "体の拍動で、部屋に入ってくる主語にはならないので合わない。"}], "explanations": {"寒気": "「窓を開けると、寒気が部屋に入ってきた」として文が通る唯一の語。", "手袋": "身につける物で、部屋に入ってくる主語にはならないので合わない。", "寝床": "寝る場所で、部屋に入ってくる主語にはならないので合わない。", "鼓動": "体の拍動で、部屋に入ってくる主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "寒気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今夜は寒気が積もるので、水道管が凍らないようにしてください。", "explanation": "ここは〈雪〉の意味。雪は積もるが、寒気は空気なので積もるとは言えず合わない。"}, {"text": "道に寒気が張るので、水道管が凍らないようにしてください。", "explanation": "ここは〈氷〉の意味。張るのは氷や膜で、寒気は空気なので合わない。"}, {"text": "今夜は寒気が上がるので、ストーブを消してください。", "explanation": "ここは〈気温〉の意味。寒気は冷たい空気を指し、上がる（暖かくなる）とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52397, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒気", "is_correct": true, "explanation": "「外に出たとたん、寒気が顔に当たった」として文が通る唯一の語。"}, {"text": "歌声", "is_correct": false, "explanation": "声の音で、顔に当たる主語にはならないので合わない。"}, {"text": "足音", "is_correct": false, "explanation": "音を表す語で、顔に当たる主語にはならないので合わない。"}, {"text": "木陰", "is_correct": false, "explanation": "日の当たらない場所で、顔に当たる主語にはならないので合わない。"}], "explanations": {"寒気": "「外に出たとたん、寒気が顔に当たった」として文が通る唯一の語。", "歌声": "声の音で、顔に当たる主語にはならないので合わない。", "足音": "音を表す語で、顔に当たる主語にはならないので合わない。", "木陰": "日の当たらない場所で、顔に当たる主語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "寒気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ようやく寒気が明けて、夏が来た。", "explanation": "ここは〈梅雨〉の意味。梅雨は季節として明けるが、寒気は明けるものではないので合わない。"}, {"text": "夜明けに寒気が晴れて、山頂が見えた。", "explanation": "ここは〈霧〉の意味。霧は晴れて視界が開けるが、寒気は晴れるものではないので合わない。"}, {"text": "庭には寒気が飛んでいる。", "explanation": "ここは〈花粉〉の意味。花粉は飛ぶが、寒気は飛ぶものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52397, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方は寒気を強いので、厚いコートを着た。", "corrected_sentence": "夕方は寒気が強いので、厚いコートを着た。", "error_description": "「強い」の主語は「が」で示す。「を」にすると寒気が目的語になり、状態を述べる文が成り立たない。正しくは「寒気が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52397, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "玄関を開けると寒気が足元に当たらて、思わず身震いした。", "corrected_sentence": "玄関を開けると寒気が足元に当たって、思わず身震いした。", "error_description": "動詞「当たる」の て形は「当たって」。「当たらて」は活用の誤りで、寒気の動作を述べる部分の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暖気", "is_correct": true, "explanation": "寒気の対義語。あたたかい空気を指し、冷たい空気と対になる。"}, {"text": "稲妻", "is_correct": false, "explanation": "光る放電の現象で、寒さと対になる語ではない。"}, {"text": "霧雨", "is_correct": false, "explanation": "細かい雨を指し、寒さと対になる語ではない。"}, {"text": "木陰", "is_correct": false, "explanation": "日の当たらない場所を指し、寒気の対義語ではない。"}], "correct_answer": "暖気", "explanations": {"暖気": "寒気の対義語。あたたかい空気を指し、冷たい空気と対になる。", "稲妻": "光る放電の現象で、寒さと対になる語ではない。", "霧雨": "細かい雨を指し、寒さと対になる語ではない。", "木陰": "日の当たらない場所を指し、寒気の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暖気", "is_correct": true, "explanation": "寒気の対義語。あたたかい空気を指し、冷たい空気と対になる。"}, {"text": "波音", "is_correct": false, "explanation": "波の音を指し、寒さと対になる語ではない。"}, {"text": "日向", "is_correct": false, "explanation": "日の当たる場所を指し、寒気の対義語ではない。"}, {"text": "春霞", "is_correct": false, "explanation": "春の霞を指し、寒さと対になる語ではない。"}], "correct_answer": "暖気", "explanations": {"暖気": "寒気の対義語。あたたかい空気を指し、冷たい空気と対になる。", "波音": "波の音を指し、寒さと対になる語ではない。", "日向": "日の当たる場所を指し、寒気の対義語ではない。", "春霞": "春の霞を指し、寒さと対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "冷たくて、からだを震えさせるような空気。また、その寒さの感じ。", "primary_collocate": null, "pronunciation": "かんき", "ipa": "kaŋki", "syllable_count": 3, "sentences": [{"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "凛[りん]とした寒気[かんき]が窓[まど]ガラスを伝[つた]い、室内[しつない]の空気[くうき]を凍[い]てつかせようとしている。", "sentence_source": "mined"}, {"text": "北から強い寒気が流れ込み、明日は全国的に雪になるそうだ。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "北[きた]から強[つよ]い寒気[かんき]が流[なが]れ込[こ]み、明日[あした]は全国的[ぜんこくてき]に雪[ゆき]になるそうだ。", "sentence_source": "generated"}, {"text": "窓の隙間から寒気が入ってくるので、カーテンを厚くした。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "窓[まど]の隙間[すきま]から寒気[かんき]が入[はい]ってくるので、カーテンを厚[あつ]くした。", "sentence_source": "generated"}, {"text": "朝の寒気に震えながら、私は駅まで走った。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "朝[あさ]の寒気[かんき]に震[ふる]えながら、私[わたし]は駅[えき]まで走[はし]った。", "sentence_source": "generated"}, {"text": "寒気が厳しい季節になり、山には霜が降りた。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "寒気[かんき]が厳[きび]しい季節[きせつ]になり、山[やま]には霜[しも]が降[お]りた。", "sentence_source": "generated"}, {"text": "冬の夜明け前は寒気が肌を刺すようだった。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜明[よあ]け前[まえ]は寒気[かんき]が肌[はだ]を刺[さ]すようだった。", "sentence_source": "generated"}, {"text": "暖炉に火を入れても、古い家は寒気が抜けない。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "暖炉[だんろ]に火[ひ]を入[い]れても、古[ふる]い家[いえ]は寒気[かんき]が抜[ぬ]けない。", "sentence_source": "generated"}, {"text": "放射冷却で寒気が地表にたまり、朝は水たまりが凍った。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "放射冷却[ほうしゃれいきゃく]で寒気[かんき]が地表[ちひょう]にたまり、朝[あさ]は水[みず]たまりが凍[こお]った。", "sentence_source": "generated"}, {"text": "扉を開けた途端、寒気が顔に吹きつけた。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "扉[とびら]を開[あ]けた途端[とたん]、寒気[かんき]が顔[かお]に吹[ふ]きつけた。", "sentence_source": "generated"}, {"text": "山頂は寒気が強く、手袋をしていても指がかじかんだ。", "target_word": "寒気", "complexity_tier": "T3", "furigana": "山頂[さんちょう]は寒気[かんき]が強[つよ]く、手袋[てぶくろ]をしていても指[ゆび]がかじかんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寒気", "label": "基本形"}], "register": "標準", "sense_fingerprint": "身を震わせるほど冷たい空気、またその寒さ(かんきと読む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: 凍てつか (Zipf 1.03)']::text[], '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寒気", "is_correct": true, "explanation": "「凛とした寒気が窓ガラスを伝う」として文が通る唯一の語。冷たい空気を指す。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物で、窓ガラスを伝う主語にはならないので合わない。"}, {"text": "足音", "is_correct": false, "explanation": "音を表す語で、窓ガラスを伝う主語にはならないので合わない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝る場所で、窓ガラスを伝う主語にはならないので合わない。"}], "explanations": {"寒気": "「凛とした寒気が窓ガラスを伝う」として文が通る唯一の語。冷たい空気を指す。", "手袋": "身につける物で、窓ガラスを伝う主語にはならないので合わない。", "足音": "音を表す語で、窓ガラスを伝う主語にはならないので合わない。", "寝床": "寝る場所で、窓ガラスを伝う主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "寒気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は寒気を飼っていて、夏でも長袖を着ている。", "explanation": "ここは〈生き物〉の意味。寒気は空気なので、飼うことはできず合わない。"}, {"text": "朝、庭に寒気が降りていた。", "explanation": "ここは〈霜〉の意味。霜は凍った水分が降りるもので、空気の寒気は降りないので合わない。"}, {"text": "昼過ぎには寒気が高くなり、雪が溶けた。", "explanation": "ここは〈気温〉の意味。気温は高くなるが、寒気は冷たい空気なので『高くなる』とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒気", "is_correct": true, "explanation": "「古い家は寒気が抜けない」として文が通る唯一の語。"}, {"text": "雨脚", "is_correct": false, "explanation": "雨の降り方を指し、家の中の状態を述べる主語にはならないので合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "声の音で、家の状態を述べる主語にはならないので合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の現象で、家の状態を述べる主語にはならないので合わない。"}], "explanations": {"寒気": "「古い家は寒気が抜けない」として文が通る唯一の語。", "雨脚": "雨の降り方を指し、家の中の状態を述べる主語にはならないので合わない。", "歌声": "声の音で、家の状態を述べる主語にはならないので合わない。", "夕焼け": "空の現象で、家の状態を述べる主語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "寒気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒気が多くて、洗濯物が乾かない。", "explanation": "ここは〈湿気〉の意味。湿気は多くなるが、寒気は冷たい空気で水分の多さを表さないので合わない。"}, {"text": "池に寒気が張った。", "explanation": "ここは〈氷〉の意味。池に張るのは氷や膜で、寒気は空気なので合わない。"}, {"text": "夜中、寒気が屋根をたたいていた。", "explanation": "ここは〈雨〉の意味。雨は屋根をたたくが、寒気は屋根をたたくものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒気を窓の隙間から入ってきた。", "corrected_sentence": "寒気が窓の隙間から入ってきた。", "error_description": "「入ってくる」の主体は「が」で示す。「を」にすると寒気が目的語になり、文の主語が欠けて誤り。正しくは「寒気が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52398, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒気が強らず、朝は外出を控えた。", "corrected_sentence": "寒気が強く、朝は外出を控えた。", "error_description": "形容詞「強い」の連用形は「強く」。「強らず」は活用の誤りで、寒気の状態を述べる部分の形が崩れている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『白銀』を『雪原』に結ぶ連体修飾の格助詞。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すため『白銀を雪原で』と置くと白銀が作られる対象になり、文の意味が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、白銀に向かう意味になり、雪原を修飾する関係を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、白銀と雪原を比べる文になり、この文の内容と合わない。"}], "correct_answer": "の", "explanations": {"の": "『白銀』を『雪原』に結ぶ連体修飾の格助詞。正解。", "を": "目的語を示すため『白銀を雪原で』と置くと白銀が作られる対象になり、文の意味が成り立たない。", "へ": "方向を示すので、白銀に向かう意味になり、雪原を修飾する関係を表せない。", "より": "比較を示すため、白銀と雪原を比べる文になり、この文の内容と合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『白銀』を『雪原』に結ぶ連体修飾の格助詞。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、『白銀が雪原が』となり、文の構造が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すので、白銀が雪原を修飾する関係にならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、光るは目的語を取らない自動詞なので「白銀を雪原がまぶしく光った」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『白銀』を『雪原』に結ぶ連体修飾の格助詞。正解。", "が": "主語を示すため、『白銀が雪原が』となり、文の構造が崩れる。", "で": "場所や手段を示すので、白銀が雪原を修飾する関係にならない。", "を": "目的語を示すが、光るは目的語を取らない自動詞なので「白銀を雪原がまぶしく光った」は成り立たない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "銀のように白くキラキラ光る雪のこと。", "primary_collocate": null, "pronunciation": "はくぎん", "ipa": "hakɯɡiɴ", "syllable_count": 4, "sentences": [{"text": "白銀の雪が朝の光できらきらと光っている。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "白銀[はくぎん]の雪[ゆき]が朝[あさ]の光[ひかり]できらきらと光[ひか]っている。", "sentence_source": "generated"}, {"text": "子どもたちは白銀の雪原で雪だるまを作った。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "子[こ]どもたちは白銀[はくぎん]の雪原[せつげん]で雪[ゆき]だるまを作[つく]った。", "sentence_source": "generated"}, {"text": "夜のうちに降った白銀の雪が、屋根をまっ白にした。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "夜[よる]のうちに降[ふ]った白銀[はくぎん]の雪[ゆき]が、屋根[やね]をまっ白[しろ]にした。", "sentence_source": "generated"}, {"text": "白銀のゲレンデを、父と一緒にゆっくり滑り降りた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "白銀[はくぎん]のゲレンデを、父[ちち]と一緒[いっしょ]にゆっくり滑[すべ]り降[お]りた。", "sentence_source": "generated"}, {"text": "窓を開けると、白銀の雪が日にあたって眩しかった。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、白銀[はくぎん]の雪[ゆき]が日[ひ]にあたって眩[まぶ]しかった。", "sentence_source": "generated"}, {"text": "白銀の雪の上に、小さな鳥の足あとがついていた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "白銀[はくぎん]の雪[ゆき]の上[うえ]に、小[ちい]さな鳥[とり]の足[あし]あとがついていた。", "sentence_source": "generated"}, {"text": "北の国では、冬になると白銀の世界が広がる。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "北[きた]の国[くに]では、冬[ふゆ]になると白銀[はくぎん]の世界[せかい]が広[ひろ]がる。", "sentence_source": "generated"}, {"text": "太陽が出ると、白銀の雪原がまぶしく光った。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "太陽[たいよう]が出[で]ると、白銀[はくぎん]の雪原[せつげん]がまぶしく光[ひか]った。", "sentence_source": "generated"}, {"text": "弟は白銀の雪をすくって、手のひらにのせた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "弟[おとうと]は白銀[はくぎん]の雪[ゆき]をすくって、手[て]のひらにのせた。", "sentence_source": "generated"}, {"text": "窓の外には白銀の雪が積もり、まだ誰の足跡も見えなかった。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]には白銀[はくぎん]の雪[ゆき]が積[つ]もり、まだ誰[だれ]の足跡[あしあと]も見[み]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "白銀", "label": "基本形"}], "register": "標準", "sense_fingerprint": "銀のように白くキラキラ光る雪そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白銀", "is_correct": true, "explanation": "「白銀の雪が朝の光できらきらと光っている」で、白く光る雪を修飾し、文脈に合う。"}, {"text": "洗濯機", "is_correct": false, "explanation": "家庭用の家電の名詞で、雪を修飾するこの文には当てはまらない。"}, {"text": "交番", "is_correct": false, "explanation": "警察の施設の名詞で、朝の光で光る雪を表す文には合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける器の名詞で、雪の描写を修飾する文には当てはまらない。"}], "explanations": {"白銀": "「白銀の雪が朝の光できらきらと光っている」で、白く光る雪を修飾し、文脈に合う。", "洗濯機": "家庭用の家電の名詞で、雪を修飾するこの文には当てはまらない。", "交番": "警察の施設の名詞で、朝の光で光る雪を表す文には合わない。", "花瓶": "花を生ける器の名詞で、雪の描写を修飾する文には当てはまらない。"}, "sentence_index": 0, "correct_answer": "白銀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨上がりの道は、白銀の泥でぬかるんでいた。", "explanation": "ここは〈泥濘〉の意味。白銀は白く光る雪を指すので、ぬかるんだ土の描写には使わない。"}, {"text": "火が消えたあと、白銀の灰が一面に広がっていた。", "explanation": "ここは〈燃えかす〉の意味。白銀は光る雪を指すので、火の後に残る粉には使わない。"}, {"text": "朝霧が晴れると、白銀の霧が草原に残っていた。", "explanation": "ここは〈もや〉の意味。白銀は光る雪を指すので、朝のもやの描写には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白銀", "is_correct": true, "explanation": "「冬になると白銀の世界が広がる」で、雪に覆われた景色を表し、文脈に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文章を指す名詞で、冬に広がる景色の世界を修飾するには合わない。"}, {"text": "地下鉄", "is_correct": false, "explanation": "地下を走る交通機関の名詞で、冬に広がる景色を表す文には当てはまらない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝るときに使う袋の名詞で、景色の世界を修飾する文には合わない。"}], "explanations": {"白銀": "「冬になると白銀の世界が広がる」で、雪に覆われた景色を表し、文脈に合う。", "手紙": "書いた文章を指す名詞で、冬に広がる景色の世界を修飾するには合わない。", "地下鉄": "地下を走る交通機関の名詞で、冬に広がる景色を表す文には当てはまらない。", "寝袋": "寝るときに使う袋の名詞で、景色の世界を修飾する文には合わない。"}, "sentence_index": 6, "correct_answer": "白銀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑さで、白銀の汗が額から流れた。", "explanation": "ここは〈しずく〉の意味。白銀は白く光る雪を指すので、体から出る水分には使わない。"}, {"text": "習字で、紙に白銀の墨が広がった。", "explanation": "ここは〈黒色〉の意味。白銀は銀色に光る色なので、黒い液体の色には合わない。"}, {"text": "煙突の周りは白銀の煤で汚れていた。", "explanation": "ここは〈黒ずみ〉の意味。白銀は銀色に光る色なので、汚れで黒ずんだ状態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "白銀に雪が朝日を反射して眩しい。", "corrected_sentence": "白銀の雪が朝日を反射して眩しい。", "error_description": "『白銀』は雪を修飾するので『の』で続ける。『に』は誤りで、『白銀の雪』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52401, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "白銀い雪が、窓の外でまぶしく輝いていた。", "corrected_sentence": "白銀の雪が、窓の外でまぶしく輝いていた。", "error_description": "『白銀』は名詞なので、い形容詞のように活用させず『の』で雪に続ける。『白銀い』は誤りで、『白銀の雪』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
