INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52402, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "白銀（はくぎん）は、銀のように白く輝く色、または雪が積もって銀色に美しく見える様子を指す名詞である。", "primary_collocate": null, "pronunciation": "はくぎん", "ipa": "hakɯɡiɴ", "syllable_count": 4, "sentences": [{"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "しかし、窓辺[まどべ]に佇[たたず]む幼[おさな]き我[わ]が子[こ]の瞳[ひとみ]は、白銀[はくぎん]に覆[おお]われた庭先[にわさき]へと注[そそ]がれ、抑[おさ]えきれない生命[せいめい]の衝動[しょうどう]に駆[か]られていた。", "sentence_source": "mined"}, {"text": "朝日を浴びて、山の頂は白銀に輝いていた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "朝日[あさひ]を浴[あ]びて、山[やま]の頂[いただき]は白銀[はくぎん]に輝[かがや]いていた。", "sentence_source": "generated"}, {"text": "一晩降り続いた雪で、町は白銀の景色に変わった。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "一晩[ひとばん]降[ふ]り続[つづ]いた雪[ゆき]で、町[まち]は白銀[はくぎん]の景色[けしき]に変[か]わった。", "sentence_source": "generated"}, {"text": "彼女は白銀の髪を風になびかせて立っていた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は白銀[はくぎん]の髪[かみ]を風[かぜ]になびかせて立[た]っていた。", "sentence_source": "generated"}, {"text": "白銀に染まった畑には、動物の足跡だけが残っていた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "白銀[はくぎん]に染[そ]まった畑[はたけ]には、動物[どうぶつ]の足跡[あしあと]だけが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "冬になると、この村は一面の白銀に包まれる。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、この村[むら]は一面[いちめん]の白銀[はくぎん]に包[つつ]まれる。", "sentence_source": "generated"}, {"text": "月の光を受けた湖の水面が、白銀にきらめいている。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "月[つき]の光[ひかり]を受[う]けた湖[みずうみ]の水面[すいめん]が、白銀[はくぎん]にきらめいている。", "sentence_source": "generated"}, {"text": "新しい車は白銀のボディが美しく、街でも目立つ。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]は白銀[はくぎん]のボディが美[うつく]しく、街[まち]でも目立[めだ]つ。", "sentence_source": "generated"}, {"text": "雪がやんだあと、白銀の山々がくっきりと見えた。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "雪[ゆき]がやんだあと、白銀[はくぎん]の山々[やまやま]がくっきりと見[み]えた。", "sentence_source": "generated"}, {"text": "白銀の世界を見たくて、私たちは早朝にスキー場へ向かった。", "target_word": "白銀", "complexity_tier": "T3", "furigana": "白銀[はくぎん]の世界[せかい]を見[み]たくて、私[わたし]たちは早朝[そうちょう]にスキー場[じょう]へ向[む]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "白銀", "label": "基本形"}], "register": "文章語", "sense_fingerprint": "銀のように白く輝く色、または雪で一面が銀色に見える様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cdbc7fe-512b-4617-968f-e3d06a6b8829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52402, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白銀", "is_correct": true, "explanation": "「白銀に覆われた庭先」で、雪に覆われて銀色に輝く様子を表し、文脈に合う。"}, {"text": "地平線", "is_correct": false, "explanation": "空と大地の境目を指す名詞で、庭先を覆うものにはならないため文が成り立たない。"}, {"text": "重力", "is_correct": false, "explanation": "物を引きつける力の名詞で、庭先を覆う物ではないため、この文には合わない。"}, {"text": "迷宮", "is_correct": false, "explanation": "入り組んだ建造物の意味で、庭先を覆うという文脈には当てはまらない。"}], "explanations": {"白銀": "「白銀に覆われた庭先」で、雪に覆われて銀色に輝く様子を表し、文脈に合う。", "地平線": "空と大地の境目を指す名詞で、庭先を覆うものにはならないため文が成り立たない。", "重力": "物を引きつける力の名詞で、庭先を覆う物ではないため、この文には合わない。", "迷宮": "入り組んだ建造物の意味で、庭先を覆うという文脈には当てはまらない。"}, "sentence_index": 0, "correct_answer": "白銀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "田んぼに、白銀に輝く稲穂が一面に実っていた。", "explanation": "ここは〈黄金〉の意味。稲穂は黄金色に実るもので、白銀の光沢とは合わない。"}, {"text": "深い森は白銀の闇に包まれていた。", "explanation": "ここは〈漆黒〉の意味。『漆黒の闇』が自然で、白く光る白銀は闇の描写には使わない。"}, {"text": "夕焼けが空を白銀に染めた。", "explanation": "ここは〈真紅〉の意味。夕焼けは赤く染まるので、白銀の色では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52402, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白銀", "is_correct": true, "explanation": "「水面が白銀にきらめいている」で、銀のように白く光る様子を表し、文脈に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸を指す名詞で、水面がきらめく対象にはならない。"}, {"text": "旋律", "is_correct": false, "explanation": "音楽の流れを指す名詞で、光を反射してきらめくものではないため文に合わない。"}, {"text": "書斎", "is_correct": false, "explanation": "書物を置く部屋の名称で、水面がきらめく対象にはならないため文が成り立たない。"}], "explanations": {"白銀": "「水面が白銀にきらめいている」で、銀のように白く光る様子を表し、文脈に合う。", "寝息": "眠っている人の呼吸を指す名詞で、水面がきらめく対象にはならない。", "旋律": "音楽の流れを指す名詞で、光を反射してきらめくものではないため文に合わない。", "書斎": "書物を置く部屋の名称で、水面がきらめく対象にはならないため文が成り立たない。"}, "sentence_index": 6, "correct_answer": "白銀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ベランダに、白銀のシーツが干してあった。", "explanation": "ここは〈真っ白〉の意味。白銀は銀のように光る色や雪景色を指し、ただ白いシーツには使わない。"}, {"text": "どんよりした白銀の空から、雨が落ちてきた。", "explanation": "ここは〈鉛色〉の意味。白銀はきらめく色なので、重く沈んだ灰色の空には合わない。"}, {"text": "病気で、片方の目が白銀に濁っていた。", "explanation": "ここは〈白く曇る〉の意味。白銀は銀のように輝く色なので、曇った白の状態には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52402, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の雪原は白銀で光っていた。", "corrected_sentence": "夕方の雪原は白銀に光っていた。", "error_description": "『白銀』に続く格助詞は『に』（白銀に光る）。『で』は誤りで、『白銀に光っていた』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52402, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜明けには、畑全体が白銀な霜に覆われていた。", "corrected_sentence": "夜明けには、畑全体が白銀の霜に覆われていた。", "error_description": "『白銀』は名詞なので、名詞に続けるときは『の』を使う。『白銀な』は誤りで、『白銀の霜』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「空を覆う」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "主格を示すが、「空が覆う」は他動詞の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置を示すが、「空に覆う」は覆う動作の対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用を示すが、「空と覆う」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「空を覆う」で正しい。", "が": "主格を示すが、「空が覆う」は他動詞の文として成り立たない。", "に": "位置を示すが、「空に覆う」は覆う動作の対象として不自然。", "と": "共同・引用を示すが、「空と覆う」は意味が通らない。"}, "error_tags": {"が": "主格", "に": "位置", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52405, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「部屋を覆う」で正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示すが、「部屋で覆う」は目的語の関係が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所有・修飾を示すが、「部屋の覆ってきた」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「部屋より覆う」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「部屋を覆う」で正しい。", "で": "手段・場所を示すが、「部屋で覆う」は目的語の関係が成り立たない。", "の": "所有・修飾を示すが、「部屋の覆ってきた」は文が成り立たない。", "より": "比較を示すが、「部屋より覆う」は意味が通らない。"}, "error_tags": {"で": "手段", "の": "所有・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01b3cb3-0f4e-43f0-b74e-a6c9fec7b561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
